window.KC={"brand":{"name":"Nuhavi Health","tagline":"Clarity before you travel. Care until you're home.","hub":"Knowledge Centre","published":"2026-11-15"},"specialties":[{"id":"cardiology","name":"Cardiology","color":"#B5473A","icon":"heart","intro":"Clear explanations of heart conditions and treatments, from blocked arteries and heart attacks to bypass surgery, valve replacement, pacemakers and life after heart surgery.","treatments":["Coronary angioplasty","CABG (bypass surgery)","Valve repair and replacement","TAVI","Pacemaker and AICD implantation","Heart failure care"],"count":10},{"id":"oncology","name":"Oncology","color":"#6B4FA3","icon":"ribbon","intro":"Understand how cancer develops, how it is staged, and how modern treatments work, including chemotherapy, radiation, immunotherapy, CyberKnife and CAR-T cell therapy.","treatments":["Medical oncology","Radiation oncology","Stereotactic radiosurgery","Immunotherapy","CAR-T cell therapy","Surgical oncology"],"count":15},{"id":"neurology","name":"Neurology","color":"#2F6FA8","icon":"brain","intro":"Plain-language guides to brain and nerve conditions such as stroke, epilepsy, Parkinson's disease and brain tumours, and treatments like craniotomy and deep brain stimulation.","treatments":["Stroke care and thrombectomy","Epilepsy management","Deep brain stimulation","Brain tumour surgery","Neuro-rehabilitation"],"count":10},{"id":"orthopedics","name":"Orthopedics","color":"#2E8A73","icon":"bone","intro":"Everything you need to know about joint pain, arthritis, sports injuries and joint replacement, including how to prepare, what happens in surgery and how to recover well.","treatments":["Knee replacement","Hip replacement","Shoulder replacement","ACL reconstruction","Arthroscopy","Sports medicine"],"count":10},{"id":"spine","name":"Spine Surgery","color":"#3B7C99","icon":"spine","intro":"Understand back and neck pain, slip disc, sciatica and spinal stenosis, when surgery helps and when it does not, and what recovery looks like.","treatments":["Microdiscectomy","Minimally invasive spine surgery","Spinal decompression","Disc replacement","Scoliosis correction"],"count":10},{"id":"hair-transplant","name":"Hair Transplantation","color":"#A8763E","icon":"hair","intro":"Honest, practical information on hair loss and hair transplantation: causes, FUE and FUT, who is suitable, the procedure, recovery, aftercare and realistic results.","treatments":["FUE hair transplant","FUT hair transplant","Beard and eyebrow restoration","Hair loss evaluation"],"count":10},{"id":"weight-loss-surgery","name":"Weight Loss Surgery","color":"#5B8A3A","icon":"scale","intro":"Learn about obesity as a medical condition and how bariatric surgery works, who it may help, how to prepare, what to eat afterwards and how to keep the weight off.","treatments":["Sleeve gastrectomy","Roux-en-Y gastric bypass","Mini gastric bypass","Metabolic surgery for diabetes"],"count":10},{"id":"ivf","name":"IVF","color":"#B05A7A","icon":"embryo","intro":"Gentle, clear guidance on infertility and IVF: causes, tests, each step of treatment, egg retrieval, embryo transfer and freezing, and preparing body and mind.","treatments":["Fertility evaluation","IUI","IVF and ICSI","Frozen embryo transfer","Fertility preservation"],"count":10},{"id":"bone-marrow-transplant","name":"Bone Marrow Transplant","color":"#8B3F55","icon":"cells","intro":"Understand bone marrow and stem cell transplants: who needs one, donor matching, what happens in the transplant unit, recovery, GVHD and life afterwards.","treatments":["Autologous transplant","Allogeneic transplant","Haploidentical transplant","Transplant for thalassaemia"],"count":10},{"id":"kidney-transplant","name":"Kidney Transplant","color":"#3F6A8A","icon":"kidney","intro":"From chronic kidney disease to life with a new kidney: donor options, compatibility testing, Indian legal requirements, surgery, recovery and anti-rejection medicines.","treatments":["Living donor transplant","Deceased donor transplant","ABO-incompatible transplant","Laparoscopic donor nephrectomy"],"count":10}],"articles":[{"slug":"coronary-artery-disease","sp":"cardiology","title":"What Is Coronary Artery Disease?","seo":"Coronary Artery Disease (CAD): Symptoms, Causes & Treatment","desc":"Learn what coronary artery disease is, why heart arteries narrow, the warning signs, how CAD is diagnosed and the treatment options available.","kw":["coronary artery disease","CAD symptoms","blocked heart arteries","heart blockage","atherosclerosis"],"links":["heart-attack-warning-signs","angioplasty-and-stenting","cabg-heart-bypass-surgery"],"video":null,"flow":{"caption":"How a coronary artery narrows","steps":[{"t":"Healthy artery","d":"Smooth inner wall, free blood flow"},{"t":"Plaque builds up","d":"Cholesterol and fat collect in the wall"},{"t":"Artery narrows","d":"Less blood reaches the heart muscle"},{"t":"Plaque ruptures","d":"A clot can block the artery completely"}]},"img":["Cross-section of a healthy coronary artery beside one narrowed by plaque","The heart with its three main coronary arteries labelled","Lifestyle risk factors shown as simple icons (smoking, diabetes, BP, cholesterol)"],"html":"\u003cp>Your heart is a muscle that needs a constant supply of oxygen-rich blood. That blood reaches it through small vessels called \u003cstrong>coronary arteries\u003c/strong>. Coronary artery disease (CAD) happens when these arteries become narrow or blocked, and it is the most common form of heart disease worldwide.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Over many years, a fatty material called \u003cstrong>plaque\u003c/strong> builds up inside the artery walls. This process is called atherosclerosis. As plaque grows, the artery narrows and the heart muscle receives less blood, especially during exercise or stress.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How a coronary artery narrows\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How a coronary artery narrows\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Healthy artery\u003c/b>\u003cspan>Smooth inner wall, free blood flow\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Plaque builds up\u003c/b>\u003cspan>Cholesterol and fat collect in the wall\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Artery narrows\u003c/b>\u003cspan>Less blood reaches the heart muscle\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Plaque ruptures\u003c/b>\u003cspan>A clot can block the artery completely\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cp>Many people have no symptoms in the early stages. When symptoms appear, they may include:\u003c/p>\n\u003cul>\n\u003cli>Chest pain, pressure or tightness (angina), often on exertion and easing with rest\u003c/li>\n\u003cli>Breathlessness while walking or climbing stairs\u003c/li>\n\u003cli>Unusual tiredness\u003c/li>\n\u003cli>Pain spreading to the arm, neck, jaw or back\u003c/li>\n\u003c/ul>\n\u003cp>People with diabetes, women and older adults may have milder or unusual symptoms.\u003c/p>\n\u003ch2 id=\"risk-factors\">Risk factors\u003c/h2>\u003cul>\n\u003cli>Smoking or chewing tobacco\u003c/li>\n\u003cli>Diabetes, high blood pressure and high cholesterol\u003c/li>\n\u003cli>Being overweight and physically inactive\u003c/li>\n\u003cli>Family history of early heart disease\u003c/li>\n\u003cli>Age (men over 45, women over 55)\u003c/li>\n\u003c/ul>\n\u003cp>People of South Asian origin tend to develop CAD at a younger age, so early screening matters.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>Doctors usually start with an ECG, blood tests and an echocardiogram (heart ultrasound). Further tests may include a treadmill stress test, CT coronary angiography or a \u003cstrong>coronary angiogram\u003c/strong>, in which dye is injected into the arteries to show exactly where they are blocked.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Lifestyle changes:\u003c/strong> stopping tobacco, a heart-healthy diet, regular activity and weight control\u003c/li>\n\u003cli>\u003cstrong>Medicines:\u003c/strong> to lower cholesterol, control blood pressure, prevent clots and relieve angina\u003c/li>\n\u003cli>\u003cstrong>Angioplasty and stenting:\u003c/strong> a balloon opens the artery and a small mesh tube keeps it open\u003c/li>\n\u003cli>\u003cstrong>Bypass surgery (CABG):\u003c/strong> a new route is created around blocked arteries, usually when several arteries are affected\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-see-a-specialist\">When should you see a specialist?\u003c/h2>\u003cp>See a cardiologist if you have chest discomfort on exertion, breathlessness that is new or worsening, or several risk factors. Sudden, severe chest pain is an emergency.\u003c/p>\n","faqs":[{"q":"Can coronary artery disease be reversed?","a":"Plaque rarely disappears completely, but medicines and lifestyle changes can slow or stop its growth and greatly lower the risk of a heart attack."},{"q":"Is a normal ECG enough to rule out CAD?","a":"No. An ECG at rest can be normal even when arteries are narrowed. Your doctor may advise a stress test or imaging."},{"q":"Do all blockages need a stent?","a":"No. Many blockages are best treated with medicines. The decision depends on symptoms, the size and location of the blockage, and test results."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"symptoms","text":"Symptoms"},{"id":"risk-factors","text":"Risk factors"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"when-should-you-see-a-specialist","text":"When should you see a specialist?"}],"words":423,"read":2},{"slug":"heart-attack-warning-signs","sp":"cardiology","title":"Heart Attack: Early Warning Signs You Should Never Ignore","seo":"Heart Attack Symptoms & Warning Signs: When to Call for Help","desc":"Recognise the early warning signs of a heart attack in men and women, what to do immediately, and why every minute matters for saving heart muscle.","kw":["heart attack symptoms","heart attack warning signs","signs of heart attack in women","chest pain emergency","myocardial infarction"],"links":["coronary-artery-disease","angioplasty-and-stenting","heart-failure-explained"],"video":null,"flow":{"caption":"What to do in a suspected heart attack","steps":[{"t":"Stop and rest","d":"Sit down, do not exert yourself"},{"t":"Call for help","d":"Dial 108 or 112, or your local emergency number"},{"t":"Do not drive yourself","d":"Wait for an ambulance or be driven"},{"t":"Reach a cath-lab hospital","d":"Fast treatment saves heart muscle"}]},"img":["Body outline showing common pain areas: chest, left arm, jaw, back, upper abdomen","Comparison of typical vs less typical symptoms in women and people with diabetes","\"Time is muscle\" clock graphic"],"html":"\u003cp>A heart attack happens when blood flow to part of the heart muscle is suddenly blocked, usually by a clot. The longer the blockage lasts, the more heart muscle is damaged. Recognising the signs early and getting to hospital fast can save a life.\u003c/p>\n\u003ch2 id=\"classic-warning-signs\">Classic warning signs\u003c/h2>\u003cul>\n\u003cli>Chest pain, pressure, squeezing or heaviness lasting more than a few minutes, or that goes away and comes back\u003c/li>\n\u003cli>Pain spreading to one or both arms, the neck, jaw, back or upper stomach\u003c/li>\n\u003cli>Breathlessness, with or without chest pain\u003c/li>\n\u003cli>Cold sweat\u003c/li>\n\u003cli>Nausea, vomiting or light-headedness\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"What to do in a suspected heart attack\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>What to do in a suspected heart attack\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Stop and rest\u003c/b>\u003cspan>Sit down, do not exert yourself\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Call for help\u003c/b>\u003cspan>Dial 108 or 112, or your local emergency number\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Do not drive yourself\u003c/b>\u003cspan>Wait for an ambulance or be driven\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Reach a cath-lab hospital\u003c/b>\u003cspan>Fast treatment saves heart muscle\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"signs-that-are-easy-to-miss\">Signs that are easy to miss\u003c/h2>\u003cp>Not every heart attack feels like the dramatic chest pain seen in films. \u003cstrong>Women, older adults and people with diabetes\u003c/strong> are more likely to have:\u003c/p>\n\u003cul>\n\u003cli>Unexplained tiredness or weakness\u003c/li>\n\u003cli>Discomfort mistaken for acidity or indigestion\u003c/li>\n\u003cli>Breathlessness without obvious chest pain\u003c/li>\n\u003cli>Back or jaw pain alone\u003c/li>\n\u003c/ul>\n\u003cp>If symptoms are new and unexplained, do not dismiss them as &quot;gas&quot;.\u003c/p>\n\u003ch2 id=\"early-warnings-in-the-days-before\">Early warnings in the days before\u003c/h2>\u003cp>Some people notice chest discomfort on exertion, unusual fatigue or breathlessness days or weeks earlier. These warning signs deserve an urgent medical check.\u003c/p>\n\u003ch2 id=\"what-to-do-immediately\">What to do immediately\u003c/h2>\u003col>\n\u003cli>Stop what you are doing and sit down.\u003c/li>\n\u003cli>Call emergency services (108 or 112 in India).\u003c/li>\n\u003cli>Do not drive yourself to hospital.\u003c/li>\n\u003cli>The emergency team may advise chewing an aspirin if you are not allergic. Follow their instructions.\u003c/li>\n\u003cli>If the person collapses and is not breathing normally, start CPR if trained.\u003c/li>\n\u003c/ol>\n\u003ch2 id=\"how-hospitals-treat-a-heart-attack\">How hospitals treat a heart attack\u003c/h2>\u003cp>Doctors confirm the diagnosis with an \u003cstrong>ECG\u003c/strong> and a blood test called troponin. The blocked artery is usually opened quickly with \u003cstrong>primary angioplasty\u003c/strong> in a cardiac catheterisation lab. Clot-dissolving medicines may be used when a cath lab is not quickly available.\u003c/p>\n\u003ch2 id=\"when-should-you-see-a-specialist\">When should you see a specialist?\u003c/h2>\u003cp>Anyone who has had chest pain, even if it settled, should be evaluated by a cardiologist. After a heart attack, regular follow-up and cardiac rehabilitation help prevent another one.\u003c/p>\n","faqs":[{"q":"Can a heart attack happen without chest pain?","a":"Yes. These \"silent\" or atypical heart attacks are more common in people with diabetes, women and the elderly."},{"q":"Is a heart attack the same as cardiac arrest?","a":"No. A heart attack is a blocked artery. Cardiac arrest is when the heart suddenly stops pumping effectively. A heart attack can lead to cardiac arrest."},{"q":"How quickly should treatment start?","a":"As soon as possible. Opening the artery within the first few hours gives the best chance of limiting damage."}],"toc":[{"id":"classic-warning-signs","text":"Classic warning signs"},{"id":"signs-that-are-easy-to-miss","text":"Signs that are easy to miss"},{"id":"early-warnings-in-the-days-before","text":"Early warnings in the days before"},{"id":"what-to-do-immediately","text":"What to do immediately"},{"id":"how-hospitals-treat-a-heart-attack","text":"How hospitals treat a heart attack"},{"id":"when-should-you-see-a-specialist","text":"When should you see a specialist?"}],"words":414,"read":2},{"slug":"cabg-heart-bypass-surgery","sp":"cardiology","title":"Heart Bypass Surgery (CABG): How Does It Work?","seo":"CABG Heart Bypass Surgery: Procedure, Who Needs It & Recovery","desc":"Understand coronary artery bypass grafting (CABG): why it is done, how grafts reroute blood around blockages, what happens in surgery and recovery.","kw":["CABG","heart bypass surgery","coronary artery bypass grafting","bypass surgery procedure","off-pump bypass"],"links":["coronary-artery-disease","angioplasty-and-stenting","life-after-heart-surgery"],"video":"v-cabg","flow":{"caption":"How a bypass graft works","steps":[{"t":"Blocked artery","d":"Plaque stops blood reaching part of the heart"},{"t":"Graft harvested","d":"A vessel is taken from the chest, leg or arm"},{"t":"Graft attached","d":"One end above the blockage, one end below"},{"t":"Blood rerouted","d":"Heart muscle receives blood again"}]},"img":["Heart showing a blocked coronary artery and a graft bypassing it","Common graft sources: internal mammary artery, leg vein, radial artery","Recovery timeline from ICU to home"],"html":"\u003cp>Coronary artery bypass grafting, or CABG (pronounced &quot;cabbage&quot;), is an operation that creates a new path for blood to reach the heart muscle when the coronary arteries are badly blocked. It is one of the most commonly performed and well-studied heart operations in the world.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Just as a road bypass lets traffic go around a blocked section, a surgical bypass lets blood flow around a narrowed artery. The surgeon uses a healthy blood vessel, called a \u003cstrong>graft\u003c/strong>, taken from elsewhere in your body.\u003c/p>\n\u003cp>Common graft sources:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Internal mammary artery\u003c/strong> from inside the chest wall\u003c/li>\n\u003cli>\u003cstrong>Saphenous vein\u003c/strong> from the leg\u003c/li>\n\u003cli>\u003cstrong>Radial artery\u003c/strong> from the forearm\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"How a bypass graft works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How a bypass graft works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Blocked artery\u003c/b>\u003cspan>Plaque stops blood reaching part of the heart\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Graft harvested\u003c/b>\u003cspan>A vessel is taken from the chest, leg or arm\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Graft attached\u003c/b>\u003cspan>One end above the blockage, one end below\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Blood rerouted\u003c/b>\u003cspan>Heart muscle receives blood again\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"who-needs-it\">Who needs it?\u003c/h2>\u003cp>Your heart team may recommend CABG if you have:\u003c/p>\n\u003cul>\n\u003cli>Blockages in several coronary arteries\u003c/li>\n\u003cli>A major blockage in the left main coronary artery\u003c/li>\n\u003cli>Diabetes with multi-vessel disease\u003c/li>\n\u003cli>Blockages that are unsuitable for stenting\u003c/li>\n\u003cli>Reduced heart pumping function along with blocked arteries\u003c/li>\n\u003c/ul>\n\u003cp>The choice between CABG and angioplasty is made by a cardiologist and cardiac surgeon together, based on your angiogram and overall health.\u003c/p>\n\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003col>\n\u003cli>You are given general anaesthesia.\u003c/li>\n\u003cli>The surgeon opens the chest through the breastbone.\u003c/li>\n\u003cli>The heart may be stopped briefly while a heart-lung machine takes over (&quot;on-pump&quot;), or the surgeon operates on the beating heart (&quot;off-pump&quot;).\u003c/li>\n\u003cli>Grafts are attached above and below each blockage.\u003c/li>\n\u003cli>The breastbone is wired together and the skin closed.\u003c/li>\n\u003c/ol>\n\u003cp>The operation usually takes 3 to 6 hours.\u003c/p>\n\u003ch2 id=\"what-should-you-expect-afterwards\">What should you expect afterwards?\u003c/h2>\u003cul>\n\u003cli>1 to 2 days in the cardiac ICU, then a ward stay of several days\u003c/li>\n\u003cli>Walking begins within a day or two\u003c/li>\n\u003cli>The breastbone takes about 6 to 8 weeks to heal\u003c/li>\n\u003cli>Most people return to light activity within 4 to 6 weeks and to full routine in about 3 months\u003c/li>\n\u003c/ul>\n\u003cp>Cardiac rehabilitation, medicines and lifestyle change are essential to keep the grafts open.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If an angiogram has shown multiple blockages, discuss with a heart team whether CABG, angioplasty or medicines are best for you.\u003c/p>\n","faqs":[{"q":"Is bypass surgery a permanent cure?","a":"It relieves symptoms and improves blood flow, but the underlying disease continues. Medicines and healthy habits help grafts last many years."},{"q":"Is CABG better than stenting?","a":"Neither is better for everyone. CABG is often preferred for complex, multi-vessel disease, especially in people with diabetes."},{"q":"Will I have a large scar?","a":"Traditional CABG leaves a scar down the centre of the chest. Minimally invasive options exist for selected patients."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"who-needs-it","text":"Who needs it?"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"what-should-you-expect-afterwards","text":"What should you expect afterwards?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":419,"read":2},{"slug":"angioplasty-and-stenting","sp":"cardiology","title":"Angioplasty and Stenting Explained","seo":"Angioplasty & Stent Procedure: How It Works and Recovery","desc":"A simple guide to coronary angioplasty and stenting: how a blocked heart artery is opened through a small tube, what to expect and recovery.","kw":["angioplasty","stent","PTCA","coronary stenting","drug-eluting stent"],"links":["coronary-artery-disease","heart-attack-warning-signs","cabg-heart-bypass-surgery"],"video":"v-angioplasty","flow":{"caption":"Angioplasty in four steps","steps":[{"t":"Access","d":"A thin tube enters through the wrist or groin"},{"t":"Guide wire","d":"A fine wire crosses the blockage"},{"t":"Balloon","d":"A balloon is inflated to push plaque aside"},{"t":"Stent","d":"A mesh tube stays to keep the artery open"}]},"img":["Catheter route from the wrist to the heart","Balloon inflating inside a narrowed artery, then stent expanded","Wrist puncture site with compression band"],"html":"\u003cp>Angioplasty is a minimally invasive procedure that opens a narrowed or blocked coronary artery without open surgery. In most cases a small mesh tube called a \u003cstrong>stent\u003c/strong> is placed to keep the artery open.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>The medical name is percutaneous coronary intervention (PCI). &quot;Percutaneous&quot; means through the skin. Instead of opening the chest, the cardiologist reaches the heart through a blood vessel in the wrist or groin.\u003c/p>\n\u003cp>Most stents used today are \u003cstrong>drug-eluting stents\u003c/strong>, coated with medicine that slowly releases to reduce the chance of the artery narrowing again.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Angioplasty in four steps\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Angioplasty in four steps\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Access\u003c/b>\u003cspan>A thin tube enters through the wrist or groin\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Guide wire\u003c/b>\u003cspan>A fine wire crosses the blockage\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Balloon\u003c/b>\u003cspan>A balloon is inflated to push plaque aside\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Stent\u003c/b>\u003cspan>A mesh tube stays to keep the artery open\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"when-is-it-recommended\">When is it recommended?\u003c/h2>\u003cul>\n\u003cli>During a heart attack, to open the blocked artery quickly\u003c/li>\n\u003cli>For angina that is not controlled with medicines\u003c/li>\n\u003cli>When tests show a significant blockage limiting blood flow\u003c/li>\n\u003c/ul>\n\u003cp>For people with many complex blockages, bypass surgery may be a better option.\u003c/p>\n\u003ch2 id=\"what-happens-during-the-procedure\">What happens during the procedure?\u003c/h2>\u003col>\n\u003cli>You stay awake but relaxed. The wrist or groin is numbed.\u003c/li>\n\u003cli>A thin tube (catheter) is guided to the heart using X-ray imaging.\u003c/li>\n\u003cli>Dye is injected to show the blockage (angiogram).\u003c/li>\n\u003cli>A tiny balloon is inflated at the blockage to widen the artery.\u003c/li>\n\u003cli>The stent is expanded and left in place permanently.\u003c/li>\n\u003c/ol>\n\u003cp>The procedure usually takes 30 to 90 minutes. You may feel brief chest discomfort while the balloon is inflated.\u003c/p>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cul>\n\u003cli>Most planned patients go home within 1 to 2 days\u003c/li>\n\u003cli>The wrist or groin site may be sore or bruised for a few days\u003c/li>\n\u003cli>Avoid heavy lifting for about a week\u003c/li>\n\u003cli>Most people return to desk work within a week\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"medicines-after-a-stent\">Medicines after a stent\u003c/h2>\u003cp>You will be prescribed \u003cstrong>blood thinners\u003c/strong>, usually two antiplatelet medicines for a period decided by your cardiologist. Stopping them early without advice can cause a dangerous clot inside the stent.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Talk to a cardiologist if you have chest pain on exertion or abnormal stress test results. Always tell any doctor or dentist that you have a stent before a procedure.\u003c/p>\n","faqs":[{"q":"Is angioplasty a surgery?","a":"It is a procedure rather than open surgery. There is no large cut and no general anaesthesia in most cases."},{"q":"Can a stented artery block again?","a":"It can, but modern drug-eluting stents have lowered this risk considerably. Medicines and lifestyle change also help."},{"q":"Can I go through airport security with a stent?","a":"Yes. Coronary stents do not set off metal detectors and are safe with MRI scans in most cases."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"when-is-it-recommended","text":"When is it recommended?"},{"id":"what-happens-during-the-procedure","text":"What happens during the procedure?"},{"id":"recovery","text":"Recovery"},{"id":"medicines-after-a-stent","text":"Medicines after a stent"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":406,"read":2},{"slug":"when-valve-replacement-is-needed","sp":"cardiology","title":"When Does a Patient Need Heart Valve Replacement?","seo":"Heart Valve Replacement: When It's Needed, Types & TAVI","desc":"Find out when a damaged heart valve needs repair or replacement, the difference between mechanical and tissue valves, and the TAVI option.","kw":["heart valve replacement","aortic valve replacement","mitral valve replacement","TAVI","TAVR"],"links":["heart-valve-disease-symptoms","heart-failure-explained","life-after-heart-surgery"],"video":null,"flow":{"caption":"Choosing a valve treatment","steps":[{"t":"Assess severity","d":"Echo shows how badly the valve is affected"},{"t":"Monitor","d":"Mild disease is watched with regular scans"},{"t":"Repair if possible","d":"Often preferred for the mitral valve"},{"t":"Replace","d":"Surgery or TAVI when damage is severe"}]},"img":["The four heart valves labelled","Mechanical vs tissue valve side by side","TAVI catheter delivering a valve through the groin artery"],"html":"\u003cp>Your heart has four valves that open and close with every heartbeat to keep blood flowing in one direction. When a valve becomes too narrow or too leaky, the heart has to work harder. Over time, severe valve disease may need repair or replacement.\u003c/p>\n\u003ch2 id=\"why-do-valves-fail\">Why do valves fail?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Stenosis:\u003c/strong> the valve becomes stiff and narrow, blocking blood flow (common in the aortic valve with age)\u003c/li>\n\u003cli>\u003cstrong>Regurgitation:\u003c/strong> the valve does not close properly and blood leaks backwards\u003c/li>\n\u003cli>\u003cstrong>Rheumatic heart disease:\u003c/strong> damage after rheumatic fever in childhood, still common in India and Africa\u003c/li>\n\u003cli>Birth defects, infection or wear and tear\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Choosing a valve treatment\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Choosing a valve treatment\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Assess severity\u003c/b>\u003cspan>Echo shows how badly the valve is affected\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Monitor\u003c/b>\u003cspan>Mild disease is watched with regular scans\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Repair if possible\u003c/b>\u003cspan>Often preferred for the mitral valve\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Replace\u003c/b>\u003cspan>Surgery or TAVI when damage is severe\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"when-is-replacement-recommended\">When is replacement recommended?\u003c/h2>\u003cp>Valve replacement is usually considered when:\u003c/p>\n\u003cul>\n\u003cli>The valve disease is \u003cstrong>severe\u003c/strong> on echocardiography, and\u003c/li>\n\u003cli>You have symptoms such as breathlessness, chest pain, fainting or tiredness, or\u003c/li>\n\u003cli>Tests show the heart is starting to enlarge or weaken, even without symptoms\u003c/li>\n\u003c/ul>\n\u003cp>Mild or moderate disease is usually monitored with regular check-ups and scans.\u003c/p>\n\u003ch2 id=\"repair-or-replace\">Repair or replace?\u003c/h2>\u003cp>Surgeons often prefer to \u003cstrong>repair\u003c/strong> the mitral valve when possible, because your own valve generally works better long term. The aortic valve is more often replaced.\u003c/p>\n\u003ch2 id=\"types-of-replacement-valve\">Types of replacement valve\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Mechanical valve\u003c/th>\n\u003cth>Tissue (biological) valve\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Made from\u003c/td>\n\u003ctd>Durable carbon or metal\u003c/td>\n\u003ctd>Animal tissue\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>How long it lasts\u003c/td>\n\u003ctd>Usually lifelong\u003c/td>\n\u003ctd>Often 10 to 20 years\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Blood thinners\u003c/td>\n\u003ctd>Needed lifelong\u003c/td>\n\u003ctd>Usually short term only\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Often chosen for\u003c/td>\n\u003ctd>Younger patients\u003c/td>\n\u003ctd>Older patients or those who cannot take long-term blood thinners\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"surgical-and-catheter-options\">Surgical and catheter options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Open valve surgery:\u003c/strong> the traditional approach through the chest\u003c/li>\n\u003cli>\u003cstrong>Minimally invasive surgery:\u003c/strong> smaller incisions in selected patients\u003c/li>\n\u003cli>\u003cstrong>TAVI (transcatheter aortic valve implantation):\u003c/strong> a new valve is placed through a catheter, usually from the groin, without opening the chest. It is mainly used for aortic stenosis in older or higher-risk patients.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you have been told you have a heart murmur or valve disease, see a cardiologist for regular echocardiograms. New breathlessness, fainting or chest pain needs prompt review.\u003c/p>\n","faqs":[{"q":"Can valve disease be treated with medicines alone?","a":"Medicines can ease symptoms, but they cannot fix a severely damaged valve."},{"q":"Who is suitable for TAVI?","a":"Your heart team decides based on age, valve anatomy, other health conditions and surgical risk."},{"q":"Will I need blood thinners after valve replacement?","a":"Lifelong with a mechanical valve; usually only for a short time with a tissue valve."}],"toc":[{"id":"why-do-valves-fail","text":"Why do valves fail?"},{"id":"when-is-replacement-recommended","text":"When is replacement recommended?"},{"id":"repair-or-replace","text":"Repair or replace?"},{"id":"types-of-replacement-valve","text":"Types of replacement valve"},{"id":"surgical-and-catheter-options","text":"Surgical and catheter options"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":387,"read":2},{"slug":"pacemaker-explained","sp":"cardiology","title":"What Is a Pacemaker and Who Needs One?","seo":"Pacemaker Implantation: Who Needs It, Procedure & Living With One","desc":"Learn how a pacemaker keeps a slow heart beating normally, who needs one, what happens during implantation and day-to-day life afterwards.","kw":["pacemaker","pacemaker implantation","slow heart rate","heart block","bradycardia"],"links":["aicd-implantation","heart-failure-explained","heart-valve-disease-symptoms"],"video":null,"flow":{"caption":"How a pacemaker works","steps":[{"t":"Senses","d":"Leads monitor every heartbeat"},{"t":"Detects a pause","d":"Heart rate falls too low"},{"t":"Sends a pulse","d":"A tiny electrical signal triggers a beat"},{"t":"Records data","d":"Checked at follow-up visits"}]},"img":["Pacemaker under the skin below the collarbone with leads in the heart","Size comparison of a pacemaker with a coin","Leadless pacemaker inside the heart"],"html":"\u003cp>A pacemaker is a small battery-powered device that helps your heart beat at a steady rate when its natural electrical system becomes too slow or unreliable. Pacemakers are among the most common heart devices and are usually implanted in a short procedure.\u003c/p>\n\u003ch2 id=\"how-does-the-heartbeat-work\">How does the heartbeat work?\u003c/h2>\u003cp>Your heart has its own natural pacemaker that sends electrical signals to make it contract. If these signals slow down or are blocked on their way through the heart, your heart rate can drop too low.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How a pacemaker works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How a pacemaker works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Senses\u003c/b>\u003cspan>Leads monitor every heartbeat\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Detects a pause\u003c/b>\u003cspan>Heart rate falls too low\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Sends a pulse\u003c/b>\u003cspan>A tiny electrical signal triggers a beat\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Records data\u003c/b>\u003cspan>Checked at follow-up visits\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"who-needs-a-pacemaker\">Who needs a pacemaker?\u003c/h2>\u003cp>Common reasons include:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Bradycardia:\u003c/strong> a heart rate that is too slow and causes symptoms\u003c/li>\n\u003cli>\u003cstrong>Heart block:\u003c/strong> electrical signals are delayed or blocked between the upper and lower chambers\u003c/li>\n\u003cli>\u003cstrong>Sick sinus syndrome:\u003c/strong> the natural pacemaker works erratically\u003c/li>\n\u003cli>Certain types of heart failure, using a special device called CRT (cardiac resynchronisation therapy)\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms-that-may-point-to-a-slow-heart\">Symptoms that may point to a slow heart\u003c/h2>\u003cul>\n\u003cli>Dizziness or light-headedness\u003c/li>\n\u003cli>Fainting or near-fainting\u003c/li>\n\u003cli>Unusual tiredness\u003c/li>\n\u003cli>Breathlessness on mild exertion\u003c/li>\n\u003cli>Confusion, especially in older adults\u003c/li>\n\u003c/ul>\n\u003cp>An ECG or a 24-hour Holter monitor can confirm whether a slow rhythm is the cause.\u003c/p>\n\u003ch2 id=\"the-procedure\">The procedure\u003c/h2>\u003col>\n\u003cli>Local anaesthesia is given below the collarbone, usually with mild sedation.\u003c/li>\n\u003cli>One or more thin wires (leads) are passed through a vein into the heart.\u003c/li>\n\u003cli>The pacemaker is placed in a small pocket under the skin.\u003c/li>\n\u003cli>The device is tested and the wound closed.\u003c/li>\n\u003c/ol>\n\u003cp>It usually takes about an hour. \u003cstrong>Leadless pacemakers\u003c/strong>, which sit directly inside the heart, are suitable for some patients.\u003c/p>\n\u003ch2 id=\"life-with-a-pacemaker\">Life with a pacemaker\u003c/h2>\u003cul>\n\u003cli>Avoid lifting the arm above shoulder level on the implant side for a few weeks\u003c/li>\n\u003cli>Regular device checks, often possible remotely\u003c/li>\n\u003cli>Batteries typically last several years and are replaced in a minor procedure\u003c/li>\n\u003cli>Keep mobile phones about 15 cm from the device and carry your device ID card\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a cardiologist if you have fainting spells, frequent dizziness or a slow pulse. Fainting while driving or at work needs urgent assessment.\u003c/p>\n","faqs":[{"q":"Will I feel the pacemaker working?","a":"Most people do not feel it at all."},{"q":"Can I have an MRI scan?","a":"Many modern pacemakers are MRI-conditional, but the scan must be planned with your cardiology team."},{"q":"Can I travel by air?","a":"Yes. Show your device card at security."}],"toc":[{"id":"how-does-the-heartbeat-work","text":"How does the heartbeat work?"},{"id":"who-needs-a-pacemaker","text":"Who needs a pacemaker?"},{"id":"symptoms-that-may-point-to-a-slow-heart","text":"Symptoms that may point to a slow heart"},{"id":"the-procedure","text":"The procedure"},{"id":"life-with-a-pacemaker","text":"Life with a pacemaker"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":381,"read":2},{"slug":"aicd-implantation","sp":"cardiology","title":"Understanding AICD Implantation","seo":"AICD / ICD Implantation: Who Needs It and How It Protects You","desc":"Understand what an AICD (implantable defibrillator) is, how it protects against sudden cardiac arrest, who needs one and what life with an ICD is like.","kw":["AICD","ICD implantation","implantable cardioverter defibrillator","sudden cardiac arrest","ventricular tachycardia"],"links":["pacemaker-explained","heart-failure-explained","heart-attack-warning-signs"],"video":null,"flow":{"caption":"How an AICD responds","steps":[{"t":"Monitors","d":"Watches the heart rhythm continuously"},{"t":"Detects danger","d":"Spots a life-threatening fast rhythm"},{"t":"Pacing first","d":"Rapid pacing may stop it painlessly"},{"t":"Shock if needed","d":"Delivers a shock to restore normal rhythm"}]},"img":["AICD under the skin with lead in the right ventricle","ECG strip showing dangerous rhythm corrected by a shock","Subcutaneous ICD placement option"],"html":"\u003cp>An AICD (automatic implantable cardioverter defibrillator), often called an ICD, is a small device placed under the skin that watches your heart rhythm around the clock. If it detects a dangerously fast rhythm that could cause sudden cardiac arrest, it corrects it within seconds.\u003c/p>\n\u003ch2 id=\"how-is-it-different-from-a-pacemaker\">How is it different from a pacemaker?\u003c/h2>\u003cp>A pacemaker treats a heart that beats \u003cstrong>too slowly\u003c/strong>. An AICD mainly protects against a heart that beats \u003cstrong>dangerously fast\u003c/strong>, such as ventricular tachycardia or ventricular fibrillation. Most AICDs can also act as a pacemaker when needed.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How an AICD responds\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How an AICD responds\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Monitors\u003c/b>\u003cspan>Watches the heart rhythm continuously\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Detects danger\u003c/b>\u003cspan>Spots a life-threatening fast rhythm\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Pacing first\u003c/b>\u003cspan>Rapid pacing may stop it painlessly\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Shock if needed\u003c/b>\u003cspan>Delivers a shock to restore normal rhythm\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"who-may-need-an-aicd\">Who may need an AICD?\u003c/h2>\u003cul>\n\u003cli>People who have survived a cardiac arrest\u003c/li>\n\u003cli>People with very weak heart pumping function, often after a heart attack or due to cardiomyopathy\u003c/li>\n\u003cli>Inherited heart rhythm conditions with a high risk of sudden death\u003c/li>\n\u003cli>Episodes of dangerous ventricular rhythms\u003c/li>\n\u003c/ul>\n\u003cp>Doctors use the \u003cstrong>ejection fraction\u003c/strong> (how much blood the heart pumps with each beat) along with other tests to decide.\u003c/p>\n\u003ch2 id=\"the-procedure\">The procedure\u003c/h2>\u003cp>The implantation is similar to a pacemaker:\u003c/p>\n\u003col>\n\u003cli>Local anaesthesia and sedation\u003c/li>\n\u003cli>A lead is passed through a vein into the heart\u003c/li>\n\u003cli>The device is placed under the skin below the collarbone\u003c/li>\n\u003cli>The device is programmed and tested\u003c/li>\n\u003c/ol>\n\u003cp>A \u003cstrong>subcutaneous ICD\u003c/strong>, with the lead under the skin rather than inside the heart, is an option for some patients.\u003c/p>\n\u003ch2 id=\"what-does-a-shock-feel-like\">What does a shock feel like?\u003c/h2>\u003cp>Many people describe it as a sudden thump or kick in the chest that lasts a second. It can be startling, but it means the device has done its job.\u003c/p>\n\u003cp>\u003cstrong>What to do after a shock:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>One shock and you feel well: inform your cardiology team the same day\u003c/li>\n\u003cli>More than one shock, or you feel unwell: seek emergency care\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"living-with-an-aicd\">Living with an AICD\u003c/h2>\u003cul>\n\u003cli>Regular device checks, often remotely\u003c/li>\n\u003cli>Driving rules apply after implantation or a shock; your doctor will advise\u003c/li>\n\u003cli>Keep magnets and strong electrical equipment away from the device\u003c/li>\n\u003cli>Carry your device card\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you have weak heart function, a family history of sudden death or unexplained fainting, ask a cardiologist whether you need a rhythm assessment.\u003c/p>\n","faqs":[{"q":"Does an AICD treat heart failure?","a":"It protects against sudden death but does not strengthen the heart. Some devices (CRT-D) also improve heart pumping coordination."},{"q":"Will the device shock me often?","a":"Most people receive few or no shocks. Programming is adjusted to reduce unnecessary shocks."},{"q":"How long does the battery last?","a":"Usually several years. Replacement is a minor procedure."}],"toc":[{"id":"how-is-it-different-from-a-pacemaker","text":"How is it different from a pacemaker?"},{"id":"who-may-need-an-aicd","text":"Who may need an AICD?"},{"id":"the-procedure","text":"The procedure"},{"id":"what-does-a-shock-feel-like","text":"What does a shock feel like?"},{"id":"living-with-an-aicd","text":"Living with an AICD"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":409,"read":2},{"slug":"heart-valve-disease-symptoms","sp":"cardiology","title":"Symptoms of Heart Valve Disease","seo":"Heart Valve Disease Symptoms: Signs, Causes & Diagnosis","desc":"Recognise the signs of heart valve disease, including breathlessness, fatigue and swelling, and learn how a heart murmur and echo lead to diagnosis.","kw":["heart valve disease symptoms","heart murmur","aortic stenosis symptoms","mitral regurgitation","rheumatic heart disease"],"links":["when-valve-replacement-is-needed","heart-failure-explained","coronary-artery-disease"],"video":null,"flow":null,"img":["Normal valve opening fully vs a narrowed valve","Doctor listening for a heart murmur with a stethoscope","Echocardiogram image explained"],"html":"\u003cp>Heart valve disease often develops slowly, and many people get used to symptoms without realising their heart is involved. Knowing the signs helps you get checked early, before the heart muscle is damaged.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Valve disease means one or more of the heart&#39;s four valves is not opening fully (\u003cstrong>stenosis\u003c/strong>) or not closing tightly (\u003cstrong>regurgitation\u003c/strong>). Either way, the heart has to pump harder to move blood around the body.\u003c/p>\n\u003ch2 id=\"common-symptoms\">Common symptoms\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Breathlessness\u003c/strong>, first on exertion and later even at rest or when lying flat\u003c/li>\n\u003cli>\u003cstrong>Tiredness\u003c/strong> and reduced ability to do daily tasks\u003c/li>\n\u003cli>\u003cstrong>Chest pain or tightness\u003c/strong>, especially with aortic stenosis\u003c/li>\n\u003cli>\u003cstrong>Dizziness or fainting\u003c/strong>, particularly during activity\u003c/li>\n\u003cli>\u003cstrong>Palpitations\u003c/strong>, a fluttering or racing heartbeat\u003c/li>\n\u003cli>\u003cstrong>Swelling\u003c/strong> of the feet, ankles or abdomen\u003c/li>\n\u003cli>Waking up at night breathless\u003c/li>\n\u003c/ul>\n\u003cp>Symptoms may not match how severe the disease is. Some people with significant valve disease feel well, which is why regular scans matter.\u003c/p>\n\u003ch2 id=\"the-heart-murmur\">The heart murmur\u003c/h2>\u003cp>Often the first clue is a \u003cstrong>murmur\u003c/strong>, an extra sound your doctor hears with a stethoscope. Not every murmur means disease, but a new murmur should be checked with an echocardiogram.\u003c/p>\n\u003ch2 id=\"causes-and-risk-factors\">Causes and risk factors\u003c/h2>\u003cul>\n\u003cli>Age-related calcium build-up on the aortic valve\u003c/li>\n\u003cli>\u003cstrong>Rheumatic fever\u003c/strong> in childhood, after untreated throat infections\u003c/li>\n\u003cli>Infection of the heart valves (endocarditis)\u003c/li>\n\u003cli>Valve problems present from birth, such as a bicuspid aortic valve\u003c/li>\n\u003cli>Previous heart attack or heart enlargement\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-is-it-diagnosed\">How is it diagnosed?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Echocardiogram:\u003c/strong> the key test, showing valve structure and how well blood flows\u003c/li>\n\u003cli>\u003cstrong>ECG and chest X-ray:\u003c/strong> check rhythm and heart size\u003c/li>\n\u003cli>\u003cstrong>Transoesophageal echo:\u003c/strong> a closer look through a probe in the food pipe\u003c/li>\n\u003cli>\u003cstrong>Stress test or cardiac CT/MRI:\u003c/strong> in selected cases\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-should-be-checked\">Who should be checked?\u003c/h2>\u003cul>\n\u003cli>Anyone with unexplained breathlessness or fainting\u003c/li>\n\u003cli>People with a known murmur\u003c/li>\n\u003cli>Adults with a history of rheumatic fever\u003c/li>\n\u003cli>Pregnant women with known valve problems, before or early in pregnancy\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a cardiologist promptly if breathlessness, chest pain or fainting is new or getting worse. Fainting during exertion is a warning sign that needs urgent assessment.\u003c/p>\n","faqs":[{"q":"Is every heart murmur dangerous?","a":"No. Some murmurs are harmless. An echocardiogram tells the difference."},{"q":"Can valve disease cause heart failure?","a":"Yes. Untreated severe valve disease can weaken the heart over time."},{"q":"How often should valve disease be monitored?","a":"Depending on severity, from every few years to every 6 to 12 months."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"common-symptoms","text":"Common symptoms"},{"id":"the-heart-murmur","text":"The heart murmur"},{"id":"causes-and-risk-factors","text":"Causes and risk factors"},{"id":"how-is-it-diagnosed","text":"How is it diagnosed?"},{"id":"who-should-be-checked","text":"Who should be checked?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":399,"read":2},{"slug":"heart-failure-explained","sp":"cardiology","title":"Heart Failure: Symptoms, Diagnosis and Treatment","seo":"Heart Failure: Symptoms, Causes, Diagnosis & Treatment Options","desc":"Heart failure does not mean the heart has stopped. Learn the symptoms, causes, tests and treatments that help people live longer and better.","kw":["heart failure","congestive heart failure symptoms","weak heart","low ejection fraction","heart failure treatment"],"links":["pacemaker-explained","aicd-implantation","when-valve-replacement-is-needed"],"video":null,"flow":{"caption":"Daily heart failure self-care","steps":[{"t":"Weigh yourself","d":"Same time every morning"},{"t":"Check swelling","d":"Feet, ankles and abdomen"},{"t":"Take medicines","d":"Exactly as prescribed"},{"t":"Limit salt and fluid","d":"As advised by your doctor"}]},"img":["Healthy heart vs enlarged, weakened heart","Fluid build-up in the lungs and legs","Daily weight log chart"],"html":"\u003cp>Heart failure means the heart is not pumping blood as well as the body needs. It does \u003cstrong>not\u003c/strong> mean the heart has stopped. With the right treatment, many people with heart failure live active lives for many years.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Heart failure happens when the heart muscle becomes weak or stiff. Blood and fluid then back up into the lungs and body, causing breathlessness and swelling.\u003c/p>\n\u003cp>Doctors often describe it by the \u003cstrong>ejection fraction (EF)\u003c/strong>, the percentage of blood pumped out with each beat. A normal EF is roughly 55 to 70 percent.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Daily heart failure self-care\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Daily heart failure self-care\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Weigh yourself\u003c/b>\u003cspan>Same time every morning\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Check swelling\u003c/b>\u003cspan>Feet, ankles and abdomen\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Take medicines\u003c/b>\u003cspan>Exactly as prescribed\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Limit salt and fluid\u003c/b>\u003cspan>As advised by your doctor\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cul>\n\u003cli>Breathlessness on activity, when lying flat or waking at night\u003c/li>\n\u003cli>Swelling in the feet, ankles, legs or abdomen\u003c/li>\n\u003cli>Rapid weight gain over a few days (fluid build-up)\u003c/li>\n\u003cli>Tiredness and weakness\u003c/li>\n\u003cli>Persistent cough or wheezing\u003c/li>\n\u003cli>Reduced appetite\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"common-causes\">Common causes\u003c/h2>\u003cul>\n\u003cli>Previous heart attack and coronary artery disease\u003c/li>\n\u003cli>Long-standing high blood pressure\u003c/li>\n\u003cli>Heart valve disease\u003c/li>\n\u003cli>Cardiomyopathy (disease of the heart muscle)\u003c/li>\n\u003cli>Irregular heart rhythms\u003c/li>\n\u003cli>Diabetes, alcohol misuse and some cancer treatments\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Echocardiogram:\u003c/strong> measures EF and checks valves\u003c/li>\n\u003cli>\u003cstrong>Blood tests:\u003c/strong> including NT-proBNP, a marker of heart strain\u003c/li>\n\u003cli>\u003cstrong>ECG and chest X-ray\u003c/strong>\u003c/li>\n\u003cli>Further tests to find the cause, such as an angiogram or cardiac MRI\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Medicines:\u003c/strong> several drug groups work together to reduce symptoms, protect the heart and help people live longer. Diuretics (&quot;water tablets&quot;) remove extra fluid.\u003c/li>\n\u003cli>\u003cstrong>Treating the cause:\u003c/strong> opening blocked arteries or fixing a faulty valve\u003c/li>\n\u003cli>\u003cstrong>Devices:\u003c/strong> CRT pacemakers to coordinate heart pumping, AICDs to prevent sudden death\u003c/li>\n\u003cli>\u003cstrong>Advanced therapies:\u003c/strong> LVAD (mechanical heart pump) or heart transplant for selected severe cases\u003c/li>\n\u003cli>\u003cstrong>Cardiac rehabilitation:\u003c/strong> supervised exercise and education\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"living-with-heart-failure\">Living with heart failure\u003c/h2>\u003cp>Self-care makes a real difference. Weigh yourself daily, take medicines regularly, limit salt and keep follow-up appointments.\u003c/p>\n\u003ch2 id=\"when-should-you-seek-help\">When should you seek help?\u003c/h2>\u003cp>Contact your heart team if your weight rises by 2 kg in 2 to 3 days, swelling increases or breathlessness worsens. Severe breathlessness at rest or chest pain needs emergency care.\u003c/p>\n","faqs":[{"q":"Is heart failure curable?","a":"It depends on the cause. Some forms improve greatly with treatment; others are long-term conditions that can be well controlled."},{"q":"Should I drink less water?","a":"Some patients are advised to limit fluids. Follow your doctor's specific advice."},{"q":"Can I exercise?","a":"Yes, usually. Supervised cardiac rehabilitation is safe and improves strength and wellbeing."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"symptoms","text":"Symptoms"},{"id":"common-causes","text":"Common causes"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"living-with-heart-failure","text":"Living with heart failure"},{"id":"when-should-you-seek-help","text":"When should you seek help?"}],"words":384,"read":2},{"slug":"life-after-heart-surgery","sp":"cardiology","title":"Life After Heart Surgery: Recovery and Precautions","seo":"Recovery After Heart Surgery: Timeline, Precautions & Tips","desc":"A practical guide to recovering after heart surgery: the first weeks at home, wound and breastbone care, activity, diet, warning signs and cardiac rehab.","kw":["recovery after heart surgery","after bypass surgery care","sternal precautions","cardiac rehabilitation","heart surgery recovery time"],"links":["cabg-heart-bypass-surgery","when-valve-replacement-is-needed","heart-failure-explained"],"video":null,"flow":{"caption":"Typical recovery timeline","steps":[{"t":"Days 1 to 7","d":"ICU, then ward; walking starts"},{"t":"Weeks 1 to 6","d":"Home recovery; short daily walks"},{"t":"Weeks 6 to 12","d":"Breastbone heals; cardiac rehab"},{"t":"After 3 months","d":"Most people resume full routine"}]},"img":["Sternal precautions: how to get out of bed without pushing on arms","Walking progression chart","Heart-healthy Indian plate"],"html":"\u003cp>Recovering from heart surgery is a gradual process. Most people feel stronger week by week, but the first two to three months need care and patience. This guide covers what to expect after open-heart surgery such as bypass or valve surgery.\u003c/p>\n\u003ch2 id=\"the-first-weeks-at-home\">The first weeks at home\u003c/h2>\u003cp>It is normal to feel:\u003c/p>\n\u003cul>\n\u003cli>Tired and low on energy\u003c/li>\n\u003cli>Some chest wall discomfort or soreness around the wound\u003c/li>\n\u003cli>Poor appetite and disturbed sleep\u003c/li>\n\u003cli>Mood changes, including feeling low or anxious\u003c/li>\n\u003c/ul>\n\u003cp>These usually improve over 4 to 6 weeks. Tell your doctor if low mood persists.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Typical recovery timeline\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Typical recovery timeline\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Days 1 to 7\u003c/b>\u003cspan>ICU, then ward; walking starts\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Weeks 1 to 6\u003c/b>\u003cspan>Home recovery; short daily walks\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Weeks 6 to 12\u003c/b>\u003cspan>Breastbone heals; cardiac rehab\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>After 3 months\u003c/b>\u003cspan>Most people resume full routine\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"protecting-your-breastbone\">Protecting your breastbone\u003c/h2>\u003cp>Your breastbone needs about 6 to 8 weeks to heal. Until your surgeon says otherwise:\u003c/p>\n\u003cul>\n\u003cli>Do not lift more than about 2 to 3 kg\u003c/li>\n\u003cli>Avoid pushing or pulling with your arms, such as pushing yourself up from a chair\u003c/li>\n\u003cli>Hug a pillow against your chest when you cough or sneeze\u003c/li>\n\u003cli>Do not drive for the period your surgeon advises\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"wound-care\">Wound care\u003c/h2>\u003cul>\n\u003cli>Keep the wound clean and dry; shower as advised\u003c/li>\n\u003cli>Do not apply creams or powders unless prescribed\u003c/li>\n\u003cli>Check daily for redness, swelling, discharge or the wound opening\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"activity\">Activity\u003c/h2>\u003cul>\n\u003cli>Walk every day, starting with 5 to 10 minutes and building up gradually\u003c/li>\n\u003cli>Rest between activities\u003c/li>\n\u003cli>Climb stairs slowly\u003c/li>\n\u003cli>Join a \u003cstrong>cardiac rehabilitation programme\u003c/strong>, which offers supervised exercise and guidance\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"food-and-medicines\">Food and medicines\u003c/h2>\u003cul>\n\u003cli>Choose a heart-healthy diet: vegetables, fruit, whole grains, pulses, fish and less salt, fried food and sweets\u003c/li>\n\u003cli>Take every medicine exactly as prescribed, especially blood thinners and cholesterol medicines\u003c/li>\n\u003cli>Keep blood sugar and blood pressure under control\u003c/li>\n\u003cli>Stop all tobacco, permanently\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-normal-life\">Returning to normal life\u003c/h2>\u003cul>\n\u003cli>Desk work: often after 6 to 8 weeks\u003c/li>\n\u003cli>Physical work: usually later, as advised\u003c/li>\n\u003cli>Sexual activity: usually when you can climb two flights of stairs comfortably, typically after a few weeks\u003c/li>\n\u003cli>Air travel: discuss timing with your surgeon\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"warning-signs-contact-your-team-urgently\">Warning signs: contact your team urgently\u003c/h2>\u003cul>\n\u003cli>Fever, chills or wound discharge\u003c/li>\n\u003cli>Chest pain different from wound soreness\u003c/li>\n\u003cli>Increasing breathlessness or swelling of the legs\u003c/li>\n\u003cli>Rapid or irregular heartbeat\u003c/li>\n\u003cli>Fainting\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"How long does full recovery take?","a":"Most people feel close to normal by about 3 months, though tiredness can last longer."},{"q":"Why do I feel emotional after surgery?","a":"Mood changes are common after major surgery. They usually ease, but tell your doctor if they persist."},{"q":"Is cardiac rehab really necessary?","a":"Yes. It improves recovery, confidence and long-term heart health."}],"toc":[{"id":"the-first-weeks-at-home","text":"The first weeks at home"},{"id":"protecting-your-breastbone","text":"Protecting your breastbone"},{"id":"wound-care","text":"Wound care"},{"id":"activity","text":"Activity"},{"id":"food-and-medicines","text":"Food and medicines"},{"id":"returning-to-normal-life","text":"Returning to normal life"},{"id":"warning-signs-contact-your-team-urgently","text":"Warning signs: contact your team urgently"}],"words":393,"read":2},{"slug":"how-cancer-develops","sp":"oncology","title":"Understanding Cancer: How Does It Develop?","seo":"How Does Cancer Develop? A Simple Guide to Cancer Cells","desc":"A simple explanation of how normal cells turn into cancer, how tumours grow and spread, and which risk factors you can and cannot control.","kw":["what is cancer","how cancer develops","cancer cells","tumour growth","cancer risk factors"],"links":["early-warning-signs-of-cancer","cancer-stages-explained","chemotherapy-what-to-expect"],"video":null,"flow":{"caption":"From normal cell to cancer","steps":[{"t":"Normal cell","d":"Grows and divides in a controlled way"},{"t":"DNA damage","d":"Changes in genes that control growth"},{"t":"Uncontrolled growth","d":"Damaged cells keep dividing"},{"t":"Tumour and spread","d":"Cells may invade nearby tissue and travel elsewhere"}]},"img":["Normal cells dividing in order vs cancer cells growing chaotically","Benign vs malignant tumour diagram","Risk factor icons: tobacco, alcohol, obesity, infections, sun"],"html":"\u003cp>Cancer is not one disease but a group of more than 100 diseases. What they share is that some of the body&#39;s cells start growing out of control. Understanding how this happens can make a diagnosis less frightening and treatment easier to follow.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Your body is made of trillions of cells. Normally they grow, divide and die in an orderly way, guided by instructions in their \u003cstrong>genes\u003c/strong>. Cancer begins when changes (mutations) in these genes cause cells to:\u003c/p>\n\u003cul>\n\u003cli>Keep dividing when they should stop\u003c/li>\n\u003cli>Ignore signals to die\u003c/li>\n\u003cli>Avoid detection by the immune system\u003c/li>\n\u003c/ul>\n\u003cp>Over time, these abnormal cells can form a lump called a \u003cstrong>tumour\u003c/strong>.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"From normal cell to cancer\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>From normal cell to cancer\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Normal cell\u003c/b>\u003cspan>Grows and divides in a controlled way\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>DNA damage\u003c/b>\u003cspan>Changes in genes that control growth\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Uncontrolled growth\u003c/b>\u003cspan>Damaged cells keep dividing\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Tumour and spread\u003c/b>\u003cspan>Cells may invade nearby tissue and travel elsewhere\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"benign-vs-malignant\">Benign vs malignant\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Benign tumours\u003c/strong> grow but do not invade nearby tissue or spread. They are not cancer, though some still need treatment.\u003c/li>\n\u003cli>\u003cstrong>Malignant tumours\u003c/strong> are cancerous. They can invade surrounding tissue and spread through the blood or lymph system to other parts of the body. This spread is called \u003cstrong>metastasis\u003c/strong>.\u003c/li>\n\u003c/ul>\n\u003cp>Blood cancers such as leukaemia usually do not form solid lumps. Instead, abnormal cells build up in the blood and bone marrow.\u003c/p>\n\u003ch2 id=\"why-do-gene-changes-happen\">Why do gene changes happen?\u003c/h2>\u003cp>Most cancers develop from a combination of factors over many years:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Ageing:\u003c/strong> cells accumulate changes with time\u003c/li>\n\u003cli>\u003cstrong>Tobacco:\u003c/strong> smoking and chewing tobacco cause many cancers of the mouth, throat, lung and more\u003c/li>\n\u003cli>\u003cstrong>Alcohol\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Infections:\u003c/strong> such as HPV (cervical cancer), hepatitis B and C (liver cancer) and H. pylori (stomach cancer)\u003c/li>\n\u003cli>\u003cstrong>Obesity and inactivity\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Radiation and certain chemicals\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Inherited gene changes:\u003c/strong> for example BRCA genes, which raise breast and ovarian cancer risk\u003c/li>\n\u003c/ul>\n\u003cp>Only about 5 to 10 percent of cancers are strongly inherited.\u003c/p>\n\u003ch2 id=\"can-cancer-be-prevented\">Can cancer be prevented?\u003c/h2>\u003cp>Not all cancers can be prevented, but you can lower your risk by:\u003c/p>\n\u003cul>\n\u003cli>Avoiding all tobacco and limiting alcohol\u003c/li>\n\u003cli>Staying active and keeping a healthy weight\u003c/li>\n\u003cli>Getting vaccinated against HPV and hepatitis B\u003c/li>\n\u003cli>Attending recommended screening tests\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Consult a doctor about unexplained symptoms that last more than a few weeks, or if several close relatives have had cancer, especially at a young age.\u003c/p>\n","faqs":[{"q":"Is cancer contagious?","a":"No. Cancer cannot spread from person to person, though some infections that raise cancer risk can."},{"q":"If my parent had cancer, will I get it?","a":"Not necessarily. Most cancers are not inherited, but a strong family history may justify genetic counselling."},{"q":"Does a lump always mean cancer?","a":"No. Most lumps are benign, but any new or growing lump should be checked."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"benign-vs-malignant","text":"Benign vs malignant"},{"id":"why-do-gene-changes-happen","text":"Why do gene changes happen?"},{"id":"can-cancer-be-prevented","text":"Can cancer be prevented?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":409,"read":2},{"slug":"early-warning-signs-of-cancer","sp":"oncology","title":"Early Warning Signs of Cancer","seo":"Early Warning Signs of Cancer You Should Not Ignore","desc":"Know the early symptoms that can point to cancer, from unexplained weight loss to a lump or a sore that won't heal, and when to see a doctor.","kw":["early signs of cancer","cancer symptoms","cancer warning signs","unexplained weight loss","cancer screening"],"links":["how-cancer-develops","cancer-stages-explained","leukaemia-explained"],"video":null,"flow":null,"img":["Body map showing common warning signs by area","Self-examination guide for breast and testicular lumps","Screening tests timeline by age"],"html":"\u003cp>Cancer is most treatable when it is found early. Many early symptoms are caused by less serious conditions, but symptoms that are new, unexplained and lasting should always be checked.\u003c/p>\n\u003ch2 id=\"general-warning-signs\">General warning signs\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Unexplained weight loss\u003c/strong> of 5 kg or more without trying\u003c/li>\n\u003cli>\u003cstrong>Persistent tiredness\u003c/strong> that rest does not relieve\u003c/li>\n\u003cli>\u003cstrong>Fever or night sweats\u003c/strong> without an obvious infection\u003c/li>\n\u003cli>\u003cstrong>Pain\u003c/strong> that is new, persistent and unexplained\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"signs-linked-to-specific-areas\">Signs linked to specific areas\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>A lump or swelling\u003c/strong> in the breast, neck, armpit, groin or testicle\u003c/li>\n\u003cli>\u003cstrong>A sore that does not heal\u003c/strong>, especially in the mouth, or white or red patches inside the mouth\u003c/li>\n\u003cli>\u003cstrong>A change in bowel habits\u003c/strong> lasting more than a few weeks, or blood in the stool\u003c/li>\n\u003cli>\u003cstrong>Blood in urine\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Unusual bleeding\u003c/strong>, such as bleeding after menopause or between periods\u003c/li>\n\u003cli>\u003cstrong>A persistent cough or hoarse voice\u003c/strong> lasting more than three weeks, or coughing up blood\u003c/li>\n\u003cli>\u003cstrong>Difficulty swallowing\u003c/strong> or persistent indigestion\u003c/li>\n\u003cli>\u003cstrong>A mole that changes\u003c/strong> in size, shape or colour\u003c/li>\n\u003cli>\u003cstrong>Frequent infections, easy bruising or bleeding gums\u003c/strong>, which can point to blood cancers\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-three-week-rule\">The three-week rule\u003c/h2>\u003cp>A useful guide: if a symptom is new, unexplained and has lasted \u003cstrong>three weeks or more\u003c/strong>, see a doctor. Do not wait for it to become painful. Many cancers cause no pain in early stages.\u003c/p>\n\u003ch2 id=\"screening-finding-cancer-before-symptoms\">Screening: finding cancer before symptoms\u003c/h2>\u003cp>Screening tests can detect some cancers before any symptoms appear:\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Cancer\u003c/th>\n\u003cth>Common screening test\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Breast\u003c/td>\n\u003ctd>Mammogram\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Cervical\u003c/td>\n\u003ctd>Pap smear or HPV test\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Colorectal\u003c/td>\n\u003ctd>Stool test or colonoscopy\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Oral\u003c/td>\n\u003ctd>Visual mouth examination, especially for tobacco users\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Lung\u003c/td>\n\u003ctd>Low-dose CT for selected heavy smokers\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>Your doctor will advise which tests suit your age, sex and risk.\u003c/p>\n\u003ch2 id=\"who-is-at-higher-risk\">Who is at higher risk?\u003c/h2>\u003cul>\n\u003cli>Tobacco and heavy alcohol users\u003c/li>\n\u003cli>People over 50\u003c/li>\n\u003cli>Those with a strong family history of cancer\u003c/li>\n\u003cli>People with long-term infections such as hepatitis B or C\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See your doctor promptly for any of the signs above. If tests suggest cancer, an oncologist will plan further evaluation.\u003c/p>\n","faqs":[{"q":"Does having a symptom mean I have cancer?","a":"Usually not. Most of these symptoms have other causes, but checking early is always worthwhile."},{"q":"Is cancer always painful?","a":"No. Early cancer is often painless, which is why painless lumps should still be checked."},{"q":"At what age should screening start?","a":"It depends on the cancer and your risk. Ask your doctor for a personalised plan."}],"toc":[{"id":"general-warning-signs","text":"General warning signs"},{"id":"signs-linked-to-specific-areas","text":"Signs linked to specific areas"},{"id":"the-three-week-rule","text":"The three-week rule"},{"id":"screening-finding-cancer-before-symptoms","text":"Screening: finding cancer before symptoms"},{"id":"who-is-at-higher-risk","text":"Who is at higher risk?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":395,"read":2},{"slug":"cancer-stages-explained","sp":"oncology","title":"Understanding the Different Stages of Cancer","seo":"Cancer Stages Explained: Stage 0 to Stage 4 and TNM System","desc":"What do cancer stages mean? A plain-language guide to stage 0 to 4, the TNM system, cancer grade, and why staging guides treatment decisions.","kw":["cancer stages","stage 4 cancer","TNM staging","cancer grade","metastatic cancer"],"links":["how-cancer-develops","chemotherapy-what-to-expect","radiation-therapy-explained"],"video":null,"flow":{"caption":"How cancer is staged","steps":[{"t":"T: Tumour","d":"Size and how far it has grown locally"},{"t":"N: Nodes","d":"Whether lymph nodes are involved"},{"t":"M: Metastasis","d":"Whether it has spread to distant organs"},{"t":"Overall stage","d":"Combined into stage 0 to IV"}]},"img":["Stages 0 to IV shown as a tumour growing and spreading","TNM explained with a simple diagram","PET-CT scan showing spread"],"html":"\u003cp>After a cancer diagnosis, one of the first things your doctor works out is the \u003cstrong>stage\u003c/strong>. Staging describes how large the cancer is and whether it has spread. It helps doctors choose the best treatment and estimate the outlook.\u003c/p>\n\u003ch2 id=\"why-staging-matters\">Why staging matters\u003c/h2>\u003cul>\n\u003cli>It guides the treatment plan\u003c/li>\n\u003cli>It helps predict the likely outcome\u003c/li>\n\u003cli>It allows doctors worldwide to compare results and use the same treatment guidelines\u003c/li>\n\u003cli>It decides eligibility for some clinical trials\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"How cancer is staged\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How cancer is staged\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>T: Tumour\u003c/b>\u003cspan>Size and how far it has grown locally\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>N: Nodes\u003c/b>\u003cspan>Whether lymph nodes are involved\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>M: Metastasis\u003c/b>\u003cspan>Whether it has spread to distant organs\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Overall stage\u003c/b>\u003cspan>Combined into stage 0 to IV\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"the-tnm-system\">The TNM system\u003c/h2>\u003cp>Most solid cancers are staged using the TNM system:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>T (Tumour):\u003c/strong> the size of the main tumour and how far it has grown into nearby tissue\u003c/li>\n\u003cli>\u003cstrong>N (Nodes):\u003c/strong> whether cancer has reached nearby lymph nodes\u003c/li>\n\u003cli>\u003cstrong>M (Metastasis):\u003c/strong> whether cancer has spread to distant organs, such as the liver, lungs, bones or brain\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"stages-0-to-iv\">Stages 0 to IV\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Stage\u003c/th>\n\u003cth>What it generally means\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Stage 0\u003c/td>\n\u003ctd>Abnormal cells present but not invading (carcinoma in situ)\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stage I\u003c/td>\n\u003ctd>Small cancer, limited to where it started\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stage II\u003c/td>\n\u003ctd>Larger, or with limited spread nearby\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stage III\u003c/td>\n\u003ctd>Spread to nearby tissue or lymph nodes\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stage IV\u003c/td>\n\u003ctd>Spread to distant organs (metastatic cancer)\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>Each cancer type has its own detailed staging rules, so &quot;stage II breast cancer&quot; and &quot;stage II lung cancer&quot; mean different things.\u003c/p>\n\u003ch2 id=\"stage-is-not-the-same-as-grade\">Stage is not the same as grade\u003c/h2>\u003cp>\u003cstrong>Grade\u003c/strong> describes how abnormal the cancer cells look under a microscope. High-grade cancers tend to grow faster. Both stage and grade, along with \u003cstrong>biomarkers\u003c/strong> (special markers on the cancer cells), shape treatment.\u003c/p>\n\u003ch2 id=\"how-is-staging-done\">How is staging done?\u003c/h2>\u003cul>\n\u003cli>Physical examination\u003c/li>\n\u003cli>Imaging: CT, MRI, PET-CT, ultrasound or bone scan\u003c/li>\n\u003cli>Biopsy: a sample of tissue examined in the lab\u003c/li>\n\u003cli>Sometimes surgery, where removed lymph nodes are tested\u003c/li>\n\u003c/ul>\n\u003cp>Blood cancers such as leukaemia and lymphoma use different staging systems.\u003c/p>\n\u003ch2 id=\"does-stage-iv-mean-nothing-can-be-done\">Does stage IV mean nothing can be done?\u003c/h2>\u003cp>No. Many stage IV cancers can be controlled for long periods with modern treatments such as targeted therapy and immunotherapy. Treatment can also relieve symptoms and improve quality of life.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask your oncologist to explain your stage, grade and biomarkers, and what they mean for your treatment.\u003c/p>\n","faqs":[{"q":"Can the stage change over time?","a":"The original stage stays the same for records, but doctors describe any later growth or spread separately."},{"q":"Is a higher stage always worse?","a":"Generally yes, but outlook also depends on cancer type, biomarkers and response to treatment."},{"q":"Why do I need a PET-CT?","a":"It helps detect spread throughout the body and supports accurate staging for many cancers."}],"toc":[{"id":"why-staging-matters","text":"Why staging matters"},{"id":"the-tnm-system","text":"The TNM system"},{"id":"stages-0-to-iv","text":"Stages 0 to IV"},{"id":"stage-is-not-the-same-as-grade","text":"Stage is not the same as grade"},{"id":"how-is-staging-done","text":"How is staging done?"},{"id":"does-stage-iv-mean-nothing-can-be-done","text":"Does stage IV mean nothing can be done?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":413,"read":2},{"slug":"chemotherapy-what-to-expect","sp":"oncology","title":"Chemotherapy: What Should Patients Expect?","seo":"Chemotherapy Explained: How It Works, Side Effects & What to Expect","desc":"Understand how chemotherapy works, how it is given in cycles, common side effects and how to manage them, and simple tips for the treatment day.","kw":["chemotherapy","chemo side effects","chemotherapy cycles","chemo port","what to expect during chemo"],"links":["radiation-therapy-explained","immunotherapy-explained","cancer-stages-explained"],"video":"v-chemo-radiation","flow":{"caption":"A typical chemotherapy cycle","steps":[{"t":"Check-up","d":"Blood tests and doctor review"},{"t":"Treatment day","d":"Drugs given by drip or tablets"},{"t":"Rest period","d":"Body recovers for 1 to 3 weeks"},{"t":"Next cycle","d":"Repeated as planned"}]},"img":["Chemotherapy drugs attacking fast-dividing cells","Patient in a day-care chemo chair with IV line","Chemo port placement under the skin"],"html":"\u003cp>Chemotherapy, often called chemo, uses medicines to destroy cancer cells or stop them from growing. For many patients it is a key part of treatment. Knowing what to expect can make it feel much more manageable.\u003c/p>\n\u003ch2 id=\"how-does-it-work\">How does it work?\u003c/h2>\u003cp>Chemotherapy drugs target cells that divide quickly, which is a feature of cancer cells. Because some healthy cells also divide quickly, such as those in hair roots, the mouth lining and bone marrow, chemo can cause side effects.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"A typical chemotherapy cycle\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>A typical chemotherapy cycle\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Check-up\u003c/b>\u003cspan>Blood tests and doctor review\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Treatment day\u003c/b>\u003cspan>Drugs given by drip or tablets\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Rest period\u003c/b>\u003cspan>Body recovers for 1 to 3 weeks\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Next cycle\u003c/b>\u003cspan>Repeated as planned\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"why-is-chemo-given\">Why is chemo given?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>To cure\u003c/strong> the cancer, alone or with other treatments\u003c/li>\n\u003cli>\u003cstrong>Before surgery\u003c/strong> (neoadjuvant) to shrink a tumour\u003c/li>\n\u003cli>\u003cstrong>After surgery\u003c/strong> (adjuvant) to destroy remaining cancer cells\u003c/li>\n\u003cli>\u003cstrong>To control\u003c/strong> advanced cancer and relieve symptoms\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-is-it-given\">How is it given?\u003c/h2>\u003cul>\n\u003cli>Through a drip into a vein (IV), usually in a day-care unit\u003c/li>\n\u003cli>As tablets taken at home\u003c/li>\n\u003cli>Through a \u003cstrong>port\u003c/strong> or PICC line, a small device that protects your veins during long treatment\u003c/li>\n\u003c/ul>\n\u003cp>Chemo is given in \u003cstrong>cycles\u003c/strong>: a treatment period followed by a rest period. A full course may last a few months.\u003c/p>\n\u003ch2 id=\"common-side-effects\">Common side effects\u003c/h2>\u003cp>Side effects vary by drug and person, and most are temporary:\u003c/p>\n\u003cul>\n\u003cli>Tiredness\u003c/li>\n\u003cli>Nausea and vomiting, now well controlled with modern medicines\u003c/li>\n\u003cli>Hair loss with some drugs; hair usually grows back\u003c/li>\n\u003cli>Mouth sores and taste changes\u003c/li>\n\u003cli>\u003cstrong>Low blood counts\u003c/strong>, raising the risk of infection, anaemia and bleeding\u003c/li>\n\u003cli>Numbness or tingling in hands and feet with certain drugs\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"tips-for-treatment-days\">Tips for treatment days\u003c/h2>\u003cul>\n\u003cli>Eat a light meal beforehand\u003c/li>\n\u003cli>Bring water, a snack and something to read\u003c/li>\n\u003cli>Wear comfortable clothes with easy arm access\u003c/li>\n\u003cli>Arrange for someone to take you home after early sessions\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"looking-after-yourself\">Looking after yourself\u003c/h2>\u003cul>\n\u003cli>Wash hands often and avoid crowds when counts are low\u003c/li>\n\u003cli>Eat small, frequent, protein-rich meals\u003c/li>\n\u003cli>Keep your mouth clean with a soft brush\u003c/li>\n\u003cli>Stay as active as you comfortably can\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-to-call-your-team-urgently\">When to call your team urgently\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Fever of 38°C (100.4°F) or above.\u003c/strong> This can be a medical emergency during chemo.\u003c/li>\n\u003cli>Chills, breathlessness or chest pain\u003c/li>\n\u003cli>Vomiting that stops you keeping fluids down\u003c/li>\n\u003cli>Unusual bleeding or bruising\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Will I definitely lose my hair?","a":"Not always. It depends on the drugs. Your team can tell you what to expect."},{"q":"Can I work during chemotherapy?","a":"Many people continue working with adjustments, depending on how they feel."},{"q":"Is chemo painful?","a":"The infusion itself is usually painless, apart from the needle or port access."}],"toc":[{"id":"how-does-it-work","text":"How does it work?"},{"id":"why-is-chemo-given","text":"Why is chemo given?"},{"id":"how-is-it-given","text":"How is it given?"},{"id":"common-side-effects","text":"Common side effects"},{"id":"tips-for-treatment-days","text":"Tips for treatment days"},{"id":"looking-after-yourself","text":"Looking after yourself"},{"id":"when-to-call-your-team-urgently","text":"When to call your team urgently"}],"words":390,"read":2},{"slug":"radiation-therapy-explained","sp":"oncology","title":"Radiation Therapy Explained","seo":"Radiation Therapy for Cancer: How It Works, Types & Side Effects","desc":"Learn how radiation therapy destroys cancer cells, the main types including IMRT and brachytherapy, what happens in planning and treatment, and side effects.","kw":["radiation therapy","radiotherapy","IMRT","brachytherapy","radiation side effects"],"links":["chemotherapy-what-to-expect","cyberknife-precision-radiation","cancer-stages-explained"],"video":"v-chemo-radiation","flow":{"caption":"Your radiation therapy journey","steps":[{"t":"Consultation","d":"Radiation oncologist plans the approach"},{"t":"Simulation","d":"CT scan in treatment position; marks made"},{"t":"Planning","d":"Team designs precise beams"},{"t":"Treatment","d":"Daily sessions of a few minutes"}]},"img":["Linear accelerator with patient on treatment couch","Radiation beams shaped around a tumour, sparing healthy organs","Immobilisation mask used for head and neck treatment"],"html":"\u003cp>Radiation therapy, or radiotherapy, uses carefully targeted high-energy rays to destroy cancer cells. About half of all cancer patients receive radiation at some point. It is painless while it is being given, much like having an X-ray.\u003c/p>\n\u003ch2 id=\"how-does-it-work\">How does it work?\u003c/h2>\u003cp>Radiation damages the DNA inside cancer cells so they can no longer grow and divide. Healthy cells are also affected but are better able to repair themselves. Modern machines shape the beam precisely to protect nearby organs.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Your radiation therapy journey\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Your radiation therapy journey\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Consultation\u003c/b>\u003cspan>Radiation oncologist plans the approach\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Simulation\u003c/b>\u003cspan>CT scan in treatment position; marks made\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Planning\u003c/b>\u003cspan>Team designs precise beams\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Treatment\u003c/b>\u003cspan>Daily sessions of a few minutes\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"why-is-it-used\">Why is it used?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>To cure\u003c/strong> cancer, alone or with surgery or chemotherapy\u003c/li>\n\u003cli>\u003cstrong>Before surgery\u003c/strong> to shrink a tumour\u003c/li>\n\u003cli>\u003cstrong>After surgery\u003c/strong> to destroy any remaining cancer cells\u003c/li>\n\u003cli>\u003cstrong>To relieve symptoms\u003c/strong> such as pain from cancer in the bones\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"main-types\">Main types\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>External beam radiation:\u003c/strong> delivered by a machine called a linear accelerator. Advanced techniques include \u003cstrong>IMRT\u003c/strong>, \u003cstrong>IGRT\u003c/strong> and \u003cstrong>VMAT\u003c/strong>, which shape and guide the beam very accurately.\u003c/li>\n\u003cli>\u003cstrong>Stereotactic radiation (SRS/SBRT):\u003c/strong> very high doses delivered in a few sessions to small targets. CyberKnife is one such system.\u003c/li>\n\u003cli>\u003cstrong>Brachytherapy:\u003c/strong> a radioactive source is placed inside or next to the tumour, commonly used for cervical and prostate cancer.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-happens-during-treatment\">What happens during treatment?\u003c/h2>\u003col>\n\u003cli>\u003cstrong>Planning scan (simulation):\u003c/strong> you lie in the treatment position while a CT scan is taken. Small skin marks or a mask may be used to keep you in exactly the same position each day.\u003c/li>\n\u003cli>\u003cstrong>Planning:\u003c/strong> physicists and doctors design the beams, which can take several days.\u003c/li>\n\u003cli>\u003cstrong>Treatment sessions:\u003c/strong> usually daily on weekdays for one to seven weeks. Each session takes 10 to 20 minutes, mostly for positioning.\u003c/li>\n\u003c/ol>\n\u003cp>You will not feel the radiation, and external beam treatment does not make you radioactive.\u003c/p>\n\u003ch2 id=\"side-effects\">Side effects\u003c/h2>\u003cp>Side effects mostly affect the area being treated and build up gradually:\u003c/p>\n\u003cul>\n\u003cli>Tiredness\u003c/li>\n\u003cli>Skin redness or dryness in the treated area\u003c/li>\n\u003cli>Mouth soreness and difficulty swallowing (head and neck)\u003c/li>\n\u003cli>Loose stools or bladder irritation (abdomen and pelvis)\u003c/li>\n\u003c/ul>\n\u003cp>Most settle within a few weeks after treatment ends.\u003c/p>\n\u003ch2 id=\"caring-for-your-skin\">Caring for your skin\u003c/h2>\u003cul>\n\u003cli>Wash gently with mild soap and lukewarm water\u003c/li>\n\u003cli>Avoid scrubbing, perfumes and tight clothing over the area\u003c/li>\n\u003cli>Use only creams recommended by your team\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A radiation oncologist will advise whether radiation is right for your cancer and which technique suits you best.\u003c/p>\n","faqs":[{"q":"Is radiation therapy painful?","a":"No. You will not feel the beam during treatment."},{"q":"Can I be around children after treatment?","a":"Yes, after external beam radiation. Some types of internal radiation need temporary precautions, which your team will explain."},{"q":"Will I lose my hair?","a":"Only if the head is being treated."}],"toc":[{"id":"how-does-it-work","text":"How does it work?"},{"id":"why-is-it-used","text":"Why is it used?"},{"id":"main-types","text":"Main types"},{"id":"what-happens-during-treatment","text":"What happens during treatment?"},{"id":"side-effects","text":"Side effects"},{"id":"caring-for-your-skin","text":"Caring for your skin"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":425,"read":2},{"slug":"immunotherapy-explained","sp":"oncology","title":"Immunotherapy: How Does It Help Fight Cancer?","seo":"Cancer Immunotherapy: How It Works, Who It Helps & Side Effects","desc":"Find out how immunotherapy helps your immune system recognise and attack cancer, which cancers it is used for, and what side effects to watch for.","kw":["immunotherapy","checkpoint inhibitors","cancer immunotherapy side effects","PD-L1","immune system and cancer"],"links":["car-t-cell-therapy-overview","chemotherapy-what-to-expect","cancer-stages-explained"],"video":null,"flow":{"caption":"How checkpoint inhibitors work","steps":[{"t":"Cancer hides","d":"Cancer cells use \"brakes\" to switch off immune cells"},{"t":"Drug given","d":"Checkpoint inhibitor blocks those brakes"},{"t":"Immune cells wake up","d":"T-cells recognise the cancer again"},{"t":"Attack","d":"Immune system destroys cancer cells"}]},"img":["T-cell and cancer cell with PD-1/PD-L1 \"brake\" connection","Checkpoint inhibitor releasing the brake","Infusion in day-care unit"],"html":"\u003cp>Your immune system protects you by finding and destroying harmful cells. Cancer cells, however, often find ways to hide from it. Immunotherapy is a group of treatments that help your own immune system recognise and attack cancer.\u003c/p>\n\u003ch2 id=\"how-does-it-work\">How does it work?\u003c/h2>\u003cp>Immune cells called \u003cstrong>T-cells\u003c/strong> have built-in &quot;brakes&quot;, known as checkpoints, that stop them from attacking healthy tissue. Some cancers press these brakes to switch T-cells off. \u003cstrong>Checkpoint inhibitors\u003c/strong>, the most widely used immunotherapy drugs, release the brakes so T-cells can attack the cancer again.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How checkpoint inhibitors work\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How checkpoint inhibitors work\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Cancer hides\u003c/b>\u003cspan>Cancer cells use &quot;brakes&quot; to switch off immune cells\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Drug given\u003c/b>\u003cspan>Checkpoint inhibitor blocks those brakes\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Immune cells wake up\u003c/b>\u003cspan>T-cells recognise the cancer again\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Attack\u003c/b>\u003cspan>Immune system destroys cancer cells\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"types-of-immunotherapy\">Types of immunotherapy\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Checkpoint inhibitors:\u003c/strong> given as an infusion every few weeks\u003c/li>\n\u003cli>\u003cstrong>CAR-T cell therapy:\u003c/strong> a patient&#39;s own T-cells are modified in a lab to target certain blood cancers\u003c/li>\n\u003cli>\u003cstrong>Cancer vaccines:\u003c/strong> such as BCG for early bladder cancer\u003c/li>\n\u003cli>\u003cstrong>Other immune-based treatments:\u003c/strong> including some monoclonal antibodies\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"which-cancers-is-it-used-for\">Which cancers is it used for?\u003c/h2>\u003cp>Immunotherapy has become part of standard treatment for several cancers, including some types of:\u003c/p>\n\u003cul>\n\u003cli>Melanoma\u003c/li>\n\u003cli>Lung cancer\u003c/li>\n\u003cli>Kidney and bladder cancer\u003c/li>\n\u003cli>Head and neck cancer\u003c/li>\n\u003cli>Some stomach, liver, cervical and colorectal cancers\u003c/li>\n\u003cli>Hodgkin lymphoma\u003c/li>\n\u003c/ul>\n\u003cp>It does not work for every patient or every cancer. Doctors may test the tumour for \u003cstrong>biomarkers\u003c/strong> such as PD-L1, MSI or tumour mutational burden to judge whether it is likely to help.\u003c/p>\n\u003ch2 id=\"how-is-it-different-from-chemotherapy\">How is it different from chemotherapy?\u003c/h2>\u003cp>Chemotherapy attacks dividing cells directly. Immunotherapy works through your immune system, so its effects can take longer to appear and may last longer in people who respond.\u003c/p>\n\u003ch2 id=\"side-effects\">Side effects\u003c/h2>\u003cp>Because immunotherapy activates the immune system, it can sometimes attack healthy organs. Possible side effects include:\u003c/p>\n\u003cul>\n\u003cli>Tiredness\u003c/li>\n\u003cli>Skin rash and itching\u003c/li>\n\u003cli>Diarrhoea (colitis)\u003c/li>\n\u003cli>Cough or breathlessness (lung inflammation)\u003c/li>\n\u003cli>Thyroid or other hormone problems\u003c/li>\n\u003cli>Liver inflammation\u003c/li>\n\u003c/ul>\n\u003cp>Most are mild and manageable, but some can be serious if not treated early. Side effects can appear even months after treatment.\u003c/p>\n\u003ch2 id=\"when-should-you-call-your-team\">When should you call your team?\u003c/h2>\u003cp>Report any new diarrhoea, breathlessness, cough, severe tiredness, rash or yellowing of the eyes promptly. Tell any doctor treating you that you have received immunotherapy.\u003c/p>\n","faqs":[{"q":"Does immunotherapy work for everyone?","a":"No. Responses vary widely. Your oncologist will explain your likely benefit."},{"q":"Is immunotherapy given alone?","a":"Sometimes. It is also often combined with chemotherapy or other treatments."},{"q":"How long is treatment?","a":"Often up to one or two years, depending on the cancer and response."}],"toc":[{"id":"how-does-it-work","text":"How does it work?"},{"id":"types-of-immunotherapy","text":"Types of immunotherapy"},{"id":"which-cancers-is-it-used-for","text":"Which cancers is it used for?"},{"id":"how-is-it-different-from-chemotherapy","text":"How is it different from chemotherapy?"},{"id":"side-effects","text":"Side effects"},{"id":"when-should-you-call-your-team","text":"When should you call your team?"}],"words":383,"read":2},{"slug":"cyberknife-precision-radiation","sp":"oncology","title":"CyberKnife: Understanding Precision Radiation Treatment","seo":"CyberKnife Radiosurgery: How It Works, Uses & What to Expect","desc":"CyberKnife is not a knife. Learn how this robotic system delivers precise, high-dose radiation in a few sessions, who it suits and what to expect.","kw":["CyberKnife","stereotactic radiosurgery","SBRT","robotic radiation therapy","non-invasive tumour treatment"],"links":["radiation-therapy-explained","brain-tumours-types-and-cancer-treatment","deep-brain-stimulation"],"video":null,"flow":{"caption":"CyberKnife treatment steps","steps":[{"t":"Imaging","d":"CT and MRI map the tumour"},{"t":"Planning","d":"Hundreds of beam angles calculated"},{"t":"Treatment","d":"Robot delivers beams; tracks movement"},{"t":"Follow-up","d":"Scans check response over months"}]},"img":["Robotic arm delivering radiation from many angles","Hundreds of narrow beams converging on a tumour","Patient lying comfortably with a mesh mask"],"html":"\u003cp>Despite its name, CyberKnife does not use a knife and involves no cuts. It is a \u003cstrong>robotic radiation system\u003c/strong> that delivers highly focused, high-dose radiation to tumours with great accuracy, usually in just one to five sessions.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>CyberKnife is a form of \u003cstrong>stereotactic radiation therapy\u003c/strong>:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>SRS (stereotactic radiosurgery)\u003c/strong> when used in the brain\u003c/li>\n\u003cli>\u003cstrong>SBRT (stereotactic body radiation therapy)\u003c/strong> when used elsewhere\u003c/li>\n\u003c/ul>\n\u003cp>A linear accelerator mounted on a robotic arm moves around you, sending many narrow beams from different angles. The beams meet at the tumour, delivering a strong dose there while sparing nearby healthy tissue.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"CyberKnife treatment steps\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>CyberKnife treatment steps\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Imaging\u003c/b>\u003cspan>CT and MRI map the tumour\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Planning\u003c/b>\u003cspan>Hundreds of beam angles calculated\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Treatment\u003c/b>\u003cspan>Robot delivers beams; tracks movement\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Follow-up\u003c/b>\u003cspan>Scans check response over months\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"what-makes-it-different\">What makes it different?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Real-time tracking:\u003c/strong> the system adjusts for small movements, including breathing\u003c/li>\n\u003cli>\u003cstrong>No rigid head frame\u003c/strong> for brain treatment; a soft mesh mask is used instead\u003c/li>\n\u003cli>\u003cstrong>Fewer sessions\u003c/strong> than conventional radiation\u003c/li>\n\u003cli>Usually done as an \u003cstrong>outpatient\u003c/strong>, with no anaesthesia\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-can-it-treat\">What can it treat?\u003c/h2>\u003cp>CyberKnife may be considered for selected:\u003c/p>\n\u003cul>\n\u003cli>Brain tumours and brain metastases\u003c/li>\n\u003cli>Spine and spinal cord tumours\u003c/li>\n\u003cli>Early-stage lung cancer, especially when surgery is unsuitable\u003c/li>\n\u003cli>Prostate cancer\u003c/li>\n\u003cli>Liver, pancreas and kidney tumours\u003c/li>\n\u003cli>Some benign conditions, such as acoustic neuroma and trigeminal neuralgia\u003c/li>\n\u003c/ul>\n\u003cp>It is generally suited to tumours that are \u003cstrong>small and well defined\u003c/strong>. It is not suitable for every cancer, and your team will compare it with surgery and other forms of radiation.\u003c/p>\n\u003ch2 id=\"what-should-you-expect\">What should you expect?\u003c/h2>\u003col>\n\u003cli>\u003cstrong>Imaging:\u003c/strong> CT and often MRI scans are used for planning. Small markers may be placed near some body tumours to help tracking.\u003c/li>\n\u003cli>\u003cstrong>Planning:\u003c/strong> the team calculates the beam pattern over a few days.\u003c/li>\n\u003cli>\u003cstrong>Treatment:\u003c/strong> you lie still on a couch while the robot moves around you. Each session typically lasts 30 to 90 minutes.\u003c/li>\n\u003cli>\u003cstrong>Going home:\u003c/strong> most people return home the same day.\u003c/li>\n\u003c/ol>\n\u003ch2 id=\"side-effects\">Side effects\u003c/h2>\u003cp>Side effects depend on the area treated and are often mild, such as tiredness, temporary swelling or local irritation. Your team will explain specific risks for your treatment site.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask your radiation oncologist whether stereotactic treatment is an option, particularly if surgery is risky or the tumour is in a hard-to-reach location.\u003c/p>\n","faqs":[{"q":"Is CyberKnife surgery?","a":"No. It is a type of radiation therapy. \"Radiosurgery\" refers to its precision, not an operation."},{"q":"Does it hurt?","a":"No. The treatment itself is painless."},{"q":"Will the tumour disappear immediately?","a":"No. Tumours respond over weeks to months, which is monitored with follow-up scans."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"what-makes-it-different","text":"What makes it different?"},{"id":"what-can-it-treat","text":"What can it treat?"},{"id":"what-should-you-expect","text":"What should you expect?"},{"id":"side-effects","text":"Side effects"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":402,"read":2},{"slug":"brain-tumours-types-and-cancer-treatment","sp":"oncology","title":"Understanding Brain Tumours and Their Treatment","seo":"Brain Tumour Types, Grades & Cancer Treatment Options","desc":"Learn the difference between primary and secondary brain tumours, how they are graded, and how surgery, radiation and chemotherapy work together.","kw":["brain tumour types","glioma","brain metastasis","brain tumour grade","brain cancer treatment"],"links":["brain-tumour-symptoms-and-surgery","cyberknife-precision-radiation","radiation-therapy-explained"],"video":null,"flow":null,"img":["Primary vs secondary brain tumour diagram","Multidisciplinary tumour board team","Glioma grades shown on MRI illustrations"],"html":"\u003cp>A brain tumour is a growth of abnormal cells in or around the brain. Some are benign and slow growing; others are cancerous. Treatment depends on the tumour type, its grade, its location and your overall health. This article focuses on types and how cancer treatments are combined.\u003c/p>\n\u003ch2 id=\"primary-and-secondary-tumours\">Primary and secondary tumours\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Primary brain tumours\u003c/strong> start in the brain or its coverings.\u003c/li>\n\u003cli>\u003cstrong>Secondary tumours (brain metastases)\u003c/strong> start elsewhere, such as the lung, breast or skin, and spread to the brain. In adults, these are more common than primary tumours.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"common-types\">Common types\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Type\u003c/th>\n\u003cth>What to know\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Meningioma\u003c/td>\n\u003ctd>Grows from the brain&#39;s covering; usually benign\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Glioma\u003c/td>\n\u003ctd>Grows from the brain&#39;s support cells; ranges from low to high grade\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Glioblastoma\u003c/td>\n\u003ctd>The most aggressive glioma\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Pituitary tumour\u003c/td>\n\u003ctd>Usually benign; may affect hormones and vision\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Acoustic neuroma\u003c/td>\n\u003ctd>Benign tumour on the hearing nerve\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Medulloblastoma\u003c/td>\n\u003ctd>A tumour seen more often in children\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"tumour-grade\">Tumour grade\u003c/h2>\u003cp>The World Health Organization grades brain tumours from \u003cstrong>1 to 4\u003c/strong>. Grade 1 and 2 tumours grow slowly; grade 3 and 4 tumours grow faster and are more likely to come back. \u003cstrong>Molecular tests\u003c/strong> on the tumour, such as IDH and MGMT status, now play a major role in diagnosis and treatment planning.\u003c/p>\n\u003ch2 id=\"how-treatment-is-planned\">How treatment is planned\u003c/h2>\u003cp>Brain tumour care works best with a \u003cstrong>multidisciplinary team\u003c/strong>: neurosurgeon, radiation oncologist, medical oncologist, neuroradiologist and pathologist.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Surgery:\u003c/strong> to remove as much tumour as safely possible and confirm the diagnosis\u003c/li>\n\u003cli>\u003cstrong>Radiation therapy:\u003c/strong> conventional radiation or precise stereotactic treatment such as CyberKnife or Gamma Knife, especially for small tumours and metastases\u003c/li>\n\u003cli>\u003cstrong>Chemotherapy:\u003c/strong> for example temozolomide tablets for some gliomas\u003c/li>\n\u003cli>\u003cstrong>Targeted therapy:\u003c/strong> for tumours with specific gene changes\u003c/li>\n\u003cli>\u003cstrong>Supportive medicines:\u003c/strong> steroids to reduce swelling and medicines to prevent seizures\u003c/li>\n\u003c/ul>\n\u003cp>Benign tumours that are small and not causing symptoms may simply be monitored with regular MRI scans.\u003c/p>\n\u003ch2 id=\"life-during-and-after-treatment\">Life during and after treatment\u003c/h2>\u003cp>Many patients benefit from rehabilitation, including physiotherapy, speech therapy and help with memory or concentration. Regular follow-up MRI scans check for any regrowth.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If an MRI shows a brain tumour, ask to be seen by a neuro-oncology team that can review the scans, biopsy results and molecular tests together.\u003c/p>\n","faqs":[{"q":"Are all brain tumours cancerous?","a":"No. Many, such as most meningiomas, are benign, though they may still need treatment."},{"q":"Can brain tumours be treated without surgery?","a":"Some can be treated with radiation alone or monitored. It depends on type, size and location."},{"q":"Why are molecular tests important?","a":"They help classify the tumour accurately and guide treatment choices."}],"toc":[{"id":"primary-and-secondary-tumours","text":"Primary and secondary tumours"},{"id":"common-types","text":"Common types"},{"id":"tumour-grade","text":"Tumour grade"},{"id":"how-treatment-is-planned","text":"How treatment is planned"},{"id":"treatment-options","text":"Treatment options"},{"id":"life-during-and-after-treatment","text":"Life during and after treatment"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":422,"read":2},{"slug":"leukaemia-explained","sp":"oncology","title":"Leukaemia: Symptoms, Diagnosis and Treatment","seo":"Leukaemia (Blood Cancer): Types, Symptoms, Diagnosis & Treatment","desc":"An easy guide to leukaemia: the four main types, early symptoms such as infections and bruising, how it is diagnosed and current treatment options.","kw":["leukaemia","leukemia symptoms","blood cancer","AML","ALL","CLL","CML"],"links":["car-t-cell-therapy-overview","what-is-bone-marrow-transplant","early-warning-signs-of-cancer"],"video":null,"flow":null,"img":["Bone marrow producing blood cells: normal vs leukaemia","The four main leukaemia types in a simple chart","Bone marrow biopsy from the hip bone"],"html":"\u003cp>Leukaemia is a cancer of the blood-forming cells in the bone marrow. Instead of making healthy blood cells, the marrow produces large numbers of abnormal white blood cells that crowd out normal ones.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Bone marrow is the soft tissue inside bones that makes red cells (carry oxygen), white cells (fight infection) and platelets (stop bleeding). In leukaemia, abnormal white cells multiply out of control and do not work properly.\u003c/p>\n\u003ch2 id=\"main-types\">Main types\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Type\u003c/th>\n\u003cth>Speed\u003c/th>\n\u003cth>Who it usually affects\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Acute lymphoblastic leukaemia (ALL)\u003c/td>\n\u003ctd>Fast\u003c/td>\n\u003ctd>Most common in children; also adults\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Acute myeloid leukaemia (AML)\u003c/td>\n\u003ctd>Fast\u003c/td>\n\u003ctd>Mostly adults\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Chronic lymphocytic leukaemia (CLL)\u003c/td>\n\u003ctd>Slow\u003c/td>\n\u003ctd>Older adults\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Chronic myeloid leukaemia (CML)\u003c/td>\n\u003ctd>Slow\u003c/td>\n\u003ctd>Adults\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>\u003cstrong>Acute\u003c/strong> leukaemias develop quickly and need urgent treatment. \u003cstrong>Chronic\u003c/strong> leukaemias develop slowly and sometimes need only monitoring at first.\u003c/p>\n\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cul>\n\u003cli>Frequent or repeated infections and fevers\u003c/li>\n\u003cli>Tiredness, weakness and paleness (anaemia)\u003c/li>\n\u003cli>Easy bruising, bleeding gums, nosebleeds or tiny red spots on the skin\u003c/li>\n\u003cli>Bone or joint pain\u003c/li>\n\u003cli>Swollen lymph nodes, or a swollen tummy from an enlarged spleen or liver\u003c/li>\n\u003cli>Unexplained weight loss and night sweats\u003c/li>\n\u003c/ul>\n\u003cp>Chronic leukaemia is sometimes found by chance on a routine blood test.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Complete blood count (CBC):\u003c/strong> often the first clue\u003c/li>\n\u003cli>\u003cstrong>Peripheral smear:\u003c/strong> blood cells examined under a microscope\u003c/li>\n\u003cli>\u003cstrong>Bone marrow biopsy:\u003c/strong> a sample taken from the hip bone under local anaesthesia\u003c/li>\n\u003cli>\u003cstrong>Flow cytometry, cytogenetics and molecular tests:\u003c/strong> identify the exact type and gene changes, which guide treatment\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Chemotherapy:\u003c/strong> the main treatment for acute leukaemias\u003c/li>\n\u003cli>\u003cstrong>Targeted therapy:\u003c/strong> for example tablets that transformed the treatment of CML\u003c/li>\n\u003cli>\u003cstrong>Immunotherapy:\u003c/strong> including antibody treatments and CAR-T cell therapy for some relapsed B-cell ALL\u003c/li>\n\u003cli>\u003cstrong>Bone marrow (stem cell) transplant:\u003c/strong> for higher-risk or relapsed cases\u003c/li>\n\u003cli>\u003cstrong>Supportive care:\u003c/strong> blood transfusions, antibiotics and infection prevention\u003c/li>\n\u003c/ul>\n\u003cp>Outcomes have improved greatly, especially for children with ALL and adults with CML.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a doctor if you have repeated infections, unexplained bruising or bleeding, or persistent fatigue. Abnormal blood counts should be reviewed by a haematologist.\u003c/p>\n","faqs":[{"q":"Is leukaemia curable?","a":"Many types can be cured or controlled long term, depending on the type, gene changes and response to treatment."},{"q":"Is a bone marrow biopsy painful?","a":"Local anaesthesia is used. Most people feel pressure and brief discomfort."},{"q":"Do all patients need a transplant?","a":"No. Transplant is recommended only for selected patients."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"main-types","text":"Main types"},{"id":"symptoms","text":"Symptoms"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":386,"read":2},{"slug":"car-t-cell-therapy-overview","sp":"oncology","title":"CAR-T Cell Therapy: A New Approach to Treating Certain Blood Cancers","seo":"CAR-T Cell Therapy: Uses, Approved Cancers & Availability in India","desc":"An overview of CAR-T cell therapy: what it is, which blood cancers it is approved for, its availability in India and why it is not for every patient.","kw":["CAR-T cell therapy","CAR-T India","NexCAR19","Qartemi","CAR-T for lymphoma","CAR-T for leukaemia"],"links":["how-car-t-therapy-works","car-t-eligibility","bone-marrow-transplant-vs-car-t"],"video":"v-cart","flow":null,"img":["Patient's own T-cells being \"re-armed\" to target cancer","Timeline of CAR-T approvals: USA 2017, India 2023 and 2025","Cell-therapy centre with apheresis and ICU"],"html":"\u003cp>CAR-T cell therapy is a personalised treatment that uses a patient&#39;s own immune cells, modified in a laboratory, to find and destroy certain blood cancers. It has given new options to some patients whose cancer returned or did not respond to standard treatment.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>CAR stands for \u003cstrong>chimeric antigen receptor\u003c/strong>. T-cells, a type of white blood cell, are collected from the patient and given a new receptor that helps them recognise a specific marker on cancer cells. These &quot;re-armed&quot; cells are then returned to the patient as a single infusion.\u003c/p>\n\u003cp>Because it uses living cells, CAR-T is sometimes called a &quot;living drug&quot;.\u003c/p>\n\u003ch2 id=\"which-cancers-is-it-approved-for\">Which cancers is it approved for?\u003c/h2>\u003cp>CAR-T is currently approved \u003cstrong>only for certain blood cancers\u003c/strong>, mostly when the cancer has come back (relapsed) or has not responded (refractory) to earlier treatments.\u003c/p>\n\u003cp>\u003cstrong>Internationally\u003c/strong>, approved CAR-T products are used for selected cases of:\u003c/p>\n\u003cul>\n\u003cli>B-cell acute lymphoblastic leukaemia (B-ALL)\u003c/li>\n\u003cli>Several types of B-cell lymphoma\u003c/li>\n\u003cli>Multiple myeloma\u003c/li>\n\u003cli>Chronic lymphocytic leukaemia (CLL)\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>In India\u003c/strong>, two locally made CAR-T products are approved by the national drug regulator (CDSCO). Both target a marker called CD19:\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Product\u003c/th>\n\u003cth>Approved in India for\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>NexCAR19 (approved 2023)\u003c/td>\n\u003ctd>Relapsed or refractory B-cell non-Hodgkin lymphoma and B-ALL, age 15 and above\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Qartemi (approved 2025)\u003c/td>\n\u003ctd>Relapsed or refractory B-cell non-Hodgkin lymphoma in adults\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>As of 2026, CAR-T for multiple myeloma is not approved in India. Approvals can change, so the current position should always be confirmed with a licensed cell-therapy centre.\u003c/p>\n\u003ch2 id=\"what-car-t-is-not\">What CAR-T is not\u003c/h2>\u003cul>\n\u003cli>It is \u003cstrong>not\u003c/strong> approved for solid cancers such as breast, lung, colon or brain tumours. Research is ongoing, but these uses are investigational.\u003c/li>\n\u003cli>It is \u003cstrong>not\u003c/strong> usually a first treatment.\u003c/li>\n\u003cli>It is \u003cstrong>not\u003c/strong> suitable for every patient, even with an approved cancer type.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"why-is-it-a-specialised-treatment\">Why is it a specialised treatment?\u003c/h2>\u003cp>CAR-T can cause serious side effects that need close monitoring. It must be given at an authorised centre with a cell-therapy team, facilities to collect cells, and an intensive care unit on site.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you or a family member has a B-cell lymphoma or leukaemia that has relapsed or not responded to treatment, ask your haematologist whether a CAR-T assessment is appropriate.\u003c/p>\n","faqs":[{"q":"Is CAR-T a cure?","a":"Some patients achieve long-lasting remission, but not all respond, and the cancer can return. Your specialist will explain realistic expectations."},{"q":"Is CAR-T given more than once?","a":"It is usually given as a single infusion."},{"q":"Can CAR-T treat solid tumours?","a":"Not as an approved treatment. Solid-tumour CAR-T is only available in clinical trials."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"which-cancers-is-it-approved-for","text":"Which cancers is it approved for?"},{"id":"what-car-t-is-not","text":"What CAR-T is not"},{"id":"why-is-it-a-specialised-treatment","text":"Why is it a specialised treatment?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":450,"read":2},{"slug":"how-car-t-therapy-works","sp":"oncology","title":"CAR-T Cell Therapy: How Does the Treatment Work?","seo":"How CAR-T Cell Therapy Works: T-Cells, CD19 and the Science Explained","desc":"The science of CAR-T made simple: how T-cells are engineered to recognise cancer markers like CD19, multiply inside the body and attack cancer cells.","kw":["how CAR-T works","CD19 CAR-T","chimeric antigen receptor","T-cell engineering","CAR-T mechanism"],"links":["car-t-cell-therapy-overview","car-t-treatment-journey","immunotherapy-explained"],"video":"v-cart","flow":{"caption":"How CAR-T cells are made and work","steps":[{"t":"Collect","d":"T-cells removed from blood (apheresis)"},{"t":"Engineer","d":"New CAR receptor added in a lab"},{"t":"Multiply","d":"Millions of CAR-T cells grown"},{"t":"Infuse","d":"Cells return and attack cancer"}]},"img":["T-cell with a new CAR receptor locking onto CD19 on a cancer cell","The four-step collect-engineer-multiply-infuse process","CAR-T cells multiplying inside the body"],"html":"\u003cp>CAR-T therapy works by teaching a patient&#39;s own immune cells to recognise cancer they previously could not see. This article explains the science in simple terms.\u003c/p>\n\u003ch2 id=\"the-problem-cancer-hides\">The problem: cancer hides\u003c/h2>\u003cp>T-cells are the immune system&#39;s &quot;soldiers&quot;. They patrol the body and destroy infected or abnormal cells. But many cancer cells look too much like normal cells, so T-cells pass them by.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How CAR-T cells are made and work\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How CAR-T cells are made and work\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Collect\u003c/b>\u003cspan>T-cells removed from blood (apheresis)\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Engineer\u003c/b>\u003cspan>New CAR receptor added in a lab\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Multiply\u003c/b>\u003cspan>Millions of CAR-T cells grown\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Infuse\u003c/b>\u003cspan>Cells return and attack cancer\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"the-solution-a-new-receptor\">The solution: a new receptor\u003c/h2>\u003cp>Scientists add a gene to the T-cells that makes them produce a \u003cstrong>chimeric antigen receptor (CAR)\u003c/strong> on their surface. &quot;Chimeric&quot; means it is built from parts of different proteins. The CAR works like a guided lock that fits a specific marker, called an \u003cstrong>antigen\u003c/strong>, on the cancer cell.\u003c/p>\n\u003cul>\n\u003cli>Most current CAR-T products target \u003cstrong>CD19\u003c/strong>, a marker found on B-cells, including cancerous B-cells in many lymphomas and B-ALL.\u003c/li>\n\u003cli>Others target \u003cstrong>BCMA\u003c/strong>, a marker found on myeloma cells.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-car-t-cells-attack\">How CAR-T cells attack\u003c/h2>\u003col>\n\u003cli>\u003cstrong>Recognise:\u003c/strong> the CAR binds to the target marker on a cancer cell.\u003c/li>\n\u003cli>\u003cstrong>Activate:\u003c/strong> binding switches the T-cell on.\u003c/li>\n\u003cli>\u003cstrong>Destroy:\u003c/strong> the T-cell releases substances that kill the cancer cell.\u003c/li>\n\u003cli>\u003cstrong>Multiply:\u003c/strong> activated CAR-T cells divide inside the body, building a larger army.\u003c/li>\n\u003cli>\u003cstrong>Persist:\u003c/strong> in some patients, CAR-T cells remain in the body for months or longer, continuing to watch for cancer.\u003c/li>\n\u003c/ol>\n\u003ch2 id=\"why-does-it-affect-healthy-cells-too\">Why does it affect healthy cells too?\u003c/h2>\u003cp>CD19 is also present on \u003cstrong>healthy B-cells\u003c/strong>, which make antibodies. CAR-T cells destroy these as well. This is called B-cell aplasia, and it can raise the risk of infections. Some patients need regular antibody (immunoglobulin) replacement.\u003c/p>\n\u003ch2 id=\"why-can-it-cause-strong-reactions\">Why can it cause strong reactions?\u003c/h2>\u003cp>When CAR-T cells attack cancer, the immune system releases large amounts of chemical messengers called \u003cstrong>cytokines\u003c/strong>. This can cause fever and other symptoms, known as cytokine release syndrome. Specialist teams are trained to recognise and treat this quickly.\u003c/p>\n\u003ch2 id=\"how-is-it-different-from-other-treatments\">How is it different from other treatments?\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Chemotherapy\u003c/th>\n\u003cth>CAR-T\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Made from\u003c/td>\n\u003ctd>Chemical drugs\u003c/td>\n\u003ctd>Patient&#39;s own cells\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Given\u003c/td>\n\u003ctd>Repeated cycles\u003c/td>\n\u003ctd>Usually a single infusion\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>How it works\u003c/td>\n\u003ctd>Kills dividing cells\u003c/td>\n\u003ctd>Immune cells target a specific marker\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A haematologist at an authorised cell-therapy centre can explain whether your cancer carries a marker that CAR-T can target.\u003c/p>\n","faqs":[{"q":"Are the cells from a donor?","a":"Approved CAR-T therapies use the patient's own cells. Donor-based (\"off-the-shelf\") CAR-T is still being studied."},{"q":"How long do CAR-T cells last?","a":"It varies from weeks to years between patients."},{"q":"Can cancer escape CAR-T?","a":"Yes. Sometimes cancer cells lose the target marker, allowing relapse."}],"toc":[{"id":"the-problem-cancer-hides","text":"The problem: cancer hides"},{"id":"the-solution-a-new-receptor","text":"The solution: a new receptor"},{"id":"how-car-t-cells-attack","text":"How CAR-T cells attack"},{"id":"why-does-it-affect-healthy-cells-too","text":"Why does it affect healthy cells too?"},{"id":"why-can-it-cause-strong-reactions","text":"Why can it cause strong reactions?"},{"id":"how-is-it-different-from-other-treatments","text":"How is it different from other treatments?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":438,"read":2},{"slug":"car-t-eligibility","sp":"oncology","title":"Who May Be Eligible for CAR-T Therapy?","seo":"CAR-T Therapy Eligibility: Who Can Receive It and Who Cannot","desc":"Learn the factors doctors consider before recommending CAR-T therapy, including cancer type, previous treatments, fitness, organ function and infections.","kw":["CAR-T eligibility","who can get CAR-T","CAR-T criteria","relapsed lymphoma treatment","CAR-T assessment"],"links":["car-t-cell-therapy-overview","car-t-treatment-journey","bone-marrow-transplant-vs-car-t"],"video":null,"flow":null,"img":["Eligibility checklist infographic","Haematologist reviewing scans and reports with a family","Tests in the pre-CAR-T work-up"],"html":"\u003cp>CAR-T therapy can be powerful, but it is suitable only for carefully selected patients. A specialist team reviews each person in detail before recommending it. This article explains the main factors they consider.\u003c/p>\n\u003ch2 id=\"1-the-type-of-cancer\">1. The type of cancer\u003c/h2>\u003cp>Eligibility starts with an \u003cstrong>approved indication\u003c/strong>. Currently this means certain B-cell blood cancers, such as specific types of lymphoma and B-cell ALL, and, outside India, multiple myeloma and CLL. The cancer cells usually need to carry the target marker, such as CD19.\u003c/p>\n\u003cp>People with solid tumours are not eligible for approved CAR-T. They may ask about clinical trials.\u003c/p>\n\u003ch2 id=\"2-previous-treatment\">2. Previous treatment\u003c/h2>\u003cp>CAR-T is generally offered when cancer has:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Relapsed\u003c/strong> (come back) after earlier treatment, or\u003c/li>\n\u003cli>Been \u003cstrong>refractory\u003c/strong> (not responded) to standard treatment\u003c/li>\n\u003c/ul>\n\u003cp>The number of earlier treatment lines required depends on the product and its approval.\u003c/p>\n\u003ch2 id=\"3-age\">3. Age\u003c/h2>\u003cp>Approvals specify age groups. For example, in India NexCAR19 is approved from age 15, while Qartemi is approved for adults. Children may have other options, which a paediatric haemato-oncologist can discuss.\u003c/p>\n\u003ch2 id=\"4-general-fitness\">4. General fitness\u003c/h2>\u003cp>Patients need to be well enough to cope with possible side effects. Doctors assess:\u003c/p>\n\u003cul>\n\u003cli>Daily activity level (performance status)\u003c/li>\n\u003cli>Heart function (echocardiogram)\u003c/li>\n\u003cli>Lung, kidney and liver function\u003c/li>\n\u003cli>Blood counts\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"5-infections-and-other-conditions\">5. Infections and other conditions\u003c/h2>\u003cul>\n\u003cli>Active, uncontrolled infections must be treated first\u003c/li>\n\u003cli>Hepatitis B, hepatitis C and HIV status are checked\u003c/li>\n\u003cli>Active brain involvement by cancer, recent stroke or seizures need special evaluation\u003c/li>\n\u003cli>Serious autoimmune disease or recent transplant medicines may affect suitability\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"6-disease-control-and-timing\">6. Disease control and timing\u003c/h2>\u003cp>Cancer that is growing very fast may need \u003cstrong>bridging therapy\u003c/strong> to control it while the CAR-T cells are being made. Timing matters, so early referral is important.\u003c/p>\n\u003ch2 id=\"7-practical-requirements\">7. Practical requirements\u003c/h2>\u003cul>\n\u003cli>Ability to stay near the treatment centre for about four weeks after infusion\u003c/li>\n\u003cli>A caregiver available around the clock during that period\u003c/li>\n\u003cli>Not driving for a period after treatment, usually about eight weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-does-the-assessment-involve\">What does the assessment involve?\u003c/h2>\u003cp>Expect detailed blood tests, scans such as PET-CT, a heart scan, and sometimes a bone marrow or tissue biopsy to confirm the diagnosis and target marker.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask for a referral soon after a relapse is diagnosed. Being assessed early keeps more treatment options open.\u003c/p>\n","faqs":[{"q":"Can older patients receive CAR-T?","a":"Age alone does not rule it out. Overall fitness matters more than the number."},{"q":"I have had a stem cell transplant. Can I still get CAR-T?","a":"Often yes. Many CAR-T recipients have had a previous transplant."},{"q":"Can I get CAR-T for stage IV breast or lung cancer?","a":"Not as an approved treatment. Ask about clinical trials."}],"toc":[{"id":"1-the-type-of-cancer","text":"1. The type of cancer"},{"id":"2-previous-treatment","text":"2. Previous treatment"},{"id":"3-age","text":"3. Age"},{"id":"4-general-fitness","text":"4. General fitness"},{"id":"5-infections-and-other-conditions","text":"5. Infections and other conditions"},{"id":"6-disease-control-and-timing","text":"6. Disease control and timing"},{"id":"7-practical-requirements","text":"7. Practical requirements"},{"id":"what-does-the-assessment-involve","text":"What does the assessment involve?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":439,"read":2},{"slug":"car-t-treatment-journey","sp":"oncology","title":"What Happens During CAR-T Cell Treatment?","seo":"CAR-T Treatment Process Step by Step: From Cell Collection to Recovery","desc":"A step-by-step guide to the CAR-T patient journey: evaluation, cell collection, manufacturing, bridging and lymphodepletion, infusion and monitoring.","kw":["CAR-T procedure","CAR-T process steps","apheresis","lymphodepletion","CAR-T infusion"],"links":["how-car-t-therapy-works","car-t-side-effects-monitoring","car-t-eligibility"],"video":"v-cart","flow":{"caption":"The CAR-T journey","steps":[{"t":"Evaluation","d":"Tests confirm suitability"},{"t":"Apheresis","d":"T-cells collected over a few hours"},{"t":"Manufacturing","d":"Cells engineered in about 2 to 4 weeks"},{"t":"Conditioning","d":"Short chemotherapy prepares the body"},{"t":"Infusion","d":"Cells returned through a drip"},{"t":"Monitoring","d":"Close watch for about 4 weeks"}]},"img":["Apheresis machine separating white cells","Timeline graphic from collection to day 28","CAR-T infusion bag at the bedside"],"html":"\u003cp>CAR-T treatment is a journey of several weeks rather than a single day. Knowing each step helps patients and families plan travel, time off work and caregiving.\u003c/p>\n\u003ch2 id=\"step-1-evaluation\">Step 1: Evaluation\u003c/h2>\u003cp>The cell-therapy team confirms the diagnosis and checks that you are fit for treatment with blood tests, scans, a heart assessment and infection screening. You and your family will discuss benefits, risks and consent.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"The CAR-T journey\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>The CAR-T journey\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Evaluation\u003c/b>\u003cspan>Tests confirm suitability\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Apheresis\u003c/b>\u003cspan>T-cells collected over a few hours\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Manufacturing\u003c/b>\u003cspan>Cells engineered in about 2 to 4 weeks\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Conditioning\u003c/b>\u003cspan>Short chemotherapy prepares the body\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>Infusion\u003c/b>\u003cspan>Cells returned through a drip\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">6\u003c/span>\u003cb>Monitoring\u003c/b>\u003cspan>Close watch for about 4 weeks\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"step-2-collecting-your-t-cells-apheresis\">Step 2: Collecting your T-cells (apheresis)\u003c/h2>\u003cul>\n\u003cli>Blood is drawn from a vein, passed through a machine that collects white cells, and returned to you.\u003c/li>\n\u003cli>It takes about 3 to 6 hours and is similar to donating platelets.\u003c/li>\n\u003cli>A temporary catheter may be placed if your arm veins are not suitable.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"step-3-manufacturing-the-cells\">Step 3: Manufacturing the cells\u003c/h2>\u003cp>Your cells are sent to a specialised laboratory where they are modified and multiplied. This typically takes \u003cstrong>about two to four weeks\u003c/strong>, depending on the product. Locally manufactured products in India report shorter turnaround times.\u003c/p>\n\u003ch2 id=\"step-4-bridging-therapy-if-needed\">Step 4: Bridging therapy (if needed)\u003c/h2>\u003cp>If the cancer is growing while you wait, your doctor may give chemotherapy, radiation or other treatment to keep it under control.\u003c/p>\n\u003ch2 id=\"step-5-lymphodepletion\">Step 5: Lymphodepletion\u003c/h2>\u003cp>A few days before infusion, you receive \u003cstrong>low-dose chemotherapy\u003c/strong>, usually over 3 days. This reduces your existing immune cells to make room for the CAR-T cells to expand.\u003c/p>\n\u003ch2 id=\"step-6-car-t-infusion-day-0\">Step 6: CAR-T infusion (Day 0)\u003c/h2>\u003cp>The cells are given through a drip, much like a blood transfusion. It usually takes less than an hour. Many people feel nothing unusual on the day.\u003c/p>\n\u003ch2 id=\"step-7-close-monitoring\">Step 7: Close monitoring\u003c/h2>\u003cp>The first weeks are the most important:\u003c/p>\n\u003cul>\n\u003cli>You may stay in hospital for 1 to 2 weeks, or be monitored closely as an outpatient\u003c/li>\n\u003cli>Doctors check daily for fever, blood pressure changes and neurological symptoms\u003c/li>\n\u003cli>Blood counts and infection risk are monitored\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"step-8-staying-near-the-centre\">Step 8: Staying near the centre\u003c/h2>\u003cp>Most programmes ask patients to stay within easy reach of the treatment centre for \u003cstrong>about four weeks after infusion\u003c/strong>, with a caregiver present at all times.\u003c/p>\n\u003ch2 id=\"step-9-checking-the-response\">Step 9: Checking the response\u003c/h2>\u003cp>A PET-CT or bone marrow test is usually done around one to three months after infusion to see how the cancer has responded. Long-term follow-up continues for years.\u003c/p>\n","faqs":[{"q":"Will I be awake during infusion?","a":"Yes. It is a simple drip, usually without sedation."},{"q":"What if manufacturing fails?","a":"Occasionally cells do not grow well enough. Your team will discuss repeat collection or other options."},{"q":"Can I go home immediately after infusion?","a":"Usually not. Close monitoring is needed for several weeks."}],"toc":[{"id":"step-1-evaluation","text":"Step 1: Evaluation"},{"id":"step-2-collecting-your-t-cells-apheresis","text":"Step 2: Collecting your T-cells (apheresis)"},{"id":"step-3-manufacturing-the-cells","text":"Step 3: Manufacturing the cells"},{"id":"step-4-bridging-therapy-if-needed","text":"Step 4: Bridging therapy (if needed)"},{"id":"step-5-lymphodepletion","text":"Step 5: Lymphodepletion"},{"id":"step-6-car-t-infusion-day-0","text":"Step 6: CAR-T infusion (Day 0)"},{"id":"step-7-close-monitoring","text":"Step 7: Close monitoring"},{"id":"step-8-staying-near-the-centre","text":"Step 8: Staying near the centre"},{"id":"step-9-checking-the-response","text":"Step 9: Checking the response"}],"words":420,"read":2},{"slug":"car-t-side-effects-monitoring","sp":"oncology","title":"Possible Side Effects and Monitoring After CAR-T Therapy","seo":"CAR-T Side Effects: CRS, Neurotoxicity (ICANS), Infections & Monitoring","desc":"Understand the main side effects of CAR-T therapy, including cytokine release syndrome and neurological effects, how they are treated and warning signs.","kw":["CAR-T side effects","cytokine release syndrome","CRS","ICANS","CAR-T neurotoxicity"],"links":["car-t-treatment-journey","how-car-t-therapy-works","car-t-cell-therapy-overview"],"video":null,"flow":null,"img":["Timeline of when side effects typically appear after infusion","Caregiver checklist for symptoms at home","Simple handwriting test used to check for neurological effects"],"html":"\u003cp>CAR-T therapy can cause side effects that are different from chemotherapy. Most are manageable when caught early, which is why patients are monitored closely and caregivers are trained to spot warning signs.\u003c/p>\n\u003ch2 id=\"1-cytokine-release-syndrome-crs\">1. Cytokine release syndrome (CRS)\u003c/h2>\u003cp>The most common side effect. As CAR-T cells attack cancer, they release chemical messengers that cause a strong body-wide reaction.\u003c/p>\n\u003cp>\u003cstrong>Signs:\u003c/strong> fever (often the first sign), chills, fatigue, fast heartbeat, low blood pressure and breathlessness.\u003c/p>\n\u003cp>\u003cstrong>Timing:\u003c/strong> usually within the first one to two weeks.\u003c/p>\n\u003cp>\u003cstrong>Treatment:\u003c/strong> ranges from fluids and fever medicines to a targeted drug called tocilizumab, steroids and, in severe cases, intensive care support.\u003c/p>\n\u003ch2 id=\"2-neurological-effects-icans\">2. Neurological effects (ICANS)\u003c/h2>\u003cp>Some patients develop temporary effects on the brain and nervous system.\u003c/p>\n\u003cp>\u003cstrong>Signs:\u003c/strong> confusion, difficulty finding words, trouble writing, drowsiness, tremor and, rarely, seizures.\u003c/p>\n\u003cp>\u003cstrong>Monitoring:\u003c/strong> nurses ask simple questions and may ask you to write a sentence daily to detect early changes.\u003c/p>\n\u003cp>\u003cstrong>Treatment:\u003c/strong> usually steroids and supportive care. Most effects are reversible.\u003c/p>\n\u003ch2 id=\"3-low-blood-counts\">3. Low blood counts\u003c/h2>\u003cp>Blood counts can stay low for weeks or longer. This may require transfusions or medicines to boost white cells.\u003c/p>\n\u003ch2 id=\"4-infections\">4. Infections\u003c/h2>\u003cp>The combination of chemotherapy, low counts and loss of healthy B-cells raises infection risk. Preventive antibiotics, antivirals and sometimes immunoglobulin replacement are used.\u003c/p>\n\u003ch2 id=\"5-longer-term-effects\">5. Longer-term effects\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Low antibody levels\u003c/strong> (B-cell aplasia), which can last a long time\u003c/li>\n\u003cli>Need for \u003cstrong>re-vaccination\u003c/strong> later\u003c/li>\n\u003cli>Regulators have asked for long-term follow-up for rare secondary blood cancers, which doctors monitor for\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"caregiver-warning-signs-call-the-team-immediately\">Caregiver warning signs: call the team immediately\u003c/h2>\u003cul>\n\u003cli>Temperature of 38°C (100.4°F) or above\u003c/li>\n\u003cli>Confusion, unusual sleepiness, difficulty speaking or writing\u003c/li>\n\u003cli>Shaking or seizures\u003c/li>\n\u003cli>Dizziness, fainting or breathlessness\u003c/li>\n\u003cli>A very fast heartbeat\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"practical-precautions\">Practical precautions\u003c/h2>\u003cul>\n\u003cli>Stay near the treatment centre for about four weeks\u003c/li>\n\u003cli>Have a caregiver with you around the clock\u003c/li>\n\u003cli>Do not drive or operate heavy machinery for about eight weeks\u003c/li>\n\u003cli>Carry your CAR-T wallet card at all times\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Any new symptom in the weeks after CAR-T should be reported straight away. Tell any other doctor or emergency team that you have had CAR-T therapy.\u003c/p>\n","faqs":[{"q":"Does everyone get CRS?","a":"Many patients get some degree of CRS, but most cases are mild to moderate."},{"q":"Are neurological effects permanent?","a":"In most patients, they are temporary and resolve with treatment."},{"q":"Why can't I drive?","a":"Neurological effects can occur suddenly in the first weeks, affecting concentration and alertness."}],"toc":[{"id":"1-cytokine-release-syndrome-crs","text":"1. Cytokine release syndrome (CRS)"},{"id":"2-neurological-effects-icans","text":"2. Neurological effects (ICANS)"},{"id":"3-low-blood-counts","text":"3. Low blood counts"},{"id":"4-infections","text":"4. Infections"},{"id":"5-longer-term-effects","text":"5. Longer-term effects"},{"id":"caregiver-warning-signs-call-the-team-immediately","text":"Caregiver warning signs: call the team immediately"},{"id":"practical-precautions","text":"Practical precautions"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":400,"read":2},{"slug":"bone-marrow-transplant-vs-car-t","sp":"oncology","title":"Bone Marrow Transplantation Versus CAR-T Therapy","seo":"Bone Marrow Transplant vs CAR-T Therapy: Differences Explained","desc":"Compare bone marrow transplant and CAR-T therapy: how each works, which patients they suit, the process, side effects and how doctors choose.","kw":["bone marrow transplant vs CAR-T","stem cell transplant vs CAR-T","relapsed lymphoma options","CAR-T or transplant"],"links":["car-t-cell-therapy-overview","what-is-bone-marrow-transplant","autologous-vs-allogeneic-transplant"],"video":null,"flow":null,"img":["Side-by-side comparison graphic: replacing marrow vs re-arming T-cells","Treatment pathway showing where each may fit","Multidisciplinary team discussion"],"html":"\u003cp>Patients with blood cancers sometimes hear about both bone marrow transplant (BMT) and CAR-T therapy. They are different treatments that work in different ways, and some patients may receive both at different stages.\u003c/p>\n\u003ch2 id=\"the-basic-difference\">The basic difference\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Bone marrow transplant\u003c/strong> replaces diseased or damaged bone marrow with healthy blood-forming stem cells, either your own or a donor&#39;s, after high-dose treatment.\u003c/li>\n\u003cli>\u003cstrong>CAR-T therapy\u003c/strong> modifies your own T-cells so they can directly recognise and attack cancer cells.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"side-by-side-comparison\">Side-by-side comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Bone marrow transplant\u003c/th>\n\u003cth>CAR-T therapy\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Cells used\u003c/td>\n\u003ctd>Your own (autologous) or a donor&#39;s (allogeneic) stem cells\u003c/td>\n\u003ctd>Your own modified T-cells\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Donor needed\u003c/td>\n\u003ctd>Only for allogeneic\u003c/td>\n\u003ctd>No\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Preparation\u003c/td>\n\u003ctd>High-dose chemotherapy, sometimes radiation\u003c/td>\n\u003ctd>Low-dose chemotherapy\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Main risks\u003c/td>\n\u003ctd>Infection, organ toxicity, graft-versus-host disease (donor transplants)\u003c/td>\n\u003ctd>Cytokine release syndrome, neurological effects, infection\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Conditions\u003c/td>\n\u003ctd>Many blood cancers and some non-cancer disorders\u003c/td>\n\u003ctd>Selected relapsed or refractory B-cell cancers and myeloma\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Experience\u003c/td>\n\u003ctd>Decades of use\u003c/td>\n\u003ctd>Newer; first approved in 2017\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"how-do-doctors-choose\">How do doctors choose?\u003c/h2>\u003cp>The choice depends on:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Cancer type and stage of treatment:\u003c/strong> for example, an autologous transplant may be preferred for some lymphomas that respond to further chemotherapy, while CAR-T may be preferred when the lymphoma relapses early or does not respond\u003c/li>\n\u003cli>\u003cstrong>Donor availability\u003c/strong> for allogeneic transplants\u003c/li>\n\u003cli>\u003cstrong>Age, fitness and organ function\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Previous treatments,\u003c/strong> including previous transplants\u003c/li>\n\u003cli>\u003cstrong>Approval and availability\u003c/strong> of CAR-T products for that specific cancer\u003c/li>\n\u003c/ul>\n\u003cp>Guidelines in this area are evolving as new research is published.\u003c/p>\n\u003ch2 id=\"can-patients-have-both\">Can patients have both?\u003c/h2>\u003cp>Yes. Some patients receive CAR-T after a transplant has failed. Others may go on to a donor transplant after CAR-T, particularly in some types of leukaemia.\u003c/p>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cp>Both require close monitoring, staying near the treatment centre and a dedicated caregiver. Donor transplants usually involve the longest recovery because of the need for immune-suppressing medicines and the risk of graft-versus-host disease.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If your cancer has relapsed, ask for a review by a team experienced in both transplant and cellular therapy, so all options are considered together.\u003c/p>\n","faqs":[{"q":"Is CAR-T replacing bone marrow transplant?","a":"No. Both remain important. For some situations CAR-T is now preferred; for others transplant remains standard."},{"q":"Which is safer?","a":"Each has different risks. Safety depends on the patient, cancer and centre experience."},{"q":"Do I need a donor for CAR-T?","a":"No. Approved CAR-T therapies use your own cells."}],"toc":[{"id":"the-basic-difference","text":"The basic difference"},{"id":"side-by-side-comparison","text":"Side-by-side comparison"},{"id":"how-do-doctors-choose","text":"How do doctors choose?"},{"id":"can-patients-have-both","text":"Can patients have both?"},{"id":"recovery","text":"Recovery"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":403,"read":2},{"slug":"parkinsons-disease","sp":"neurology","title":"Understanding Parkinson's Disease","seo":"Parkinson's Disease: Early Symptoms, Causes, Diagnosis & Treatment","desc":"Learn the early signs of Parkinson's disease, why it happens, how it is diagnosed and the medicines, therapies and surgery that help people live well.","kw":["Parkinson's disease","Parkinson's symptoms","tremor","dopamine","Parkinson's treatment"],"links":["deep-brain-stimulation","neuro-rehabilitation","alzheimers-and-dementia"],"video":null,"flow":null,"img":["Brain showing the dopamine-producing area (substantia nigra)","Four main movement symptoms as icons: tremor, stiffness, slowness, balance","Physiotherapy and exercise for Parkinson's"],"html":"\u003cp>Parkinson&#39;s disease is a long-term condition of the brain that mainly affects movement. It develops slowly, often over years. While there is no cure yet, treatment can control symptoms well and help people stay active and independent.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Parkinson&#39;s happens when nerve cells in a part of the brain that produces \u003cstrong>dopamine\u003c/strong> gradually stop working. Dopamine is a chemical messenger that helps control smooth, coordinated movement. As levels fall, movement becomes slower and less controlled.\u003c/p>\n\u003ch2 id=\"main-symptoms\">Main symptoms\u003c/h2>\u003cp>\u003cstrong>Movement symptoms:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Tremor:\u003c/strong> shaking, often starting in one hand at rest\u003c/li>\n\u003cli>\u003cstrong>Stiffness\u003c/strong> of the arms, legs or neck\u003c/li>\n\u003cli>\u003cstrong>Slowness of movement\u003c/strong> (bradykinesia), such as difficulty buttoning clothes\u003c/li>\n\u003cli>\u003cstrong>Balance problems\u003c/strong> and a shuffling walk, usually later\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Non-movement symptoms\u003c/strong>, which can appear years earlier:\u003c/p>\n\u003cul>\n\u003cli>Loss of sense of smell\u003c/li>\n\u003cli>Constipation\u003c/li>\n\u003cli>Acting out dreams during sleep\u003c/li>\n\u003cli>Low mood, anxiety or sleep problems\u003c/li>\n\u003cli>Smaller handwriting and a softer voice\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-gets-it\">Who gets it?\u003c/h2>\u003cp>Parkinson&#39;s usually begins after 60, though some people develop it earlier. The exact cause is unknown. A mix of ageing, genes and environmental factors is thought to play a role.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>There is no single test. A \u003cstrong>neurologist\u003c/strong> makes the diagnosis based on your symptoms and a careful examination. MRI and other scans may be done to rule out other conditions. Improvement with Parkinson&#39;s medicine also supports the diagnosis.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Medicines:\u003c/strong> levodopa and other drugs replace or mimic dopamine. Doses are adjusted over time.\u003c/li>\n\u003cli>\u003cstrong>Physiotherapy and exercise:\u003c/strong> walking, stretching, balance training and activities like dancing or tai chi help mobility\u003c/li>\n\u003cli>\u003cstrong>Speech and occupational therapy:\u003c/strong> for voice, swallowing and daily tasks\u003c/li>\n\u003cli>\u003cstrong>Deep Brain Stimulation (DBS):\u003c/strong> surgery for selected patients whose symptoms are no longer well controlled by medicines\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"living-well-with-parkinson-39-s\">Living well with Parkinson&#39;s\u003c/h2>\u003cul>\n\u003cli>Take medicines on time, every time\u003c/li>\n\u003cli>Stay physically active every day\u003c/li>\n\u003cli>Make the home safer to prevent falls\u003c/li>\n\u003cli>Seek support for mood and sleep problems\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a neurologist if you notice a persistent tremor, slowness, stiffness or changes in walking or handwriting.\u003c/p>\n","faqs":[{"q":"Is every tremor Parkinson's?","a":"No. Essential tremor, anxiety, thyroid problems and some medicines can also cause tremor."},{"q":"Is Parkinson's inherited?","a":"Most cases are not. A small number are linked to specific genes."},{"q":"Does Parkinson's shorten life?","a":"Many people live for decades with good treatment and care."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"main-symptoms","text":"Main symptoms"},{"id":"who-gets-it","text":"Who gets it?"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"living-well-with-parkinson-39-s","text":"Living well with Parkinson&#39;s"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":376,"read":2},{"slug":"epilepsy-explained","sp":"neurology","title":"Epilepsy: Causes, Symptoms and Treatment","seo":"Epilepsy: Seizure Types, Causes, Diagnosis, Treatment & First Aid","desc":"Understand what epilepsy is, the different types of seizures, common causes, tests like EEG and MRI, treatment options and seizure first aid.","kw":["epilepsy","seizures","fits","epilepsy treatment","seizure first aid"],"links":["brain-tumour-symptoms-and-surgery","craniotomy-explained","neuro-rehabilitation"],"video":null,"flow":{"caption":"Seizure first aid","steps":[{"t":"Stay calm","d":"Note the time"},{"t":"Protect","d":"Move hard objects away; cushion the head"},{"t":"Turn on side","d":"Once jerking stops, place in recovery position"},{"t":"Call for help","d":"If it lasts over 5 minutes or repeats"}]},"img":["Brain electrical activity: normal vs seizure","EEG cap and recording","Recovery position step by step"],"html":"\u003cp>Epilepsy is a condition in which a person has repeated seizures. A seizure is a sudden burst of abnormal electrical activity in the brain. About 70 percent of people with epilepsy can become seizure-free with the right treatment.\u003c/p>\n\u003ch2 id=\"what-is-a-seizure\">What is a seizure?\u003c/h2>\u003cp>Seizures can look very different depending on which part of the brain is involved:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Generalised tonic-clonic seizure:\u003c/strong> loss of consciousness, stiffening and jerking of the body\u003c/li>\n\u003cli>\u003cstrong>Absence seizure:\u003c/strong> brief blank staring, common in children\u003c/li>\n\u003cli>\u003cstrong>Focal seizure:\u003c/strong> affects one part of the brain; may cause jerking of one limb, strange sensations, or confusion and unusual behaviour\u003c/li>\n\u003c/ul>\n\u003cp>A single seizure is not always epilepsy. Epilepsy is usually diagnosed after two or more unprovoked seizures, or one seizure with a high risk of more.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Seizure first aid\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Seizure first aid\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Stay calm\u003c/b>\u003cspan>Note the time\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Protect\u003c/b>\u003cspan>Move hard objects away; cushion the head\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Turn on side\u003c/b>\u003cspan>Once jerking stops, place in recovery position\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Call for help\u003c/b>\u003cspan>If it lasts over 5 minutes or repeats\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"causes\">Causes\u003c/h2>\u003cul>\n\u003cli>Brain injury or head trauma\u003c/li>\n\u003cli>Stroke, especially in older adults\u003c/li>\n\u003cli>Brain infections such as meningitis or \u003cstrong>neurocysticercosis\u003c/strong> (a tapeworm infection that is a common cause in India)\u003c/li>\n\u003cli>Brain tumours\u003c/li>\n\u003cli>Birth injury or developmental conditions\u003c/li>\n\u003cli>Genetic factors\u003c/li>\n\u003c/ul>\n\u003cp>In many people, no cause is found.\u003c/p>\n\u003ch2 id=\"common-triggers\">Common triggers\u003c/h2>\u003cul>\n\u003cli>Missed medicines\u003c/li>\n\u003cli>Lack of sleep\u003c/li>\n\u003cli>Alcohol\u003c/li>\n\u003cli>Fever or illness\u003c/li>\n\u003cli>Flashing lights in a small number of people\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Detailed history:\u003c/strong> a video of the event taken by a family member is very helpful\u003c/li>\n\u003cli>\u003cstrong>EEG:\u003c/strong> records the brain&#39;s electrical activity\u003c/li>\n\u003cli>\u003cstrong>MRI:\u003c/strong> looks for structural causes\u003c/li>\n\u003cli>Blood tests\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Anti-seizure medicines:\u003c/strong> the main treatment; most people need them for several years\u003c/li>\n\u003cli>\u003cstrong>Epilepsy surgery:\u003c/strong> for selected people whose seizures continue despite medicines, when a specific brain area is responsible\u003c/li>\n\u003cli>\u003cstrong>Nerve stimulation devices:\u003c/strong> such as vagus nerve stimulation\u003c/li>\n\u003cli>\u003cstrong>Special diets:\u003c/strong> like the ketogenic diet, mainly for children\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"living-with-epilepsy\">Living with epilepsy\u003c/h2>\u003cul>\n\u003cli>Never stop medicines suddenly\u003c/li>\n\u003cli>Keep regular sleep habits\u003c/li>\n\u003cli>Avoid swimming alone or working at heights until seizures are controlled\u003c/li>\n\u003cli>Driving rules apply; ask your doctor\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Anyone who has had a seizure should see a neurologist. Call emergency services if a seizure lasts longer than 5 minutes, repeats without recovery, or happens in water.\u003c/p>\n","faqs":[{"q":"Should I put something in the person's mouth during a seizure?","a":"No. Never put anything in their mouth. They cannot swallow their tongue."},{"q":"Can women with epilepsy have children?","a":"Yes. Pregnancy should be planned with the neurologist, as some medicines need adjusting."},{"q":"Can epilepsy go away?","a":"Some childhood epilepsies resolve. Others are well controlled long term."}],"toc":[{"id":"what-is-a-seizure","text":"What is a seizure?"},{"id":"causes","text":"Causes"},{"id":"common-triggers","text":"Common triggers"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"living-with-epilepsy","text":"Living with epilepsy"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":384,"read":2},{"slug":"brain-haemorrhage-warning-signs","sp":"neurology","title":"Brain Haemorrhage: Warning Signs and Emergency Treatment","seo":"Brain Haemorrhage: Symptoms, Causes & Emergency Treatment","desc":"Recognise the warning signs of bleeding in the brain, including the sudden \"worst headache of life\", why it happens and how it is treated in an emergency.","kw":["brain haemorrhage","brain bleed symptoms","subarachnoid haemorrhage","aneurysm","haemorrhagic stroke"],"links":["stroke-warning-signs","craniotomy-explained","neuro-rehabilitation"],"video":null,"flow":null,"img":["Types of brain bleed by location","Brain aneurysm on an artery","CT scan showing a bleed"],"html":"\u003cp>A brain haemorrhage is bleeding in or around the brain. It is a medical emergency. Fast treatment can save life and reduce long-term disability.\u003c/p>\n\u003ch2 id=\"types-of-brain-bleed\">Types of brain bleed\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Intracerebral haemorrhage:\u003c/strong> bleeding inside the brain tissue, often linked to high blood pressure\u003c/li>\n\u003cli>\u003cstrong>Subarachnoid haemorrhage:\u003c/strong> bleeding in the space around the brain, often from a burst \u003cstrong>aneurysm\u003c/strong> (a weak, ballooned area of an artery)\u003c/li>\n\u003cli>\u003cstrong>Subdural and extradural haematoma:\u003c/strong> bleeding between the brain and skull, usually after a head injury\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"warning-signs\">Warning signs\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Sudden, severe headache\u003c/strong>, often described as &quot;the worst headache of my life&quot;\u003c/li>\n\u003cli>Vomiting\u003c/li>\n\u003cli>Stiff neck and sensitivity to light\u003c/li>\n\u003cli>Weakness or numbness of the face, arm or leg\u003c/li>\n\u003cli>Difficulty speaking or understanding\u003c/li>\n\u003cli>Blurred or double vision\u003c/li>\n\u003cli>Confusion, drowsiness or loss of consciousness\u003c/li>\n\u003cli>Seizure\u003c/li>\n\u003c/ul>\n\u003cp>After a head injury, symptoms may develop hours or even days later, especially in older people taking blood thinners.\u003c/p>\n\u003ch2 id=\"causes-and-risk-factors\">Causes and risk factors\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Uncontrolled high blood pressure:\u003c/strong> the most common cause\u003c/li>\n\u003cli>Ruptured aneurysm or abnormal blood vessels (AVM)\u003c/li>\n\u003cli>Head injury\u003c/li>\n\u003cli>Blood-thinning medicines\u003c/li>\n\u003cli>Heavy alcohol use, smoking and drug use\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-to-do\">What to do\u003c/h2>\u003cp>Call emergency services (108 or 112 in India) immediately. Do not give food, drink or medicines. Note the time symptoms started.\u003c/p>\n\u003ch2 id=\"emergency-diagnosis\">Emergency diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>CT scan of the brain:\u003c/strong> quickly shows bleeding\u003c/li>\n\u003cli>\u003cstrong>CT or catheter angiography:\u003c/strong> looks for aneurysms or abnormal vessels\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"emergency-treatment\">Emergency treatment\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Stabilisation:\u003c/strong> breathing support and careful blood pressure control in the ICU\u003c/li>\n\u003cli>\u003cstrong>Reversing blood thinners\u003c/strong> if relevant\u003c/li>\n\u003cli>\u003cstrong>Aneurysm treatment:\u003c/strong> either \u003cstrong>coiling\u003c/strong> (closing the aneurysm from inside through a catheter) or \u003cstrong>clipping\u003c/strong> (open surgery)\u003c/li>\n\u003cli>\u003cstrong>Surgery:\u003c/strong> a craniotomy may be needed to remove a large clot or relieve pressure\u003c/li>\n\u003cli>\u003cstrong>Drain:\u003c/strong> to remove excess fluid from the brain\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cp>Recovery depends on the size and location of the bleed. Many patients need rehabilitation, including physiotherapy, speech therapy and help with daily activities.\u003c/p>\n\u003ch2 id=\"prevention\">Prevention\u003c/h2>\u003cul>\n\u003cli>Check and control blood pressure regularly\u003c/li>\n\u003cli>Avoid tobacco and limit alcohol\u003c/li>\n\u003cli>Wear helmets and seat belts\u003c/li>\n\u003cli>Take blood thinners exactly as prescribed\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Is a brain haemorrhage a type of stroke?","a":"Yes. It is called a haemorrhagic stroke, and it needs different treatment from a clot-related stroke."},{"q":"Can a brain aneurysm be found before it bursts?","a":"Sometimes, on scans done for other reasons. A specialist will advise whether treatment is needed."},{"q":"Is every severe headache a brain bleed?","a":"No, but a sudden, explosive headache unlike any before needs emergency assessment."}],"toc":[{"id":"types-of-brain-bleed","text":"Types of brain bleed"},{"id":"warning-signs","text":"Warning signs"},{"id":"causes-and-risk-factors","text":"Causes and risk factors"},{"id":"what-to-do","text":"What to do"},{"id":"emergency-diagnosis","text":"Emergency diagnosis"},{"id":"emergency-treatment","text":"Emergency treatment"},{"id":"recovery","text":"Recovery"},{"id":"prevention","text":"Prevention"}],"words":389,"read":2},{"slug":"brain-tumour-symptoms-and-surgery","sp":"neurology","title":"Brain Tumours: Symptoms and Treatment Options","seo":"Brain Tumour Symptoms: Early Signs & Neurosurgical Treatment Options","desc":"Recognise the symptoms of a brain tumour, from morning headaches to seizures and personality change, and how neurosurgeons diagnose and treat them.","kw":["brain tumour symptoms","brain tumour signs","brain tumour surgery","neurosurgery","awake brain surgery"],"links":["brain-tumours-types-and-cancer-treatment","craniotomy-explained","epilepsy-explained"],"video":null,"flow":null,"img":["How tumour location affects symptoms: brain regions map","MRI scan with contrast","Neuronavigation during surgery"],"html":"\u003cp>Brain tumours can cause a wide range of symptoms, depending on their size and where they are in the brain. Many symptoms are also caused by common, less serious conditions, so recognising the pattern matters. For tumour types and grades, see our oncology guide.\u003c/p>\n\u003ch2 id=\"common-symptoms\">Common symptoms\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Headaches\u003c/strong> that are new, persistent, worse in the morning or when lying down, and getting more frequent\u003c/li>\n\u003cli>\u003cstrong>Nausea or vomiting\u003c/strong>, especially in the morning\u003c/li>\n\u003cli>\u003cstrong>Seizures\u003c/strong> in someone who has never had one before\u003c/li>\n\u003cli>\u003cstrong>Vision changes:\u003c/strong> blurring, double vision or loss of side vision\u003c/li>\n\u003cli>\u003cstrong>Weakness or numbness\u003c/strong> on one side of the body\u003c/li>\n\u003cli>\u003cstrong>Speech difficulty\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Personality or behaviour changes\u003c/strong>, confusion or memory problems\u003c/li>\n\u003cli>\u003cstrong>Balance problems\u003c/strong> and clumsiness\u003c/li>\n\u003cli>\u003cstrong>Hearing loss\u003c/strong> on one side (with tumours near the hearing nerve)\u003c/li>\n\u003cli>\u003cstrong>Hormone problems\u003c/strong> (with pituitary tumours)\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"why-location-matters\">Why location matters\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Area of the brain\u003c/th>\n\u003cth>Possible symptoms\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Frontal lobe\u003c/td>\n\u003ctd>Personality change, weakness, poor judgement\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Temporal lobe\u003c/td>\n\u003ctd>Memory and speech problems, seizures\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Parietal lobe\u003c/td>\n\u003ctd>Numbness, difficulty with spatial tasks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Occipital lobe\u003c/td>\n\u003ctd>Vision loss\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Cerebellum\u003c/td>\n\u003ctd>Poor balance and coordination\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Neurological examination:\u003c/strong> checks strength, reflexes, vision and coordination\u003c/li>\n\u003cli>\u003cstrong>MRI with contrast:\u003c/strong> the main test to see the tumour\u003c/li>\n\u003cli>\u003cstrong>Advanced imaging:\u003c/strong> functional MRI and tractography to map important brain areas before surgery\u003c/li>\n\u003cli>\u003cstrong>Biopsy:\u003c/strong> a tissue sample to confirm the type\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"neurosurgical-treatment-options\">Neurosurgical treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Craniotomy and tumour removal:\u003c/strong> the surgeon removes as much tumour as safely possible\u003c/li>\n\u003cli>\u003cstrong>Image-guided surgery (neuronavigation):\u003c/strong> works like a GPS for the brain\u003c/li>\n\u003cli>\u003cstrong>Awake brain surgery:\u003c/strong> used for tumours near speech or movement areas, so these functions can be tested during surgery\u003c/li>\n\u003cli>\u003cstrong>Endoscopic surgery:\u003c/strong> through the nose for many pituitary tumours\u003c/li>\n\u003cli>\u003cstrong>Stereotactic biopsy:\u003c/strong> a needle biopsy for deep tumours\u003c/li>\n\u003cli>\u003cstrong>Radiosurgery:\u003c/strong> focused radiation for small tumours, without an incision\u003c/li>\n\u003c/ul>\n\u003cp>After surgery, further treatment such as radiation or chemotherapy may be planned by the oncology team.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a doctor if headaches are new and worsening, or occur with vomiting, vision changes or weakness. A first seizure or sudden weakness needs urgent attention.\u003c/p>\n","faqs":[{"q":"Do most headaches mean a brain tumour?","a":"No. The vast majority of headaches are not caused by tumours."},{"q":"Is brain surgery very risky?","a":"All brain surgery has risks, but modern techniques have made it much safer. Your surgeon will explain risks specific to you."},{"q":"Will I need to shave my head?","a":"Usually only a small area is shaved."}],"toc":[{"id":"common-symptoms","text":"Common symptoms"},{"id":"why-location-matters","text":"Why location matters"},{"id":"diagnosis","text":"Diagnosis"},{"id":"neurosurgical-treatment-options","text":"Neurosurgical treatment options"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":387,"read":2},{"slug":"deep-brain-stimulation","sp":"neurology","title":"What Is Deep Brain Stimulation (DBS)?","seo":"Deep Brain Stimulation (DBS): How It Works, Who It Helps & Recovery","desc":"Learn how deep brain stimulation works for Parkinson's disease, tremor and dystonia, who is a suitable candidate, what surgery involves and results.","kw":["deep brain stimulation","DBS surgery","DBS for Parkinson's","essential tremor treatment","dystonia"],"links":["parkinsons-disease","neuro-rehabilitation","craniotomy-explained"],"video":"v-dbs","flow":{"caption":"How DBS works","steps":[{"t":"Electrodes","d":"Thin wires placed in a precise brain target"},{"t":"Extension wire","d":"Runs under the skin of the neck"},{"t":"Stimulator","d":"Battery device under the collarbone"},{"t":"Programming","d":"Settings adjusted to control symptoms"}]},"img":["Electrode placement deep in the brain with wire to chest stimulator","Before and after: tremor control during stimulation","Programming session with a tablet device"],"html":"\u003cp>Deep Brain Stimulation (DBS) is a surgical treatment that uses mild electrical signals to calm abnormal brain activity that causes certain movement disorders. It is often described as a &quot;pacemaker for the brain&quot;.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>In DBS, very thin electrodes are placed in specific areas deep inside the brain. They are connected to a small battery-powered device, similar to a heart pacemaker, placed under the skin of the chest. The device sends continuous, adjustable signals that help control symptoms.\u003c/p>\n\u003cp>DBS does not destroy brain tissue, and the settings can be changed or switched off.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How DBS works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How DBS works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Electrodes\u003c/b>\u003cspan>Thin wires placed in a precise brain target\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Extension wire\u003c/b>\u003cspan>Runs under the skin of the neck\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Stimulator\u003c/b>\u003cspan>Battery device under the collarbone\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Programming\u003c/b>\u003cspan>Settings adjusted to control symptoms\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"who-may-benefit\">Who may benefit?\u003c/h2>\u003cp>DBS is an established treatment for:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Parkinson&#39;s disease:\u003c/strong> when medicines no longer control symptoms smoothly, causing &quot;on-off&quot; fluctuations or troublesome involuntary movements\u003c/li>\n\u003cli>\u003cstrong>Essential tremor:\u003c/strong> severe tremor that interferes with daily life despite medicines\u003c/li>\n\u003cli>\u003cstrong>Dystonia:\u003c/strong> conditions causing involuntary muscle contractions\u003c/li>\n\u003c/ul>\n\u003cp>It is also used in selected cases of epilepsy and is being studied for other conditions.\u003c/p>\n\u003ch2 id=\"who-is-a-good-candidate\">Who is a good candidate?\u003c/h2>\u003cul>\n\u003cli>A confirmed diagnosis by a movement disorder specialist\u003c/li>\n\u003cli>Symptoms that respond to levodopa (for Parkinson&#39;s)\u003c/li>\n\u003cli>Reasonable general health\u003c/li>\n\u003cli>No significant memory problems or uncontrolled psychiatric illness\u003c/li>\n\u003c/ul>\n\u003cp>A detailed evaluation, including brain imaging and memory assessment, is done first.\u003c/p>\n\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003col>\n\u003cli>A frame or frameless system and MRI images are used to plan the exact target.\u003c/li>\n\u003cli>Electrodes are placed through small openings in the skull. Some centres keep the patient awake for part of the procedure to test the effect.\u003c/li>\n\u003cli>The battery is placed under the collarbone, usually in the same or a second session.\u003c/li>\n\u003c/ol>\n\u003ch2 id=\"after-surgery\">After surgery\u003c/h2>\u003cul>\n\u003cli>Hospital stay of a few days\u003c/li>\n\u003cli>The device is switched on and programmed over several visits\u003c/li>\n\u003cli>Medicines are often reduced gradually\u003c/li>\n\u003cli>Rechargeable batteries may last many years; non-rechargeable ones need replacing every few years\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-results-can-you-expect\">What results can you expect?\u003c/h2>\u003cp>DBS can significantly reduce tremor, stiffness and slowness, and smooth out fluctuations. It \u003cstrong>does not cure\u003c/strong> Parkinson&#39;s and does not usually help balance, speech or memory problems.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If Parkinson&#39;s or tremor is affecting your daily life despite medicines, ask a neurologist whether a DBS evaluation is appropriate.\u003c/p>\n","faqs":[{"q":"Is DBS a new treatment?","a":"No. DBS has been used for decades worldwide."},{"q":"Can I have an MRI after DBS?","a":"Only under specific conditions. Always check with your DBS team first."},{"q":"Will I feel the stimulation?","a":"Most people do not feel it once settings are adjusted."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"who-may-benefit","text":"Who may benefit?"},{"id":"who-is-a-good-candidate","text":"Who is a good candidate?"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"after-surgery","text":"After surgery"},{"id":"what-results-can-you-expect","text":"What results can you expect?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":400,"read":2},{"slug":"craniotomy-explained","sp":"neurology","title":"Craniotomy: Why Is Brain Surgery Performed?","seo":"Craniotomy Surgery: Reasons, Procedure, Risks & Recovery","desc":"Understand what a craniotomy is, why surgeons perform it, what happens before, during and after the operation, and what recovery looks like.","kw":["craniotomy","brain surgery","skull surgery","craniotomy recovery","neurosurgery procedure"],"links":["brain-tumour-symptoms-and-surgery","brain-haemorrhage-warning-signs","neuro-rehabilitation"],"video":null,"flow":{"caption":"Craniotomy step by step","steps":[{"t":"Planning","d":"MRI/CT and navigation set-up"},{"t":"Opening","d":"A small window of skull bone removed"},{"t":"Surgery","d":"Tumour, clot or aneurysm treated"},{"t":"Closure","d":"Bone replaced and fixed with small plates"}]},"img":["Skull \"bone flap\" opened and replaced","Surgeon using an operating microscope","ICU recovery after brain surgery"],"html":"\u003cp>A craniotomy is an operation in which a surgeon temporarily removes a small section of the skull to reach the brain. After the procedure, the bone is usually put back in place. It is one of the most common neurosurgical operations.\u003c/p>\n\u003ch2 id=\"why-is-it-performed\">Why is it performed?\u003c/h2>\u003cul>\n\u003cli>Removing \u003cstrong>brain tumours\u003c/strong>\u003c/li>\n\u003cli>Removing \u003cstrong>blood clots\u003c/strong> after a brain haemorrhage or head injury\u003c/li>\n\u003cli>Treating \u003cstrong>aneurysms\u003c/strong> (clipping) or abnormal blood vessels (AVMs)\u003c/li>\n\u003cli>Relieving \u003cstrong>pressure\u003c/strong> on the brain from swelling\u003c/li>\n\u003cli>\u003cstrong>Epilepsy surgery\u003c/strong> to remove the area causing seizures\u003c/li>\n\u003cli>Treating brain \u003cstrong>abscesses\u003c/strong> or infections\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Craniotomy step by step\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Craniotomy step by step\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Planning\u003c/b>\u003cspan>MRI/CT and navigation set-up\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Opening\u003c/b>\u003cspan>A small window of skull bone removed\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Surgery\u003c/b>\u003cspan>Tumour, clot or aneurysm treated\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Closure\u003c/b>\u003cspan>Bone replaced and fixed with small plates\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"types-of-craniotomy\">Types of craniotomy\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Standard craniotomy:\u003c/strong> opening sized to reach the problem area\u003c/li>\n\u003cli>\u003cstrong>Keyhole (minimally invasive) craniotomy:\u003c/strong> a smaller opening for selected cases\u003c/li>\n\u003cli>\u003cstrong>Awake craniotomy:\u003c/strong> the patient is woken during part of the surgery to test speech or movement\u003c/li>\n\u003cli>\u003cstrong>Endoscopic surgery:\u003c/strong> through small openings or the nose, for some tumours\u003c/li>\n\u003cli>\u003cstrong>Decompressive craniectomy:\u003c/strong> the bone is left out temporarily to allow severe swelling to settle\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"before-surgery\">Before surgery\u003c/h2>\u003cul>\n\u003cli>Scans such as MRI or CT\u003c/li>\n\u003cli>Blood tests, ECG and anaesthesia review\u003c/li>\n\u003cli>You may be asked to stop blood thinners several days beforehand\u003c/li>\n\u003cli>Fasting for several hours before the operation\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"during-surgery\">During surgery\u003c/h2>\u003col>\n\u003cli>General anaesthesia (except during the awake part of awake surgery)\u003c/li>\n\u003cli>A small area of hair is shaved and the scalp opened\u003c/li>\n\u003cli>A bone flap is removed using special tools\u003c/li>\n\u003cli>The surgeon operates using a microscope and navigation system\u003c/li>\n\u003cli>The bone is replaced and fixed with small plates and screws\u003c/li>\n\u003cli>The scalp is closed\u003c/li>\n\u003c/ol>\n\u003cp>Surgery may take from 2 to 6 hours or more.\u003c/p>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cul>\n\u003cli>Usually 1 to 2 days in the neuro ICU\u003c/li>\n\u003cli>Total hospital stay of about 3 to 7 days for planned surgery\u003c/li>\n\u003cli>Headache, swelling around the eyes and tiredness are common\u003c/li>\n\u003cli>Stitches or staples removed in 10 to 14 days\u003c/li>\n\u003cli>Return to normal activities over 4 to 8 weeks\u003c/li>\n\u003c/ul>\n\u003cp>Some patients need physiotherapy, speech therapy or occupational therapy.\u003c/p>\n\u003ch2 id=\"possible-risks\">Possible risks\u003c/h2>\u003cp>Infection, bleeding, swelling of the brain, seizures, and temporary or permanent changes in function. Your surgeon will explain risks specific to your condition.\u003c/p>\n\u003ch2 id=\"warning-signs-after-discharge\">Warning signs after discharge\u003c/h2>\u003cp>Seek urgent help for worsening headache, fever, wound discharge, new weakness, confusion, seizures or clear fluid leaking from the wound or nose.\u003c/p>\n","faqs":[{"q":"Is a craniotomy painful?","a":"Pain after surgery is usually moderate and well controlled with medicines."},{"q":"Will my hair grow back?","a":"Yes. Hair usually covers the scar."},{"q":"When can I fly after a craniotomy?","a":"Ask your surgeon. Timing depends on the type of surgery."}],"toc":[{"id":"why-is-it-performed","text":"Why is it performed?"},{"id":"types-of-craniotomy","text":"Types of craniotomy"},{"id":"before-surgery","text":"Before surgery"},{"id":"during-surgery","text":"During surgery"},{"id":"recovery","text":"Recovery"},{"id":"possible-risks","text":"Possible risks"},{"id":"warning-signs-after-discharge","text":"Warning signs after discharge"}],"words":404,"read":2},{"slug":"stroke-warning-signs","sp":"neurology","title":"Understanding Stroke and Its Early Warning Signs","seo":"Stroke Symptoms: BE FAST Warning Signs & Emergency Treatment","desc":"Learn the BE FAST warning signs of stroke, why every minute counts, how clot-busting treatment and thrombectomy work, and how to lower your risk.","kw":["stroke symptoms","BE FAST stroke","brain stroke treatment","thrombolysis","mechanical thrombectomy"],"links":["brain-haemorrhage-warning-signs","neuro-rehabilitation","coronary-artery-disease"],"video":null,"flow":{"caption":"Spot a stroke: BE FAST","steps":[{"t":"B: Balance","d":"Sudden loss of balance"},{"t":"E: Eyes","d":"Sudden vision loss or blurring"},{"t":"F: Face","d":"One side of the face droops"},{"t":"A: Arm","d":"One arm weak or numb"},{"t":"S: Speech","d":"Slurred or strange speech"},{"t":"T: Time","d":"Call 108 or 112 now"}]},"img":["Blocked artery (ischaemic) vs bleeding (haemorrhagic) stroke","Thrombectomy device removing a clot","Stroke-ready hospital pathway timeline"],"html":"\u003cp>A stroke happens when blood supply to part of the brain is suddenly cut off. Brain cells begin to die within minutes. Stroke is a medical emergency, and the faster treatment begins, the better the chances of recovery.\u003c/p>\n\u003ch2 id=\"types-of-stroke\">Types of stroke\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Ischaemic stroke:\u003c/strong> a clot blocks a brain artery. About 80 to 85 percent of strokes are this type.\u003c/li>\n\u003cli>\u003cstrong>Haemorrhagic stroke:\u003c/strong> a blood vessel bursts and bleeds into the brain.\u003c/li>\n\u003cli>\u003cstrong>TIA (&quot;mini-stroke&quot;):\u003c/strong> stroke symptoms that go away within minutes to hours. It is a serious warning sign of a future stroke.\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Spot a stroke: BE FAST\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Spot a stroke: BE FAST\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>B: Balance\u003c/b>\u003cspan>Sudden loss of balance\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>E: Eyes\u003c/b>\u003cspan>Sudden vision loss or blurring\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>F: Face\u003c/b>\u003cspan>One side of the face droops\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>A: Arm\u003c/b>\u003cspan>One arm weak or numb\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>S: Speech\u003c/b>\u003cspan>Slurred or strange speech\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">6\u003c/span>\u003cb>T: Time\u003c/b>\u003cspan>Call 108 or 112 now\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"warning-signs-be-fast\">Warning signs: BE FAST\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>B – Balance:\u003c/strong> sudden loss of balance or coordination\u003c/li>\n\u003cli>\u003cstrong>E – Eyes:\u003c/strong> sudden loss of vision in one or both eyes\u003c/li>\n\u003cli>\u003cstrong>F – Face:\u003c/strong> one side of the face droops\u003c/li>\n\u003cli>\u003cstrong>A – Arm:\u003c/strong> weakness or numbness in one arm or leg\u003c/li>\n\u003cli>\u003cstrong>S – Speech:\u003c/strong> slurred speech or difficulty understanding\u003c/li>\n\u003cli>\u003cstrong>T – Time:\u003c/strong> call emergency services immediately and note the time symptoms began\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"why-time-matters\">Why time matters\u003c/h2>\u003cp>Treatments for clot-related stroke work best when given early:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Thrombolysis (clot-busting medicine):\u003c/strong> usually within 4.5 hours of symptom onset, for suitable patients\u003c/li>\n\u003cli>\u003cstrong>Mechanical thrombectomy:\u003c/strong> a catheter is passed to the brain to pull out a large clot. It can help selected patients up to 24 hours after onset, based on scans.\u003c/li>\n\u003c/ul>\n\u003cp>A \u003cstrong>CT or MRI scan\u003c/strong> is done first to confirm whether the stroke is caused by a clot or bleeding, because treatments are very different.\u003c/p>\n\u003ch2 id=\"what-to-do\">What to do\u003c/h2>\u003col>\n\u003cli>Call 108 or 112 immediately.\u003c/li>\n\u003cli>Note the time symptoms started, or when the person was last seen well.\u003c/li>\n\u003cli>Do not give food, water or medicines.\u003c/li>\n\u003cli>Go to a hospital equipped to treat stroke, ideally with a CT scanner and thrombectomy facilities.\u003c/li>\n\u003c/ol>\n\u003ch2 id=\"risk-factors\">Risk factors\u003c/h2>\u003cul>\n\u003cli>High blood pressure, the biggest risk factor\u003c/li>\n\u003cli>Diabetes and high cholesterol\u003c/li>\n\u003cli>Smoking and tobacco\u003c/li>\n\u003cli>Irregular heartbeat (atrial fibrillation)\u003c/li>\n\u003cli>Obesity, inactivity and heavy alcohol use\u003c/li>\n\u003cli>Previous stroke or TIA\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cp>Many patients recover significant function with early rehabilitation. Medicines to prevent another stroke, such as blood thinners and cholesterol-lowering drugs, are usually needed long term.\u003c/p>\n","faqs":[{"q":"Can young people have strokes?","a":"Yes. Stroke can occur at any age, though risk rises after 55."},{"q":"If symptoms go away, do I still need to go to hospital?","a":"Yes. A TIA needs urgent assessment because the risk of a full stroke is high in the following days."},{"q":"Can stroke be prevented?","a":"Up to 80 percent of strokes may be preventable by controlling risk factors."}],"toc":[{"id":"types-of-stroke","text":"Types of stroke"},{"id":"warning-signs-be-fast","text":"Warning signs: BE FAST"},{"id":"why-time-matters","text":"Why time matters"},{"id":"what-to-do","text":"What to do"},{"id":"risk-factors","text":"Risk factors"},{"id":"recovery","text":"Recovery"}],"words":409,"read":2},{"slug":"alzheimers-and-dementia","sp":"neurology","title":"Alzheimer's Disease and Dementia Explained","seo":"Alzheimer's Disease & Dementia: Early Signs, Diagnosis & Care","desc":"Understand the difference between dementia and Alzheimer's disease, early signs beyond normal forgetfulness, diagnosis, treatment and caregiving tips.","kw":["Alzheimer's disease","dementia symptoms","memory loss","early signs of dementia","dementia care"],"links":["parkinsons-disease","stroke-warning-signs","neuro-rehabilitation"],"video":null,"flow":null,"img":["Normal ageing vs dementia: a comparison chart","Brain changes in Alzheimer's (shrinkage)","Caregiver helping with a daily routine"],"html":"\u003cp>Dementia is not a normal part of ageing. It is a group of conditions that affect memory, thinking and the ability to manage daily life. Alzheimer&#39;s disease is the most common cause of dementia.\u003c/p>\n\u003ch2 id=\"dementia-vs-alzheimer-39-s\">Dementia vs Alzheimer&#39;s\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Dementia\u003c/strong> is an umbrella term for symptoms such as memory loss, confusion and difficulty with daily tasks.\u003c/li>\n\u003cli>\u003cstrong>Alzheimer&#39;s disease\u003c/strong> is a specific brain disease and the most common cause of dementia.\u003c/li>\n\u003c/ul>\n\u003cp>Other causes include vascular dementia (after strokes or poor blood flow), Lewy body dementia and frontotemporal dementia.\u003c/p>\n\u003ch2 id=\"normal-forgetfulness-or-dementia\">Normal forgetfulness or dementia?\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Normal ageing\u003c/th>\n\u003cth>Possible dementia\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Occasionally forgetting a name, then remembering later\u003c/td>\n\u003ctd>Frequently forgetting recent events or conversations\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Misplacing keys now and then\u003c/td>\n\u003ctd>Putting things in unusual places and being unable to retrace steps\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Sometimes searching for a word\u003c/td>\n\u003ctd>Struggling to follow or join a conversation\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Making an occasional poor decision\u003c/td>\n\u003ctd>Repeated poor judgement, such as with money\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"early-warning-signs\">Early warning signs\u003c/h2>\u003cul>\n\u003cli>Memory loss that affects daily life\u003c/li>\n\u003cli>Repeating the same questions\u003c/li>\n\u003cli>Getting lost in familiar places\u003c/li>\n\u003cli>Difficulty planning or managing finances\u003c/li>\n\u003cli>Changes in mood, personality or withdrawal from social activities\u003c/li>\n\u003cli>Confusion about time or place\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>There is no single test. Doctors use:\u003c/p>\n\u003cul>\n\u003cli>Detailed history from the patient and family\u003c/li>\n\u003cli>\u003cstrong>Memory and thinking tests\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Blood tests\u003c/strong> to rule out treatable causes such as thyroid problems and vitamin B12 deficiency\u003c/li>\n\u003cli>\u003cstrong>MRI or CT\u003c/strong> brain scans\u003c/li>\n\u003cli>Sometimes specialised scans or spinal fluid tests\u003c/li>\n\u003c/ul>\n\u003cp>Some causes of memory problems, such as depression or vitamin deficiency, can be treated, so evaluation is important.\u003c/p>\n\u003ch2 id=\"treatment\">Treatment\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Medicines\u003c/strong> can help with symptoms for some people\u003c/li>\n\u003cli>\u003cstrong>Newer treatments\u003c/strong> that target amyloid protein in the brain are approved in some countries for early Alzheimer&#39;s in carefully selected patients\u003c/li>\n\u003cli>\u003cstrong>Managing risk factors:\u003c/strong> blood pressure, diabetes, hearing loss and cholesterol\u003c/li>\n\u003cli>\u003cstrong>Staying active:\u003c/strong> physical exercise, social engagement and mental stimulation\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"support-for-caregivers\">Support for caregivers\u003c/h2>\u003cul>\n\u003cli>Keep a simple, predictable daily routine\u003c/li>\n\u003cli>Use calendars, notes and labels\u003c/li>\n\u003cli>Make the home safe to prevent falls and wandering\u003c/li>\n\u003cli>Plan legal and financial matters early\u003c/li>\n\u003cli>Look after your own health and seek support\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a neurologist if memory problems are affecting daily life or are getting worse.\u003c/p>\n","faqs":[{"q":"Is memory loss always dementia?","a":"No. Stress, depression, sleep problems, medicines and vitamin deficiency can affect memory."},{"q":"Is Alzheimer's hereditary?","a":"Most cases are not directly inherited, though family history slightly raises risk."},{"q":"Can dementia be prevented?","a":"Not entirely, but healthy habits and controlling risk factors may lower the risk."}],"toc":[{"id":"dementia-vs-alzheimer-39-s","text":"Dementia vs Alzheimer&#39;s"},{"id":"normal-forgetfulness-or-dementia","text":"Normal forgetfulness or dementia?"},{"id":"early-warning-signs","text":"Early warning signs"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment","text":"Treatment"},{"id":"support-for-caregivers","text":"Support for caregivers"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":402,"read":2},{"slug":"migraine-and-chronic-headache","sp":"neurology","title":"Understanding Migraine and Chronic Headaches","seo":"Migraine & Chronic Headache: Symptoms, Triggers & Treatment","desc":"Learn how migraine differs from other headaches, common triggers, treatment and prevention options, and the headache warning signs that need urgent care.","kw":["migraine","chronic headache","migraine triggers","tension headache","headache treatment"],"links":["brain-haemorrhage-warning-signs","brain-tumour-symptoms-and-surgery","stroke-warning-signs"],"video":null,"flow":null,"img":["Migraine phases: prodrome, aura, headache, postdrome","Common triggers as icons","Headache diary template"],"html":"\u003cp>Headaches are one of the most common health complaints. Most are not dangerous, but frequent or severe headaches can seriously affect work, study and family life. Migraine is a common cause and can be treated effectively.\u003c/p>\n\u003ch2 id=\"common-types-of-headache\">Common types of headache\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Migraine:\u003c/strong> moderate to severe throbbing pain, often on one side, with nausea and sensitivity to light and sound. Attacks last 4 to 72 hours.\u003c/li>\n\u003cli>\u003cstrong>Tension-type headache:\u003c/strong> a band-like pressure on both sides of the head; usually milder\u003c/li>\n\u003cli>\u003cstrong>Cluster headache:\u003c/strong> intense pain around one eye, occurring in clusters over weeks\u003c/li>\n\u003cli>\u003cstrong>Medication-overuse headache:\u003c/strong> caused by taking painkillers too often\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-is-migraine\">What is migraine?\u003c/h2>\u003cp>Migraine is a brain condition, not &quot;just a headache&quot;. Some people experience an \u003cstrong>aura\u003c/strong> before the pain, such as flashing lights, zigzag lines or tingling.\u003c/p>\n\u003cp>Migraine is about three times more common in women and often runs in families.\u003c/p>\n\u003ch2 id=\"common-triggers\">Common triggers\u003c/h2>\u003cul>\n\u003cli>Lack of sleep or oversleeping\u003c/li>\n\u003cli>Skipped meals or dehydration\u003c/li>\n\u003cli>Stress\u003c/li>\n\u003cli>Hormonal changes around periods\u003c/li>\n\u003cli>Bright lights, strong smells or loud noise\u003c/li>\n\u003cli>Certain foods and alcohol\u003c/li>\n\u003cli>Weather changes\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"chronic-headache\">Chronic headache\u003c/h2>\u003cp>Headaches on \u003cstrong>15 or more days a month\u003c/strong> for over three months are called chronic. Overusing painkillers is a common reason headaches become chronic.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>Most headaches are diagnosed from a careful history and examination. Scans are needed only when there are warning signs. A \u003cstrong>headache diary\u003c/strong> helps your doctor identify patterns and triggers.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>\u003cstrong>For attacks:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Simple pain relievers taken early\u003c/li>\n\u003cli>Migraine-specific medicines such as triptans\u003c/li>\n\u003cli>Anti-sickness medicines\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>For prevention\u003c/strong>, if attacks are frequent:\u003c/p>\n\u003cul>\n\u003cli>Daily preventive medicines\u003c/li>\n\u003cli>Newer injectable treatments that target migraine pathways\u003c/li>\n\u003cli>Botox injections for chronic migraine\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Lifestyle measures:\u003c/strong> regular sleep, meals and exercise, staying hydrated and managing stress.\u003c/p>\n\u003ch2 id=\"warning-signs-that-need-urgent-care\">Warning signs that need urgent care\u003c/h2>\u003cul>\n\u003cli>Sudden, severe &quot;thunderclap&quot; headache\u003c/li>\n\u003cli>Headache with fever and stiff neck\u003c/li>\n\u003cli>Headache with weakness, confusion, vision loss or difficulty speaking\u003c/li>\n\u003cli>New headache after age 50\u003c/li>\n\u003cli>Headache after a head injury\u003c/li>\n\u003cli>Headache that steadily worsens over days or weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a neurologist if headaches are frequent, affect daily life, change pattern, or need painkillers more than two or three days a week.\u003c/p>\n","faqs":[{"q":"Can migraine be cured?","a":"There is no permanent cure, but most people can greatly reduce attacks with treatment."},{"q":"Do I need a brain scan for migraine?","a":"Usually not, unless there are warning signs."},{"q":"Can taking painkillers daily make headaches worse?","a":"Yes. Frequent use can cause medication-overuse headache."}],"toc":[{"id":"common-types-of-headache","text":"Common types of headache"},{"id":"what-is-migraine","text":"What is migraine?"},{"id":"common-triggers","text":"Common triggers"},{"id":"chronic-headache","text":"Chronic headache"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"warning-signs-that-need-urgent-care","text":"Warning signs that need urgent care"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":399,"read":2},{"slug":"neuro-rehabilitation","sp":"neurology","title":"Recovery and Rehabilitation After a Neurological Condition","seo":"Neuro Rehabilitation After Stroke & Brain Surgery: What to Expect","desc":"Learn how neuro-rehabilitation helps recovery after stroke, brain surgery or injury, the team involved, therapies used and how families can help.","kw":["neuro rehabilitation","stroke rehabilitation","physiotherapy after stroke","speech therapy","recovery after brain surgery"],"links":["stroke-warning-signs","craniotomy-explained","parkinsons-disease"],"video":null,"flow":{"caption":"The rehabilitation pathway","steps":[{"t":"In hospital","d":"Early, gentle therapy within days"},{"t":"Inpatient rehab","d":"Intensive daily therapy"},{"t":"Outpatient","d":"Regular sessions after discharge"},{"t":"Home programme","d":"Ongoing exercises and community activity"}]},"img":["Rehab team around a patient: physio, OT, speech therapist","Physiotherapy for walking and balance","Occupational therapy for daily tasks"],"html":"\u003cp>After a stroke, brain surgery, brain injury or a progressive neurological condition, many people need help regaining abilities they have lost. Neuro-rehabilitation is a structured programme that helps the brain and body recover as much function and independence as possible.\u003c/p>\n\u003ch2 id=\"how-does-recovery-happen\">How does recovery happen?\u003c/h2>\u003cp>The brain can reorganise itself and form new connections, a process called \u003cstrong>neuroplasticity\u003c/strong>. Repeated, focused practice helps healthy parts of the brain take over some lost functions. The fastest recovery usually happens in the first three to six months, but improvement can continue much longer.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"The rehabilitation pathway\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>The rehabilitation pathway\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>In hospital\u003c/b>\u003cspan>Early, gentle therapy within days\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Inpatient rehab\u003c/b>\u003cspan>Intensive daily therapy\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Outpatient\u003c/b>\u003cspan>Regular sessions after discharge\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Home programme\u003c/b>\u003cspan>Ongoing exercises and community activity\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"who-is-in-the-rehab-team\">Who is in the rehab team?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Neurologist or rehabilitation physician:\u003c/strong> leads the plan\u003c/li>\n\u003cli>\u003cstrong>Physiotherapist:\u003c/strong> strength, balance and walking\u003c/li>\n\u003cli>\u003cstrong>Occupational therapist:\u003c/strong> daily activities such as dressing, bathing and eating\u003c/li>\n\u003cli>\u003cstrong>Speech and language therapist:\u003c/strong> speech, understanding and swallowing\u003c/li>\n\u003cli>\u003cstrong>Psychologist:\u003c/strong> memory, mood and adjustment\u003c/li>\n\u003cli>\u003cstrong>Nurses, dietitians and social workers\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"common-therapies\">Common therapies\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Movement training:\u003c/strong> exercises to improve strength, balance and walking\u003c/li>\n\u003cli>\u003cstrong>Task-specific practice:\u003c/strong> repeating everyday activities\u003c/li>\n\u003cli>\u003cstrong>Speech therapy:\u003c/strong> for difficulty speaking (aphasia) or slurred speech\u003c/li>\n\u003cli>\u003cstrong>Swallowing therapy:\u003c/strong> to eat and drink safely\u003c/li>\n\u003cli>\u003cstrong>Cognitive rehabilitation:\u003c/strong> for memory, attention and problem solving\u003c/li>\n\u003cli>\u003cstrong>Assistive devices:\u003c/strong> walkers, braces and adapted utensils\u003c/li>\n\u003cli>\u003cstrong>Technology-assisted therapy:\u003c/strong> in some centres, robotic or computer-based training\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-does-rehabilitation-start\">When does rehabilitation start?\u003c/h2>\u003cp>As soon as the patient is medically stable, often within a few days in hospital. Early mobilisation helps prevent complications such as bed sores, stiff joints and chest infections.\u003c/p>\n\u003ch2 id=\"how-families-can-help\">How families can help\u003c/h2>\u003cul>\n\u003cli>Attend therapy sessions to learn exercises\u003c/li>\n\u003cli>Encourage independence rather than doing everything for the patient\u003c/li>\n\u003cli>Keep a regular daily routine\u003c/li>\n\u003cli>Make the home safe: handrails, good lighting and no loose rugs\u003c/li>\n\u003cli>Watch for low mood, which is common and treatable\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"setting-realistic-goals\">Setting realistic goals\u003c/h2>\u003cp>Recovery varies widely. Small, measurable goals, such as walking to the bathroom or feeding oneself, help track progress and keep motivation high.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask your neurologist for a rehabilitation referral after any stroke, brain surgery or serious neurological event, and whenever function is declining in a long-term condition.\u003c/p>\n","faqs":[{"q":"How long does rehabilitation take?","a":"It depends on the condition and severity, from a few weeks to many months."},{"q":"Can recovery continue after six months?","a":"Yes. Progress often slows but can continue for a long time with practice."},{"q":"Can rehab be done at home?","a":"Yes. Home programmes are an important part of recovery once inpatient therapy ends."}],"toc":[{"id":"how-does-recovery-happen","text":"How does recovery happen?"},{"id":"who-is-in-the-rehab-team","text":"Who is in the rehab team?"},{"id":"common-therapies","text":"Common therapies"},{"id":"when-does-rehabilitation-start","text":"When does rehabilitation start?"},{"id":"how-families-can-help","text":"How families can help"},{"id":"setting-realistic-goals","text":"Setting realistic goals"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":387,"read":2},{"slug":"when-you-need-knee-replacement","sp":"orthopedics","title":"When Do You Need a Knee Replacement?","seo":"When Do You Need a Knee Replacement? Signs, Options & Timing","desc":"Signs that it may be time to consider knee replacement, the treatments to try first, total vs partial and robotic options, and how surgeons decide.","kw":["knee replacement","when to get knee replacement","total knee replacement","partial knee replacement","robotic knee surgery"],"links":["osteoarthritis-explained","joint-replacement-before-and-after","physiotherapy-after-joint-replacement"],"video":"v-joint-replacement","flow":{"caption":"Steps before deciding on surgery","steps":[{"t":"Diagnosis","d":"X-ray confirms arthritis severity"},{"t":"Conservative care","d":"Weight control, exercise, medicines"},{"t":"Injections","d":"May give temporary relief"},{"t":"Surgery","d":"Considered when pain limits daily life"}]},"img":["Healthy knee vs arthritic knee vs replaced knee (before-and-after anatomy)","Total vs partial knee replacement implants","Robotic-assisted knee surgery set-up"],"html":"\u003cp>Knee replacement is one of the most successful operations in modern medicine. But surgery is not the first step for knee pain. The right time depends on how much the knee affects your life, not just on what the X-ray shows.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>In a knee replacement, the damaged surfaces of the knee joint are removed and replaced with smooth metal and medical-grade plastic parts. This allows the joint to move without bone rubbing on bone.\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Total knee replacement (TKR):\u003c/strong> all joint surfaces are replaced\u003c/li>\n\u003cli>\u003cstrong>Partial (unicompartmental) knee replacement:\u003c/strong> only the damaged part is replaced, when arthritis is limited to one area\u003c/li>\n\u003cli>\u003cstrong>Robotic-assisted surgery:\u003c/strong> a robotic system helps the surgeon plan and position implants precisely\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Steps before deciding on surgery\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Steps before deciding on surgery\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Diagnosis\u003c/b>\u003cspan>X-ray confirms arthritis severity\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Conservative care\u003c/b>\u003cspan>Weight control, exercise, medicines\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Injections\u003c/b>\u003cspan>May give temporary relief\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Surgery\u003c/b>\u003cspan>Considered when pain limits daily life\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"signs-it-may-be-time\">Signs it may be time\u003c/h2>\u003cul>\n\u003cli>Knee pain that limits walking, climbing stairs or getting up from a chair\u003c/li>\n\u003cli>Pain at rest or pain that disturbs your sleep\u003c/li>\n\u003cli>Stiffness or swelling that does not improve\u003c/li>\n\u003cli>A knee that is bending outwards or inwards (bow legs or knock knees)\u003c/li>\n\u003cli>Little or no relief from medicines, physiotherapy or injections\u003c/li>\n\u003cli>Pain stopping you from working or enjoying daily life\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"common-causes\">Common causes\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Osteoarthritis:\u003c/strong> wear-and-tear of the cartilage, the most common reason\u003c/li>\n\u003cli>\u003cstrong>Rheumatoid arthritis\u003c/strong> and other inflammatory conditions\u003c/li>\n\u003cli>Arthritis after an old injury\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"try-these-first\">Try these first\u003c/h2>\u003cul>\n\u003cli>Weight loss, which significantly reduces load on the knees\u003c/li>\n\u003cli>Strengthening exercises and physiotherapy\u003c/li>\n\u003cli>Pain relief medicines, used as advised\u003c/li>\n\u003cli>Walking aids or knee braces\u003c/li>\n\u003cli>Joint injections, which may give temporary relief\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-surgeons-decide\">How surgeons decide\u003c/h2>\u003cp>Your surgeon considers your symptoms, examination, X-rays, age, activity level and general health. There is no &quot;right age&quot;. The decision is about quality of life and whether conservative treatment has stopped working.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See an orthopaedic surgeon if knee pain has lasted more than a few months, is getting worse, or is limiting your independence.\u003c/p>\n","faqs":[{"q":"Am I too young or too old for a knee replacement?","a":"Age alone is not the deciding factor. Your symptoms, health and activity level matter more."},{"q":"How long does a knee replacement last?","a":"Most modern knee replacements last 15 to 20 years or more."},{"q":"Should I wait until I can barely walk?","a":"No. Waiting too long can weaken muscles and make recovery harder."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"signs-it-may-be-time","text":"Signs it may be time"},{"id":"common-causes","text":"Common causes"},{"id":"try-these-first","text":"Try these first"},{"id":"how-surgeons-decide","text":"How surgeons decide"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":369,"read":2},{"slug":"total-hip-replacement","sp":"orthopedics","title":"Total Hip Replacement Explained","seo":"Total Hip Replacement: Who Needs It, Surgery & Recovery","desc":"A clear guide to total hip replacement: the hip conditions it treats, how the ball-and-socket joint is replaced, recovery milestones and precautions.","kw":["total hip replacement","hip replacement surgery","hip arthritis","avascular necrosis","hip replacement recovery"],"links":["minimally-invasive-hip-replacement","joint-replacement-before-and-after","osteoarthritis-explained"],"video":"v-joint-replacement","flow":{"caption":"Parts of a hip replacement","steps":[{"t":"Socket (cup)","d":"Metal shell fitted into the pelvis"},{"t":"Liner","d":"Smooth plastic or ceramic surface"},{"t":"Ball (head)","d":"Metal or ceramic ball"},{"t":"Stem","d":"Fits inside the thigh bone"}]},"img":["Hip joint anatomy: healthy vs arthritic","Hip implant components labelled","Patient walking with a walker on day one"],"html":"\u003cp>The hip is a ball-and-socket joint that carries your body weight with every step. When it is badly damaged, walking and even sleeping can become painful. A total hip replacement replaces the damaged joint with an artificial one to relieve pain and restore movement.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>During the surgery, the damaged ball at the top of the thigh bone and the worn socket in the pelvis are replaced with implants. These are made from metal, ceramic and highly durable plastic.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Parts of a hip replacement\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Parts of a hip replacement\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Socket (cup)\u003c/b>\u003cspan>Metal shell fitted into the pelvis\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Liner\u003c/b>\u003cspan>Smooth plastic or ceramic surface\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Ball (head)\u003c/b>\u003cspan>Metal or ceramic ball\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Stem\u003c/b>\u003cspan>Fits inside the thigh bone\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"who-may-need-it\">Who may need it?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Osteoarthritis\u003c/strong> of the hip\u003c/li>\n\u003cli>\u003cstrong>Avascular necrosis (AVN):\u003c/strong> loss of blood supply to the ball of the hip, which can affect younger adults, often linked to steroid use or alcohol\u003c/li>\n\u003cli>\u003cstrong>Rheumatoid arthritis\u003c/strong> and ankylosing spondylitis\u003c/li>\n\u003cli>\u003cstrong>Hip fractures\u003c/strong> in older adults\u003c/li>\n\u003cli>Childhood hip problems that lead to early arthritis\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms-that-suggest-hip-damage\">Symptoms that suggest hip damage\u003c/h2>\u003cul>\n\u003cli>Pain in the groin, thigh or buttock\u003c/li>\n\u003cli>Limping\u003c/li>\n\u003cli>Difficulty putting on socks and shoes\u003c/li>\n\u003cli>Stiffness after sitting\u003c/li>\n\u003cli>Pain that disturbs sleep\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>An X-ray usually shows the condition of the joint. MRI may be needed to detect early AVN.\u003c/p>\n\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003col>\n\u003cli>Spinal or general anaesthesia is given.\u003c/li>\n\u003cli>The surgeon reaches the hip through an incision at the side, back or front of the hip.\u003c/li>\n\u003cli>The damaged bone is removed and implants are fixed, with or without bone cement.\u003c/li>\n\u003cli>The wound is closed.\u003c/li>\n\u003c/ol>\n\u003cp>The operation usually takes 1 to 2 hours.\u003c/p>\n\u003ch2 id=\"recovery-milestones\">Recovery milestones\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Day 1:\u003c/strong> standing and walking with a walker\u003c/li>\n\u003cli>\u003cstrong>Days 3 to 5:\u003c/strong> discharge home in most cases\u003c/li>\n\u003cli>\u003cstrong>2 to 6 weeks:\u003c/strong> walking with a stick, then independently\u003c/li>\n\u003cli>\u003cstrong>6 to 12 weeks:\u003c/strong> return to most daily activities, including driving when cleared\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"precautions\">Precautions\u003c/h2>\u003cp>Depending on the surgical approach, your surgeon may advise avoiding:\u003c/p>\n\u003cul>\n\u003cli>Bending the hip beyond 90 degrees\u003c/li>\n\u003cli>Crossing your legs\u003c/li>\n\u003cli>Twisting the operated leg inwards\u003c/li>\n\u003c/ul>\n\u003cp>Follow your surgeon&#39;s specific instructions, as precautions vary.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See an orthopaedic surgeon if hip or groin pain is persistent, affects walking or sleep, or does not improve with treatment.\u003c/p>\n","faqs":[{"q":"Can young people have hip replacements?","a":"Yes, particularly for conditions such as AVN, when the joint is severely damaged."},{"q":"Will I be able to sit cross-legged or on the floor?","a":"Discuss this with your surgeon. Some positions may be restricted, depending on the implant and approach."},{"q":"What is a dislocation?","a":"The ball slipping out of the socket. It is uncommon, and precautions reduce the risk."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"who-may-need-it","text":"Who may need it?"},{"id":"symptoms-that-suggest-hip-damage","text":"Symptoms that suggest hip damage"},{"id":"diagnosis","text":"Diagnosis"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"recovery-milestones","text":"Recovery milestones"},{"id":"precautions","text":"Precautions"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":404,"read":2},{"slug":"minimally-invasive-hip-replacement","sp":"orthopedics","title":"Minimally Invasive Hip Replacement","seo":"Minimally Invasive Hip Replacement: Anterior Approach, Benefits & Limits","desc":"Learn how minimally invasive hip replacement differs from the traditional approach, the possible benefits, who it suits and its limitations.","kw":["minimally invasive hip replacement","anterior hip replacement","muscle-sparing hip surgery","small incision hip replacement"],"links":["total-hip-replacement","physiotherapy-after-joint-replacement","joint-replacement-before-and-after"],"video":null,"flow":null,"img":["Comparison of incision length: traditional vs minimally invasive","Muscle-sparing anterior approach diagram","Early walking after surgery"],"html":"\u003cp>Minimally invasive hip replacement uses smaller incisions and techniques that disturb less muscle than traditional surgery. The joint replacement itself is the same; what changes is how the surgeon reaches the hip.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>In traditional hip replacement, the incision may be 15 to 25 cm long, and some muscles are cut and repaired. Minimally invasive techniques often use an incision of about 8 to 12 cm and work \u003cstrong>between\u003c/strong> muscles rather than through them.\u003c/p>\n\u003cp>Common approaches include:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Direct anterior approach:\u003c/strong> from the front of the hip\u003c/li>\n\u003cli>\u003cstrong>Mini-posterior approach:\u003c/strong> a shorter incision at the back of the hip\u003c/li>\n\u003cli>\u003cstrong>Other muscle-sparing approaches\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"possible-benefits\">Possible benefits\u003c/h2>\u003cul>\n\u003cli>Less muscle damage\u003c/li>\n\u003cli>Smaller scar\u003c/li>\n\u003cli>Less pain in the early days\u003c/li>\n\u003cli>Faster early recovery, such as walking sooner\u003c/li>\n\u003cli>Shorter hospital stay for some patients\u003c/li>\n\u003cli>Fewer movement restrictions with some approaches\u003c/li>\n\u003c/ul>\n\u003cp>Research shows that the main advantages are in the \u003cstrong>first few weeks\u003c/strong>. Long-term results are similar to traditional surgery when performed by experienced surgeons.\u003c/p>\n\u003ch2 id=\"who-is-suitable\">Who is suitable?\u003c/h2>\u003cp>Minimally invasive surgery may suit patients who:\u003c/p>\n\u003cul>\n\u003cli>Are within a healthy weight range or have moderate body weight\u003c/li>\n\u003cli>Have normal hip anatomy\u003c/li>\n\u003cli>Have not had previous hip surgery\u003c/li>\n\u003cli>Have good bone quality\u003c/li>\n\u003c/ul>\n\u003cp>It may not be suitable for people with severe deformity, very high body weight, complex revision surgery or significant bone loss.\u003c/p>\n\u003ch2 id=\"limitations-and-risks\">Limitations and risks\u003c/h2>\u003cul>\n\u003cli>It requires specialised training and equipment\u003c/li>\n\u003cli>The surgeon has a smaller view of the joint\u003c/li>\n\u003cli>Some approaches carry a risk of temporary numbness on the front of the thigh\u003c/li>\n\u003cli>All hip replacement risks still apply, including infection, blood clots and dislocation\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"choosing-the-right-approach\">Choosing the right approach\u003c/h2>\u003cp>The best approach is the one your surgeon performs regularly and that fits your anatomy. A well-performed traditional operation is better than a poorly suited minimally invasive one.\u003c/p>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cp>Many patients walk on the same or next day and go home within a few days. Physiotherapy remains essential to restore strength and walking pattern.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you are considering hip replacement, ask your surgeon which approach they recommend for you and why.\u003c/p>\n","faqs":[{"q":"Is minimally invasive surgery better in the long run?","a":"Long-term outcomes are generally similar. The main benefit is a quicker early recovery."},{"q":"Is robotic surgery the same as minimally invasive?","a":"Not exactly. Robotics helps implant positioning; minimally invasive refers to the surgical approach. They can be combined."},{"q":"Will I need physiotherapy?","a":"Yes. It is important regardless of the approach."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"possible-benefits","text":"Possible benefits"},{"id":"who-is-suitable","text":"Who is suitable?"},{"id":"limitations-and-risks","text":"Limitations and risks"},{"id":"choosing-the-right-approach","text":"Choosing the right approach"},{"id":"recovery","text":"Recovery"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":404,"read":2},{"slug":"acl-injury","sp":"orthopedics","title":"ACL Injury: Symptoms, Diagnosis and Treatment","seo":"ACL Tear: Symptoms, Diagnosis & Treatment Options","desc":"Learn how ACL tears happen, the symptoms such as a \"pop\" and knee giving way, how they are diagnosed with MRI, and when surgery or rehab is best.","kw":["ACL tear","ACL injury symptoms","anterior cruciate ligament","knee ligament injury","ACL treatment"],"links":["acl-reconstruction-surgery","sports-injuries-treatment","physiotherapy-after-joint-replacement"],"video":null,"flow":{"caption":"Immediate care for a knee injury","steps":[{"t":"Protect","d":"Stop playing; avoid weight if painful"},{"t":"Rest and ice","d":"15 to 20 minutes every few hours"},{"t":"Compress and elevate","d":"Reduce swelling"},{"t":"See a specialist","d":"Especially if you heard a pop or the knee gives way"}]},"img":["Knee anatomy showing the ACL inside the joint","How ACL tears happen: twisting or sudden stop","MRI image of a torn ACL"],"html":"\u003cp>The anterior cruciate ligament (ACL) is one of the main ligaments that keeps your knee stable. ACL tears are among the most common sports injuries, especially in football, kabaddi, basketball and badminton.\u003c/p>\n\u003ch2 id=\"what-is-the-acl\">What is the ACL?\u003c/h2>\u003cp>The ACL is a strong band inside the knee that connects the thigh bone to the shin bone. It stops the shin bone from sliding forward and helps control twisting movements.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Immediate care for a knee injury\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Immediate care for a knee injury\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Protect\u003c/b>\u003cspan>Stop playing; avoid weight if painful\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Rest and ice\u003c/b>\u003cspan>15 to 20 minutes every few hours\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Compress and elevate\u003c/b>\u003cspan>Reduce swelling\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>See a specialist\u003c/b>\u003cspan>Especially if you heard a pop or the knee gives way\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"how-does-it-get-injured\">How does it get injured?\u003c/h2>\u003cul>\n\u003cli>Sudden stopping or changing direction\u003c/li>\n\u003cli>Landing awkwardly from a jump\u003c/li>\n\u003cli>Twisting the knee with the foot planted\u003c/li>\n\u003cli>A direct blow to the knee\u003c/li>\n\u003c/ul>\n\u003cp>Women athletes have a higher risk of ACL injury than men.\u003c/p>\n\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cul>\n\u003cli>A \u003cstrong>&quot;pop&quot;\u003c/strong> felt or heard at the time of injury\u003c/li>\n\u003cli>Rapid \u003cstrong>swelling\u003c/strong> within a few hours\u003c/li>\n\u003cli>Pain and difficulty putting weight on the leg\u003c/li>\n\u003cli>The knee feeling unstable or \u003cstrong>giving way\u003c/strong>, especially when turning\u003c/li>\n\u003cli>Loss of full movement\u003c/li>\n\u003c/ul>\n\u003cp>ACL tears often occur with other injuries, such as meniscus (cartilage cushion) tears.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Physical examination:\u003c/strong> special tests such as the Lachman test check knee stability\u003c/li>\n\u003cli>\u003cstrong>X-ray:\u003c/strong> to rule out fractures\u003c/li>\n\u003cli>\u003cstrong>MRI:\u003c/strong> confirms the ACL tear and shows other damage\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>\u003cstrong>Non-surgical treatment\u003c/strong> may suit people who:\u003c/p>\n\u003cul>\n\u003cli>Are less active or do not play pivoting sports\u003c/li>\n\u003cli>Have a partial tear with a stable knee\u003c/li>\n\u003cli>Are willing to adjust activities\u003c/li>\n\u003c/ul>\n\u003cp>This involves structured physiotherapy to strengthen the muscles around the knee and sometimes a brace.\u003c/p>\n\u003cp>\u003cstrong>Surgery (ACL reconstruction)\u003c/strong> is usually recommended for:\u003c/p>\n\u003cul>\n\u003cli>Young, active people and athletes\u003c/li>\n\u003cli>People whose knee keeps giving way\u003c/li>\n\u003cli>Those with other injuries such as meniscus tears\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"why-treatment-matters\">Why treatment matters\u003c/h2>\u003cp>Repeated episodes of the knee giving way can damage the meniscus and cartilage, raising the risk of early arthritis.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a sports medicine or orthopaedic specialist after any knee injury with a pop, significant swelling or instability.\u003c/p>\n","faqs":[{"q":"Can a torn ACL heal on its own?","a":"A completely torn ACL usually does not heal back together, though some people manage well with rehabilitation."},{"q":"Can I walk with a torn ACL?","a":"Often yes, once swelling settles, but the knee may give way during twisting activities."},{"q":"Should I have surgery immediately?","a":"Surgery is often done after swelling settles and movement returns, typically a few weeks after injury."}],"toc":[{"id":"what-is-the-acl","text":"What is the ACL?"},{"id":"how-does-it-get-injured","text":"How does it get injured?"},{"id":"symptoms","text":"Symptoms"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"why-treatment-matters","text":"Why treatment matters"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":372,"read":2},{"slug":"acl-reconstruction-surgery","sp":"orthopedics","title":"ACL Reconstruction: What Happens During Surgery?","seo":"ACL Reconstruction Surgery: Procedure, Graft Options & Recovery","desc":"Understand ACL reconstruction: graft choices, how arthroscopic keyhole surgery is performed, the rehabilitation timeline and return to sport.","kw":["ACL reconstruction","ACL surgery","arthroscopic knee surgery","ACL graft","return to sport after ACL"],"links":["acl-injury","sports-injuries-treatment","physiotherapy-after-joint-replacement"],"video":null,"flow":{"caption":"ACL rehabilitation timeline","steps":[{"t":"Weeks 0 to 2","d":"Control swelling; regain straightening"},{"t":"Weeks 2 to 6","d":"Walk normally; bend the knee"},{"t":"Months 2 to 4","d":"Strength and balance training"},{"t":"Months 4 to 6","d":"Running and agility drills"},{"t":"Months 9 to 12","d":"Gradual return to sport"}]},"img":["Arthroscopic portals on the knee","New graft placed through tunnels in the thigh and shin bones","Rehab exercises progression"],"html":"\u003cp>ACL reconstruction is a keyhole operation that replaces a torn anterior cruciate ligament with a new ligament, called a graft. It restores stability to the knee so you can return to active life and sports.\u003c/p>\n\u003ch2 id=\"why-reconstruction-rather-than-repair\">Why reconstruction rather than repair?\u003c/h2>\u003cp>A torn ACL rarely heals well when stitched. Instead, surgeons use a graft that acts as a framework for a new ligament to grow into.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"ACL rehabilitation timeline\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>ACL rehabilitation timeline\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Weeks 0 to 2\u003c/b>\u003cspan>Control swelling; regain straightening\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Weeks 2 to 6\u003c/b>\u003cspan>Walk normally; bend the knee\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Months 2 to 4\u003c/b>\u003cspan>Strength and balance training\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Months 4 to 6\u003c/b>\u003cspan>Running and agility drills\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>Months 9 to 12\u003c/b>\u003cspan>Gradual return to sport\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"graft-options\">Graft options\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Graft\u003c/th>\n\u003cth>Taken from\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Hamstring tendon\u003c/td>\n\u003ctd>Tendons at the back of your thigh\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Patellar tendon\u003c/td>\n\u003ctd>The middle third of the tendon below the kneecap\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Quadriceps tendon\u003c/td>\n\u003ctd>The tendon above the kneecap\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Allograft\u003c/td>\n\u003ctd>Donor tissue\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>Your surgeon will recommend the best option based on your age, activity and knee condition.\u003c/p>\n\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003col>\n\u003cli>Spinal or general anaesthesia is given.\u003c/li>\n\u003cli>The surgeon makes two or three small cuts and inserts a camera (\u003cstrong>arthroscope\u003c/strong>) into the knee.\u003c/li>\n\u003cli>The torn ACL is cleared and any meniscus injury is treated.\u003c/li>\n\u003cli>The graft is harvested and prepared.\u003c/li>\n\u003cli>Small tunnels are drilled in the thigh and shin bones.\u003c/li>\n\u003cli>The graft is passed through and fixed with screws or buttons.\u003c/li>\n\u003c/ol>\n\u003cp>Surgery usually takes 1 to 2 hours. Many patients go home the same day or the next day.\u003c/p>\n\u003ch2 id=\"recovery-and-rehabilitation\">Recovery and rehabilitation\u003c/h2>\u003cp>Rehabilitation is just as important as surgery. It follows a staged plan:\u003c/p>\n\u003cul>\n\u003cli>Walking with crutches for the first few weeks\u003c/li>\n\u003cli>Physiotherapy starting within days\u003c/li>\n\u003cli>Gradually increasing strength, balance and control\u003c/li>\n\u003cli>Sport-specific training after several months\u003c/li>\n\u003c/ul>\n\u003cp>Return to pivoting sports usually takes \u003cstrong>9 to 12 months\u003c/strong>. Returning too early increases the risk of a second injury.\u003c/p>\n\u003ch2 id=\"possible-risks\">Possible risks\u003c/h2>\u003cul>\n\u003cli>Knee stiffness\u003c/li>\n\u003cli>Infection or blood clots (uncommon)\u003c/li>\n\u003cli>Graft failure or re-injury\u003c/li>\n\u003cli>Pain at the graft site\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Talk to a sports orthopaedic surgeon if your knee gives way after an ACL injury or you want to return to sports.\u003c/p>\n","faqs":[{"q":"Is ACL surgery painful?","a":"There is some pain for the first few days, which is managed with medicines and ice."},{"q":"When can I drive?","a":"Usually after a few weeks, once you have good control of the leg. Ask your surgeon."},{"q":"Will my knee be as good as before?","a":"Most people regain a stable knee and return to activity, though results depend on rehabilitation and other knee damage."}],"toc":[{"id":"why-reconstruction-rather-than-repair","text":"Why reconstruction rather than repair?"},{"id":"graft-options","text":"Graft options"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"recovery-and-rehabilitation","text":"Recovery and rehabilitation"},{"id":"possible-risks","text":"Possible risks"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":379,"read":2},{"slug":"shoulder-replacement","sp":"orthopedics","title":"Shoulder Replacement: Who Needs It?","seo":"Shoulder Replacement Surgery: Who Needs It, Types & Recovery","desc":"Learn when shoulder replacement may be recommended, the difference between anatomical and reverse shoulder replacement, and what recovery involves.","kw":["shoulder replacement","reverse shoulder replacement","shoulder arthritis","rotator cuff arthropathy","shoulder surgery recovery"],"links":["osteoarthritis-explained","physiotherapy-after-joint-replacement","joint-replacement-before-and-after"],"video":null,"flow":null,"img":["Shoulder anatomy: ball, socket and rotator cuff","Anatomical vs reverse shoulder replacement implants","Sling and early pendulum exercises"],"html":"\u003cp>The shoulder is the most mobile joint in the body. When it is badly damaged by arthritis or injury, simple tasks like combing hair or reaching a shelf can become painful. Shoulder replacement can relieve pain and improve movement when other treatments no longer work.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Like the hip, the shoulder is a ball-and-socket joint. In shoulder replacement, the damaged ball and socket are replaced with artificial parts.\u003c/p>\n\u003ch2 id=\"types-of-shoulder-replacement\">Types of shoulder replacement\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Anatomical total shoulder replacement:\u003c/strong> the new ball and socket mimic your natural shoulder. It needs healthy rotator cuff muscles.\u003c/li>\n\u003cli>\u003cstrong>Reverse shoulder replacement:\u003c/strong> the ball and socket positions are swapped. This allows the larger deltoid muscle to lift the arm, and is used when the rotator cuff is badly torn or not working.\u003c/li>\n\u003cli>\u003cstrong>Partial replacement (hemiarthroplasty):\u003c/strong> only the ball is replaced, used in selected cases such as some fractures.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-may-need-it\">Who may need it?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Osteoarthritis\u003c/strong> of the shoulder\u003c/li>\n\u003cli>\u003cstrong>Rheumatoid arthritis\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Rotator cuff tear arthropathy:\u003c/strong> arthritis after a large, long-standing rotator cuff tear\u003c/li>\n\u003cli>\u003cstrong>Complex shoulder fractures\u003c/strong> in older adults\u003c/li>\n\u003cli>\u003cstrong>Avascular necrosis\u003c/strong> of the shoulder\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cul>\n\u003cli>Persistent shoulder pain, often worse at night\u003c/li>\n\u003cli>Difficulty lifting the arm or reaching behind the back\u003c/li>\n\u003cli>Stiffness and a grinding sensation\u003c/li>\n\u003cli>Weakness\u003c/li>\n\u003cli>Little relief from medicines, injections or physiotherapy\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>Physical examination of movement and strength\u003c/li>\n\u003cli>\u003cstrong>X-rays\u003c/strong> to assess joint damage\u003c/li>\n\u003cli>\u003cstrong>CT or MRI\u003c/strong> to check bone shape and rotator cuff condition\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-to-expect-from-surgery\">What to expect from surgery\u003c/h2>\u003cul>\n\u003cli>Performed under general anaesthesia, often with a nerve block for pain relief\u003c/li>\n\u003cli>Takes about 1.5 to 2 hours\u003c/li>\n\u003cli>Hospital stay of 1 to 3 days\u003c/li>\n\u003cli>Arm in a sling for around 4 to 6 weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cul>\n\u003cli>Gentle exercises begin early, guided by a physiotherapist\u003c/li>\n\u003cli>Active movement and strengthening follow in stages\u003c/li>\n\u003cli>Most daily activities are possible by around 3 months\u003c/li>\n\u003cli>Full recovery may take 6 to 12 months\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See an orthopaedic shoulder specialist if shoulder pain affects sleep or daily activities and has not improved with treatment.\u003c/p>\n","faqs":[{"q":"How long does a shoulder replacement last?","a":"Most last 15 years or more."},{"q":"Will I be able to lift my arm above my head?","a":"Most patients gain useful overhead movement, though the final range varies."},{"q":"Can I sleep on the operated side?","a":"Usually not for the first few weeks. Your surgeon will advise."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"types-of-shoulder-replacement","text":"Types of shoulder replacement"},{"id":"who-may-need-it","text":"Who may need it?"},{"id":"symptoms","text":"Symptoms"},{"id":"diagnosis","text":"Diagnosis"},{"id":"what-to-expect-from-surgery","text":"What to expect from surgery"},{"id":"recovery","text":"Recovery"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":383,"read":2},{"slug":"osteoarthritis-explained","sp":"orthopedics","title":"Understanding Osteoarthritis","seo":"Osteoarthritis: Symptoms, Causes, Stages & Treatment Options","desc":"Understand osteoarthritis, the most common type of arthritis: why cartilage wears out, early signs, diagnosis and the treatments that help at each stage.","kw":["osteoarthritis","knee arthritis","joint pain","cartilage damage","arthritis treatment"],"links":["when-you-need-knee-replacement","total-hip-replacement","physiotherapy-after-joint-replacement"],"video":null,"flow":{"caption":"Stages of osteoarthritis care","steps":[{"t":"Early","d":"Exercise, weight control, education"},{"t":"Moderate","d":"Physiotherapy, medicines, supports"},{"t":"Advanced","d":"Injections for symptom relief"},{"t":"Severe","d":"Joint replacement considered"}]},"img":["Healthy cartilage vs worn cartilage with bone spurs","Joints most often affected: knees, hips, hands, spine","Strengthening exercises for knee osteoarthritis"],"html":"\u003cp>Osteoarthritis is the most common type of arthritis. It affects millions of people, especially after the age of 50. Although it cannot be reversed, there is a lot you can do to reduce pain and stay active.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>The ends of bones in a joint are covered with smooth \u003cstrong>cartilage\u003c/strong>, which allows them to glide over each other. In osteoarthritis, this cartilage gradually wears down. The bone underneath changes, small bony growths called \u003cstrong>bone spurs\u003c/strong> form, and the joint can become painful, stiff and swollen.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Stages of osteoarthritis care\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Stages of osteoarthritis care\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Early\u003c/b>\u003cspan>Exercise, weight control, education\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Moderate\u003c/b>\u003cspan>Physiotherapy, medicines, supports\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Advanced\u003c/b>\u003cspan>Injections for symptom relief\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Severe\u003c/b>\u003cspan>Joint replacement considered\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"joints-commonly-affected\">Joints commonly affected\u003c/h2>\u003cul>\n\u003cli>Knees (very common in India)\u003c/li>\n\u003cli>Hips\u003c/li>\n\u003cli>Hands and fingers\u003c/li>\n\u003cli>Neck and lower back\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cul>\n\u003cli>Pain that worsens with activity and improves with rest\u003c/li>\n\u003cli>Morning stiffness lasting less than about 30 minutes\u003c/li>\n\u003cli>Stiffness after sitting for a long time\u003c/li>\n\u003cli>Swelling\u003c/li>\n\u003cli>A grinding or crackling feeling\u003c/li>\n\u003cli>Reduced movement\u003c/li>\n\u003cli>In the knees, gradual bowing of the legs\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"risk-factors\">Risk factors\u003c/h2>\u003cul>\n\u003cli>Increasing age\u003c/li>\n\u003cli>Excess body weight, which multiplies the load on the knees\u003c/li>\n\u003cli>Previous joint injury\u003c/li>\n\u003cli>Family history\u003c/li>\n\u003cli>Being female\u003c/li>\n\u003cli>Jobs involving repeated kneeling, squatting or heavy lifting\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>Doctors diagnose osteoarthritis from your symptoms, an examination and \u003cstrong>X-rays\u003c/strong>. Blood tests may be done to rule out other types of arthritis, such as rheumatoid arthritis.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>\u003cstrong>Self-care and lifestyle:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Regular exercise, especially strengthening the thigh muscles for knee arthritis\u003c/li>\n\u003cli>Weight loss: even 5 to 10 percent can noticeably reduce knee pain\u003c/li>\n\u003cli>Low-impact activities such as walking, swimming and cycling\u003c/li>\n\u003cli>Supportive footwear and walking aids if needed\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Medical treatment:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Pain-relief medicines and gels, used as advised\u003c/li>\n\u003cli>Physiotherapy\u003c/li>\n\u003cli>Joint injections for temporary relief in some cases\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Surgery:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Joint replacement\u003c/strong> when pain and disability are severe despite other treatments\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"myths\">Myths\u003c/h2>\u003cul>\n\u003cli>\u003cem>Rest is best:\u003c/em> in fact, appropriate exercise improves pain and function\u003c/li>\n\u003cli>\u003cem>Arthritis is just ageing:\u003c/em> it is a medical condition that can be managed\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See an orthopaedic specialist if joint pain lasts more than a few weeks, limits activity or keeps getting worse.\u003c/p>\n","faqs":[{"q":"Can osteoarthritis be cured?","a":"It cannot be reversed, but symptoms can usually be well managed."},{"q":"Should I stop exercising if my joints hurt?","a":"No. The right type of exercise helps. A physiotherapist can guide you."},{"q":"Do supplements help?","a":"Evidence is mixed. Discuss with your doctor before spending on supplements."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"joints-commonly-affected","text":"Joints commonly affected"},{"id":"symptoms","text":"Symptoms"},{"id":"risk-factors","text":"Risk factors"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"myths","text":"Myths"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":377,"read":2},{"slug":"sports-injuries-treatment","sp":"orthopedics","title":"Sports Injuries and Their Treatment","seo":"Common Sports Injuries: Symptoms, First Aid, Treatment & Prevention","desc":"A guide to common sports injuries such as sprains, meniscus tears, tennis elbow and rotator cuff injuries, first aid, treatment options and prevention.","kw":["sports injuries","ligament sprain","meniscus tear","rotator cuff injury","tennis elbow","sports medicine"],"links":["acl-injury","acl-reconstruction-surgery","osteoarthritis-explained"],"video":null,"flow":null,"img":["Common injury sites on an athlete's body","Arthroscopic (keyhole) surgery illustration","Warm-up and stretching routine"],"html":"\u003cp>Sports injuries can happen to anyone, from professional athletes to weekend players and gym-goers. Most heal well with prompt care, but some need specialist treatment to prevent long-term problems.\u003c/p>\n\u003ch2 id=\"common-sports-injuries\">Common sports injuries\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Injury\u003c/th>\n\u003cth>What happens\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Ankle sprain\u003c/td>\n\u003ctd>Ligaments stretched or torn when the ankle rolls\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Meniscus tear\u003c/td>\n\u003ctd>The knee&#39;s cartilage cushion torn by twisting\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>ACL tear\u003c/td>\n\u003ctd>A major knee ligament torn\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Rotator cuff injury\u003c/td>\n\u003ctd>Shoulder tendons strained or torn\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Shoulder dislocation\u003c/td>\n\u003ctd>The ball slips out of the socket\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Tennis or golfer&#39;s elbow\u003c/td>\n\u003ctd>Overuse of forearm tendons\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Hamstring strain\u003c/td>\n\u003ctd>Back of thigh muscle pulled\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Achilles tendon injury\u003c/td>\n\u003ctd>Inflammation or tear above the heel\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stress fracture\u003c/td>\n\u003ctd>Small crack in bone from repeated impact\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"acute-vs-overuse-injuries\">Acute vs overuse injuries\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Acute injuries\u003c/strong> happen suddenly, such as a fall, twist or collision.\u003c/li>\n\u003cli>\u003cstrong>Overuse injuries\u003c/strong> develop gradually from repeated stress without enough rest.\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"first-aid\">First aid\u003c/h2>\u003cp>For most minor injuries in the first 48 to 72 hours:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Protect\u003c/strong> the injured area\u003c/li>\n\u003cli>\u003cstrong>Rest\u003c/strong> and avoid painful activity\u003c/li>\n\u003cli>\u003cstrong>Ice\u003c/strong> for 15 to 20 minutes every few hours\u003c/li>\n\u003cli>\u003cstrong>Compression\u003c/strong> with an elastic bandage\u003c/li>\n\u003cli>\u003cstrong>Elevation\u003c/strong> above heart level\u003c/li>\n\u003c/ul>\n\u003cp>Gentle movement should begin as pain allows.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>Examination by a sports medicine or orthopaedic specialist\u003c/li>\n\u003cli>X-ray for suspected fractures\u003c/li>\n\u003cli>MRI or ultrasound for ligament, tendon and cartilage injuries\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Physiotherapy:\u003c/strong> the cornerstone of recovery\u003c/li>\n\u003cli>\u003cstrong>Bracing or taping\u003c/strong> for support\u003c/li>\n\u003cli>\u003cstrong>Medicines\u003c/strong> for pain and swelling, as advised\u003c/li>\n\u003cli>\u003cstrong>Injections\u003c/strong> in selected cases\u003c/li>\n\u003cli>\u003cstrong>Arthroscopic (keyhole) surgery:\u003c/strong> to repair meniscus tears, reconstruct ligaments or stabilise a shoulder\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-sport\">Returning to sport\u003c/h2>\u003cp>Return gradually once you have full movement, good strength and no pain. Returning too early is a major cause of re-injury.\u003c/p>\n\u003ch2 id=\"prevention\">Prevention\u003c/h2>\u003cul>\n\u003cli>Warm up before and cool down after exercise\u003c/li>\n\u003cli>Build strength, balance and flexibility\u003c/li>\n\u003cli>Increase training intensity gradually\u003c/li>\n\u003cli>Use correct technique and proper footwear\u003c/li>\n\u003cli>Allow rest days for recovery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a specialist if you cannot bear weight, the joint is unstable or deformed, swelling is severe, or pain does not improve within a week or two.\u003c/p>\n","faqs":[{"q":"Should I use heat or ice?","a":"Ice is generally better for new injuries. Heat may help muscle stiffness later."},{"q":"Can I play through pain?","a":"No. Pain is a warning sign and continuing can worsen the injury."},{"q":"Do all sports injuries need an MRI?","a":"No. Your doctor will decide based on the examination."}],"toc":[{"id":"common-sports-injuries","text":"Common sports injuries"},{"id":"acute-vs-overuse-injuries","text":"Acute vs overuse injuries"},{"id":"first-aid","text":"First aid"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"returning-to-sport","text":"Returning to sport"},{"id":"prevention","text":"Prevention"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":383,"read":2},{"slug":"joint-replacement-before-and-after","sp":"orthopedics","title":"Joint Replacement: What Happens Before and After Surgery?","seo":"Joint Replacement Surgery: Preparation, Hospital Stay & Recovery Guide","desc":"A practical guide to preparing for knee or hip replacement: tests, home preparation, the day of surgery, the hospital stay and the first weeks at home.","kw":["joint replacement preparation","before knee replacement","after hip replacement","joint replacement recovery","pre-operative tests"],"links":["when-you-need-knee-replacement","total-hip-replacement","physiotherapy-after-joint-replacement"],"video":null,"flow":{"caption":"Your joint replacement journey","steps":[{"t":"2 to 4 weeks before","d":"Tests, medicine review, home preparation"},{"t":"Surgery day","d":"Anaesthesia, 1 to 2 hour operation"},{"t":"Days 1 to 4","d":"Walking with physio; discharge"},{"t":"Weeks 2 to 12","d":"Home exercises and follow-up visits"}]},"img":["Pre-surgery checklist infographic","Home set-up: raised toilet seat, handrails, clear walkways","Wound and swelling care after surgery"],"html":"\u003cp>Good preparation and a clear plan for recovery make a real difference to how quickly you get back on your feet after knee or hip replacement. This guide covers what usually happens before and after surgery.\u003c/p>\n\u003ch2 id=\"before-surgery\">Before surgery\u003c/h2>\u003cp>\u003cstrong>Medical assessment\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Blood tests, ECG and chest X-ray\u003c/li>\n\u003cli>Heart or lung evaluation if needed\u003c/li>\n\u003cli>Review of all medicines; some, such as blood thinners, may need to be stopped\u003c/li>\n\u003cli>Dental check to treat any infection, which could spread to the new joint\u003c/li>\n\u003cli>Good control of diabetes and blood pressure\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Getting your body ready\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Stop smoking, which slows healing\u003c/li>\n\u003cli>Do pre-surgery exercises to strengthen your muscles\u003c/li>\n\u003cli>Eat well and stay active\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Getting your home ready\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Remove loose rugs and clutter\u003c/li>\n\u003cli>Arrange a firm chair with armrests\u003c/li>\n\u003cli>Consider a raised toilet seat or commode chair\u003c/li>\n\u003cli>Keep essentials within easy reach\u003c/li>\n\u003cli>Arrange help from family for the first few weeks\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Your joint replacement journey\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Your joint replacement journey\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>2 to 4 weeks before\u003c/b>\u003cspan>Tests, medicine review, home preparation\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Surgery day\u003c/b>\u003cspan>Anaesthesia, 1 to 2 hour operation\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Days 1 to 4\u003c/b>\u003cspan>Walking with physio; discharge\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Weeks 2 to 12\u003c/b>\u003cspan>Home exercises and follow-up visits\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"the-day-of-surgery\">The day of surgery\u003c/h2>\u003cul>\n\u003cli>Fast for the time advised by your anaesthetist\u003c/li>\n\u003cli>Spinal anaesthesia is commonly used, sometimes with sedation\u003c/li>\n\u003cli>The operation usually takes 1 to 2 hours\u003c/li>\n\u003cli>You will wake up in the recovery area with pain relief in place\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"in-hospital\">In hospital\u003c/h2>\u003cul>\n\u003cli>Walking with a walker often begins on the same or next day\u003c/li>\n\u003cli>Physiotherapy teaches exercises, walking and stair climbing\u003c/li>\n\u003cli>Blood clot prevention with medicines, stockings or foot pumps\u003c/li>\n\u003cli>Most patients go home in 2 to 5 days\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-first-weeks-at-home\">The first weeks at home\u003c/h2>\u003cul>\n\u003cli>Continue your exercises several times a day\u003c/li>\n\u003cli>Use ice and keep the leg raised to reduce swelling\u003c/li>\n\u003cli>Take pain relief as prescribed so you can exercise\u003c/li>\n\u003cli>Keep the wound clean and dry\u003c/li>\n\u003cli>Use your walker or stick until your physiotherapist advises otherwise\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"warning-signs-contact-your-surgeon\">Warning signs: contact your surgeon\u003c/h2>\u003cul>\n\u003cli>Fever, redness, warmth or discharge from the wound\u003c/li>\n\u003cli>Increasing pain or swelling\u003c/li>\n\u003cli>Calf pain or swelling, which may suggest a blood clot\u003c/li>\n\u003cli>Sudden breathlessness or chest pain, which is an emergency\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"follow-up\">Follow-up\u003c/h2>\u003cp>Expect review visits at around 2 weeks, 6 weeks and 3 months, then periodically to check the implant.\u003c/p>\n","faqs":[{"q":"How soon can I walk after surgery?","a":"Often on the same day or the next day, with support."},{"q":"When can I climb stairs?","a":"You will practise stairs with a physiotherapist before going home."},{"q":"Do I need antibiotics before dental work later?","a":"Ask your surgeon. Recommendations vary."}],"toc":[{"id":"before-surgery","text":"Before surgery"},{"id":"the-day-of-surgery","text":"The day of surgery"},{"id":"in-hospital","text":"In hospital"},{"id":"the-first-weeks-at-home","text":"The first weeks at home"},{"id":"warning-signs-contact-your-surgeon","text":"Warning signs: contact your surgeon"},{"id":"follow-up","text":"Follow-up"}],"words":375,"read":2},{"slug":"physiotherapy-after-joint-replacement","sp":"orthopedics","title":"Physiotherapy After Joint Replacement: Why Is It Important?","seo":"Physiotherapy After Knee & Hip Replacement: Exercises & Timeline","desc":"Why physiotherapy is essential after knee or hip replacement, the stages of rehabilitation, key exercises, and tips to manage pain and stay motivated.","kw":["physiotherapy after knee replacement","exercises after hip replacement","joint replacement rehabilitation","knee bending after surgery"],"links":["joint-replacement-before-and-after","when-you-need-knee-replacement","total-hip-replacement"],"video":null,"flow":{"caption":"Physiotherapy stages","steps":[{"t":"Stage 1: Hospital","d":"Walking, ankle pumps, safe transfers"},{"t":"Stage 2: Weeks 1 to 6","d":"Range of motion, gentle strengthening"},{"t":"Stage 3: Weeks 6 to 12","d":"Strength, balance, walking without aids"},{"t":"Stage 4: 3 months+","d":"Return to activities and fitness"}]},"img":["Ankle pumps, quad sets and heel slides illustrated","Knee bending progress chart (degrees over weeks)","Balance training with support"],"html":"\u003cp>A new joint is only part of the solution. Physiotherapy is what turns a successful operation into a successful recovery. The effort you put into exercises in the first three months largely decides how well your new joint works.\u003c/p>\n\u003ch2 id=\"why-is-physiotherapy-so-important\">Why is physiotherapy so important?\u003c/h2>\u003cul>\n\u003cli>Restores \u003cstrong>movement\u003c/strong>, especially knee bending and straightening\u003c/li>\n\u003cli>Rebuilds \u003cstrong>muscle strength\u003c/strong> lost before and after surgery\u003c/li>\n\u003cli>Improves \u003cstrong>balance\u003c/strong> and reduces fall risk\u003c/li>\n\u003cli>Reduces \u003cstrong>stiffness\u003c/strong> and swelling\u003c/li>\n\u003cli>Helps prevent \u003cstrong>blood clots\u003c/strong> through movement\u003c/li>\n\u003cli>Builds confidence for daily activities\u003c/li>\n\u003c/ul>\n\u003cp>Skipping exercises can lead to a stiff joint that may need further treatment.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Physiotherapy stages\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Physiotherapy stages\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Stage 1: Hospital\u003c/b>\u003cspan>Walking, ankle pumps, safe transfers\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Stage 2: Weeks 1 to 6\u003c/b>\u003cspan>Range of motion, gentle strengthening\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Stage 3: Weeks 6 to 12\u003c/b>\u003cspan>Strength, balance, walking without aids\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Stage 4: 3 months+\u003c/b>\u003cspan>Return to activities and fitness\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"common-early-exercises\">Common early exercises\u003c/h2>\u003cp>Your physiotherapist will tailor a programme for you. Typical early exercises include:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Ankle pumps:\u003c/strong> moving the foot up and down to improve circulation\u003c/li>\n\u003cli>\u003cstrong>Quadriceps sets:\u003c/strong> tightening the thigh muscle while the leg is straight\u003c/li>\n\u003cli>\u003cstrong>Heel slides:\u003c/strong> sliding the heel towards you to bend the knee\u003c/li>\n\u003cli>\u003cstrong>Straight leg raises:\u003c/strong> lifting the leg with the knee straight\u003c/li>\n\u003cli>\u003cstrong>Hip abduction:\u003c/strong> sliding the leg out to the side (after hip replacement)\u003c/li>\n\u003c/ul>\n\u003cp>Perform them several times daily as advised.\u003c/p>\n\u003ch2 id=\"typical-goals-after-knee-replacement\">Typical goals after knee replacement\u003c/h2>\u003cul>\n\u003cli>Full straightening of the knee\u003c/li>\n\u003cli>Bending to about 90 degrees by around 4 to 6 weeks\u003c/li>\n\u003cli>Further improvement over the following months\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"managing-pain-during-exercise\">Managing pain during exercise\u003c/h2>\u003cul>\n\u003cli>Take prescribed pain relief about 30 to 45 minutes before exercises\u003c/li>\n\u003cli>Use ice after sessions\u003c/li>\n\u003cli>Expect some discomfort; sharp or worsening pain should be reported\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"home-vs-clinic-physiotherapy\">Home vs clinic physiotherapy\u003c/h2>\u003cp>Both can work well. Many patients start with home visits and move to clinic sessions. A clear home exercise plan is essential either way.\u003c/p>\n\u003ch2 id=\"tips-to-stay-on-track\">Tips to stay on track\u003c/h2>\u003cul>\n\u003cli>Set a fixed daily routine for exercises\u003c/li>\n\u003cli>Track your progress, such as how far you can bend the knee\u003c/li>\n\u003cli>Walk a little more each day\u003c/li>\n\u003cli>Involve a family member for encouragement\u003c/li>\n\u003cli>Celebrate small milestones\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-activities\">Returning to activities\u003c/h2>\u003cul>\n\u003cli>Walking without aids: often by 4 to 8 weeks\u003c/li>\n\u003cli>Driving: usually after 4 to 6 weeks, when cleared\u003c/li>\n\u003cli>Swimming and cycling: often after wounds heal and with your surgeon&#39;s approval\u003c/li>\n\u003cli>High-impact sports such as running or jumping: usually discouraged\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Contact your surgeon or physiotherapist if progress stalls, the joint stays very stiff, or pain is increasing rather than decreasing.\u003c/p>\n","faqs":[{"q":"How long will I need physiotherapy?","a":"Usually 6 to 12 weeks of structured therapy, then continued home exercises."},{"q":"Is it normal for the knee to be swollen for weeks?","a":"Yes, mild swelling can last for a few months."},{"q":"Can I do too much?","a":"Yes. Follow your physiotherapist's guidance and increase activity gradually."}],"toc":[{"id":"why-is-physiotherapy-so-important","text":"Why is physiotherapy so important?"},{"id":"common-early-exercises","text":"Common early exercises"},{"id":"typical-goals-after-knee-replacement","text":"Typical goals after knee replacement"},{"id":"managing-pain-during-exercise","text":"Managing pain during exercise"},{"id":"home-vs-clinic-physiotherapy","text":"Home vs clinic physiotherapy"},{"id":"tips-to-stay-on-track","text":"Tips to stay on track"},{"id":"returning-to-activities","text":"Returning to activities"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":415,"read":2},{"slug":"slip-disc-symptoms","sp":"spine","title":"Understanding Slip Disc and Its Symptoms","seo":"Slip Disc (Herniated Disc): Symptoms, Causes & Treatment","desc":"Learn what a slip disc really is, why it causes back pain and leg pain, the warning signs to watch for, and how most cases improve without surgery.","kw":["slip disc","herniated disc","disc prolapse","slipped disc symptoms","lower back pain with leg pain"],"links":["sciatica-explained","when-is-spine-surgery-necessary","minimally-invasive-spine-surgery"],"video":null,"flow":{"caption":"What happens in a slip disc","steps":[{"t":"Healthy disc","d":"Soft centre held by a tough outer ring"},{"t":"Wear or strain","d":"Outer ring weakens or tears"},{"t":"Bulge or herniation","d":"Soft centre pushes out"},{"t":"Nerve pressure","d":"Pain, numbness or weakness in the limb"}]},"img":["Spine segment showing a normal disc vs a herniated disc pressing on a nerve","Common pain patterns: lower back to leg, neck to arm","Correct lifting posture"],"html":"\u003cp>&quot;Slip disc&quot; is a common term, but the disc does not actually slip out of place. The term describes a disc that has bulged or burst, pressing on nearby nerves. The good news is that most people improve without surgery.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Between each bone of your spine (vertebrae) sits a disc that acts as a shock absorber. Each disc has a soft, jelly-like centre and a tough outer ring. When the outer ring weakens or tears, the soft centre can push out. This is called a \u003cstrong>herniated\u003c/strong> or \u003cstrong>prolapsed\u003c/strong> disc.\u003c/p>\n\u003cp>It most often affects the \u003cstrong>lower back (lumbar spine)\u003c/strong> and the \u003cstrong>neck (cervical spine)\u003c/strong>.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"What happens in a slip disc\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>What happens in a slip disc\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Healthy disc\u003c/b>\u003cspan>Soft centre held by a tough outer ring\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Wear or strain\u003c/b>\u003cspan>Outer ring weakens or tears\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Bulge or herniation\u003c/b>\u003cspan>Soft centre pushes out\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Nerve pressure\u003c/b>\u003cspan>Pain, numbness or weakness in the limb\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cp>\u003cstrong>Lower back disc:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Lower back pain\u003c/li>\n\u003cli>Pain shooting down one leg, often below the knee (sciatica)\u003c/li>\n\u003cli>Numbness or tingling in the leg or foot\u003c/li>\n\u003cli>Weakness in the leg or foot\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Neck disc:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Neck pain\u003c/li>\n\u003cli>Pain radiating into the shoulder and arm\u003c/li>\n\u003cli>Numbness or tingling in the hand\u003c/li>\n\u003cli>Weak grip\u003c/li>\n\u003c/ul>\n\u003cp>Pain often worsens with sitting, bending, coughing or sneezing.\u003c/p>\n\u003ch2 id=\"causes-and-risk-factors\">Causes and risk factors\u003c/h2>\u003cul>\n\u003cli>Age-related wear of the discs\u003c/li>\n\u003cli>Lifting heavy objects with poor technique\u003c/li>\n\u003cli>Sudden twisting movements\u003c/li>\n\u003cli>Long hours of sitting or driving\u003c/li>\n\u003cli>Excess body weight\u003c/li>\n\u003cli>Smoking\u003c/li>\n\u003cli>Physically demanding work\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Examination:\u003c/strong> checking reflexes, strength, sensation and nerve stretch tests\u003c/li>\n\u003cli>\u003cstrong>MRI:\u003c/strong> the best test to see the disc and nerves\u003c/li>\n\u003cli>X-rays do not show discs but may be used to check alignment\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>Most people improve within \u003cstrong>6 to 12 weeks\u003c/strong> with:\u003c/p>\n\u003cul>\n\u003cli>Staying gently active rather than full bed rest\u003c/li>\n\u003cli>Pain relief medicines, as advised\u003c/li>\n\u003cli>\u003cstrong>Physiotherapy\u003c/strong> and core-strengthening exercises\u003c/li>\n\u003cli>\u003cstrong>Epidural or nerve root injections\u003c/strong> for severe leg pain\u003c/li>\n\u003c/ul>\n\u003cp>Surgery may be considered if pain persists despite treatment, or if there is significant nerve weakness.\u003c/p>\n\u003ch2 id=\"red-flag-symptoms-seek-emergency-care\">Red flag symptoms: seek emergency care\u003c/h2>\u003cul>\n\u003cli>Numbness around the genitals or buttocks (saddle area)\u003c/li>\n\u003cli>Loss of bladder or bowel control\u003c/li>\n\u003cli>Rapidly worsening weakness in the legs\u003c/li>\n\u003c/ul>\n\u003cp>These can indicate \u003cstrong>cauda equina syndrome\u003c/strong>, which needs urgent surgery.\u003c/p>\n","faqs":[{"q":"Can a slip disc heal on its own?","a":"Yes. In many people, the herniated part shrinks over time and symptoms improve."},{"q":"Should I take complete bed rest?","a":"No. Gentle activity is better than prolonged bed rest."},{"q":"Does every disc bulge on MRI need treatment?","a":"No. Disc bulges are common even in people without pain. Treatment depends on symptoms."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"symptoms","text":"Symptoms"},{"id":"causes-and-risk-factors","text":"Causes and risk factors"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"red-flag-symptoms-seek-emergency-care","text":"Red flag symptoms: seek emergency care"}],"words":381,"read":2},{"slug":"when-is-spine-surgery-necessary","sp":"spine","title":"When Is Spine Surgery Necessary?","seo":"When Is Spine Surgery Needed? Signs, Red Flags & Alternatives","desc":"Most back pain does not need surgery. Learn the situations where spine surgery is recommended, the red flags, and questions to ask your surgeon.","kw":["when is spine surgery necessary","back surgery","spine surgery indications","avoid spine surgery","second opinion spine surgery"],"links":["slip-disc-symptoms","spinal-decompression-surgery","minimally-invasive-spine-surgery"],"video":null,"flow":null,"img":["Decision pathway: conservative care to surgery","MRI showing nerve compression","Surgeon discussing options with a patient"],"html":"\u003cp>Back and neck pain are extremely common, and the vast majority of cases improve without surgery. Spine surgery is recommended only in specific situations, when the potential benefit clearly outweighs the risks.\u003c/p>\n\u003ch2 id=\"most-back-pain-does-not-need-surgery\">Most back pain does not need surgery\u003c/h2>\u003cp>Around 9 out of 10 people with back pain improve within a few weeks to months with:\u003c/p>\n\u003cul>\n\u003cli>Staying active\u003c/li>\n\u003cli>Physiotherapy and exercise\u003c/li>\n\u003cli>Medicines for pain and inflammation\u003c/li>\n\u003cli>Injections in some cases\u003c/li>\n\u003cli>Posture and lifestyle changes\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-surgery-may-be-recommended\">When surgery may be recommended\u003c/h2>\u003cp>\u003cstrong>Urgent or emergency surgery:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Cauda equina syndrome:\u003c/strong> loss of bladder or bowel control, or numbness in the saddle area\u003c/li>\n\u003cli>\u003cstrong>Rapidly worsening weakness\u003c/strong> in the arms or legs\u003c/li>\n\u003cli>\u003cstrong>Spinal cord compression\u003c/strong> causing problems with walking, balance or hand function\u003c/li>\n\u003cli>\u003cstrong>Spinal fractures\u003c/strong> that are unstable\u003c/li>\n\u003cli>\u003cstrong>Spinal infections or tumours\u003c/strong> pressing on nerves\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Planned (elective) surgery may be considered when:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Leg or arm pain from a pinched nerve continues for more than 6 to 12 weeks despite good treatment\u003c/li>\n\u003cli>Pain seriously affects daily life, work or sleep\u003c/li>\n\u003cli>\u003cstrong>Spinal stenosis\u003c/strong> limits walking distance significantly\u003c/li>\n\u003cli>There is \u003cstrong>instability\u003c/strong>, such as one vertebra slipping forward on another (spondylolisthesis)\u003c/li>\n\u003cli>There is a progressive spinal deformity such as severe scoliosis\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-surgery-is-less-likely-to-help\">When surgery is less likely to help\u003c/h2>\u003cul>\n\u003cli>Back pain alone, without nerve symptoms or a clear structural cause\u003c/li>\n\u003cli>MRI findings that do not match symptoms\u003c/li>\n\u003cli>Widespread pain affecting many areas of the body\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"questions-to-ask-your-surgeon\">Questions to ask your surgeon\u003c/h2>\u003cul>\n\u003cli>What exactly is causing my symptoms?\u003c/li>\n\u003cli>What happens if I wait or continue non-surgical treatment?\u003c/li>\n\u003cli>What type of surgery do you recommend, and why?\u003c/li>\n\u003cli>What are the risks and expected recovery time?\u003c/li>\n\u003cli>What improvement can I realistically expect?\u003c/li>\n\u003c/ul>\n\u003cp>Seeking a second opinion before major spine surgery is reasonable and common.\u003c/p>\n\u003ch2 id=\"types-of-spine-surgery\">Types of spine surgery\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Discectomy:\u003c/strong> removing a herniated part of a disc\u003c/li>\n\u003cli>\u003cstrong>Decompression (laminectomy):\u003c/strong> creating more space for nerves\u003c/li>\n\u003cli>\u003cstrong>Spinal fusion:\u003c/strong> joining vertebrae to stabilise the spine\u003c/li>\n\u003cli>\u003cstrong>Disc replacement:\u003c/strong> replacing a damaged disc with an artificial one\u003c/li>\n\u003cli>\u003cstrong>Minimally invasive surgery:\u003c/strong> smaller incisions for many of these procedures\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a spine specialist if pain spreads into an arm or leg, causes numbness or weakness, or has not improved after several weeks of treatment. Seek emergency care for red flag symptoms.\u003c/p>\n","faqs":[{"q":"Is spine surgery dangerous?","a":"All surgery has risks, but serious complications are uncommon when surgery is appropriately chosen and performed by experienced surgeons."},{"q":"Will surgery cure my back pain completely?","a":"Surgery is most effective for leg or arm pain caused by nerve compression. Back pain alone may improve less predictably."},{"q":"Can I avoid surgery with physiotherapy?","a":"Many people can. It depends on the cause and severity."}],"toc":[{"id":"most-back-pain-does-not-need-surgery","text":"Most back pain does not need surgery"},{"id":"when-surgery-may-be-recommended","text":"When surgery may be recommended"},{"id":"when-surgery-is-less-likely-to-help","text":"When surgery is less likely to help"},{"id":"questions-to-ask-your-surgeon","text":"Questions to ask your surgeon"},{"id":"types-of-spine-surgery","text":"Types of spine surgery"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":432,"read":2},{"slug":"minimally-invasive-spine-surgery","sp":"spine","title":"Minimally Invasive Spine Surgery Explained","seo":"Minimally Invasive Spine Surgery (MISS): Types, Benefits & Recovery","desc":"Learn how minimally invasive and endoscopic spine surgery work, which conditions they treat, possible benefits, limitations and recovery time.","kw":["minimally invasive spine surgery","endoscopic spine surgery","keyhole spine surgery","microdiscectomy","MIS TLIF"],"links":["slip-disc-symptoms","spinal-decompression-surgery","recovery-after-spine-surgery"],"video":"v-mis-spine","flow":{"caption":"How keyhole spine surgery works","steps":[{"t":"Small incision","d":"Often under 2.5 cm"},{"t":"Tubular retractor","d":"Gently separates muscles"},{"t":"Camera or microscope","d":"Magnified view of nerves"},{"t":"Targeted repair","d":"Disc or bone removed; nerves freed"}]},"img":["Traditional open incision vs small tubular access","Endoscope reaching a herniated disc","Patient walking on the day of surgery"],"html":"\u003cp>Minimally invasive spine surgery (MISS) treats spinal problems through small incisions, using special instruments and high-magnification cameras. The goal is to fix the problem while causing less damage to surrounding muscles.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>In traditional open spine surgery, muscles are pulled away from the spine through a larger incision. In minimally invasive surgery, the surgeon:\u003c/p>\n\u003cul>\n\u003cli>Makes one or more small incisions\u003c/li>\n\u003cli>Uses \u003cstrong>tubular retractors\u003c/strong> to gently separate rather than cut muscles\u003c/li>\n\u003cli>Works with a \u003cstrong>microscope\u003c/strong> or \u003cstrong>endoscope\u003c/strong> (a tiny camera)\u003c/li>\n\u003cli>Uses live X-ray guidance and sometimes navigation or robotics\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"How keyhole spine surgery works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How keyhole spine surgery works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Small incision\u003c/b>\u003cspan>Often under 2.5 cm\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Tubular retractor\u003c/b>\u003cspan>Gently separates muscles\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Camera or microscope\u003c/b>\u003cspan>Magnified view of nerves\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Targeted repair\u003c/b>\u003cspan>Disc or bone removed; nerves freed\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"common-minimally-invasive-procedures\">Common minimally invasive procedures\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Microdiscectomy / endoscopic discectomy:\u003c/strong> removal of a herniated disc fragment pressing on a nerve\u003c/li>\n\u003cli>\u003cstrong>Minimally invasive decompression:\u003c/strong> creating space for nerves in spinal stenosis\u003c/li>\n\u003cli>\u003cstrong>MIS fusion (such as MIS TLIF):\u003c/strong> stabilising the spine with screws and a spacer through small incisions\u003c/li>\n\u003cli>\u003cstrong>Kyphoplasty / vertebroplasty:\u003c/strong> injecting bone cement to treat certain painful spinal fractures\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"possible-benefits\">Possible benefits\u003c/h2>\u003cul>\n\u003cli>Less muscle injury\u003c/li>\n\u003cli>Smaller scars\u003c/li>\n\u003cli>Less pain after surgery\u003c/li>\n\u003cli>Less blood loss\u003c/li>\n\u003cli>Shorter hospital stay, sometimes same-day discharge\u003c/li>\n\u003cli>Faster return to daily activities\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"limitations\">Limitations\u003c/h2>\u003cul>\n\u003cli>Not suitable for every spinal condition, such as some complex deformities, large tumours or severe instability\u003c/li>\n\u003cli>Requires specialised training and equipment\u003c/li>\n\u003cli>Long-term results for many conditions are similar to open surgery; the main advantage is early recovery\u003c/li>\n\u003cli>Risks still exist, including infection, nerve injury, dural tear (leak of spinal fluid) and the need for further surgery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-is-suitable\">Who is suitable?\u003c/h2>\u003cp>Your surgeon will consider:\u003c/p>\n\u003cul>\n\u003cli>The exact diagnosis and its location\u003c/li>\n\u003cli>The number of spinal levels involved\u003c/li>\n\u003cli>Your bone quality and overall health\u003c/li>\n\u003cli>Previous spine surgery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cul>\n\u003cli>Walking often begins on the same day\u003c/li>\n\u003cli>Hospital stay of 0 to 3 days for most procedures\u003c/li>\n\u003cli>Return to desk work in 1 to 4 weeks\u003c/li>\n\u003cli>Physiotherapy to strengthen the back and core\u003c/li>\n\u003c/ul>\n\u003cp>Fusion surgery takes longer to recover from than discectomy or decompression.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you have been advised spine surgery, ask whether a minimally invasive approach is suitable for your condition, and what the surgeon&#39;s experience is with it.\u003c/p>\n","faqs":[{"q":"Is keyhole spine surgery done under general anaesthesia?","a":"Usually yes, though some endoscopic procedures can be done under local or regional anaesthesia."},{"q":"Is minimally invasive surgery always better?","a":"Not always. The right procedure depends on your condition."},{"q":"Can laser surgery fix a slip disc?","a":"\"Laser spine surgery\" is often a marketing term. Ask exactly what procedure is planned and what evidence supports it."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"common-minimally-invasive-procedures","text":"Common minimally invasive procedures"},{"id":"possible-benefits","text":"Possible benefits"},{"id":"limitations","text":"Limitations"},{"id":"who-is-suitable","text":"Who is suitable?"},{"id":"recovery","text":"Recovery"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":401,"read":2},{"slug":"total-disc-replacement","sp":"spine","title":"Total Disc Replacement: How Does It Work?","seo":"Artificial Disc Replacement: How It Works, Who It Suits & Recovery","desc":"Learn how artificial disc replacement preserves neck or back movement, how it compares with spinal fusion, who is a good candidate and recovery.","kw":["total disc replacement","artificial disc replacement","cervical disc replacement","lumbar disc replacement","disc replacement vs fusion"],"links":["cervical-spondylosis-neck-pain","when-is-spine-surgery-necessary","recovery-after-spine-surgery"],"video":null,"flow":null,"img":["Artificial disc implant between two vertebrae","Disc replacement (moves) vs fusion (fixed) comparison","Cervical disc replacement through the front of the neck"],"html":"\u003cp>Total disc replacement removes a damaged spinal disc and replaces it with an artificial one. Unlike spinal fusion, which joins two vertebrae permanently, a disc replacement is designed to \u003cstrong>keep movement\u003c/strong> in that part of the spine.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>An artificial disc is usually made of metal plates with a plastic or metal core. It sits between two vertebrae and allows them to bend and rotate, similar to a natural disc.\u003c/p>\n\u003cp>It is performed in:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>The neck (cervical disc replacement):\u003c/strong> the more common use\u003c/li>\n\u003cli>\u003cstrong>The lower back (lumbar disc replacement):\u003c/strong> for carefully selected patients\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-may-benefit\">Who may benefit?\u003c/h2>\u003cp>\u003cstrong>Cervical disc replacement\u003c/strong> may be considered for:\u003c/p>\n\u003cul>\n\u003cli>A herniated disc or bone spur in the neck pressing on a nerve or the spinal cord\u003c/li>\n\u003cli>Arm pain, numbness or weakness that has not improved with treatment\u003c/li>\n\u003cli>Usually one or two affected levels\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Lumbar disc replacement\u003c/strong> may be considered for:\u003c/p>\n\u003cul>\n\u003cli>Severe low back pain caused by a damaged disc at one level\u003c/li>\n\u003cli>When non-surgical treatment has failed for an extended period\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-is-not-suitable\">Who is not suitable?\u003c/h2>\u003cul>\n\u003cli>Significant arthritis of the spinal facet joints\u003c/li>\n\u003cli>Osteoporosis (weak bones)\u003c/li>\n\u003cli>Spinal instability or significant deformity\u003c/li>\n\u003cli>Active infection\u003c/li>\n\u003cli>Previous surgery at that level in some cases\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"disc-replacement-vs-fusion\">Disc replacement vs fusion\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Disc replacement\u003c/th>\n\u003cth>Fusion\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Movement at treated level\u003c/td>\n\u003ctd>Preserved\u003c/td>\n\u003ctd>Permanently stopped\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stress on neighbouring discs\u003c/td>\n\u003ctd>May be lower\u003c/td>\n\u003ctd>May be higher over time\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Suitable for\u003c/td>\n\u003ctd>Selected patients with good bone and joints\u003c/td>\n\u003ctd>A wider range of conditions\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Recovery\u003c/td>\n\u003ctd>Often quicker\u003c/td>\n\u003ctd>Bone takes months to fuse\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003cp>For the neck, the surgeon makes a small incision at the front, moves soft tissues aside, removes the damaged disc and any bone spurs, and inserts the implant. Surgery usually takes 1 to 2 hours, with a hospital stay of 1 to 2 days.\u003c/p>\n\u003cp>Lumbar disc replacement is approached through the abdomen and is a larger operation.\u003c/p>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cul>\n\u003cli>Walking on the day of or day after surgery\u003c/li>\n\u003cli>Return to light activities in 1 to 2 weeks\u003c/li>\n\u003cli>Most normal activities within 6 to 12 weeks\u003c/li>\n\u003cli>Physiotherapy as advised\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you have been offered spinal fusion, ask whether disc replacement is an option for your condition.\u003c/p>\n","faqs":[{"q":"How long does an artificial disc last?","a":"Long-term studies show good durability for many years."},{"q":"Will I set off airport metal detectors?","a":"Possibly. Carry your implant card."},{"q":"Is disc replacement suitable for older patients?","a":"It depends on bone strength and joint health more than age."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"who-may-benefit","text":"Who may benefit?"},{"id":"who-is-not-suitable","text":"Who is not suitable?"},{"id":"disc-replacement-vs-fusion","text":"Disc replacement vs fusion"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"recovery","text":"Recovery"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":405,"read":2},{"slug":"spinal-decompression-surgery","sp":"spine","title":"Spine Decompression Surgery Explained","seo":"Spinal Decompression Surgery: Laminectomy, Discectomy & Recovery","desc":"Understand spinal decompression surgery, including laminectomy and discectomy, why it relieves nerve pain, how it is done and what recovery involves.","kw":["spinal decompression surgery","laminectomy","discectomy","foraminotomy","nerve compression surgery"],"links":["spinal-stenosis","minimally-invasive-spine-surgery","recovery-after-spine-surgery"],"video":null,"flow":{"caption":"Decompression in four steps","steps":[{"t":"Identify","d":"MRI pinpoints the compressed nerve"},{"t":"Access","d":"Open or keyhole approach"},{"t":"Remove pressure","d":"Bone, ligament or disc trimmed"},{"t":"Protect stability","d":"Fusion added only if needed"}]},"img":["Compressed spinal nerve before and freed nerve after decompression","Laminectomy: removal of the back part of a vertebra","Types of decompression compared"],"html":"\u003cp>Spine decompression surgery relieves pressure on the spinal cord or nerves. When nerves are squeezed, they cause pain, numbness or weakness in the arms or legs. Creating more space allows them to recover.\u003c/p>\n\u003ch2 id=\"what-causes-nerve-compression\">What causes nerve compression?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Herniated discs\u003c/strong> pushing on a nerve\u003c/li>\n\u003cli>\u003cstrong>Spinal stenosis:\u003c/strong> narrowing of the spinal canal from thickened ligaments and bone spurs\u003c/li>\n\u003cli>\u003cstrong>Bone spurs\u003c/strong> from arthritis\u003c/li>\n\u003cli>\u003cstrong>Spondylolisthesis:\u003c/strong> a vertebra slipping forward\u003c/li>\n\u003cli>Less commonly, tumours or injuries\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Decompression in four steps\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Decompression in four steps\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Identify\u003c/b>\u003cspan>MRI pinpoints the compressed nerve\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Access\u003c/b>\u003cspan>Open or keyhole approach\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Remove pressure\u003c/b>\u003cspan>Bone, ligament or disc trimmed\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Protect stability\u003c/b>\u003cspan>Fusion added only if needed\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"types-of-decompression-surgery\">Types of decompression surgery\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Procedure\u003c/th>\n\u003cth>What is removed\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Discectomy / microdiscectomy\u003c/td>\n\u003ctd>The part of a disc pressing on a nerve\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Laminectomy\u003c/td>\n\u003ctd>The back part of the vertebra (lamina) to widen the canal\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Laminotomy\u003c/td>\n\u003ctd>A smaller part of the lamina\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Foraminotomy\u003c/td>\n\u003ctd>Bone or tissue narrowing the nerve exit opening\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>These can be done through open surgery or minimally invasive techniques.\u003c/p>\n\u003ch2 id=\"when-is-fusion-added\">When is fusion added?\u003c/h2>\u003cp>If removing bone may make the spine unstable, or if instability already exists, the surgeon may also perform a \u003cstrong>spinal fusion\u003c/strong> to join vertebrae together with screws and rods.\u003c/p>\n\u003ch2 id=\"who-may-benefit\">Who may benefit?\u003c/h2>\u003cul>\n\u003cli>Leg or arm pain, numbness or weakness from nerve compression that does not improve with treatment\u003c/li>\n\u003cli>Difficulty walking because of leg pain or heaviness (spinal stenosis)\u003c/li>\n\u003cli>Progressive weakness\u003c/li>\n\u003cli>Signs of spinal cord compression, such as clumsiness of hands or unsteady walking\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003col>\n\u003cli>General anaesthesia is given, and you lie face down.\u003c/li>\n\u003cli>The surgeon reaches the spine through an incision in the back (or the front for some neck surgeries).\u003c/li>\n\u003cli>Bone, ligament or disc material compressing the nerves is carefully removed.\u003c/li>\n\u003cli>Fusion is added if needed.\u003c/li>\n\u003cli>The wound is closed.\u003c/li>\n\u003c/ol>\n\u003cp>Surgery takes about 1 to 3 hours, depending on the number of levels.\u003c/p>\n\u003ch2 id=\"results\">Results\u003c/h2>\u003cp>Decompression is usually most effective for \u003cstrong>leg or arm pain\u003c/strong>. Numbness and weakness may improve more slowly, sometimes over months. Back pain may improve less predictably.\u003c/p>\n\u003ch2 id=\"risks\">Risks\u003c/h2>\u003cp>Infection, bleeding, dural tear (leak of spinal fluid), nerve injury, persistent symptoms and, occasionally, need for further surgery.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a spine surgeon if leg or arm symptoms limit walking or daily activities despite treatment, or if weakness is getting worse.\u003c/p>\n","faqs":[{"q":"How long is the hospital stay?","a":"From the same day to a few days, depending on the procedure."},{"q":"Will I need a brace?","a":"Usually not after simple decompression. Your surgeon will advise."},{"q":"Can the problem come back?","a":"Sometimes, especially as the spine continues to age, but many people have long-lasting relief."}],"toc":[{"id":"what-causes-nerve-compression","text":"What causes nerve compression?"},{"id":"types-of-decompression-surgery","text":"Types of decompression surgery"},{"id":"when-is-fusion-added","text":"When is fusion added?"},{"id":"who-may-benefit","text":"Who may benefit?"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"results","text":"Results"},{"id":"risks","text":"Risks"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":402,"read":2},{"slug":"scoliosis-explained","sp":"spine","title":"Understanding Scoliosis","seo":"Scoliosis: Signs, Causes, Diagnosis & Treatment in Children and Adults","desc":"Learn what scoliosis is, how to spot an abnormal spinal curve in children and adults, how it is measured, and when bracing or surgery is advised.","kw":["scoliosis","curved spine","scoliosis in children","scoliosis brace","scoliosis surgery"],"links":["when-is-spine-surgery-necessary","recovery-after-spine-surgery","spinal-stenosis"],"video":null,"flow":null,"img":["Normal spine vs S-shaped scoliosis curve from behind","Forward bend test showing a rib hump","Cobb angle measurement on X-ray"],"html":"\u003cp>Scoliosis is a sideways curve of the spine. Seen from behind, a normal spine looks straight, while a spine with scoliosis looks like a &quot;C&quot; or &quot;S&quot;. Most cases are mild and need only monitoring, but some need treatment to stop the curve getting worse.\u003c/p>\n\u003ch2 id=\"types-of-scoliosis\">Types of scoliosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Idiopathic scoliosis:\u003c/strong> the most common type; the cause is unknown. It usually appears in adolescents between 10 and 18, more often in girls.\u003c/li>\n\u003cli>\u003cstrong>Congenital scoliosis:\u003c/strong> caused by spinal bones that formed abnormally before birth\u003c/li>\n\u003cli>\u003cstrong>Neuromuscular scoliosis:\u003c/strong> linked to conditions such as cerebral palsy or muscular dystrophy\u003c/li>\n\u003cli>\u003cstrong>Degenerative (adult) scoliosis:\u003c/strong> develops in older adults due to wear of discs and joints\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"signs-to-look-for\">Signs to look for\u003c/h2>\u003cul>\n\u003cli>Uneven shoulders\u003c/li>\n\u003cli>One shoulder blade sticking out more than the other\u003c/li>\n\u003cli>Uneven waist or hips\u003c/li>\n\u003cli>The body leaning to one side\u003c/li>\n\u003cli>A rib hump when bending forward\u003c/li>\n\u003cli>Clothes hanging unevenly\u003c/li>\n\u003c/ul>\n\u003cp>In adults, scoliosis may cause back pain, leg pain from nerve compression, or loss of height.\u003c/p>\n\u003cp>Mild scoliosis is often painless and may be noticed first by parents, teachers or tailors.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Forward bend test:\u003c/strong> the doctor looks for a rib hump\u003c/li>\n\u003cli>\u003cstrong>Full-spine X-ray:\u003c/strong> the curve is measured in degrees, called the \u003cstrong>Cobb angle\u003c/strong>\u003c/li>\n\u003cli>MRI or CT in some cases\u003c/li>\n\u003c/ul>\n\u003cp>A curve of 10 degrees or more is considered scoliosis.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>Treatment depends on the curve size, the person&#39;s age and how much growing is left:\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Curve size (approximate)\u003c/th>\n\u003cth>Usual approach\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Under 20–25 degrees\u003c/td>\n\u003ctd>Observation with regular X-rays\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>25–45 degrees in a growing child\u003c/td>\n\u003ctd>Brace, worn many hours a day\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Over 45–50 degrees\u003c/td>\n\u003ctd>Surgery may be considered\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>\u003cstrong>Physiotherapy and scoliosis-specific exercises\u003c/strong> can help with posture, strength and pain.\u003c/p>\n\u003ch2 id=\"surgery\">Surgery\u003c/h2>\u003cp>The most common operation is \u003cstrong>spinal fusion\u003c/strong>, where screws and rods are used to straighten and stabilise the spine. Newer growth-friendly techniques are used for some young children.\u003c/p>\n\u003ch2 id=\"living-with-scoliosis\">Living with scoliosis\u003c/h2>\u003cp>Most people with scoliosis lead full, active lives, including sports, careers and pregnancy.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a spine specialist if you notice uneven shoulders, hips or a rib hump in a child, especially during growth spurts. Early detection gives more treatment options.\u003c/p>\n","faqs":[{"q":"Is scoliosis caused by bad posture or heavy school bags?","a":"No. These do not cause scoliosis."},{"q":"Will a brace straighten the spine?","a":"A brace aims to stop the curve getting worse during growth, not to correct it fully."},{"q":"Does scoliosis stop progressing after growth?","a":"Mild curves often stop; larger curves may continue to progress slowly in adulthood."}],"toc":[{"id":"types-of-scoliosis","text":"Types of scoliosis"},{"id":"signs-to-look-for","text":"Signs to look for"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"surgery","text":"Surgery"},{"id":"living-with-scoliosis","text":"Living with scoliosis"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":412,"read":2},{"slug":"sciatica-explained","sp":"spine","title":"Sciatica: Causes, Symptoms and Treatment","seo":"Sciatica: Causes, Symptoms, Exercises & Treatment Options","desc":"Understand sciatica, the shooting leg pain caused by an irritated sciatic nerve: common causes, symptoms, self-care, treatments and when to worry.","kw":["sciatica","sciatic nerve pain","leg pain from back","sciatica treatment","sciatica exercises"],"links":["slip-disc-symptoms","spinal-stenosis","minimally-invasive-spine-surgery"],"video":null,"flow":null,"img":["Path of the sciatic nerve from the lower back down the leg","Common causes: disc, stenosis, piriformis","Gentle nerve-friendly exercises"],"html":"\u003cp>Sciatica is pain that travels along the path of the sciatic nerve, from the lower back through the buttock and down the leg. It is a symptom rather than a disease, and it usually improves within weeks.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>The sciatic nerve is the longest nerve in the body. It is formed by nerve roots from the lower back that join together and run down each leg. When one of these roots is irritated or squeezed, pain can shoot down the leg.\u003c/p>\n\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cul>\n\u003cli>Pain spreading from the lower back or buttock down the back of one leg, often below the knee\u003c/li>\n\u003cli>Burning, sharp or electric-shock-like pain\u003c/li>\n\u003cli>Numbness or tingling in the leg or foot\u003c/li>\n\u003cli>Weakness in the leg or foot\u003c/li>\n\u003cli>Pain worse when sitting, coughing or sneezing\u003c/li>\n\u003c/ul>\n\u003cp>Usually only one leg is affected.\u003c/p>\n\u003ch2 id=\"common-causes\">Common causes\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Herniated (slip) disc:\u003c/strong> the most common cause, especially in people aged 30 to 50\u003c/li>\n\u003cli>\u003cstrong>Lumbar spinal stenosis:\u003c/strong> narrowing of the spinal canal, more common in older adults\u003c/li>\n\u003cli>\u003cstrong>Spondylolisthesis:\u003c/strong> one vertebra slipping forward\u003c/li>\n\u003cli>\u003cstrong>Piriformis syndrome:\u003c/strong> a buttock muscle irritating the nerve\u003c/li>\n\u003cli>Rarely, infection, tumour or injury\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"risk-factors\">Risk factors\u003c/h2>\u003cul>\n\u003cli>Prolonged sitting or driving\u003c/li>\n\u003cli>Heavy lifting and twisting\u003c/li>\n\u003cli>Excess body weight\u003c/li>\n\u003cli>Diabetes, which can increase nerve sensitivity\u003c/li>\n\u003cli>Ageing\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>Your doctor will examine your strength, reflexes and sensation, and may do a \u003cstrong>straight leg raise test\u003c/strong>. An MRI is usually needed only if symptoms are severe, persist beyond 6 weeks, or there are red flags.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>\u003cstrong>Self-care:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Stay active with gentle walking\u003c/li>\n\u003cli>Avoid prolonged sitting; take breaks\u003c/li>\n\u003cli>Use heat or cold packs\u003c/li>\n\u003cli>Gentle stretches as advised\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Medical treatment:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Pain-relief and nerve-pain medicines\u003c/li>\n\u003cli>Physiotherapy to strengthen the core and improve flexibility\u003c/li>\n\u003cli>\u003cstrong>Epidural steroid injection\u003c/strong> for severe pain\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Surgery\u003c/strong> is considered when pain is severe and persistent, or there is progressive weakness.\u003c/p>\n\u003ch2 id=\"red-flags-seek-urgent-care\">Red flags: seek urgent care\u003c/h2>\u003cul>\n\u003cli>Pain in both legs\u003c/li>\n\u003cli>Numbness around the genitals or buttocks\u003c/li>\n\u003cli>Loss of bladder or bowel control\u003c/li>\n\u003cli>Rapidly worsening leg weakness\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a doctor if sciatica lasts more than a few weeks, is severe, or is accompanied by numbness or weakness.\u003c/p>\n","faqs":[{"q":"How long does sciatica last?","a":"Most episodes improve within 4 to 6 weeks."},{"q":"Is walking good for sciatica?","a":"Yes. Gentle walking is usually helpful."},{"q":"Can sciatica come back?","a":"Yes. Regular exercise, good posture and weight control reduce the risk."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"symptoms","text":"Symptoms"},{"id":"common-causes","text":"Common causes"},{"id":"risk-factors","text":"Risk factors"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"red-flags-seek-urgent-care","text":"Red flags: seek urgent care"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":390,"read":2},{"slug":"cervical-spondylosis-neck-pain","sp":"spine","title":"Cervical Spondylosis and Neck Pain","seo":"Cervical Spondylosis: Neck Pain Symptoms, Causes & Treatment","desc":"Learn about cervical spondylosis, the age-related wear of the neck spine: symptoms, nerve and spinal cord warning signs, treatment and posture tips.","kw":["cervical spondylosis","neck pain","cervical radiculopathy","cervical myelopathy","neck posture"],"links":["total-disc-replacement","spinal-decompression-surgery","slip-disc-symptoms"],"video":null,"flow":null,"img":["Neck spine with disc wear and bone spurs","Correct workstation and phone posture","Neck strengthening exercises"],"html":"\u003cp>Cervical spondylosis is the general term for age-related wear and tear of the discs and joints in the neck. It is very common, especially after 40, and in most people causes only occasional neck stiffness or pain.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>Over time, the discs in the neck lose water and height, and the joints develop \u003cstrong>bone spurs\u003c/strong>. These changes are part of normal ageing and appear on many X-rays even in people without symptoms.\u003c/p>\n\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cp>\u003cstrong>Neck symptoms:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Neck pain and stiffness\u003c/li>\n\u003cli>Pain spreading to the shoulders or between the shoulder blades\u003c/li>\n\u003cli>Headaches starting at the back of the head\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Nerve root compression (cervical radiculopathy):\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Pain shooting down the arm\u003c/li>\n\u003cli>Numbness or tingling in the hand or fingers\u003c/li>\n\u003cli>Weakness in the arm or grip\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Spinal cord compression (cervical myelopathy):\u003c/strong> less common but more serious\u003c/p>\n\u003cul>\n\u003cli>Clumsiness of the hands, such as difficulty buttoning or writing\u003c/li>\n\u003cli>Unsteady walking or poor balance\u003c/li>\n\u003cli>Numbness in the hands or legs\u003c/li>\n\u003cli>Bladder problems in advanced cases\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"risk-factors\">Risk factors\u003c/h2>\u003cul>\n\u003cli>Age\u003c/li>\n\u003cli>Long hours looking down at phones or laptops\u003c/li>\n\u003cli>Jobs involving repeated neck movement or heavy loads on the head\u003c/li>\n\u003cli>Previous neck injury\u003c/li>\n\u003cli>Smoking\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>Examination of neck movement, strength, reflexes and walking\u003c/li>\n\u003cli>\u003cstrong>X-ray\u003c/strong> to see bone changes\u003c/li>\n\u003cli>\u003cstrong>MRI\u003c/strong> if there are nerve or spinal cord symptoms\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>Most people improve with:\u003c/p>\n\u003cul>\n\u003cli>Posture correction and regular breaks from screens\u003c/li>\n\u003cli>Neck stretching and strengthening exercises\u003c/li>\n\u003cli>\u003cstrong>Physiotherapy\u003c/strong>\u003c/li>\n\u003cli>Pain-relief medicines, used as advised\u003c/li>\n\u003cli>A soft collar only for short periods during severe pain\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Surgery\u003c/strong> may be advised for:\u003c/p>\n\u003cul>\n\u003cli>Spinal cord compression (myelopathy)\u003c/li>\n\u003cli>Persistent arm pain or weakness despite treatment\u003c/li>\n\u003c/ul>\n\u003cp>Options include anterior cervical discectomy and fusion (ACDF), cervical disc replacement, or posterior decompression.\u003c/p>\n\u003ch2 id=\"everyday-tips\">Everyday tips\u003c/h2>\u003cul>\n\u003cli>Keep screens at eye level\u003c/li>\n\u003cli>Hold your phone up rather than bending your neck down\u003c/li>\n\u003cli>Use a supportive pillow that keeps your neck in line with your spine\u003c/li>\n\u003cli>Take a break every 30 to 45 minutes\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a spine specialist if neck pain spreads into the arm, or if you notice clumsy hands or unsteady walking. These symptoms need prompt evaluation.\u003c/p>\n","faqs":[{"q":"Is cervical spondylosis the same as arthritis?","a":"It is a form of age-related arthritis of the neck."},{"q":"Should I wear a neck collar all the time?","a":"No. Long-term use weakens neck muscles."},{"q":"Can neck pain cause dizziness?","a":"It can be associated, but dizziness has many causes and should be evaluated."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"symptoms","text":"Symptoms"},{"id":"risk-factors","text":"Risk factors"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"everyday-tips","text":"Everyday tips"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":398,"read":2},{"slug":"spinal-stenosis","sp":"spine","title":"Spinal Stenosis: Symptoms and Treatment","seo":"Lumbar Spinal Stenosis: Symptoms, Diagnosis & Treatment Options","desc":"Learn how spinal stenosis causes leg pain and heaviness when walking, how it differs from circulation problems, and the treatments that help.","kw":["spinal stenosis","lumbar canal stenosis","neurogenic claudication","leg pain when walking","spinal stenosis treatment"],"links":["spinal-decompression-surgery","sciatica-explained","minimally-invasive-spine-surgery"],"video":null,"flow":null,"img":["Normal spinal canal vs narrowed canal in cross-section","\"Shopping cart sign\": leaning forward eases symptoms","Exercise bike as a stenosis-friendly activity"],"html":"\u003cp>Spinal stenosis is a narrowing of the spaces inside the spine that puts pressure on the nerves. It most commonly affects the lower back in people over 50, and it typically causes leg pain or heaviness when walking.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>With age, discs lose height, ligaments thicken and bone spurs form. Together, these changes narrow the \u003cstrong>spinal canal\u003c/strong> or the openings where nerves leave the spine. The nerves then have less room, especially when standing upright.\u003c/p>\n\u003cp>Stenosis can occur in:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>The lower back (lumbar stenosis):\u003c/strong> the most common\u003c/li>\n\u003cli>\u003cstrong>The neck (cervical stenosis):\u003c/strong> can compress the spinal cord\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms-of-lumbar-stenosis\">Symptoms of lumbar stenosis\u003c/h2>\u003cul>\n\u003cli>Pain, cramping, heaviness or numbness in the buttocks and legs when \u003cstrong>standing or walking\u003c/strong>\u003c/li>\n\u003cli>Symptoms that ease when \u003cstrong>sitting or bending forward\u003c/strong>\u003c/li>\n\u003cli>Reduced walking distance over time\u003c/li>\n\u003cli>Lower back pain\u003c/li>\n\u003cli>Weakness in the legs in advanced cases\u003c/li>\n\u003c/ul>\n\u003cp>Many people find they can walk further when leaning on a shopping trolley, because bending forward opens up the spinal canal.\u003c/p>\n\u003ch2 id=\"stenosis-or-circulation-problem\">Stenosis or circulation problem?\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Spinal stenosis\u003c/th>\n\u003cth>Poor leg circulation\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Relieved by\u003c/td>\n\u003ctd>Sitting or bending forward\u003c/td>\n\u003ctd>Simply standing still\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Cycling\u003c/td>\n\u003ctd>Often comfortable\u003c/td>\n\u003ctd>Often painful\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Pulses in feet\u003c/td>\n\u003ctd>Usually normal\u003c/td>\n\u003ctd>Often weak\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>Your doctor can tell the difference with an examination and tests.\u003c/p>\n\u003ch2 id=\"causes\">Causes\u003c/h2>\u003cul>\n\u003cli>Age-related wear (most common)\u003c/li>\n\u003cli>Spondylolisthesis\u003c/li>\n\u003cli>Previous spinal surgery or injury\u003c/li>\n\u003cli>Being born with a narrow spinal canal\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>MRI:\u003c/strong> the main test\u003c/li>\n\u003cli>CT scan if MRI is not possible\u003c/li>\n\u003cli>Tests to rule out circulation problems if needed\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>\u003cstrong>Non-surgical:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Physiotherapy focusing on core strength and flexibility\u003c/li>\n\u003cli>Exercises such as cycling or water exercise\u003c/li>\n\u003cli>Pain and nerve-pain medicines\u003c/li>\n\u003cli>Epidural steroid injections for symptom relief\u003c/li>\n\u003cli>Weight loss\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Surgery\u003c/strong> is considered when walking distance and quality of life are significantly limited:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Decompression (laminectomy):\u003c/strong> creates more space for the nerves\u003c/li>\n\u003cli>\u003cstrong>Fusion:\u003c/strong> added if the spine is unstable\u003c/li>\n\u003cli>Minimally invasive techniques are available for many patients\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a spine specialist if leg pain limits how far you can walk, or if you notice weakness. Loss of bladder or bowel control needs emergency care.\u003c/p>\n","faqs":[{"q":"Does spinal stenosis get worse over time?","a":"It often progresses slowly, but many people remain stable for years."},{"q":"Can exercise help?","a":"Yes. Targeted exercise often improves walking ability."},{"q":"Is surgery successful for stenosis?","a":"Decompression often improves leg symptoms and walking distance in suitable patients."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"symptoms-of-lumbar-stenosis","text":"Symptoms of lumbar stenosis"},{"id":"stenosis-or-circulation-problem","text":"Stenosis or circulation problem?"},{"id":"causes","text":"Causes"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":384,"read":2},{"slug":"recovery-after-spine-surgery","sp":"spine","title":"Recovery After Spine Surgery: What Should Patients Expect?","seo":"Recovery After Spine Surgery: Timeline, Do's & Don'ts and Warning Signs","desc":"A practical guide to recovering after spine surgery: hospital stay, pain, wound care, walking, sitting, driving, return to work and warning signs.","kw":["recovery after spine surgery","after back surgery care","spine surgery recovery time","spinal fusion recovery","back surgery precautions"],"links":["minimally-invasive-spine-surgery","spinal-decompression-surgery","total-disc-replacement"],"video":null,"flow":{"caption":"Typical recovery after spine surgery","steps":[{"t":"Day 0 to 2","d":"Walking begins; pain control"},{"t":"Weeks 1 to 2","d":"Short walks; wound heals"},{"t":"Weeks 2 to 6","d":"Gradual activity; desk work for many"},{"t":"Months 3 to 6","d":"Full activity; fusion matures"}]},"img":["Log-roll technique for getting out of bed","Do's and don'ts: bending, lifting, twisting","Walking progression plan"],"html":"\u003cp>Recovery after spine surgery depends on the procedure. A simple discectomy may have you back at a desk job in a couple of weeks, while a spinal fusion can take several months to fully heal. Knowing what to expect helps you recover safely and confidently.\u003c/p>\n\u003ch2 id=\"in-hospital\">In hospital\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Walking begins early,\u003c/strong> often on the same day or the next day\u003c/li>\n\u003cli>Pain is managed with medicines; let the team know if pain is not controlled\u003c/li>\n\u003cli>A physiotherapist teaches you how to get in and out of bed safely using the \u003cstrong>log-roll\u003c/strong> method\u003c/li>\n\u003cli>Hospital stay ranges from same-day discharge to about 5 days, depending on the surgery\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Typical recovery after spine surgery\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Typical recovery after spine surgery\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Day 0 to 2\u003c/b>\u003cspan>Walking begins; pain control\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Weeks 1 to 2\u003c/b>\u003cspan>Short walks; wound heals\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Weeks 2 to 6\u003c/b>\u003cspan>Gradual activity; desk work for many\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Months 3 to 6\u003c/b>\u003cspan>Full activity; fusion matures\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"typical-recovery-by-procedure\">Typical recovery by procedure\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Procedure\u003c/th>\n\u003cth>Return to light activity\u003c/th>\n\u003cth>Fuller recovery\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Microdiscectomy\u003c/td>\n\u003ctd>1 to 2 weeks\u003c/td>\n\u003ctd>6 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Decompression\u003c/td>\n\u003ctd>2 to 4 weeks\u003c/td>\n\u003ctd>6 to 12 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Disc replacement\u003c/td>\n\u003ctd>1 to 2 weeks\u003c/td>\n\u003ctd>6 to 12 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Spinal fusion\u003c/td>\n\u003ctd>4 to 6 weeks\u003c/td>\n\u003ctd>6 to 12 months\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"do-39-s\">Do&#39;s\u003c/h2>\u003cul>\n\u003cli>Walk several times a day, increasing distance gradually\u003c/li>\n\u003cli>Change position often; avoid sitting for long periods\u003c/li>\n\u003cli>Keep the wound clean and dry\u003c/li>\n\u003cli>Take medicines as prescribed\u003c/li>\n\u003cli>Eat a balanced diet with enough protein\u003c/li>\n\u003cli>Begin physiotherapy when advised\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"don-39-ts-for-the-period-your-surgeon-advises\">Don&#39;ts (for the period your surgeon advises)\u003c/h2>\u003cul>\n\u003cli>Do not bend, lift or twist excessively\u003c/li>\n\u003cli>Do not lift heavy objects, often nothing more than 2 to 5 kg initially\u003c/li>\n\u003cli>Do not drive until you can sit comfortably and are off strong painkillers\u003c/li>\n\u003cli>\u003cstrong>Do not smoke:\u003c/strong> it slows healing and greatly reduces the success of fusion\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-is-normal\">What is normal?\u003c/h2>\u003cul>\n\u003cli>Some pain and stiffness around the incision\u003c/li>\n\u003cli>Leg pain often improves quickly; numbness and tingling may take weeks to months\u003c/li>\n\u003cli>Tiredness for a few weeks\u003c/li>\n\u003cli>Good and bad days during recovery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-work\">Returning to work\u003c/h2>\u003cul>\n\u003cli>Desk work: often after 2 to 6 weeks\u003c/li>\n\u003cli>Physical or manual work: often after 6 to 12 weeks or longer, especially after fusion\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"warning-signs-contact-your-surgeon-urgently\">Warning signs: contact your surgeon urgently\u003c/h2>\u003cul>\n\u003cli>Fever, redness, swelling or discharge from the wound\u003c/li>\n\u003cli>Clear fluid leaking from the wound\u003c/li>\n\u003cli>Severe headache when sitting or standing\u003c/li>\n\u003cli>New or worsening leg weakness or numbness\u003c/li>\n\u003cli>Loss of bladder or bowel control (emergency)\u003c/li>\n\u003cli>Calf pain or breathlessness\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"long-term-spine-health\">Long-term spine health\u003c/h2>\u003cul>\n\u003cli>Continue core-strengthening exercises\u003c/li>\n\u003cli>Maintain a healthy weight\u003c/li>\n\u003cli>Use good posture and lifting technique\u003c/li>\n\u003cli>Stay active\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"When can I sleep in my normal position?","a":"Most people can sleep in a comfortable position soon after surgery."},{"q":"Will I need to wear a brace?","a":"Only after certain surgeries. Your surgeon will advise."},{"q":"Can I travel by air after spine surgery?","a":"Usually yes after a short period. Discuss timing with your surgeon and walk regularly during the flight."}],"toc":[{"id":"in-hospital","text":"In hospital"},{"id":"typical-recovery-by-procedure","text":"Typical recovery by procedure"},{"id":"do-39-s","text":"Do&#39;s"},{"id":"don-39-ts-for-the-period-your-surgeon-advises","text":"Don&#39;ts (for the period your surgeon advises)"},{"id":"what-is-normal","text":"What is normal?"},{"id":"returning-to-work","text":"Returning to work"},{"id":"warning-signs-contact-your-surgeon-urgently","text":"Warning signs: contact your surgeon urgently"},{"id":"long-term-spine-health","text":"Long-term spine health"}],"words":428,"read":2},{"slug":"causes-of-hair-loss","sp":"hair-transplant","title":"What Causes Hair Loss?","seo":"Causes of Hair Loss in Men & Women: Types, Tests & Treatment","desc":"Learn the common causes of hair loss, from genetic pattern baldness to stress, thyroid problems and nutrition, and how doctors find the cause.","kw":["causes of hair loss","hair fall","androgenetic alopecia","telogen effluvium","alopecia areata"],"links":["hair-loss-men-vs-women","hair-transplant-candidate","hair-transplant-myths"],"video":null,"flow":null,"img":["Hair growth cycle: growth, resting and shedding phases","Patterns of hair loss: receding hairline, crown thinning, patchy loss","Blood tests commonly done for hair fall"],"html":"\u003cp>Losing 50 to 100 hairs a day is normal. Hair loss becomes a concern when you notice thinning, a receding hairline, bald patches or much more shedding than usual. Finding the cause is the first step to the right treatment.\u003c/p>\n\u003ch2 id=\"how-hair-grows\">How hair grows\u003c/h2>\u003cp>Each hair goes through a cycle: a long \u003cstrong>growth phase\u003c/strong> lasting several years, a short transition phase, and a \u003cstrong>resting phase\u003c/strong> after which the hair falls out and a new one grows. Hair loss happens when this cycle is disrupted.\u003c/p>\n\u003ch2 id=\"common-causes\">Common causes\u003c/h2>\u003cp>\u003cstrong>1. Pattern hair loss (androgenetic alopecia)\u003c/strong>\nThe most common cause in both men and women. It is inherited and linked to hormones. Hair follicles gradually shrink and produce thinner, shorter hairs.\u003c/p>\n\u003cp>\u003cstrong>2. Telogen effluvium (temporary shedding)\u003c/strong>\nHeavy shedding 2 to 3 months after a trigger, such as:\u003c/p>\n\u003cul>\n\u003cli>High fever, dengue, typhoid or COVID-19\u003c/li>\n\u003cli>Surgery or major illness\u003c/li>\n\u003cli>Childbirth\u003c/li>\n\u003cli>Severe stress\u003c/li>\n\u003cli>Crash dieting\u003c/li>\n\u003c/ul>\n\u003cp>Hair usually regrows within 6 to 12 months once the trigger passes.\u003c/p>\n\u003cp>\u003cstrong>3. Medical conditions\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Thyroid disorders\u003c/li>\n\u003cli>Iron deficiency and anaemia\u003c/li>\n\u003cli>Polycystic ovary syndrome (PCOS)\u003c/li>\n\u003cli>Vitamin D or B12 deficiency\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>4. Alopecia areata\u003c/strong>\nAn autoimmune condition causing round, smooth bald patches.\u003c/p>\n\u003cp>\u003cstrong>5. Medicines and treatments\u003c/strong>\nChemotherapy, some blood pressure medicines, and others.\u003c/p>\n\u003cp>\u003cstrong>6. Hair care practices\u003c/strong>\nTight hairstyles (traction alopecia), harsh chemical treatments and excessive heat styling.\u003c/p>\n\u003cp>\u003cstrong>7. Scarring alopecias\u003c/strong>\nRare conditions that permanently destroy hair follicles.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>A dermatologist or hair specialist will:\u003c/p>\n\u003cul>\n\u003cli>Ask about your history, diet, medicines and family history\u003c/li>\n\u003cli>Examine your scalp, sometimes with a magnifying device (\u003cstrong>trichoscopy\u003c/strong>)\u003c/li>\n\u003cli>Perform a \u003cstrong>pull test\u003c/strong> to check shedding\u003c/li>\n\u003cli>Order blood tests such as thyroid function, iron levels, vitamin D and B12, and hormone tests in women\u003c/li>\n\u003cli>Occasionally take a small scalp biopsy\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"treatment-depends-on-the-cause\">Treatment depends on the cause\u003c/h2>\u003cul>\n\u003cli>Correcting deficiencies or treating thyroid problems\u003c/li>\n\u003cli>Medicines approved for pattern hair loss\u003c/li>\n\u003cli>Treatments for autoimmune hair loss\u003c/li>\n\u003cli>Hair transplantation for stable, permanent pattern hair loss\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a dermatologist if hair loss is sudden, patchy, accompanied by scalp pain or itching, or getting steadily worse.\u003c/p>\n","faqs":[{"q":"Does frequent shampooing cause hair loss?","a":"No. Hair seen during washing was already due to fall."},{"q":"Can stress cause hair loss?","a":"Yes. Severe stress can trigger temporary shedding."},{"q":"Is hair loss always permanent?","a":"No. Many causes, such as temporary shedding and deficiencies, are reversible."}],"toc":[{"id":"how-hair-grows","text":"How hair grows"},{"id":"common-causes","text":"Common causes"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-depends-on-the-cause","text":"Treatment depends on the cause"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":382,"read":2},{"slug":"fue-vs-fut","sp":"hair-transplant","title":"FUE Versus FUT Hair Transplantation","seo":"FUE vs FUT Hair Transplant: Differences, Pros, Cons & Which to Choose","desc":"Compare FUE and FUT hair transplant techniques: how grafts are harvested, scarring, recovery, graft numbers and which method may suit you.","kw":["FUE vs FUT","FUE hair transplant","FUT strip method","hair transplant techniques","follicular unit extraction"],"links":["hair-transplant-procedure","hair-transplant-grafts","hair-transplant-candidate"],"video":null,"flow":{"caption":"Two ways to harvest grafts","steps":[{"t":"FUE","d":"Individual follicles punched out one by one"},{"t":"FUT","d":"A thin strip of scalp removed and divided"},{"t":"Both","d":"Grafts placed in tiny slits in thinning areas"},{"t":"Result","d":"Natural growth over 9 to 12 months"}]},"img":["FUE extraction with tiny circular punches vs FUT strip removal","Donor area appearance after FUE (dots) vs FUT (linear scar)","Graft placement in the recipient area"],"html":"\u003cp>FUE and FUT are the two main techniques used in modern hair transplantation. Both move hair follicles from the back and sides of the scalp, where hair is usually permanent, to thinning areas. The difference is how the follicles are removed.\u003c/p>\n\u003ch2 id=\"what-is-fue\">What is FUE?\u003c/h2>\u003cp>\u003cstrong>Follicular Unit Extraction (FUE)\u003c/strong> removes individual follicular units, natural groups of 1 to 4 hairs, one at a time using a tiny circular punch, usually under 1 mm. The donor area heals with very small dot-like scars that are hard to see once hair grows back.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Two ways to harvest grafts\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Two ways to harvest grafts\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>FUE\u003c/b>\u003cspan>Individual follicles punched out one by one\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>FUT\u003c/b>\u003cspan>A thin strip of scalp removed and divided\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Both\u003c/b>\u003cspan>Grafts placed in tiny slits in thinning areas\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Result\u003c/b>\u003cspan>Natural growth over 9 to 12 months\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"what-is-fut\">What is FUT?\u003c/h2>\u003cp>\u003cstrong>Follicular Unit Transplantation (FUT)\u003c/strong>, also called the strip method, removes a thin strip of skin from the back of the scalp. The strip is divided into individual grafts under a microscope. The wound is stitched, leaving a fine linear scar usually hidden by surrounding hair.\u003c/p>\n\u003ch2 id=\"side-by-side-comparison\">Side-by-side comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>FUE\u003c/th>\n\u003cth>FUT\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Harvesting\u003c/td>\n\u003ctd>Individual follicles\u003c/td>\n\u003ctd>A strip of scalp\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Donor scar\u003c/td>\n\u003ctd>Tiny dots\u003c/td>\n\u003ctd>A thin line\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Stitches\u003c/td>\n\u003ctd>None in donor area\u003c/td>\n\u003ctd>Yes, removed after about 10 days\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Short hairstyles\u003c/td>\n\u003ctd>Generally possible\u003c/td>\n\u003ctd>Scar may show with very short hair\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Donor recovery\u003c/td>\n\u003ctd>Usually quicker\u003c/td>\n\u003ctd>A little more tightness and discomfort\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Shaving\u003c/td>\n\u003ctd>Donor area usually shaved\u003c/td>\n\u003ctd>Usually not required\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Graft survival\u003c/td>\n\u003ctd>Good with experienced teams\u003c/td>\n\u003ctd>Good with experienced teams\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"which-technique-is-right-for-you\">Which technique is right for you?\u003c/h2>\u003cp>\u003cstrong>FUE may suit people who:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Prefer to wear their hair short\u003c/li>\n\u003cli>Want to avoid a linear scar\u003c/li>\n\u003cli>Need a small to moderate number of grafts\u003c/li>\n\u003cli>Have a tight scalp\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>FUT may suit people who:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Need a large number of grafts in one session\u003c/li>\n\u003cli>Prefer not to shave the donor area\u003c/li>\n\u003cli>Wear their hair longer\u003c/li>\n\u003c/ul>\n\u003cp>Some surgeons combine both methods to maximise grafts in advanced baldness.\u003c/p>\n\u003ch2 id=\"what-matters-most\">What matters most\u003c/h2>\u003cp>The skill and experience of the surgical team matter more than the technique name. Ask about:\u003c/p>\n\u003cul>\n\u003cli>Who performs each step of the procedure\u003c/li>\n\u003cli>How grafts are handled and stored\u003c/li>\n\u003cli>How the donor area is protected from over-harvesting\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Consult a qualified, registered hair transplant surgeon who can assess your donor area and recommend the most suitable technique.\u003c/p>\n","faqs":[{"q":"Is FUE scarless?","a":"No. FUE leaves tiny dot scars, but they are usually barely visible."},{"q":"Is one method more natural looking?","a":"Both can look natural. Results depend on graft placement and design."},{"q":"Is \"DHI\" a different procedure?","a":"DHI is a variation of FUE that uses an implanter pen for placing grafts."}],"toc":[{"id":"what-is-fue","text":"What is FUE?"},{"id":"what-is-fut","text":"What is FUT?"},{"id":"side-by-side-comparison","text":"Side-by-side comparison"},{"id":"which-technique-is-right-for-you","text":"Which technique is right for you?"},{"id":"what-matters-most","text":"What matters most"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":398,"read":2},{"slug":"hair-transplant-candidate","sp":"hair-transplant","title":"Who Is a Suitable Candidate for Hair Transplant?","seo":"Who Is a Good Candidate for Hair Transplant? Eligibility Explained","desc":"Find out who is suitable for hair transplantation, the importance of donor hair and stable hair loss, and when transplant may not be the right choice.","kw":["hair transplant candidate","hair transplant eligibility","donor area","Norwood scale","hair transplant age"],"links":["causes-of-hair-loss","hair-transplant-procedure","hair-transplant-myths"],"video":null,"flow":null,"img":["Donor area at the back and sides of the scalp","Norwood scale for men and Ludwig scale for women","Consultation with scalp examination"],"html":"\u003cp>Hair transplantation can give natural, permanent results, but it is not suitable for everyone. A careful assessment of your hair loss and donor hair decides whether a transplant will help.\u003c/p>\n\u003ch2 id=\"the-key-requirement-good-donor-hair\">The key requirement: good donor hair\u003c/h2>\u003cp>Hair at the back and sides of the scalp is usually resistant to pattern hair loss. This is the \u003cstrong>donor area\u003c/strong>. A good candidate has enough healthy, dense hair there to cover the thinning areas. Beard and body hair may be used as extra donor sources in selected cases.\u003c/p>\n\u003ch2 id=\"who-may-be-a-good-candidate\">Who may be a good candidate?\u003c/h2>\u003cul>\n\u003cli>Men with \u003cstrong>pattern baldness\u003c/strong> that has stabilised\u003c/li>\n\u003cli>Women with pattern hair loss that is limited to certain areas and with a stable donor area\u003c/li>\n\u003cli>People with hair loss from old scars, burns or previous surgery\u003c/li>\n\u003cli>People wanting to restore eyebrows or beards\u003c/li>\n\u003cli>Those who have realistic expectations about results\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"factors-the-surgeon-considers\">Factors the surgeon considers\u003c/h2>\u003cp>\u003cstrong>Age:\u003c/strong> Very young men may continue to lose hair, so the pattern of future loss must be considered. Many surgeons prefer to wait until hair loss has become more predictable, often after the mid-20s.\u003c/p>\n\u003cp>\u003cstrong>Stage of hair loss:\u003c/strong> Hair loss is graded on scales such as the \u003cstrong>Norwood scale\u003c/strong> for men and the \u003cstrong>Ludwig scale\u003c/strong> for women. Very advanced baldness with limited donor hair may allow only partial coverage.\u003c/p>\n\u003cp>\u003cstrong>Hair characteristics:\u003c/strong> Thick, curly or wavy hair and a small contrast between hair and skin colour can give the appearance of more coverage.\u003c/p>\n\u003cp>\u003cstrong>General health:\u003c/strong> Conditions such as uncontrolled diabetes, bleeding disorders or heart disease need to be evaluated before surgery.\u003c/p>\n\u003ch2 id=\"who-may-not-be-suitable\">Who may not be suitable?\u003c/h2>\u003cul>\n\u003cli>People with \u003cstrong>diffuse thinning\u003c/strong> across the whole scalp, including the donor area\u003c/li>\n\u003cli>Hair loss from causes that may be reversible, such as thyroid disease or deficiencies, which should be treated first\u003c/li>\n\u003cli>Active \u003cstrong>alopecia areata\u003c/strong> or certain scarring scalp conditions\u003c/li>\n\u003cli>People expecting the density they had as teenagers\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"medicines-alongside-transplant\">Medicines alongside transplant\u003c/h2>\u003cp>Transplanted hair is usually long-lasting, but \u003cstrong>native hair\u003c/strong> around it may continue to thin. Your doctor may recommend medicines to protect existing hair.\u003c/p>\n\u003ch2 id=\"the-consultation\">The consultation\u003c/h2>\u003cp>Expect a scalp examination, assessment of donor density, a discussion of your goals and a plan for the hairline. A good surgeon will tell you honestly if transplant is not right for you.\u003c/p>\n","faqs":[{"q":"Can women have hair transplants?","a":"Yes, if hair loss is localised and the donor area is stable."},{"q":"Can I use someone else's hair?","a":"No. Transplants use your own hair to avoid rejection."},{"q":"How many sessions will I need?","a":"Many people need one session; advanced hair loss may need two."}],"toc":[{"id":"the-key-requirement-good-donor-hair","text":"The key requirement: good donor hair"},{"id":"who-may-be-a-good-candidate","text":"Who may be a good candidate?"},{"id":"factors-the-surgeon-considers","text":"Factors the surgeon considers"},{"id":"who-may-not-be-suitable","text":"Who may not be suitable?"},{"id":"medicines-alongside-transplant","text":"Medicines alongside transplant"},{"id":"the-consultation","text":"The consultation"}],"words":419,"read":2},{"slug":"hair-transplant-procedure","sp":"hair-transplant","title":"Hair Transplant Procedure Explained","seo":"Hair Transplant Procedure Step by Step: What Happens on the Day","desc":"A step-by-step guide to the hair transplant procedure: hairline design, anaesthesia, graft harvesting, implantation and what to expect on the day.","kw":["hair transplant procedure","hair transplant steps","hairline design","local anaesthesia hair transplant","hair transplant duration"],"links":["fue-vs-fut","hair-transplant-recovery","hair-transplant-grafts"],"video":null,"flow":{"caption":"Hair transplant day","steps":[{"t":"Planning","d":"Hairline designed and marked"},{"t":"Anaesthesia","d":"Local anaesthesia numbs the scalp"},{"t":"Harvesting","d":"Grafts removed from the donor area"},{"t":"Implantation","d":"Grafts placed into tiny slits"}]},"img":["Hairline design drawn on the forehead","Graft sorting under a microscope","Implantation into recipient sites at natural angles"],"html":"\u003cp>A hair transplant is a day-care procedure performed under local anaesthesia. You stay awake and can usually go home the same evening. Here is what typically happens.\u003c/p>\n\u003ch2 id=\"before-the-procedure\">Before the procedure\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Consultation and planning:\u003c/strong> your surgeon examines your scalp and agrees a plan with you\u003c/li>\n\u003cli>\u003cstrong>Blood tests:\u003c/strong> to check general health and rule out infections or bleeding problems\u003c/li>\n\u003cli>\u003cstrong>Medicines:\u003c/strong> you may be asked to stop blood thinners, certain supplements, alcohol and smoking for some days beforehand\u003c/li>\n\u003cli>\u003cstrong>On the day:\u003c/strong> wash your hair, eat a light breakfast and wear a button-up shirt\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Hair transplant day\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Hair transplant day\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Planning\u003c/b>\u003cspan>Hairline designed and marked\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Anaesthesia\u003c/b>\u003cspan>Local anaesthesia numbs the scalp\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Harvesting\u003c/b>\u003cspan>Grafts removed from the donor area\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Implantation\u003c/b>\u003cspan>Grafts placed into tiny slits\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"step-1-hairline-design\">Step 1: Hairline design\u003c/h2>\u003cp>The surgeon draws the new hairline and marks the areas to be covered. A natural hairline is irregular and matches your age and face shape. You should agree on the design before starting.\u003c/p>\n\u003ch2 id=\"step-2-preparing-the-donor-area\">Step 2: Preparing the donor area\u003c/h2>\u003cp>The donor area is trimmed or shaved, depending on the technique.\u003c/p>\n\u003ch2 id=\"step-3-local-anaesthesia\">Step 3: Local anaesthesia\u003c/h2>\u003cp>The donor and recipient areas are numbed with injections. The first injections may sting briefly. After that, most people feel only pressure.\u003c/p>\n\u003ch2 id=\"step-4-harvesting-grafts\">Step 4: Harvesting grafts\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>FUE:\u003c/strong> individual follicles are removed with a tiny punch\u003c/li>\n\u003cli>\u003cstrong>FUT:\u003c/strong> a thin strip is removed, then divided under a microscope\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"step-5-preparing-grafts\">Step 5: Preparing grafts\u003c/h2>\u003cp>Grafts are sorted by the number of hairs and kept in a cooled solution to protect them.\u003c/p>\n\u003ch2 id=\"step-6-creating-recipient-sites\">Step 6: Creating recipient sites\u003c/h2>\u003cp>Tiny slits are made in the thinning areas. Their \u003cstrong>angle, direction and density\u003c/strong> are crucial for a natural look.\u003c/p>\n\u003ch2 id=\"step-7-implantation\">Step 7: Implantation\u003c/h2>\u003cp>Grafts are placed into the slits. Single-hair grafts are used at the front of the hairline for a soft, natural edge.\u003c/p>\n\u003ch2 id=\"how-long-does-it-take\">How long does it take?\u003c/h2>\u003cp>Usually \u003cstrong>6 to 9 hours\u003c/strong>, depending on the number of grafts. There are breaks for meals and rest. Many people watch films or listen to music.\u003c/p>\n\u003ch2 id=\"after-the-procedure\">After the procedure\u003c/h2>\u003cul>\n\u003cli>The donor area may be bandaged\u003c/li>\n\u003cli>You will receive instructions for sleeping, washing and medicines\u003c/li>\n\u003cli>A follow-up visit is usually scheduled for the next day for the first wash\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"choosing-a-clinic\">Choosing a clinic\u003c/h2>\u003cp>Ensure the procedure is performed by a qualified, registered surgeon, with trained technicians, in a clean, properly equipped facility.\u003c/p>\n","faqs":[{"q":"Is a hair transplant painful?","a":"The anaesthetic injections may sting briefly; after that, the procedure is usually comfortable."},{"q":"Can I go home the same day?","a":"Yes. Hair transplant is usually a day-care procedure."},{"q":"How many grafts will I need?","a":"It depends on the area to be covered and your donor supply. Your surgeon will estimate this."}],"toc":[{"id":"before-the-procedure","text":"Before the procedure"},{"id":"step-1-hairline-design","text":"Step 1: Hairline design"},{"id":"step-2-preparing-the-donor-area","text":"Step 2: Preparing the donor area"},{"id":"step-3-local-anaesthesia","text":"Step 3: Local anaesthesia"},{"id":"step-4-harvesting-grafts","text":"Step 4: Harvesting grafts"},{"id":"step-5-preparing-grafts","text":"Step 5: Preparing grafts"},{"id":"step-6-creating-recipient-sites","text":"Step 6: Creating recipient sites"},{"id":"step-7-implantation","text":"Step 7: Implantation"},{"id":"how-long-does-it-take","text":"How long does it take?"},{"id":"after-the-procedure","text":"After the procedure"},{"id":"choosing-a-clinic","text":"Choosing a clinic"}],"words":410,"read":2},{"slug":"hair-transplant-recovery","sp":"hair-transplant","title":"Recovery After Hair Transplantation","seo":"Hair Transplant Recovery: Day-by-Day Healing in the First Two Weeks","desc":"What to expect in the first two weeks after a hair transplant: swelling, scabs, itching, the first wash and when you can return to work.","kw":["hair transplant recovery","hair transplant healing days","scabs after hair transplant","swelling after hair transplant","return to work after hair transplant"],"links":["hair-transplant-aftercare","hair-transplant-results-timeline","hair-transplant-procedure"],"video":null,"flow":{"caption":"Healing in the first two weeks","steps":[{"t":"Days 1 to 3","d":"Mild discomfort; possible forehead swelling"},{"t":"Days 4 to 7","d":"Small scabs; itching begins"},{"t":"Days 7 to 10","d":"Scabs fall off with gentle washing"},{"t":"Days 10 to 14","d":"Redness fades; donor area healed"}]},"img":["Scalp appearance on day 1, day 7 and day 14","Sleeping position with head elevated","Gentle first wash technique"],"html":"\u003cp>The first two weeks after a hair transplant are about healing the skin and protecting the new grafts. Most people find recovery straightforward with good care. This article covers short-term healing; for long-term growth, see our results timeline.\u003c/p>\n\u003ch2 id=\"day-1-to-3\">Day 1 to 3\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Discomfort:\u003c/strong> mild soreness, mainly in the donor area, controlled with prescribed medicines\u003c/li>\n\u003cli>\u003cstrong>Swelling:\u003c/strong> may appear on the forehead or around the eyes around days 2 to 4. It is temporary and usually settles within a week.\u003c/li>\n\u003cli>\u003cstrong>Sleep\u003c/strong> with your head elevated at about 45 degrees to reduce swelling\u003c/li>\n\u003cli>\u003cstrong>Avoid touching\u003c/strong> the grafts; they are delicate in the first days\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Healing in the first two weeks\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Healing in the first two weeks\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Days 1 to 3\u003c/b>\u003cspan>Mild discomfort; possible forehead swelling\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Days 4 to 7\u003c/b>\u003cspan>Small scabs; itching begins\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Days 7 to 10\u003c/b>\u003cspan>Scabs fall off with gentle washing\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Days 10 to 14\u003c/b>\u003cspan>Redness fades; donor area healed\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"day-4-to-7\">Day 4 to 7\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Tiny scabs\u003c/strong> form around each graft\u003c/li>\n\u003cli>\u003cstrong>Itching\u003c/strong> is common as the skin heals; do not scratch\u003c/li>\n\u003cli>Wash gently as instructed by your clinic\u003c/li>\n\u003cli>Pinkness in the recipient area is normal\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"day-7-to-10\">Day 7 to 10\u003c/h2>\u003cul>\n\u003cli>Scabs soften and fall off with gentle washing\u003c/li>\n\u003cli>Small hairs may come off with the scabs; this is normal\u003c/li>\n\u003cli>Stitches are removed around day 10 if you had FUT\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"day-10-to-14\">Day 10 to 14\u003c/h2>\u003cul>\n\u003cli>Most redness fades, though fair skin may stay pink longer\u003c/li>\n\u003cli>The donor area is usually well healed\u003c/li>\n\u003cli>You can usually resume most routine activities\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-work-and-activities\">Returning to work and activities\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Activity\u003c/th>\n\u003cth>Typical timing\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Desk work\u003c/td>\n\u003ctd>3 to 7 days, depending on comfort with appearance\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Light walking\u003c/td>\n\u003ctd>From the next day\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Gym and heavy exercise\u003c/td>\n\u003ctd>Usually after 2 to 4 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Swimming\u003c/td>\n\u003ctd>Usually after 3 to 4 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Wearing a loose cap\u003c/td>\n\u003ctd>After a few days, if permitted\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"air-travel\">Air travel\u003c/h2>\u003cp>Many people fly home within a few days. Ask your surgeon about timing and how to protect the grafts during travel.\u003c/p>\n\u003ch2 id=\"what-is-normal-and-what-is-not\">What is normal and what is not\u003c/h2>\u003cp>\u003cstrong>Normal:\u003c/strong> mild swelling, itching, tightness, small scabs, temporary numbness\u003c/p>\n\u003cp>\u003cstrong>Contact your clinic if you notice:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Increasing pain or redness after the first few days\u003c/li>\n\u003cli>Pus, discharge or a bad smell\u003c/li>\n\u003cli>Fever\u003c/li>\n\u003cli>Bleeding that does not stop with gentle pressure\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"When can I wash my hair?","a":"Usually from the day after surgery, following your clinic's gentle washing technique."},{"q":"Is swelling a sign that something is wrong?","a":"No. Forehead swelling is common and usually settles within a week."},{"q":"Can I wear a helmet?","a":"Usually not for the first couple of weeks. Ask your surgeon."}],"toc":[{"id":"day-1-to-3","text":"Day 1 to 3"},{"id":"day-4-to-7","text":"Day 4 to 7"},{"id":"day-7-to-10","text":"Day 7 to 10"},{"id":"day-10-to-14","text":"Day 10 to 14"},{"id":"returning-to-work-and-activities","text":"Returning to work and activities"},{"id":"air-travel","text":"Air travel"},{"id":"what-is-normal-and-what-is-not","text":"What is normal and what is not"}],"words":372,"read":2},{"slug":"hair-transplant-grafts","sp":"hair-transplant","title":"Understanding Hair Transplant Grafts","seo":"What Is a Hair Graft? Graft Counts, Hair Density & Donor Limits","desc":"Learn what a hair graft is, how many hairs it contains, how graft numbers are estimated, why the donor supply is limited and what affects survival.","kw":["hair grafts","how many grafts do I need","follicular unit","hair density","graft survival"],"links":["fue-vs-fut","hair-transplant-candidate","hair-transplant-procedure"],"video":null,"flow":null,"img":["Follicular units with 1, 2, 3 and 4 hairs","Single-hair grafts at the hairline, multi-hair behind","Donor area safe zone diagram"],"html":"\u003cp>&quot;Grafts&quot; are the units used to plan and perform a hair transplant. Understanding what a graft is helps you make sense of your treatment plan and set realistic expectations.\u003c/p>\n\u003ch2 id=\"what-is-a-graft\">What is a graft?\u003c/h2>\u003cp>Hair naturally grows in small groups called \u003cstrong>follicular units\u003c/strong>. Each unit usually contains \u003cstrong>1 to 4 hairs\u003c/strong>. In a transplant, each of these units is moved as a single graft.\u003c/p>\n\u003cul>\n\u003cli>On average, a graft contains about 2 to 2.5 hairs\u003c/li>\n\u003cli>So 2,000 grafts may contain roughly 4,000 to 5,000 hairs\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-grafts-are-placed\">How grafts are placed\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Single-hair grafts\u003c/strong> are placed at the front of the hairline for a soft, natural edge\u003c/li>\n\u003cli>\u003cstrong>Two- and three-hair grafts\u003c/strong> are placed behind to build density\u003c/li>\n\u003cli>Grafts follow the natural \u003cstrong>angle and direction\u003c/strong> of hair growth\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-many-grafts-do-you-need\">How many grafts do you need?\u003c/h2>\u003cp>It depends on:\u003c/p>\n\u003cul>\n\u003cli>The size of the area to be covered\u003c/li>\n\u003cli>The density you hope to achieve\u003c/li>\n\u003cli>Your donor area&#39;s capacity\u003c/li>\n\u003cli>Hair characteristics such as thickness and curl\u003c/li>\n\u003c/ul>\n\u003cp>As a broad guide, restoring a receding hairline needs fewer grafts than covering the front and crown together. Your surgeon will give a personalised estimate.\u003c/p>\n\u003ch2 id=\"the-donor-area-is-limited\">The donor area is limited\u003c/h2>\u003cp>Your donor supply is \u003cstrong>finite\u003c/strong>. Over-harvesting can leave the donor area visibly thin. A responsible surgeon:\u003c/p>\n\u003cul>\n\u003cli>Harvests only from the \u003cstrong>safe donor zone\u003c/strong>, where hair is resistant to balding\u003c/li>\n\u003cli>Spreads extraction evenly\u003c/li>\n\u003cli>Plans for possible future hair loss and keeps reserves\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"why-more-grafts-is-not-always-better\">Why more grafts is not always better\u003c/h2>\u003cp>Packing too many grafts too closely can reduce survival and use up donor hair needed later. Good design focuses on \u003cstrong>natural appearance and long-term planning\u003c/strong>, not just a high graft count.\u003c/p>\n\u003ch2 id=\"what-affects-graft-survival\">What affects graft survival?\u003c/h2>\u003cul>\n\u003cli>Gentle handling and minimal time outside the body\u003c/li>\n\u003cli>Correct storage solution and temperature\u003c/li>\n\u003cli>Skilled placement\u003c/li>\n\u003cli>Following aftercare instructions\u003c/li>\n\u003cli>Avoiding smoking\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"body-and-beard-hair\">Body and beard hair\u003c/h2>\u003cp>Beard and body hair can supplement scalp donor hair in some patients, but they may differ in texture and growth.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A qualified hair transplant surgeon can examine your donor density and give you a realistic plan for coverage.\u003c/p>\n","faqs":[{"q":"Are all grafts the same?","a":"No. They contain different numbers of hairs and are placed strategically."},{"q":"Does every graft grow?","a":"Most do with good technique and care, but not all grafts survive."},{"q":"Can I have more grafts later?","a":"Possibly, if your donor area still has enough hair."}],"toc":[{"id":"what-is-a-graft","text":"What is a graft?"},{"id":"how-grafts-are-placed","text":"How grafts are placed"},{"id":"how-many-grafts-do-you-need","text":"How many grafts do you need?"},{"id":"the-donor-area-is-limited","text":"The donor area is limited"},{"id":"why-more-grafts-is-not-always-better","text":"Why more grafts is not always better"},{"id":"what-affects-graft-survival","text":"What affects graft survival?"},{"id":"body-and-beard-hair","text":"Body and beard hair"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":393,"read":2},{"slug":"hair-transplant-myths","sp":"hair-transplant","title":"Common Myths About Hair Transplantation","seo":"Hair Transplant Myths vs Facts: What Is True and What Isn't","desc":"We separate fact from fiction on hair transplants: pain, permanence, results, age, women, donor hair and the promises you should be wary of.","kw":["hair transplant myths","hair transplant facts","is hair transplant permanent","hair transplant side effects","hair transplant truth"],"links":["hair-transplant-candidate","hair-transplant-results-timeline","causes-of-hair-loss"],"video":null,"flow":null,"img":["Myth vs fact infographic","Natural hairline design vs an unnatural straight line","Patient consultation discussing expectations"],"html":"\u003cp>Hair transplantation attracts a lot of advertising and misinformation. Separating myth from fact helps you make a well-informed decision.\u003c/p>\n\u003ch2 id=\"myth-1-hair-transplants-look-fake\">Myth 1: &quot;Hair transplants look fake.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Modern techniques, using individual follicular units placed at natural angles, can give results that look completely natural. Unnatural results usually come from poor planning or technique.\u003c/p>\n\u003ch2 id=\"myth-2-the-procedure-is-very-painful\">Myth 2: &quot;The procedure is very painful.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> It is done under local anaesthesia. Most people feel only the initial injections and mild soreness afterwards.\u003c/p>\n\u003ch2 id=\"myth-3-results-are-immediate\">Myth 3: &quot;Results are immediate.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Transplanted hairs usually shed in the first few weeks. New growth begins around 3 to 4 months, and full results take about 12 months or longer.\u003c/p>\n\u003ch2 id=\"myth-4-transplanted-hair-will-fall-out-again\">Myth 4: &quot;Transplanted hair will fall out again.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Hair taken from the safe donor zone is generally resistant to pattern hair loss and tends to last long term. However, your \u003cstrong>existing native hair\u003c/strong> may continue to thin, which is why ongoing care is important.\u003c/p>\n\u003ch2 id=\"myth-5-you-can-use-hair-from-another-person\">Myth 5: &quot;You can use hair from another person.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Only your own hair can be used. Hair from another person would be rejected by the immune system.\u003c/p>\n\u003ch2 id=\"myth-6-anyone-can-get-a-full-head-of-hair\">Myth 6: &quot;Anyone can get a full head of hair.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Results depend on your donor supply. Very advanced baldness may allow only partial coverage.\u003c/p>\n\u003ch2 id=\"myth-7-hair-transplants-are-only-for-men\">Myth 7: &quot;Hair transplants are only for men.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Women with suitable patterns of hair loss and a stable donor area can benefit.\u003c/p>\n\u003ch2 id=\"myth-8-younger-is-always-better\">Myth 8: &quot;Younger is always better.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Transplanting too early, before hair loss patterns are clear, can lead to an unnatural look as hair loss continues around the grafts.\u003c/p>\n\u003ch2 id=\"myth-9-more-grafts-in-one-day-is-always-better\">Myth 9: &quot;More grafts in one day is always better.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> Excessively large sessions can compromise graft survival and use up limited donor hair.\u003c/p>\n\u003ch2 id=\"myth-10-results-are-guaranteed\">Myth 10: &quot;Results are guaranteed.&quot;\u003c/h2>\u003cp>\u003cstrong>Fact:\u003c/strong> No reputable surgeon can guarantee a specific outcome. Growth varies between individuals. Be cautious of advertisements promising guaranteed results.\u003c/p>\n\u003ch2 id=\"choosing-safely\">Choosing safely\u003c/h2>\u003cul>\n\u003cli>Choose a qualified, registered surgeon\u003c/li>\n\u003cli>Ask who performs each part of the procedure\u003c/li>\n\u003cli>Look for honest discussion of risks and realistic expectations\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Is a hair transplant permanent?","a":"Transplanted hair from the safe donor zone usually lasts long term, but native hair can continue to thin."},{"q":"Can a transplant cause cancer or brain damage?","a":"No. These are myths. The procedure involves only the skin of the scalp."},{"q":"Will people know I had a transplant?","a":"With good technique and after healing, results usually look natural."}],"toc":[{"id":"myth-1-hair-transplants-look-fake","text":"Myth 1: &quot;Hair transplants look fake.&quot;"},{"id":"myth-2-the-procedure-is-very-painful","text":"Myth 2: &quot;The procedure is very painful.&quot;"},{"id":"myth-3-results-are-immediate","text":"Myth 3: &quot;Results are immediate.&quot;"},{"id":"myth-4-transplanted-hair-will-fall-out-again","text":"Myth 4: &quot;Transplanted hair will fall out again.&quot;"},{"id":"myth-5-you-can-use-hair-from-another-person","text":"Myth 5: &quot;You can use hair from another person.&quot;"},{"id":"myth-6-anyone-can-get-a-full-head-of-hair","text":"Myth 6: &quot;Anyone can get a full head of hair.&quot;"},{"id":"myth-7-hair-transplants-are-only-for-men","text":"Myth 7: &quot;Hair transplants are only for men.&quot;"},{"id":"myth-8-younger-is-always-better","text":"Myth 8: &quot;Younger is always better.&quot;"},{"id":"myth-9-more-grafts-in-one-day-is-always-better","text":"Myth 9: &quot;More grafts in one day is always better.&quot;"},{"id":"myth-10-results-are-guaranteed","text":"Myth 10: &quot;Results are guaranteed.&quot;"},{"id":"choosing-safely","text":"Choosing safely"}],"words":394,"read":2},{"slug":"hair-loss-men-vs-women","sp":"hair-transplant","title":"Hair Loss in Men and Women","seo":"Hair Loss in Men vs Women: Patterns, Causes & Treatment Differences","desc":"Understand how hair loss differs between men and women, the common patterns, causes such as PCOS and hormones, and how treatment approaches differ.","kw":["male pattern baldness","female pattern hair loss","hair thinning in women","PCOS hair loss","hair loss treatment"],"links":["causes-of-hair-loss","hair-transplant-candidate","hair-transplant-myths"],"video":null,"flow":null,"img":["Male pattern: receding temples and crown","Female pattern: widening parting and diffuse thinning","Hormonal factors chart"],"html":"\u003cp>Hair loss affects both men and women, but it usually looks different and can have different causes. Understanding these differences helps guide the right treatment.\u003c/p>\n\u003ch2 id=\"hair-loss-in-men\">Hair loss in men\u003c/h2>\u003cp>\u003cstrong>Male pattern baldness\u003c/strong> is the most common type. It typically starts with:\u003c/p>\n\u003cul>\n\u003cli>A receding hairline at the temples\u003c/li>\n\u003cli>Thinning at the crown\u003c/li>\n\u003cli>Gradual progression, which may lead to baldness on top\u003c/li>\n\u003c/ul>\n\u003cp>It is caused by genetics and sensitivity of hair follicles to a hormone called \u003cstrong>DHT\u003c/strong> (dihydrotestosterone). It can begin as early as the late teens or twenties.\u003c/p>\n\u003ch2 id=\"hair-loss-in-women\">Hair loss in women\u003c/h2>\u003cp>\u003cstrong>Female pattern hair loss\u003c/strong> usually looks different:\u003c/p>\n\u003cul>\n\u003cli>A widening centre parting\u003c/li>\n\u003cli>Diffuse thinning over the top of the scalp\u003c/li>\n\u003cli>The front hairline is often preserved\u003c/li>\n\u003cli>Complete baldness is rare\u003c/li>\n\u003c/ul>\n\u003cp>Women are also more likely to have hair loss related to:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Hormonal changes:\u003c/strong> pregnancy, after childbirth, menopause\u003c/li>\n\u003cli>\u003cstrong>PCOS:\u003c/strong> may cause scalp thinning along with acne or excess facial hair\u003c/li>\n\u003cli>\u003cstrong>Thyroid disorders\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Iron deficiency\u003c/strong>, especially with heavy periods\u003c/li>\n\u003cli>\u003cstrong>Tight hairstyles\u003c/strong> (traction alopecia)\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"comparison\">Comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Men\u003c/th>\n\u003cth>Women\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Typical pattern\u003c/td>\n\u003ctd>Receding hairline, crown baldness\u003c/td>\n\u003ctd>Widening parting, diffuse thinning\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Hairline\u003c/td>\n\u003ctd>Often recedes\u003c/td>\n\u003ctd>Usually preserved\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Common contributing factors\u003c/td>\n\u003ctd>Genetics, DHT\u003c/td>\n\u003ctd>Genetics, hormones, deficiencies, thyroid, PCOS\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Tests commonly needed\u003c/td>\n\u003ctd>Often minimal\u003c/td>\n\u003ctd>Blood tests, sometimes hormone profile\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>Both men and women benefit from evaluation by a dermatologist. Women often need blood tests such as iron studies, thyroid function, vitamin levels and hormone tests to find contributing causes.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cp>\u003cstrong>For men:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Medicines approved for male pattern hair loss\u003c/li>\n\u003cli>Hair transplantation for stable patterns with good donor hair\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>For women:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Treating underlying causes, such as iron deficiency or thyroid disease\u003c/li>\n\u003cli>Topical treatments\u003c/li>\n\u003cli>Hormonal therapy in selected cases, prescribed by a doctor\u003c/li>\n\u003cli>Hair transplantation is suitable for some women with localised thinning\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>For both:\u003c/strong> supportive procedures offered at some clinics, healthy diet and gentle hair care.\u003c/p>\n\u003ch2 id=\"emotional-impact\">Emotional impact\u003c/h2>\u003cp>Hair loss can affect confidence and wellbeing in both men and women. It is a valid reason to seek medical advice.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a dermatologist if hair loss is sudden, patchy, causing distress, or associated with other symptoms such as irregular periods or tiredness.\u003c/p>\n","faqs":[{"q":"Is female hair loss always hormonal?","a":"Not always. Genetics, deficiencies and stress also play roles."},{"q":"Do hair loss medicines work for everyone?","a":"No. Responses vary, and medicines need to be continued to maintain benefit."},{"q":"Can postpartum hair loss be permanent?","a":"Usually not. It typically recovers within a year."}],"toc":[{"id":"hair-loss-in-men","text":"Hair loss in men"},{"id":"hair-loss-in-women","text":"Hair loss in women"},{"id":"comparison","text":"Comparison"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"emotional-impact","text":"Emotional impact"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":397,"read":2},{"slug":"hair-transplant-results-timeline","sp":"hair-transplant","title":"What to Expect After a Hair Transplant","seo":"Hair Transplant Results Timeline: Month-by-Month Growth Explained","desc":"A month-by-month guide to hair transplant results, from shock loss and the \"ugly duckling\" phase to new growth and final results at 12 to 18 months.","kw":["hair transplant results timeline","shock loss","hair transplant growth","hair transplant months","final hair transplant results"],"links":["hair-transplant-recovery","hair-transplant-aftercare","hair-transplant-myths"],"video":null,"flow":{"caption":"Month-by-month growth","steps":[{"t":"Weeks 2 to 6","d":"Transplanted hairs shed (normal)"},{"t":"Months 1 to 3","d":"Quiet \"resting\" phase"},{"t":"Months 3 to 6","d":"Fine new hairs appear"},{"t":"Months 6 to 9","d":"Hair thickens and lengthens"},{"t":"Months 12 to 18","d":"Final results visible"}]},"img":["Photo-style illustration timeline: month 1, 4, 8, 12","Hair follicle resting then regrowing","Monthly progress photo checklist"],"html":"\u003cp>Hair transplant results take patience. Understanding the normal growth timeline helps you avoid unnecessary worry. This article covers the long-term growth phase after the first two weeks of healing.\u003c/p>\n\u003ch2 id=\"weeks-2-to-6-shedding-phase\">Weeks 2 to 6: shedding phase\u003c/h2>\u003cp>Most transplanted hairs \u003cstrong>fall out\u003c/strong>. This is normal and expected. The hair shaft sheds, but the \u003cstrong>follicle stays in place\u003c/strong> under the skin, ready to grow new hair.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Month-by-month growth\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Month-by-month growth\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Weeks 2 to 6\u003c/b>\u003cspan>Transplanted hairs shed (normal)\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Months 1 to 3\u003c/b>\u003cspan>Quiet &quot;resting&quot; phase\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Months 3 to 6\u003c/b>\u003cspan>Fine new hairs appear\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Months 6 to 9\u003c/b>\u003cspan>Hair thickens and lengthens\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>Months 12 to 18\u003c/b>\u003cspan>Final results visible\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"months-1-to-3-the-ugly-duckling-phase\">Months 1 to 3: the &quot;ugly duckling&quot; phase\u003c/h2>\u003cp>The scalp may look much as it did before surgery. Some people also notice \u003cstrong>shock loss\u003c/strong>, temporary shedding of existing native hair around the transplanted area. It usually recovers within a few months.\u003c/p>\n\u003ch2 id=\"months-3-to-4-early-growth\">Months 3 to 4: early growth\u003c/h2>\u003cp>Fine, thin new hairs begin to appear. They may be wavy or slightly different in texture at first. Some people notice small pimple-like bumps as hairs emerge, which usually settle on their own.\u003c/p>\n\u003ch2 id=\"months-5-to-8-visible-improvement\">Months 5 to 8: visible improvement\u003c/h2>\u003cp>Hair becomes thicker, longer and more noticeable. Most people see clear improvement during this period.\u003c/p>\n\u003ch2 id=\"months-9-to-12-maturing-results\">Months 9 to 12: maturing results\u003c/h2>\u003cp>Hair continues to thicken and blend with surrounding hair. You can usually style it normally.\u003c/p>\n\u003ch2 id=\"months-12-to-18-final-results\">Months 12 to 18: final results\u003c/h2>\u003cp>Most results are visible by 12 months. The \u003cstrong>crown\u003c/strong> and some hair types may take up to 18 months to reach full density.\u003c/p>\n\u003ch2 id=\"factors-that-affect-results\">Factors that affect results\u003c/h2>\u003cul>\n\u003cli>Quality and number of grafts\u003c/li>\n\u003cli>Surgical skill and graft handling\u003c/li>\n\u003cli>Your hair type, thickness and colour\u003c/li>\n\u003cli>Following aftercare instructions\u003c/li>\n\u003cli>General health and smoking habits\u003c/li>\n\u003cli>Continued thinning of native hair\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"tracking-your-progress\">Tracking your progress\u003c/h2>\u003cp>Take photos in the same lighting and position once a month. Changes are gradual and easier to see in photos than in the mirror.\u003c/p>\n\u003ch2 id=\"will-i-need-a-second-procedure\">Will I need a second procedure?\u003c/h2>\u003cp>Some people choose a second session for more density or to cover areas affected by later hair loss. This is usually considered only after the first results have fully matured, around 12 months.\u003c/p>\n\u003ch2 id=\"when-should-you-contact-your-surgeon\">When should you contact your surgeon?\u003c/h2>\u003cul>\n\u003cli>No visible growth by 6 to 8 months\u003c/li>\n\u003cli>Persistent redness, pain or bumps\u003c/li>\n\u003cli>Concerns about shock loss that is not improving\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Is it normal to lose hair after a transplant?","a":"Yes. Shedding of transplanted hair in the first weeks is expected."},{"q":"When will I see the final result?","a":"Usually by 12 months; sometimes up to 18 months."},{"q":"Will new hair be the same texture as before?","a":"Early hairs may be finer or wavier but usually normalise over time."}],"toc":[{"id":"weeks-2-to-6-shedding-phase","text":"Weeks 2 to 6: shedding phase"},{"id":"months-1-to-3-the-ugly-duckling-phase","text":"Months 1 to 3: the &quot;ugly duckling&quot; phase"},{"id":"months-3-to-4-early-growth","text":"Months 3 to 4: early growth"},{"id":"months-5-to-8-visible-improvement","text":"Months 5 to 8: visible improvement"},{"id":"months-9-to-12-maturing-results","text":"Months 9 to 12: maturing results"},{"id":"months-12-to-18-final-results","text":"Months 12 to 18: final results"},{"id":"factors-that-affect-results","text":"Factors that affect results"},{"id":"tracking-your-progress","text":"Tracking your progress"},{"id":"will-i-need-a-second-procedure","text":"Will I need a second procedure?"},{"id":"when-should-you-contact-your-surgeon","text":"When should you contact your surgeon?"}],"words":401,"read":2},{"slug":"hair-transplant-aftercare","sp":"hair-transplant","title":"Hair Transplant Aftercare","seo":"Hair Transplant Aftercare: Do's, Don'ts, Washing & Sleeping Guide","desc":"A practical aftercare checklist after hair transplant: how to wash, sleep, protect grafts, manage itching, and when to resume exercise and grooming.","kw":["hair transplant aftercare","washing after hair transplant","sleeping after hair transplant","hair transplant do's and don'ts","post hair transplant care"],"links":["hair-transplant-recovery","hair-transplant-results-timeline","hair-transplant-grafts"],"video":null,"flow":null,"img":["Aftercare checklist infographic","How to gently wash the scalp with a cup","Protecting the scalp from sun with a loose hat"],"html":"\u003cp>Good aftercare protects your new grafts and helps them grow well. Always follow your own clinic&#39;s instructions; this checklist covers the general principles.\u003c/p>\n\u003ch2 id=\"washing-your-hair\">Washing your hair\u003c/h2>\u003cul>\n\u003cli>Begin washing as instructed, often from the day after surgery\u003c/li>\n\u003cli>Use the mild shampoo or lotion recommended by your clinic\u003c/li>\n\u003cli>Pour water gently from a cup or mug; avoid direct shower pressure on grafts for the first week or so\u003c/li>\n\u003cli>\u003cstrong>Pat\u003c/strong>, do not rub; let the recipient area air dry\u003c/li>\n\u003cli>Gradually return to normal washing after about two weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"sleeping\">Sleeping\u003c/h2>\u003cul>\n\u003cli>Sleep with your head elevated for the first several nights\u003c/li>\n\u003cli>Use a travel pillow to avoid rubbing grafts on the pillow\u003c/li>\n\u003cli>Use a clean pillow cover\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"protecting-the-grafts\">Protecting the grafts\u003c/h2>\u003cul>\n\u003cli>Do not touch, scratch or pick at scabs\u003c/li>\n\u003cli>Avoid bumping your head\u003c/li>\n\u003cli>Wear only a loose cap if allowed, usually after a few days\u003c/li>\n\u003cli>Avoid helmets and tight headwear for the time advised\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"managing-itching-and-discomfort\">Managing itching and discomfort\u003c/h2>\u003cul>\n\u003cli>Itching is a sign of healing; do not scratch\u003c/li>\n\u003cli>Use the sprays or medicines your clinic recommends\u003c/li>\n\u003cli>Take pain relief as prescribed\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"sun-heat-and-water\">Sun, heat and water\u003c/h2>\u003cul>\n\u003cli>Protect your scalp from direct sun for several weeks\u003c/li>\n\u003cli>Avoid saunas, steam rooms and swimming pools for about 3 to 4 weeks\u003c/li>\n\u003cli>Avoid heavy sweating in the first week or two\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"exercise\">Exercise\u003c/h2>\u003cul>\n\u003cli>Light walking is usually fine immediately\u003c/li>\n\u003cli>Avoid strenuous exercise, weight lifting and bending for about 2 weeks\u003c/li>\n\u003cli>Return gradually as advised\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"hair-styling-and-grooming\">Hair styling and grooming\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Activity\u003c/th>\n\u003cth>Usual guidance\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Combing over grafts\u003c/td>\n\u003ctd>Gently, after scabs have fallen off\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Haircut with scissors\u003c/td>\n\u003ctd>After about 3 to 4 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Hair colouring or chemical treatments\u003c/td>\n\u003ctd>Usually after 6 to 8 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Hair dryer\u003c/td>\n\u003ctd>Cool setting only, after a couple of weeks\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"lifestyle\">Lifestyle\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Avoid smoking\u003c/strong> for at least two weeks before and after surgery; it reduces blood flow to grafts\u003c/li>\n\u003cli>Limit alcohol in the first week\u003c/li>\n\u003cli>Eat a balanced, protein-rich diet\u003c/li>\n\u003cli>Continue any prescribed medicines to protect native hair\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-to-contact-your-clinic\">When to contact your clinic\u003c/h2>\u003cul>\n\u003cli>Signs of infection: increasing redness, pain, pus or fever\u003c/li>\n\u003cli>Bleeding that will not stop\u003c/li>\n\u003cli>A graft that appears dislodged in the first few days\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Can I wear a cap after a hair transplant?","a":"Usually a loose cap after a few days. Ask your clinic."},{"q":"When can I go to the gym?","a":"Usually after about two weeks for light exercise, longer for heavy lifting."},{"q":"Do I need to continue medicines afterwards?","a":"Your doctor may recommend medicines to protect your existing hair."}],"toc":[{"id":"washing-your-hair","text":"Washing your hair"},{"id":"sleeping","text":"Sleeping"},{"id":"protecting-the-grafts","text":"Protecting the grafts"},{"id":"managing-itching-and-discomfort","text":"Managing itching and discomfort"},{"id":"sun-heat-and-water","text":"Sun, heat and water"},{"id":"exercise","text":"Exercise"},{"id":"hair-styling-and-grooming","text":"Hair styling and grooming"},{"id":"lifestyle","text":"Lifestyle"},{"id":"when-to-contact-your-clinic","text":"When to contact your clinic"}],"words":401,"read":2},{"slug":"obesity-health-risks","sp":"weight-loss-surgery","title":"Understanding Obesity and Its Health Risks","seo":"Obesity: BMI, Health Risks & Why It Is a Medical Condition","desc":"Understand obesity as a medical condition, how BMI and waist size are measured, why Asian thresholds differ, and the health problems it can cause.","kw":["obesity","BMI","obesity health risks","waist circumference","obesity in India"],"links":["who-benefits-from-bariatric-surgery","bariatric-surgery-vs-lifestyle","gastric-sleeve-surgery"],"video":null,"flow":null,"img":["BMI categories chart with Asian cut-offs","Body map of obesity-related conditions","Waist measurement technique"],"html":"\u003cp>Obesity is a long-term medical condition, not simply a matter of willpower. It is influenced by genetics, hormones, environment, sleep, stress and lifestyle. Recognising it as a disease helps people get proper medical support.\u003c/p>\n\u003ch2 id=\"how-is-obesity-measured\">How is obesity measured?\u003c/h2>\u003cp>\u003cstrong>Body Mass Index (BMI)\u003c/strong> is weight in kilograms divided by height in metres squared.\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Category\u003c/th>\n\u003cth>General BMI\u003c/th>\n\u003cth>Asian guidance (often used in India)\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Healthy\u003c/td>\n\u003ctd>18.5–24.9\u003c/td>\n\u003ctd>18.5–22.9\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Overweight\u003c/td>\n\u003ctd>25–29.9\u003c/td>\n\u003ctd>23–24.9\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Obesity\u003c/td>\n\u003ctd>30 and above\u003c/td>\n\u003ctd>25 and above\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>People of South Asian origin tend to develop diabetes and heart disease at lower BMI levels, which is why lower cut-offs are used.\u003c/p>\n\u003cp>\u003cstrong>Waist circumference\u003c/strong> matters too. Fat around the abdomen is linked to higher health risk. For Asian adults, a waist above about 90 cm in men and 80 cm in women indicates increased risk.\u003c/p>\n\u003ch2 id=\"why-does-obesity-happen\">Why does obesity happen?\u003c/h2>\u003cul>\n\u003cli>Genetics and family history\u003c/li>\n\u003cli>High-calorie diets and large portion sizes\u003c/li>\n\u003cli>Low physical activity\u003c/li>\n\u003cli>Poor sleep and chronic stress\u003c/li>\n\u003cli>Hormonal conditions such as hypothyroidism and PCOS\u003c/li>\n\u003cli>Certain medicines\u003c/li>\n\u003cli>Changes in appetite-regulating hormones that make weight loss hard to sustain\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"health-risks-of-obesity\">Health risks of obesity\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Type 2 diabetes\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>High blood pressure\u003c/strong> and \u003cstrong>heart disease\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Stroke\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Obstructive sleep apnoea:\u003c/strong> loud snoring and pauses in breathing at night\u003c/li>\n\u003cli>\u003cstrong>Fatty liver disease\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Joint pain\u003c/strong> and osteoarthritis, especially in the knees\u003c/li>\n\u003cli>\u003cstrong>Infertility\u003c/strong> and PCOS\u003c/li>\n\u003cli>\u003cstrong>Acid reflux\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Some cancers\u003c/strong>, including breast, colon and uterine cancer\u003c/li>\n\u003cli>\u003cstrong>Depression\u003c/strong> and reduced quality of life\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-good-news\">The good news\u003c/h2>\u003cp>Losing even \u003cstrong>5 to 10 percent\u003c/strong> of body weight can improve blood sugar, blood pressure, cholesterol and joint pain.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>Diet, physical activity and behaviour change\u003c/li>\n\u003cli>Medicines for weight management, prescribed by a doctor\u003c/li>\n\u003cli>Endoscopic procedures for selected patients\u003c/li>\n\u003cli>\u003cstrong>Bariatric (metabolic) surgery\u003c/strong> for severe obesity or obesity with related conditions\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a doctor if your BMI or waist size is above the healthy range, especially if you have diabetes, high blood pressure, sleep apnoea or joint pain.\u003c/p>\n","faqs":[{"q":"Is BMI accurate for everyone?","a":"Not perfectly. Muscular people may have a high BMI without excess fat, so doctors also consider waist size and health conditions."},{"q":"Is obesity genetic?","a":"Genes play a significant role, but environment and lifestyle also matter."},{"q":"Can obesity medicines replace surgery?","a":"For some people, medicines help significantly. Doctors decide based on BMI, health conditions and goals."}],"toc":[{"id":"how-is-obesity-measured","text":"How is obesity measured?"},{"id":"why-does-obesity-happen","text":"Why does obesity happen?"},{"id":"health-risks-of-obesity","text":"Health risks of obesity"},{"id":"the-good-news","text":"The good news"},{"id":"treatment-options","text":"Treatment options"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":379,"read":2},{"slug":"who-benefits-from-bariatric-surgery","sp":"weight-loss-surgery","title":"Who May Benefit from Bariatric Surgery?","seo":"Who Is Eligible for Bariatric Surgery? BMI Criteria & Assessment","desc":"Learn who may be eligible for weight loss surgery, the BMI and health criteria used, the evaluation process and situations where surgery is not advised.","kw":["bariatric surgery eligibility","who can have weight loss surgery","BMI for bariatric surgery","metabolic surgery for diabetes","obesity surgery criteria"],"links":["obesity-health-risks","gastric-sleeve-surgery","preparing-for-weight-loss-surgery"],"video":null,"flow":null,"img":["Eligibility criteria infographic","Multidisciplinary bariatric team","Pre-surgery evaluation steps"],"html":"\u003cp>Bariatric surgery, also called weight loss or metabolic surgery, can lead to substantial, long-lasting weight loss and improve many obesity-related conditions. It is suitable for people who meet certain medical criteria after careful evaluation.\u003c/p>\n\u003ch2 id=\"general-eligibility-criteria\">General eligibility criteria\u003c/h2>\u003cp>International guidelines updated in 2022 generally recommend considering surgery for adults with:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>BMI of 35 or more\u003c/strong>, with or without related health conditions\u003c/li>\n\u003cli>\u003cstrong>BMI of 30 to 34.9\u003c/strong> with metabolic disease, such as type 2 diabetes that is difficult to control\u003c/li>\n\u003c/ul>\n\u003cp>Because people of Asian origin develop obesity-related diseases at lower weights, \u003cstrong>lower BMI thresholds\u003c/strong> may apply. Doctors in India often consider surgery at lower BMI levels when serious conditions such as uncontrolled diabetes are present.\u003c/p>\n\u003ch2 id=\"conditions-that-may-improve-after-surgery\">Conditions that may improve after surgery\u003c/h2>\u003cul>\n\u003cli>Type 2 diabetes\u003c/li>\n\u003cli>High blood pressure\u003c/li>\n\u003cli>Obstructive sleep apnoea\u003c/li>\n\u003cli>Fatty liver disease\u003c/li>\n\u003cli>High cholesterol\u003c/li>\n\u003cli>Joint pain\u003c/li>\n\u003cli>PCOS and fertility problems\u003c/li>\n\u003cli>Acid reflux (particularly after gastric bypass)\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-is-a-good-candidate\">Who is a good candidate?\u003c/h2>\u003cul>\n\u003cli>Previous attempts at weight loss have not given lasting results\u003c/li>\n\u003cli>Willingness to make lifelong changes in eating and activity\u003c/li>\n\u003cli>Commitment to long-term follow-up and vitamin supplements\u003c/li>\n\u003cli>Understanding of the risks and benefits\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-evaluation-process\">The evaluation process\u003c/h2>\u003cp>A multidisciplinary team assesses you before surgery:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Bariatric surgeon:\u003c/strong> reviews history and suitable procedures\u003c/li>\n\u003cli>\u003cstrong>Physician or endocrinologist:\u003c/strong> checks diabetes, thyroid and other conditions\u003c/li>\n\u003cli>\u003cstrong>Dietitian:\u003c/strong> reviews eating patterns and prepares you for changes\u003c/li>\n\u003cli>\u003cstrong>Psychologist or counsellor:\u003c/strong> assesses readiness and eating behaviours\u003c/li>\n\u003cli>\u003cstrong>Anaesthetist:\u003c/strong> checks fitness for surgery\u003c/li>\n\u003cli>\u003cstrong>Tests:\u003c/strong> blood tests, ultrasound, endoscopy, sleep study and heart and lung evaluation as needed\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-surgery-may-not-be-advised\">When surgery may not be advised\u003c/h2>\u003cul>\n\u003cli>Uncontrolled psychiatric conditions or active substance misuse\u003c/li>\n\u003cli>Untreated eating disorders\u003c/li>\n\u003cli>Inability to follow long-term care\u003c/li>\n\u003cli>Very high surgical risk from other illnesses\u003c/li>\n\u003cli>Pregnancy or planning pregnancy within the next 12 to 18 months\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"teenagers-and-older-adults\">Teenagers and older adults\u003c/h2>\u003cp>Surgery may be considered for selected adolescents with severe obesity at specialised centres, and for older adults based on overall fitness rather than age alone.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you have tried to lose weight without lasting success and have a high BMI or obesity-related conditions, ask for a bariatric assessment.\u003c/p>\n","faqs":[{"q":"Is bariatric surgery a cosmetic procedure?","a":"No. It is a medical treatment for obesity and related diseases."},{"q":"Do I need to lose weight before surgery?","a":"Often a modest pre-operative weight loss is advised to make surgery safer."},{"q":"Can it cure diabetes?","a":"Many people see major improvement or remission, but results vary and require follow-up."}],"toc":[{"id":"general-eligibility-criteria","text":"General eligibility criteria"},{"id":"conditions-that-may-improve-after-surgery","text":"Conditions that may improve after surgery"},{"id":"who-is-a-good-candidate","text":"Who is a good candidate?"},{"id":"the-evaluation-process","text":"The evaluation process"},{"id":"when-surgery-may-not-be-advised","text":"When surgery may not be advised"},{"id":"teenagers-and-older-adults","text":"Teenagers and older adults"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":405,"read":2},{"slug":"gastric-sleeve-surgery","sp":"weight-loss-surgery","title":"Gastric Sleeve Surgery Explained","seo":"Gastric Sleeve Surgery: How It Works, Benefits, Risks & Recovery","desc":"Learn how gastric sleeve surgery (sleeve gastrectomy) works, why it reduces hunger, what happens during keyhole surgery, benefits, risks and recovery.","kw":["gastric sleeve","sleeve gastrectomy","laparoscopic sleeve","weight loss surgery","bariatric surgery"],"links":["gastric-bypass-surgery","recovery-after-bariatric-surgery","diet-after-bariatric-surgery"],"video":null,"flow":{"caption":"How sleeve gastrectomy works","steps":[{"t":"Keyhole access","d":"4 to 6 small cuts in the abdomen"},{"t":"Stomach reshaped","d":"About 75 to 80 percent removed"},{"t":"Tube-shaped stomach","d":"Holds much less food"},{"t":"Hormone change","d":"Less of the hunger hormone ghrelin"}]},"img":["Stomach before and after sleeve gastrectomy (anatomical)","Laparoscopic ports on the abdomen","Portion size before vs after surgery"],"html":"\u003cp>Gastric sleeve surgery, or sleeve gastrectomy, is the most commonly performed weight loss operation worldwide. It reduces the size of the stomach and changes hunger hormones, helping people eat less and feel full sooner.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>The surgeon removes about \u003cstrong>75 to 80 percent\u003c/strong> of the stomach, leaving a narrow, tube-shaped &quot;sleeve&quot; about the size of a banana. The removed part cannot be put back, so the procedure is permanent.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How sleeve gastrectomy works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How sleeve gastrectomy works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Keyhole access\u003c/b>\u003cspan>4 to 6 small cuts in the abdomen\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Stomach reshaped\u003c/b>\u003cspan>About 75 to 80 percent removed\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Tube-shaped stomach\u003c/b>\u003cspan>Holds much less food\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Hormone change\u003c/b>\u003cspan>Less of the hunger hormone ghrelin\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"how-does-it-help-weight-loss\">How does it help weight loss?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Smaller stomach:\u003c/strong> you feel full with much smaller portions\u003c/li>\n\u003cli>\u003cstrong>Less hunger:\u003c/strong> the removed section produces most of the hunger hormone \u003cstrong>ghrelin\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Metabolic changes:\u003c/strong> improve blood sugar control\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-happens-during-surgery\">What happens during surgery?\u003c/h2>\u003col>\n\u003cli>General anaesthesia is given.\u003c/li>\n\u003cli>The surgery is done by \u003cstrong>laparoscopy\u003c/strong> (keyhole surgery) through 4 to 6 small cuts.\u003c/li>\n\u003cli>A tube is placed in the stomach to guide the sleeve size.\u003c/li>\n\u003cli>A stapling device divides and seals the stomach.\u003c/li>\n\u003cli>The removed portion is taken out through one of the small cuts.\u003c/li>\n\u003c/ol>\n\u003cp>The operation usually takes \u003cstrong>1 to 2 hours\u003c/strong>. Most patients stay in hospital for \u003cstrong>2 to 3 days\u003c/strong>.\u003c/p>\n\u003ch2 id=\"expected-results\">Expected results\u003c/h2>\u003cul>\n\u003cli>Many people lose a substantial proportion of their excess weight over 12 to 18 months\u003c/li>\n\u003cli>Obesity-related conditions such as diabetes, high blood pressure and sleep apnoea often improve\u003c/li>\n\u003cli>Results depend on long-term changes in eating and activity\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"advantages\">Advantages\u003c/h2>\u003cul>\n\u003cli>Does not reroute the intestine\u003c/li>\n\u003cli>Technically simpler than gastric bypass\u003c/li>\n\u003cli>Fewer long-term vitamin absorption problems than bypass, though supplements are still needed\u003c/li>\n\u003cli>Can be converted to a bypass later if needed\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"possible-risks\">Possible risks\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Leak\u003c/strong> from the staple line (uncommon but serious)\u003c/li>\n\u003cli>Bleeding\u003c/li>\n\u003cli>Blood clots\u003c/li>\n\u003cli>\u003cstrong>Acid reflux\u003c/strong> may start or worsen in some people\u003c/li>\n\u003cli>Narrowing of the sleeve\u003c/li>\n\u003cli>Vitamin and mineral deficiencies\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"who-may-it-suit\">Who may it suit?\u003c/h2>\u003cp>Sleeve gastrectomy is suitable for many people who meet bariatric criteria. It may be less ideal for people with severe acid reflux, for whom gastric bypass may be preferred.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A bariatric surgeon will help you decide whether the sleeve or another procedure is best for your health and goals.\u003c/p>\n","faqs":[{"q":"Is the gastric sleeve reversible?","a":"No. Part of the stomach is permanently removed."},{"q":"Will I feel hungry after surgery?","a":"Most people feel significantly less hungry, especially in the first year."},{"q":"Can the stomach stretch back?","a":"It can stretch somewhat over time if large portions are eaten regularly."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"how-does-it-help-weight-loss","text":"How does it help weight loss?"},{"id":"what-happens-during-surgery","text":"What happens during surgery?"},{"id":"expected-results","text":"Expected results"},{"id":"advantages","text":"Advantages"},{"id":"possible-risks","text":"Possible risks"},{"id":"who-may-it-suit","text":"Who may it suit?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":394,"read":2},{"slug":"gastric-bypass-surgery","sp":"weight-loss-surgery","title":"Gastric Bypass Surgery Explained","seo":"Gastric Bypass Surgery: Roux-en-Y & Mini Bypass, Benefits and Risks","desc":"Understand gastric bypass surgery: how the small stomach pouch and rerouted intestine work, types, benefits for diabetes and reflux, risks and recovery.","kw":["gastric bypass","Roux-en-Y gastric bypass","mini gastric bypass","one anastomosis gastric bypass","metabolic surgery"],"links":["gastric-sleeve-surgery","bariatric-surgery-vs-lifestyle","bariatric-surgery-complications"],"video":null,"flow":{"caption":"How Roux-en-Y gastric bypass works","steps":[{"t":"Small pouch","d":"Egg-sized stomach pouch created"},{"t":"Intestine rerouted","d":"Small bowel connected to the pouch"},{"t":"Bypass","d":"Food skips most of the stomach and first part of intestine"},{"t":"Effects","d":"Less food, fewer calories absorbed, hormone changes"}]},"img":["Roux-en-Y gastric bypass anatomy (labelled)","Comparison: sleeve vs Roux-en-Y vs mini bypass","Lifelong supplement routine"],"html":"\u003cp>Gastric bypass is a well-established weight loss operation that both reduces stomach size and changes how food passes through the digestive system. It is especially effective for type 2 diabetes and acid reflux.\u003c/p>\n\u003ch2 id=\"what-is-it\">What is it?\u003c/h2>\u003cp>The most common type is the \u003cstrong>Roux-en-Y gastric bypass\u003c/strong>:\u003c/p>\n\u003col>\n\u003cli>A small stomach pouch, about the size of an egg, is created at the top of the stomach.\u003c/li>\n\u003cli>The small intestine is divided and connected to this pouch.\u003c/li>\n\u003cli>Food passes from the pouch directly into the lower part of the small intestine, \u003cstrong>bypassing\u003c/strong> most of the stomach and the first part of the intestine.\u003c/li>\n\u003c/ol>\n\u003cp>The remaining stomach is not removed; it stays in place and continues to make digestive juices.\u003c/p>\n\u003cp>\u003cstrong>One-anastomosis (mini) gastric bypass\u003c/strong> is a variation with a single intestinal connection.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How Roux-en-Y gastric bypass works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How Roux-en-Y gastric bypass works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Small pouch\u003c/b>\u003cspan>Egg-sized stomach pouch created\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Intestine rerouted\u003c/b>\u003cspan>Small bowel connected to the pouch\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Bypass\u003c/b>\u003cspan>Food skips most of the stomach and first part of intestine\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Effects\u003c/b>\u003cspan>Less food, fewer calories absorbed, hormone changes\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"how-does-it-help\">How does it help?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Smaller stomach pouch:\u003c/strong> smaller meals\u003c/li>\n\u003cli>\u003cstrong>Less absorption:\u003c/strong> fewer calories are absorbed\u003c/li>\n\u003cli>\u003cstrong>Hormone changes:\u003c/strong> improve fullness and blood sugar control, often quickly after surgery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"benefits\">Benefits\u003c/h2>\u003cul>\n\u003cli>Substantial, long-lasting weight loss\u003c/li>\n\u003cli>Strong effect on type 2 diabetes, often reducing or stopping diabetes medicines\u003c/li>\n\u003cli>Improves or resolves acid reflux in many people\u003c/li>\n\u003cli>Improves blood pressure, cholesterol and sleep apnoea\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-surgery\">The surgery\u003c/h2>\u003cul>\n\u003cli>Performed by laparoscopy (keyhole surgery) under general anaesthesia\u003c/li>\n\u003cli>Usually takes \u003cstrong>2 to 3 hours\u003c/strong>\u003c/li>\n\u003cli>Hospital stay of \u003cstrong>2 to 4 days\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"possible-risks\">Possible risks\u003c/h2>\u003cul>\n\u003cli>Leaks at the joins (uncommon)\u003c/li>\n\u003cli>Bleeding and blood clots\u003c/li>\n\u003cli>\u003cstrong>Dumping syndrome:\u003c/strong> nausea, cramps, sweating or diarrhoea after eating sugary or fatty foods\u003c/li>\n\u003cli>Ulcers at the join, especially with smoking or painkillers such as NSAIDs\u003c/li>\n\u003cli>Internal hernia or bowel obstruction\u003c/li>\n\u003cli>\u003cstrong>Vitamin and mineral deficiencies:\u003c/strong> iron, vitamin B12, calcium, vitamin D and others\u003c/li>\n\u003c/ul>\n\u003cp>Lifelong supplements and regular blood tests are essential.\u003c/p>\n\u003ch2 id=\"sleeve-vs-bypass\">Sleeve vs bypass\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Sleeve\u003c/th>\n\u003cth>Roux-en-Y bypass\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Stomach removed\u003c/td>\n\u003ctd>Yes, mostly\u003c/td>\n\u003ctd>No, bypassed\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Intestine rerouted\u003c/td>\n\u003ctd>No\u003c/td>\n\u003ctd>Yes\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Reflux\u003c/td>\n\u003ctd>May worsen\u003c/td>\n\u003ctd>Often improves\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Diabetes improvement\u003c/td>\n\u003ctd>Good\u003c/td>\n\u003ctd>Often greater\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Deficiency risk\u003c/td>\n\u003ctd>Lower\u003c/td>\n\u003ctd>Higher\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask a bariatric surgeon whether gastric bypass suits you, particularly if you have type 2 diabetes or acid reflux.\u003c/p>\n","faqs":[{"q":"Is gastric bypass reversible?","a":"It is technically possible in some cases but is complex. It should be considered a permanent operation."},{"q":"What is dumping syndrome?","a":"Unpleasant symptoms after sugary or fatty meals. Diet changes usually prevent it."},{"q":"Will I need vitamins forever?","a":"Yes. Lifelong supplements are essential after gastric bypass."}],"toc":[{"id":"what-is-it","text":"What is it?"},{"id":"how-does-it-help","text":"How does it help?"},{"id":"benefits","text":"Benefits"},{"id":"the-surgery","text":"The surgery"},{"id":"possible-risks","text":"Possible risks"},{"id":"sleeve-vs-bypass","text":"Sleeve vs bypass"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":386,"read":2},{"slug":"bariatric-surgery-vs-lifestyle","sp":"weight-loss-surgery","title":"Bariatric Surgery Versus Lifestyle Management","seo":"Weight Loss Surgery vs Diet & Exercise: Which Is Right for You?","desc":"An honest comparison of bariatric surgery with diet, exercise and medicines: expected results, risks, long-term success and how doctors decide.","kw":["bariatric surgery vs diet","weight loss surgery vs exercise","obesity treatment options","weight loss medicines","lifestyle modification"],"links":["obesity-health-risks","who-benefits-from-bariatric-surgery","life-after-bariatric-surgery"],"video":null,"flow":null,"img":["Treatment ladder: lifestyle, medicines, endoscopic options, surgery","Comparison chart of approaches","Healthy habits that support every option"],"html":"\u003cp>Choosing how to treat obesity is a personal and medical decision. Lifestyle changes, medicines and surgery all have a place. Understanding what each offers helps you have an informed conversation with your doctor.\u003c/p>\n\u003ch2 id=\"lifestyle-management\">Lifestyle management\u003c/h2>\u003cp>This includes diet changes, physical activity, better sleep and behaviour change.\u003c/p>\n\u003cp>\u003cstrong>Benefits:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>No surgical risk\u003c/li>\n\u003cli>Improves health even with modest weight loss\u003c/li>\n\u003cli>Builds the habits needed for every treatment\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Limitations:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>For people with severe obesity, diet and exercise alone often lead to modest weight loss\u003c/li>\n\u003cli>The body adapts by increasing hunger and slowing metabolism, making weight regain common\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"weight-loss-medicines\">Weight-loss medicines\u003c/h2>\u003cp>Newer medicines can help many people lose a meaningful amount of weight. They are prescribed and monitored by doctors, and are usually needed long term because weight often returns when they are stopped. Availability, side effects and suitability vary.\u003c/p>\n\u003ch2 id=\"bariatric-surgery\">Bariatric surgery\u003c/h2>\u003cp>\u003cstrong>Benefits:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>The most effective long-term treatment for severe obesity\u003c/li>\n\u003cli>Substantial and sustained weight loss for most patients\u003c/li>\n\u003cli>Significant improvement in diabetes, blood pressure and sleep apnoea\u003c/li>\n\u003cli>Studies show improved long-term health outcomes in suitable patients\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Limitations:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Surgical risks\u003c/li>\n\u003cli>Permanent changes to the digestive system\u003c/li>\n\u003cli>Lifelong supplements and follow-up\u003c/li>\n\u003cli>Weight regain is possible without lasting lifestyle change\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"comparison\">Comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Lifestyle\u003c/th>\n\u003cth>Medicines\u003c/th>\n\u003cth>Surgery\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Typical weight loss\u003c/td>\n\u003ctd>Modest\u003c/td>\n\u003ctd>Moderate to substantial\u003c/td>\n\u003ctd>Substantial\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Durability\u003c/td>\n\u003ctd>Often regained\u003c/td>\n\u003ctd>Usually requires continued use\u003c/td>\n\u003ctd>Generally long lasting\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Invasiveness\u003c/td>\n\u003ctd>None\u003c/td>\n\u003ctd>Non-surgical\u003c/td>\n\u003ctd>Surgical\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Effect on diabetes\u003c/td>\n\u003ctd>Helpful\u003c/td>\n\u003ctd>Helpful\u003c/td>\n\u003ctd>Often major improvement\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Lifelong commitment\u003c/td>\n\u003ctd>Yes\u003c/td>\n\u003ctd>Yes\u003c/td>\n\u003ctd>Yes\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"it-is-not-either-or\">It is not either-or\u003c/h2>\u003cp>Surgery and medicines work best alongside healthy eating, activity, good sleep and emotional support. Every successful approach needs lifestyle change.\u003c/p>\n\u003ch2 id=\"how-doctors-decide\">How doctors decide\u003c/h2>\u003cul>\n\u003cli>BMI and waist circumference\u003c/li>\n\u003cli>Obesity-related conditions\u003c/li>\n\u003cli>Previous weight-loss attempts\u003c/li>\n\u003cli>Your preferences and readiness\u003c/li>\n\u003cli>Surgical risk and general health\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If your BMI is high or you have obesity-related conditions, a doctor or bariatric team can discuss all options with you, not only surgery.\u003c/p>\n","faqs":[{"q":"Is surgery \"the easy way out\"?","a":"No. Surgery is a tool that still requires significant, lifelong effort."},{"q":"Can I try medicines before surgery?","a":"Often yes. Your doctor will advise based on your situation."},{"q":"Will I regain weight after surgery?","a":"Some regain is common, but most people maintain significant weight loss with good habits."}],"toc":[{"id":"lifestyle-management","text":"Lifestyle management"},{"id":"weight-loss-medicines","text":"Weight-loss medicines"},{"id":"bariatric-surgery","text":"Bariatric surgery"},{"id":"comparison","text":"Comparison"},{"id":"it-is-not-either-or","text":"It is not either-or"},{"id":"how-doctors-decide","text":"How doctors decide"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":368,"read":2},{"slug":"preparing-for-weight-loss-surgery","sp":"weight-loss-surgery","title":"Preparing for Weight Loss Surgery","seo":"Preparing for Bariatric Surgery: Tests, Pre-Op Diet & Checklist","desc":"How to prepare for bariatric surgery: medical tests, the pre-operative liquid diet, stopping smoking, mental preparation and what to pack for hospital.","kw":["preparing for bariatric surgery","pre-op diet bariatric","liver shrinking diet","bariatric surgery checklist","before weight loss surgery"],"links":["who-benefits-from-bariatric-surgery","recovery-after-bariatric-surgery","diet-after-bariatric-surgery"],"video":null,"flow":{"caption":"Getting ready for surgery","steps":[{"t":"Evaluation","d":"Tests and team assessments"},{"t":"Habit change","d":"Practise eating slowly; stop smoking"},{"t":"Pre-op diet","d":"Low-calorie, often liquid diet"},{"t":"Surgery day","d":"Fasting; admission; operation"}]},"img":["Pre-surgery checklist infographic","Liver size before and after pre-op diet","Hospital bag checklist"],"html":"\u003cp>Good preparation makes bariatric surgery safer and helps you adapt more easily afterwards. Preparation usually begins several weeks before your operation.\u003c/p>\n\u003ch2 id=\"medical-preparation\">Medical preparation\u003c/h2>\u003cp>Your team may arrange:\u003c/p>\n\u003cul>\n\u003cli>Blood tests, including blood sugar, thyroid and vitamin levels\u003c/li>\n\u003cli>ECG, chest X-ray and sometimes heart tests\u003c/li>\n\u003cli>\u003cstrong>Upper GI endoscopy\u003c/strong> to check the stomach\u003c/li>\n\u003cli>\u003cstrong>Abdominal ultrasound\u003c/strong> to check the liver and gallbladder\u003c/li>\n\u003cli>\u003cstrong>Sleep study\u003c/strong> if sleep apnoea is suspected\u003c/li>\n\u003cli>Review of all medicines\u003c/li>\n\u003c/ul>\n\u003cp>Good control of diabetes and blood pressure before surgery reduces risk.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Getting ready for surgery\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Getting ready for surgery\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Evaluation\u003c/b>\u003cspan>Tests and team assessments\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Habit change\u003c/b>\u003cspan>Practise eating slowly; stop smoking\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Pre-op diet\u003c/b>\u003cspan>Low-calorie, often liquid diet\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Surgery day\u003c/b>\u003cspan>Fasting; admission; operation\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"stop-smoking\">Stop smoking\u003c/h2>\u003cp>Stop all forms of tobacco at least \u003cstrong>4 to 6 weeks before\u003c/strong> surgery. Smoking increases the risk of leaks, ulcers, blood clots and poor healing.\u003c/p>\n\u003ch2 id=\"the-pre-operative-diet\">The pre-operative diet\u003c/h2>\u003cp>Most patients follow a special low-calorie, high-protein diet, often liquid-based, for \u003cstrong>1 to 3 weeks\u003c/strong> before surgery. This shrinks the liver, which sits over the stomach, making keyhole surgery safer.\u003c/p>\n\u003cp>Follow your dietitian&#39;s plan carefully.\u003c/p>\n\u003ch2 id=\"practise-new-habits-early\">Practise new habits early\u003c/h2>\u003cul>\n\u003cli>Eat slowly and chew thoroughly\u003c/li>\n\u003cli>Use smaller plates\u003c/li>\n\u003cli>Stop drinking with meals; drink between meals instead\u003c/li>\n\u003cli>Reduce sugary drinks, fried foods and sweets\u003c/li>\n\u003cli>Start daily walking\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"mental-and-emotional-preparation\">Mental and emotional preparation\u003c/h2>\u003cul>\n\u003cli>Understand that surgery changes your relationship with food\u003c/li>\n\u003cli>Discuss emotional eating with a counsellor if needed\u003c/li>\n\u003cli>Involve your family so they can support you\u003c/li>\n\u003cli>Join a support group if available\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"practical-preparation\">Practical preparation\u003c/h2>\u003cul>\n\u003cli>Arrange time off work, usually 1 to 3 weeks\u003c/li>\n\u003cli>Stock up on approved liquids, protein shakes and supplements\u003c/li>\n\u003cli>Arrange support at home for the first week\u003c/li>\n\u003cli>For international patients, plan to stay near the hospital for the time your team advises before flying\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-to-pack-for-hospital\">What to pack for hospital\u003c/h2>\u003cul>\n\u003cli>Loose, comfortable clothes\u003c/li>\n\u003cli>Slip-on footwear\u003c/li>\n\u003cli>Your medicines and medical reports\u003c/li>\n\u003cli>A CPAP machine, if you use one for sleep apnoea\u003c/li>\n\u003cli>Personal care items\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-day-before-and-the-day-of-surgery\">The day before and the day of surgery\u003c/h2>\u003cul>\n\u003cli>Follow fasting instructions exactly\u003c/li>\n\u003cli>Shower as advised\u003c/li>\n\u003cli>Remove jewellery and nail polish\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-your-team\">When should you consult your team?\u003c/h2>\u003cp>Contact your team if you become unwell, develop a cough or fever, or find it hard to follow the pre-operative diet before surgery.\u003c/p>\n","faqs":[{"q":"Why do I need to lose weight before surgery?","a":"A smaller liver and lower weight make surgery safer and easier."},{"q":"Can I take my usual medicines?","a":"Some may need adjustment. Your team will tell you which to continue or stop."},{"q":"How long will I be off work?","a":"Often 1 to 3 weeks, depending on your job and recovery."}],"toc":[{"id":"medical-preparation","text":"Medical preparation"},{"id":"stop-smoking","text":"Stop smoking"},{"id":"the-pre-operative-diet","text":"The pre-operative diet"},{"id":"practise-new-habits-early","text":"Practise new habits early"},{"id":"mental-and-emotional-preparation","text":"Mental and emotional preparation"},{"id":"practical-preparation","text":"Practical preparation"},{"id":"what-to-pack-for-hospital","text":"What to pack for hospital"},{"id":"the-day-before-and-the-day-of-surgery","text":"The day before and the day of surgery"},{"id":"when-should-you-consult-your-team","text":"When should you consult your team?"}],"words":396,"read":2},{"slug":"recovery-after-bariatric-surgery","sp":"weight-loss-surgery","title":"Recovery After Bariatric Surgery","seo":"Recovery After Bariatric Surgery: Hospital Stay, First Weeks & Milestones","desc":"What to expect after weight loss surgery: the hospital stay, pain, walking, hydration, returning to work and the warning signs that need urgent care.","kw":["recovery after bariatric surgery","after gastric sleeve recovery","bariatric surgery recovery time","post-op bariatric care","return to work after bariatric surgery"],"links":["diet-after-bariatric-surgery","bariatric-surgery-complications","life-after-bariatric-surgery"],"video":null,"flow":{"caption":"Recovery milestones","steps":[{"t":"Day 0 to 1","d":"Walking begins; sips of fluid"},{"t":"Days 2 to 4","d":"Discharge home"},{"t":"Weeks 1 to 3","d":"Return to light activity and desk work"},{"t":"Weeks 4 to 6","d":"Most normal activities; exercise builds"}]},"img":["Walking soon after surgery to prevent clots","Sipping fluids throughout the day","Small keyhole wounds healing"],"html":"\u003cp>Most people recover quickly after keyhole bariatric surgery. The first few weeks focus on healing, hydration and gradually adjusting to your new way of eating. This article covers physical recovery; see our separate guide on diet stages.\u003c/p>\n\u003ch2 id=\"in-hospital\">In hospital\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Walking\u003c/strong> begins within hours or the next day, which helps prevent blood clots and chest infections\u003c/li>\n\u003cli>\u003cstrong>Breathing exercises\u003c/strong> keep your lungs clear\u003c/li>\n\u003cli>\u003cstrong>Sips of water\u003c/strong> usually begin within the first day after checks\u003c/li>\n\u003cli>\u003cstrong>Pain\u003c/strong> is usually moderate and managed with medicines\u003c/li>\n\u003cli>\u003cstrong>Blood clot prevention:\u003c/strong> injections, stockings or foot pumps\u003c/li>\n\u003cli>Most people go home in \u003cstrong>2 to 4 days\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Recovery milestones\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Recovery milestones\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Day 0 to 1\u003c/b>\u003cspan>Walking begins; sips of fluid\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Days 2 to 4\u003c/b>\u003cspan>Discharge home\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Weeks 1 to 3\u003c/b>\u003cspan>Return to light activity and desk work\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Weeks 4 to 6\u003c/b>\u003cspan>Most normal activities; exercise builds\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"the-first-weeks-at-home\">The first weeks at home\u003c/h2>\u003cp>\u003cstrong>Hydration is the top priority.\u003c/strong> Take small sips throughout the day, aiming for the fluid goal your team sets, often about 1.5 to 2 litres. Dehydration is a common reason for readmission.\u003c/p>\n\u003cp>\u003cstrong>Other key points:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Walk several times a day and increase gradually\u003c/li>\n\u003cli>Take prescribed medicines, including acid-reducing tablets and supplements\u003c/li>\n\u003cli>Avoid heavy lifting for about 4 weeks\u003c/li>\n\u003cli>Keep wounds clean and dry\u003c/li>\n\u003cli>Expect tiredness, which improves over a few weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-is-normal\">What is normal?\u003c/h2>\u003cul>\n\u003cli>Mild pain at wound sites and in the shoulders (from gas used during surgery)\u003c/li>\n\u003cli>Feeling full quickly\u003c/li>\n\u003cli>Low energy\u003c/li>\n\u003cli>Mood swings as hormones and eating patterns change\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-normal-life\">Returning to normal life\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Activity\u003c/th>\n\u003cth>Typical timing\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Desk work\u003c/td>\n\u003ctd>1 to 3 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Driving\u003c/td>\n\u003ctd>When you can move comfortably and are off strong painkillers\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Light exercise\u003c/td>\n\u003ctd>Walking from day one\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>More intense exercise\u003c/td>\n\u003ctd>Usually from about 4 to 6 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Air travel\u003c/td>\n\u003ctd>As advised by your surgeon, with walking and hydration on the flight\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"follow-up-visits\">Follow-up visits\u003c/h2>\u003cp>Expect regular visits in the first year, typically at about 2 weeks, 1, 3, 6 and 12 months, then yearly. These monitor weight, nutrition, medicines and blood tests.\u003c/p>\n\u003ch2 id=\"warning-signs-seek-urgent-care\">Warning signs: seek urgent care\u003c/h2>\u003cul>\n\u003cli>Fever, fast heartbeat or breathlessness\u003c/li>\n\u003cli>Severe or increasing abdominal pain\u003c/li>\n\u003cli>Persistent vomiting or inability to keep fluids down\u003c/li>\n\u003cli>Pain or swelling in the calf\u003c/li>\n\u003cli>Chest pain\u003c/li>\n\u003cli>Vomiting blood or black stools\u003c/li>\n\u003c/ul>\n\u003cp>A fast heart rate can be an early sign of a leak and should not be ignored.\u003c/p>\n","faqs":[{"q":"How painful is recovery?","a":"Most people find pain manageable with medicines and improving within days."},{"q":"Why is hydration so important?","a":"Your small stomach makes it easy to fall behind on fluids, leading to dehydration."},{"q":"When can I start exercising?","a":"Walking starts immediately; more vigorous exercise usually after a few weeks."}],"toc":[{"id":"in-hospital","text":"In hospital"},{"id":"the-first-weeks-at-home","text":"The first weeks at home"},{"id":"what-is-normal","text":"What is normal?"},{"id":"returning-to-normal-life","text":"Returning to normal life"},{"id":"follow-up-visits","text":"Follow-up visits"},{"id":"warning-signs-seek-urgent-care","text":"Warning signs: seek urgent care"}],"words":392,"read":2},{"slug":"diet-after-bariatric-surgery","sp":"weight-loss-surgery","title":"Diet After Bariatric Surgery","seo":"Diet After Bariatric Surgery: Stages, Protein Goals & Eating Rules","desc":"A stage-by-stage diet guide after weight loss surgery, from clear liquids to regular food, with protein goals, eating rules and foods to avoid.","kw":["diet after bariatric surgery","bariatric diet stages","post gastric sleeve diet","protein after bariatric surgery","bariatric eating rules"],"links":["recovery-after-bariatric-surgery","life-after-bariatric-surgery","bariatric-surgery-complications"],"video":null,"flow":{"caption":"Diet stages after surgery","steps":[{"t":"Stage 1: Clear liquids","d":"First few days"},{"t":"Stage 2: Full liquids","d":"About weeks 1 to 2"},{"t":"Stage 3: Purée","d":"About weeks 3 to 4"},{"t":"Stage 4: Soft foods","d":"About weeks 5 to 6"},{"t":"Stage 5: Regular healthy diet","d":"From about week 6 to 8"}]},"img":["Diet stage progression with example foods","Bariatric plate: protein first, then vegetables","Small portion sizes using a small plate and spoon"],"html":"\u003cp>Your diet after bariatric surgery changes in stages to protect your stomach while it heals. Over time, you move towards a balanced, protein-rich diet in much smaller portions. Always follow your own team&#39;s timeline, as plans vary.\u003c/p>\n\u003ch2 id=\"the-diet-stages\">The diet stages\u003c/h2>\u003cp>\u003cstrong>Stage 1: Clear liquids (first few days)\u003c/strong>\nWater, clear soups, diluted juices without sugar, coconut water in moderation.\u003c/p>\n\u003cp>\u003cstrong>Stage 2: Full liquids (roughly weeks 1 to 2)\u003c/strong>\nThin dal water, buttermilk, low-fat milk, protein shakes, thin soups.\u003c/p>\n\u003cp>\u003cstrong>Stage 3: Purée (roughly weeks 3 to 4)\u003c/strong>\nBlended dal, mashed vegetables, smooth curd, puréed paneer or eggs.\u003c/p>\n\u003cp>\u003cstrong>Stage 4: Soft foods (roughly weeks 5 to 6)\u003c/strong>\nSoft-cooked vegetables, scrambled eggs, soft paneer, well-cooked fish, soft khichdi in small amounts.\u003c/p>\n\u003cp>\u003cstrong>Stage 5: Regular healthy diet (from about week 6 to 8)\u003c/strong>\nBalanced meals with protein, vegetables and controlled carbohydrates.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Diet stages after surgery\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Diet stages after surgery\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Stage 1: Clear liquids\u003c/b>\u003cspan>First few days\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Stage 2: Full liquids\u003c/b>\u003cspan>About weeks 1 to 2\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Stage 3: Purée\u003c/b>\u003cspan>About weeks 3 to 4\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Stage 4: Soft foods\u003c/b>\u003cspan>About weeks 5 to 6\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>Stage 5: Regular healthy diet\u003c/b>\u003cspan>From about week 6 to 8\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"protein-comes-first\">Protein comes first\u003c/h2>\u003cp>Protein helps healing and protects muscle during weight loss. Many programmes recommend around \u003cstrong>60 to 80 grams a day\u003c/strong>, or as advised by your dietitian.\u003c/p>\n\u003cp>Good protein sources:\u003c/p>\n\u003cul>\n\u003cli>Eggs, chicken, fish\u003c/li>\n\u003cli>Paneer, curd, milk\u003c/li>\n\u003cli>Dal, sprouts, soya and tofu\u003c/li>\n\u003cli>Protein supplements when needed\u003c/li>\n\u003c/ul>\n\u003cp>Eat protein first at each meal.\u003c/p>\n\u003ch2 id=\"golden-eating-rules\">Golden eating rules\u003c/h2>\u003cul>\n\u003cli>Eat slowly; take \u003cstrong>20 to 30 minutes\u003c/strong> for each meal\u003c/li>\n\u003cli>Chew each bite thoroughly\u003c/li>\n\u003cli>Stop as soon as you feel full\u003c/li>\n\u003cli>\u003cstrong>Do not drink with meals;\u003c/strong> wait about 30 minutes before and after eating\u003c/li>\n\u003cli>Have 3 small meals and 1 to 2 small snacks\u003c/li>\n\u003cli>Sip water throughout the day\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"foods-to-avoid-or-limit\">Foods to avoid or limit\u003c/h2>\u003cul>\n\u003cli>Sugary drinks, sweets and desserts\u003c/li>\n\u003cli>Carbonated drinks\u003c/li>\n\u003cli>Fried and very fatty foods\u003c/li>\n\u003cli>Alcohol, which is absorbed faster after surgery\u003c/li>\n\u003cli>Doughy breads and dry meats early on, which may get stuck\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"lifelong-supplements\">Lifelong supplements\u003c/h2>\u003cp>Most patients need lifelong:\u003c/p>\n\u003cul>\n\u003cli>A multivitamin with minerals\u003c/li>\n\u003cli>Vitamin B12\u003c/li>\n\u003cli>Calcium and vitamin D\u003c/li>\n\u003cli>Iron, especially for women\u003c/li>\n\u003c/ul>\n\u003cp>Your team will check blood levels regularly.\u003c/p>\n\u003ch2 id=\"common-problems\">Common problems\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Food intolerance:\u003c/strong> reintroduce foods slowly\u003c/li>\n\u003cli>\u003cstrong>Vomiting:\u003c/strong> often from eating too fast or too much\u003c/li>\n\u003cli>\u003cstrong>Constipation:\u003c/strong> increase fluids and fibre gradually\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-your-team\">When should you consult your team?\u003c/h2>\u003cp>Contact your dietitian or surgeon if you cannot meet your fluid or protein goals, vomit frequently, or have difficulty swallowing.\u003c/p>\n","faqs":[{"q":"Can I eat Indian food after surgery?","a":"Yes, with healthy cooking methods, small portions and protein first."},{"q":"Why can't I drink with meals?","a":"It fills the small stomach and can push food through too quickly."},{"q":"Do I need protein shakes forever?","a":"Usually only until you can meet protein needs from food."}],"toc":[{"id":"the-diet-stages","text":"The diet stages"},{"id":"protein-comes-first","text":"Protein comes first"},{"id":"golden-eating-rules","text":"Golden eating rules"},{"id":"foods-to-avoid-or-limit","text":"Foods to avoid or limit"},{"id":"lifelong-supplements","text":"Lifelong supplements"},{"id":"common-problems","text":"Common problems"},{"id":"when-should-you-consult-your-team","text":"When should you consult your team?"}],"words":406,"read":2},{"slug":"bariatric-surgery-complications","sp":"weight-loss-surgery","title":"Possible Complications and Precautions After Bariatric Surgery","seo":"Bariatric Surgery Risks & Complications: Signs, Prevention & Care","desc":"An honest look at the possible short- and long-term complications of weight loss surgery, warning signs to watch for and how to reduce your risk.","kw":["bariatric surgery complications","gastric sleeve risks","gastric bypass complications","leak after sleeve","nutritional deficiency after bariatric surgery"],"links":["recovery-after-bariatric-surgery","diet-after-bariatric-surgery","gastric-bypass-surgery"],"video":null,"flow":null,"img":["Timeline: early vs long-term complications","Warning signs card for patients","Regular blood test schedule"],"html":"\u003cp>Bariatric surgery is considered safe when performed at experienced centres, with a risk profile similar to other common abdominal operations. Like all surgery, it has possible complications. Knowing them helps you recognise problems early and reduce your risk.\u003c/p>\n\u003ch2 id=\"early-complications-first-few-weeks\">Early complications (first few weeks)\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Leak:\u003c/strong> fluid leaking from a staple line or join. It is uncommon but serious. Warning signs include fever, fast heartbeat, worsening abdominal pain and breathlessness.\u003c/li>\n\u003cli>\u003cstrong>Bleeding\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Blood clots\u003c/strong> in the legs or lungs\u003c/li>\n\u003cli>\u003cstrong>Infection\u003c/strong> at wound sites or inside the abdomen\u003c/li>\n\u003cli>\u003cstrong>Dehydration:\u003c/strong> from not drinking enough\u003c/li>\n\u003cli>\u003cstrong>Nausea and vomiting\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"longer-term-complications\">Longer-term complications\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Nutritional deficiencies:\u003c/strong> iron, vitamin B12, folate, calcium, vitamin D and others, which can cause anaemia, bone weakness or nerve problems\u003c/li>\n\u003cli>\u003cstrong>Acid reflux,\u003c/strong> particularly after sleeve gastrectomy\u003c/li>\n\u003cli>\u003cstrong>Gallstones,\u003c/strong> due to rapid weight loss\u003c/li>\n\u003cli>\u003cstrong>Narrowing (stricture)\u003c/strong> at the sleeve or join, causing difficulty swallowing\u003c/li>\n\u003cli>\u003cstrong>Ulcers,\u003c/strong> especially after bypass, more likely with smoking or anti-inflammatory painkillers\u003c/li>\n\u003cli>\u003cstrong>Dumping syndrome\u003c/strong> after bypass\u003c/li>\n\u003cli>\u003cstrong>Internal hernia\u003c/strong> after bypass, causing intermittent or severe abdominal pain\u003c/li>\n\u003cli>\u003cstrong>Excess skin\u003c/strong> after major weight loss\u003c/li>\n\u003cli>\u003cstrong>Weight regain\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Alcohol sensitivity,\u003c/strong> with a higher risk of alcohol problems\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-to-reduce-your-risk\">How to reduce your risk\u003c/h2>\u003cul>\n\u003cli>Choose an experienced bariatric team at a well-equipped hospital\u003c/li>\n\u003cli>Stop smoking before and after surgery\u003c/li>\n\u003cli>Walk early and often after surgery\u003c/li>\n\u003cli>Follow the diet stages carefully\u003c/li>\n\u003cli>Stay well hydrated\u003c/li>\n\u003cli>Take lifelong supplements as prescribed\u003c/li>\n\u003cli>Avoid NSAID painkillers unless your surgeon approves\u003c/li>\n\u003cli>Attend all follow-up appointments and blood tests\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"pregnancy-after-surgery\">Pregnancy after surgery\u003c/h2>\u003cp>Avoid pregnancy for \u003cstrong>12 to 18 months\u003c/strong> after surgery, while weight is changing rapidly. Use reliable contraception and plan pregnancy with your bariatric team.\u003c/p>\n\u003ch2 id=\"warning-signs-seek-urgent-care\">Warning signs: seek urgent care\u003c/h2>\u003cul>\n\u003cli>Fever, fast heart rate or breathlessness\u003c/li>\n\u003cli>Severe or persistent abdominal pain\u003c/li>\n\u003cli>Persistent vomiting or inability to drink\u003c/li>\n\u003cli>Black stools or vomiting blood\u003c/li>\n\u003cli>Calf pain or swelling\u003c/li>\n\u003cli>Difficulty swallowing that is getting worse\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"mental-health\">Mental health\u003c/h2>\u003cp>Big changes in body and eating can affect mood. Depression, anxiety or difficulties adjusting should be discussed with your team.\u003c/p>\n","faqs":[{"q":"How common are serious complications?","a":"Serious complications are uncommon at experienced centres, but no surgery is risk-free."},{"q":"Why do I need blood tests every year?","a":"To detect and correct nutritional deficiencies early."},{"q":"Can excess skin be treated?","a":"Body contouring surgery may be considered once weight has been stable for some time."}],"toc":[{"id":"early-complications-first-few-weeks","text":"Early complications (first few weeks)"},{"id":"longer-term-complications","text":"Longer-term complications"},{"id":"how-to-reduce-your-risk","text":"How to reduce your risk"},{"id":"pregnancy-after-surgery","text":"Pregnancy after surgery"},{"id":"warning-signs-seek-urgent-care","text":"Warning signs: seek urgent care"},{"id":"mental-health","text":"Mental health"}],"words":373,"read":2},{"slug":"life-after-bariatric-surgery","sp":"weight-loss-surgery","title":"Long-Term Lifestyle Changes After Bariatric Surgery","seo":"Life After Bariatric Surgery: Habits for Lasting Weight Loss","desc":"The habits that help you keep weight off after bariatric surgery: eating patterns, exercise, follow-up, managing weight regain, relationships and emotional health.","kw":["life after bariatric surgery","long term weight loss after surgery","weight regain after sleeve","exercise after bariatric surgery","bariatric follow-up"],"links":["diet-after-bariatric-surgery","bariatric-surgery-vs-lifestyle","bariatric-surgery-complications"],"video":null,"flow":null,"img":["Lifelong habits wheel: eat, move, sleep, supplements, follow-up","Exercise progression after surgery","Support group meeting"],"html":"\u003cp>Bariatric surgery is a powerful tool, but long-term success depends on the habits you build. The first 12 to 18 months bring the most weight loss. What you do in the years after decides whether that weight stays off.\u003c/p>\n\u003ch2 id=\"eating-habits-for-life\">Eating habits for life\u003c/h2>\u003cul>\n\u003cli>Eat 3 small meals and planned snacks\u003c/li>\n\u003cli>Protein first, then vegetables, then carbohydrates\u003c/li>\n\u003cli>Eat slowly and stop when full\u003c/li>\n\u003cli>Keep drinks separate from meals\u003c/li>\n\u003cli>Limit sugar, fried foods and sweetened drinks\u003c/li>\n\u003cli>Avoid &quot;grazing&quot; (snacking continuously through the day)\u003c/li>\n\u003cli>Plan meals ahead, especially when travelling or eating out\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"physical-activity\">Physical activity\u003c/h2>\u003cp>Regular activity helps maintain weight loss and protect muscle:\u003c/p>\n\u003cul>\n\u003cli>Aim for at least \u003cstrong>150 minutes\u003c/strong> of moderate activity a week, such as brisk walking\u003c/li>\n\u003cli>Add \u003cstrong>strength exercises\u003c/strong> 2 to 3 times a week\u003c/li>\n\u003cli>Build up gradually and choose activities you enjoy\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"supplements-and-check-ups\">Supplements and check-ups\u003c/h2>\u003cul>\n\u003cli>Take vitamins and minerals every day, for life\u003c/li>\n\u003cli>Have blood tests as advised, usually once or twice a year\u003c/li>\n\u003cli>Attend follow-up visits with your bariatric team\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"watching-for-weight-regain\">Watching for weight regain\u003c/h2>\u003cp>Some regain after the lowest weight is common. Warning signs include:\u003c/p>\n\u003cul>\n\u003cli>Slowly increasing portion sizes\u003c/li>\n\u003cli>Frequent snacking\u003c/li>\n\u003cli>Return of sugary drinks\u003c/li>\n\u003cli>Reduced activity\u003c/li>\n\u003c/ul>\n\u003cp>If you notice regain, contact your team early. Dietitian support, behaviour therapy, medicines and sometimes revision surgery are options.\u003c/p>\n\u003ch2 id=\"emotional-health\">Emotional health\u003c/h2>\u003cul>\n\u003cli>Your relationship with food changes, which can be challenging\u003c/li>\n\u003cli>Emotional eating may return in stressful times\u003c/li>\n\u003cli>Body image may take time to adjust to rapid change\u003c/li>\n\u003cli>Seek counselling or support groups if you are struggling\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"social-life\">Social life\u003c/h2>\u003cul>\n\u003cli>Order smaller portions or share dishes at restaurants\u003c/li>\n\u003cli>Explain your needs to family so meals can be planned together\u003c/li>\n\u003cli>Be cautious with alcohol, which affects you faster after surgery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"health-improvements-to-track\">Health improvements to track\u003c/h2>\u003cp>Many people see:\u003c/p>\n\u003cul>\n\u003cli>Better blood sugar and fewer diabetes medicines\u003c/li>\n\u003cli>Lower blood pressure\u003c/li>\n\u003cli>Improved sleep and less snoring\u003c/li>\n\u003cli>Easier movement and less joint pain\u003c/li>\n\u003cli>Improved fertility\u003c/li>\n\u003c/ul>\n\u003cp>Medicines should only be adjusted by your doctor.\u003c/p>\n\u003ch2 id=\"pregnancy-and-family-planning\">Pregnancy and family planning\u003c/h2>\u003cp>Pregnancy is generally advised after weight has stabilised, usually 12 to 18 months after surgery, with close monitoring of nutrition.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-your-team\">When should you consult your team?\u003c/h2>\u003cp>Contact your team if you notice weight regain, ongoing digestive problems, low mood or symptoms of deficiency such as fatigue, hair loss or tingling.\u003c/p>\n","faqs":[{"q":"Is follow-up really needed if I feel well?","a":"Yes. Deficiencies can develop silently."},{"q":"Will I always eat small portions?","a":"Portions remain smaller than before, though capacity increases somewhat after the first year."},{"q":"Can I have revision surgery if I regain weight?","a":"In selected cases. Your team will first look at diet, activity and medical options."}],"toc":[{"id":"eating-habits-for-life","text":"Eating habits for life"},{"id":"physical-activity","text":"Physical activity"},{"id":"supplements-and-check-ups","text":"Supplements and check-ups"},{"id":"watching-for-weight-regain","text":"Watching for weight regain"},{"id":"emotional-health","text":"Emotional health"},{"id":"social-life","text":"Social life"},{"id":"health-improvements-to-track","text":"Health improvements to track"},{"id":"pregnancy-and-family-planning","text":"Pregnancy and family planning"},{"id":"when-should-you-consult-your-team","text":"When should you consult your team?"}],"words":427,"read":2},{"slug":"understanding-infertility","sp":"ivf","title":"Understanding Infertility","seo":"Infertility in Men & Women: Causes, Tests & When to See a Specialist","desc":"Learn what infertility means, common causes in women and men, the tests used to find the cause and when couples should seek specialist help.","kw":["infertility","causes of infertility","male infertility","female infertility","fertility tests"],"links":["what-is-ivf","reasons-for-ivf","ivf-vs-iui"],"video":null,"flow":null,"img":["Natural conception pathway: egg, sperm, fallopian tube, uterus","Causes of infertility split by female, male and unexplained","Fertility tests for both partners"],"html":"\u003cp>Infertility is more common than many people realise, affecting about 1 in 6 people worldwide at some point. It is a medical condition, not anyone&#39;s fault, and in many cases it can be treated.\u003c/p>\n\u003ch2 id=\"what-is-infertility\">What is infertility?\u003c/h2>\u003cp>Infertility is usually defined as not becoming pregnant after \u003cstrong>12 months\u003c/strong> of regular unprotected intercourse. For women aged \u003cstrong>35 or older\u003c/strong>, evaluation is advised after \u003cstrong>6 months\u003c/strong>.\u003c/p>\n\u003ch2 id=\"how-common-are-the-causes\">How common are the causes?\u003c/h2>\u003cp>Infertility can involve the woman, the man, both partners or, sometimes, no cause is found. Roughly a third of cases relate to female factors, a third to male factors, and the rest to both partners or unexplained causes.\u003c/p>\n\u003ch2 id=\"common-causes-in-women\">Common causes in women\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Ovulation problems:\u003c/strong> PCOS, thyroid disorders, high prolactin, being very underweight or overweight\u003c/li>\n\u003cli>\u003cstrong>Blocked or damaged fallopian tubes:\u003c/strong> from infection, previous surgery or tuberculosis, which remains an important cause in India and Africa\u003c/li>\n\u003cli>\u003cstrong>Endometriosis:\u003c/strong> tissue similar to the womb lining growing outside the uterus\u003c/li>\n\u003cli>\u003cstrong>Uterine problems:\u003c/strong> fibroids, polyps, scarring\u003c/li>\n\u003cli>\u003cstrong>Reduced egg reserve:\u003c/strong> egg numbers and quality decline with age, especially after 35\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"common-causes-in-men\">Common causes in men\u003c/h2>\u003cul>\n\u003cli>Low sperm count or poor sperm movement or shape\u003c/li>\n\u003cli>Varicocele (enlarged veins in the scrotum)\u003c/li>\n\u003cli>Hormonal problems\u003c/li>\n\u003cli>Blockages in the sperm ducts\u003c/li>\n\u003cli>Infections, smoking, alcohol, heat exposure and certain medicines\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"tests-for-women\">Tests for women\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Hormone blood tests,\u003c/strong> including AMH (an indicator of egg reserve)\u003c/li>\n\u003cli>\u003cstrong>Pelvic ultrasound\u003c/strong> to check the uterus, ovaries and egg follicles\u003c/li>\n\u003cli>\u003cstrong>HSG or saline scan\u003c/strong> to check whether the tubes are open\u003c/li>\n\u003cli>Laparoscopy or hysteroscopy in some cases\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"tests-for-men\">Tests for men\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Semen analysis:\u003c/strong> the key test, checking count, movement and shape\u003c/li>\n\u003cli>Hormone tests and scrotal ultrasound if needed\u003c/li>\n\u003c/ul>\n\u003cp>Both partners should be evaluated together from the start.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>Lifestyle changes and treating underlying conditions\u003c/li>\n\u003cli>Ovulation-inducing medicines\u003c/li>\n\u003cli>Surgery for fibroids, polyps, endometriosis or varicocele\u003c/li>\n\u003cli>\u003cstrong>IUI (intrauterine insemination)\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>IVF and ICSI\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a fertility specialist after 12 months of trying (6 months if the woman is 35 or older), or sooner if periods are irregular, there is known endometriosis or PCOS, or previous pelvic surgery or infection.\u003c/p>\n","faqs":[{"q":"Is infertility usually the woman's problem?","a":"No. Male factors contribute in about half of all cases."},{"q":"Does stress cause infertility?","a":"Stress alone is rarely the main cause, but managing it supports overall wellbeing."},{"q":"Does age affect male fertility?","a":"Yes, though more gradually than in women."}],"toc":[{"id":"what-is-infertility","text":"What is infertility?"},{"id":"how-common-are-the-causes","text":"How common are the causes?"},{"id":"common-causes-in-women","text":"Common causes in women"},{"id":"common-causes-in-men","text":"Common causes in men"},{"id":"tests-for-women","text":"Tests for women"},{"id":"tests-for-men","text":"Tests for men"},{"id":"treatment-options","text":"Treatment options"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":388,"read":2},{"slug":"what-is-ivf","sp":"ivf","title":"What Is IVF and How Does It Work?","seo":"What Is IVF? How In Vitro Fertilisation Works & Who It Helps","desc":"A simple explanation of IVF: how eggs and sperm are combined outside the body, what ICSI is, factors that influence success and legal eligibility in India.","kw":["what is IVF","in vitro fertilisation","IVF treatment","ICSI","test tube baby"],"links":["ivf-step-by-step","reasons-for-ivf","ivf-vs-iui"],"video":"v-ivf","flow":{"caption":"IVF in brief","steps":[{"t":"Eggs grow","d":"Medicines help several eggs mature"},{"t":"Eggs collected","d":"Retrieved from the ovaries"},{"t":"Fertilised in lab","d":"Combined with sperm"},{"t":"Embryo transferred","d":"Placed in the uterus"}]},"img":["Egg and sperm meeting in a laboratory dish","ICSI: single sperm injected into an egg","Embryo development from day 1 to day 5 (blastocyst)"],"html":"\u003cp>IVF, or in vitro fertilisation, is a fertility treatment in which eggs and sperm are joined in a laboratory to create embryos. An embryo is then placed in the uterus to try to achieve pregnancy. &quot;In vitro&quot; means &quot;in glass&quot;, referring to the lab dish.\u003c/p>\n\u003ch2 id=\"how-does-it-work\">How does it work?\u003c/h2>\u003cp>In natural conception, an egg released from the ovary meets sperm in the fallopian tube. IVF carries out this step in the laboratory:\u003c/p>\n\u003col>\n\u003cli>Medicines stimulate the ovaries to produce several eggs.\u003c/li>\n\u003cli>Eggs are collected in a short procedure.\u003c/li>\n\u003cli>Eggs are fertilised with sperm in the lab.\u003c/li>\n\u003cli>Embryos grow for 3 to 5 days.\u003c/li>\n\u003cli>A selected embryo is transferred into the uterus.\u003c/li>\n\u003c/ol>\n\u003cfigure class=\"flow\" aria-label=\"IVF in brief\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>IVF in brief\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Eggs grow\u003c/b>\u003cspan>Medicines help several eggs mature\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Eggs collected\u003c/b>\u003cspan>Retrieved from the ovaries\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Fertilised in lab\u003c/b>\u003cspan>Combined with sperm\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Embryo transferred\u003c/b>\u003cspan>Placed in the uterus\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"what-is-icsi\">What is ICSI?\u003c/h2>\u003cp>\u003cstrong>ICSI (intracytoplasmic sperm injection)\u003c/strong> is a technique in which a single sperm is injected directly into each egg. It is commonly used when sperm count or quality is low, or when fertilisation failed in a previous IVF cycle.\u003c/p>\n\u003ch2 id=\"who-may-need-ivf\">Who may need IVF?\u003c/h2>\u003cul>\n\u003cli>Blocked or damaged fallopian tubes\u003c/li>\n\u003cli>Significant male infertility\u003c/li>\n\u003cli>Endometriosis\u003c/li>\n\u003cli>Reduced egg reserve\u003c/li>\n\u003cli>Unexplained infertility after other treatments\u003c/li>\n\u003cli>Failed IUI cycles\u003c/li>\n\u003cli>Couples needing genetic testing of embryos\u003c/li>\n\u003cli>Fertility preservation before cancer treatment\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-affects-success\">What affects success?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>The woman&#39;s age:\u003c/strong> the most important factor. Success rates fall with age, particularly after 35 to 40.\u003c/li>\n\u003cli>Egg reserve and quality\u003c/li>\n\u003cli>Sperm quality\u003c/li>\n\u003cli>Uterine health\u003c/li>\n\u003cli>Lifestyle factors such as smoking and weight\u003c/li>\n\u003cli>Laboratory quality and clinic experience\u003c/li>\n\u003c/ul>\n\u003cp>No clinic can guarantee a pregnancy. Success rates should be discussed honestly for your individual situation.\u003c/p>\n\u003ch2 id=\"legal-eligibility-in-india\">Legal eligibility in India\u003c/h2>\u003cp>India&#39;s \u003cstrong>Assisted Reproductive Technology (Regulation) Act, 2021\u003c/strong> regulates IVF clinics. Under the Act, ART services are generally available to women aged 21 to 50 and men aged 21 to 55. Clinics and banks must be registered. Your clinic will explain the current legal requirements, including documents needed for international patients.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Consult a fertility specialist to understand whether IVF, a simpler treatment, or treating an underlying cause is the right first step for you.\u003c/p>\n","faqs":[{"q":"Is IVF the same as a \"test tube baby\"?","a":"Yes. \"Test tube baby\" is an older popular term for IVF."},{"q":"Are IVF babies healthy?","a":"The vast majority of babies born after IVF are healthy."},{"q":"How many IVF cycles might I need?","a":"Some people conceive in the first cycle; others need more. Your specialist will advise."}],"toc":[{"id":"how-does-it-work","text":"How does it work?"},{"id":"what-is-icsi","text":"What is ICSI?"},{"id":"who-may-need-ivf","text":"Who may need IVF?"},{"id":"what-affects-success","text":"What affects success?"},{"id":"legal-eligibility-in-india","text":"Legal eligibility in India"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":385,"read":2},{"slug":"ivf-step-by-step","sp":"ivf","title":"Step-by-Step IVF Treatment Process","seo":"IVF Process Step by Step: From Stimulation to Pregnancy Test","desc":"Walk through each stage of an IVF cycle: assessment, ovarian stimulation, egg retrieval, fertilisation, embryo culture, transfer and the pregnancy test.","kw":["IVF process","IVF steps","IVF cycle timeline","ovarian stimulation","IVF procedure"],"links":["egg-retrieval-explained","embryo-transfer-explained","what-to-expect-during-ivf"],"video":"v-ivf","flow":{"caption":"A typical IVF cycle","steps":[{"t":"Day 1 to 2","d":"Baseline scan and blood tests"},{"t":"Days 2 to 12","d":"Daily hormone injections; monitoring scans"},{"t":"Trigger","d":"Final injection about 34 to 36 hours before retrieval"},{"t":"Retrieval","d":"Eggs collected under sedation"},{"t":"Days 1 to 5","d":"Embryos grow in the lab"},{"t":"Transfer","d":"Embryo placed in the uterus"},{"t":"About 2 weeks later","d":"Pregnancy blood test"}]},"img":["IVF timeline calendar graphic","Follicle monitoring ultrasound","Embryologist working in the laboratory"],"html":"\u003cp>An IVF cycle follows a sequence of carefully timed steps. Knowing what happens at each stage helps you plan and feel more in control. A typical fresh cycle takes about four to six weeks from start to pregnancy test.\u003c/p>\n\u003ch2 id=\"step-1-assessment-and-planning\">Step 1: Assessment and planning\u003c/h2>\u003cp>Both partners have tests, including hormone levels, ultrasound and semen analysis. The specialist chooses a medicine plan (protocol) suited to you.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"A typical IVF cycle\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>A typical IVF cycle\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Day 1 to 2\u003c/b>\u003cspan>Baseline scan and blood tests\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Days 2 to 12\u003c/b>\u003cspan>Daily hormone injections; monitoring scans\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Trigger\u003c/b>\u003cspan>Final injection about 34 to 36 hours before retrieval\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Retrieval\u003c/b>\u003cspan>Eggs collected under sedation\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>Days 1 to 5\u003c/b>\u003cspan>Embryos grow in the lab\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">6\u003c/span>\u003cb>Transfer\u003c/b>\u003cspan>Embryo placed in the uterus\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">7\u003c/span>\u003cb>About 2 weeks later\u003c/b>\u003cspan>Pregnancy blood test\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"step-2-ovarian-stimulation\">Step 2: Ovarian stimulation\u003c/h2>\u003cul>\n\u003cli>Daily \u003cstrong>hormone injections\u003c/strong> for about \u003cstrong>8 to 14 days\u003c/strong> encourage several eggs to mature\u003c/li>\n\u003cli>Most injections are given under the skin, and many people learn to give them at home\u003c/li>\n\u003cli>Additional medicines prevent eggs being released too early\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"step-3-monitoring\">Step 3: Monitoring\u003c/h2>\u003cp>You will have regular \u003cstrong>ultrasound scans\u003c/strong> and blood tests to track how the follicles (fluid sacs containing eggs) are growing. Doses may be adjusted.\u003c/p>\n\u003ch2 id=\"step-4-trigger-injection\">Step 4: Trigger injection\u003c/h2>\u003cp>When follicles reach the right size, a final injection matures the eggs. Egg collection is scheduled about \u003cstrong>34 to 36 hours\u003c/strong> later. Timing is critical.\u003c/p>\n\u003ch2 id=\"step-5-egg-retrieval\">Step 5: Egg retrieval\u003c/h2>\u003cp>Eggs are collected using a thin needle guided by ultrasound, under sedation. It takes about 15 to 30 minutes, and you usually go home the same day.\u003c/p>\n\u003ch2 id=\"step-6-sperm-preparation\">Step 6: Sperm preparation\u003c/h2>\u003cp>On the same day, a semen sample is provided and prepared in the lab. Frozen or surgically retrieved sperm can also be used.\u003c/p>\n\u003ch2 id=\"step-7-fertilisation\">Step 7: Fertilisation\u003c/h2>\u003cp>Eggs and sperm are combined by conventional IVF or \u003cstrong>ICSI\u003c/strong>. The next day, the embryologist checks how many eggs have fertilised.\u003c/p>\n\u003ch2 id=\"step-8-embryo-culture\">Step 8: Embryo culture\u003c/h2>\u003cp>Embryos grow in an incubator for \u003cstrong>3 to 5 days\u003c/strong>. Many clinics transfer at the \u003cstrong>blastocyst\u003c/strong> stage (day 5).\u003c/p>\n\u003ch2 id=\"step-9-embryo-transfer\">Step 9: Embryo transfer\u003c/h2>\u003cp>One embryo, or sometimes two, is gently placed in the uterus through a thin catheter. Remaining good-quality embryos may be frozen.\u003c/p>\n\u003ch2 id=\"step-10-waiting-and-the-pregnancy-test\">Step 10: Waiting and the pregnancy test\u003c/h2>\u003cp>Progesterone support is given to prepare the uterine lining. A \u003cstrong>blood pregnancy test\u003c/strong> (beta-hCG) is usually done about \u003cstrong>10 to 14 days\u003c/strong> after transfer.\u003c/p>\n\u003ch2 id=\"frozen-embryo-transfer\">Frozen embryo transfer\u003c/h2>\u003cp>Sometimes all embryos are frozen and transferred in a later cycle. This may be advised to reduce the risk of ovarian hyperstimulation or to allow genetic testing.\u003c/p>\n","faqs":[{"q":"How long does one IVF cycle take?","a":"Usually about 4 to 6 weeks from starting medicines to the pregnancy test."},{"q":"Do I need to stay in hospital?","a":"No. Most steps are outpatient, including egg retrieval and transfer."},{"q":"Can I travel during IVF?","a":"Short travel may be possible, but frequent monitoring visits are needed during stimulation."}],"toc":[{"id":"step-1-assessment-and-planning","text":"Step 1: Assessment and planning"},{"id":"step-2-ovarian-stimulation","text":"Step 2: Ovarian stimulation"},{"id":"step-3-monitoring","text":"Step 3: Monitoring"},{"id":"step-4-trigger-injection","text":"Step 4: Trigger injection"},{"id":"step-5-egg-retrieval","text":"Step 5: Egg retrieval"},{"id":"step-6-sperm-preparation","text":"Step 6: Sperm preparation"},{"id":"step-7-fertilisation","text":"Step 7: Fertilisation"},{"id":"step-8-embryo-culture","text":"Step 8: Embryo culture"},{"id":"step-9-embryo-transfer","text":"Step 9: Embryo transfer"},{"id":"step-10-waiting-and-the-pregnancy-test","text":"Step 10: Waiting and the pregnancy test"},{"id":"frozen-embryo-transfer","text":"Frozen embryo transfer"}],"words":413,"read":2},{"slug":"ivf-vs-iui","sp":"ivf","title":"IVF Versus IUI","seo":"IVF vs IUI: Differences, Who Each Suits & How to Choose","desc":"Compare IUI and IVF fertility treatments: how they work, who each is suitable for, the process involved, and how specialists decide which to try first.","kw":["IVF vs IUI","IUI treatment","intrauterine insemination","IUI success","fertility treatment options"],"links":["what-is-ivf","understanding-infertility","reasons-for-ivf"],"video":null,"flow":{"caption":"How IUI works","steps":[{"t":"Monitoring","d":"Follicle growth tracked with scans"},{"t":"Trigger","d":"Ovulation timed with an injection or test"},{"t":"Sperm washed","d":"Best sperm concentrated in the lab"},{"t":"Insemination","d":"Sperm placed in the uterus with a thin catheter"}]},"img":["IUI: sperm placed inside the uterus","IVF: fertilisation in the lab, embryo placed in uterus","Decision flowchart: IUI or IVF"],"html":"\u003cp>IUI and IVF are two of the most common fertility treatments. They work very differently and suit different situations. Many couples start with simpler treatments before moving to IVF, but this depends on the cause of infertility.\u003c/p>\n\u003ch2 id=\"what-is-iui\">What is IUI?\u003c/h2>\u003cp>\u003cstrong>Intrauterine insemination (IUI)\u003c/strong> places washed, concentrated sperm directly into the uterus around the time of ovulation. It gives sperm a head start, but fertilisation still happens naturally inside the body.\u003c/p>\n\u003cp>IUI is often combined with tablets or injections to help ovulation.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How IUI works\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How IUI works\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Monitoring\u003c/b>\u003cspan>Follicle growth tracked with scans\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Trigger\u003c/b>\u003cspan>Ovulation timed with an injection or test\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Sperm washed\u003c/b>\u003cspan>Best sperm concentrated in the lab\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Insemination\u003c/b>\u003cspan>Sperm placed in the uterus with a thin catheter\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"what-is-ivf\">What is IVF?\u003c/h2>\u003cp>\u003cstrong>In vitro fertilisation (IVF)\u003c/strong> involves collecting eggs, fertilising them in the lab, and transferring an embryo into the uterus.\u003c/p>\n\u003ch2 id=\"comparison\">Comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>IUI\u003c/th>\n\u003cth>IVF\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Where fertilisation happens\u003c/td>\n\u003ctd>Inside the body\u003c/td>\n\u003ctd>In the laboratory\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Medicines\u003c/td>\n\u003ctd>Mild or none\u003c/td>\n\u003ctd>Stronger hormone injections\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Egg retrieval\u003c/td>\n\u003ctd>Not needed\u003c/td>\n\u003ctd>Needed, under sedation\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Open fallopian tubes required\u003c/td>\n\u003ctd>Yes\u003c/td>\n\u003ctd>No\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Procedure time\u003c/td>\n\u003ctd>A few minutes\u003c/td>\n\u003ctd>Several weeks of treatment\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Success per cycle\u003c/td>\n\u003ctd>Lower\u003c/td>\n\u003ctd>Higher\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Embryo freezing\u003c/td>\n\u003ctd>Not applicable\u003c/td>\n\u003ctd>Possible\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"who-may-iui-suit\">Who may IUI suit?\u003c/h2>\u003cul>\n\u003cli>Mild male factor infertility\u003c/li>\n\u003cli>Ovulation problems such as PCOS, with medicines\u003c/li>\n\u003cli>Unexplained infertility in younger women\u003c/li>\n\u003cli>Use of donor sperm\u003c/li>\n\u003cli>Difficulties with intercourse\u003c/li>\n\u003c/ul>\n\u003cp>At least one fallopian tube must be open, and sperm quality should be reasonable.\u003c/p>\n\u003ch2 id=\"who-may-ivf-suit\">Who may IVF suit?\u003c/h2>\u003cul>\n\u003cli>Blocked or damaged tubes\u003c/li>\n\u003cli>Moderate to severe male infertility\u003c/li>\n\u003cli>Advanced age or reduced egg reserve\u003c/li>\n\u003cli>Moderate to severe endometriosis\u003c/li>\n\u003cli>Several failed IUI cycles\u003c/li>\n\u003cli>Need for genetic testing of embryos\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-specialists-decide\">How specialists decide\u003c/h2>\u003cp>Factors include the woman&#39;s age, egg reserve, tubal health, sperm quality, duration of infertility and previous treatments. For women over 37 or with reduced egg reserve, specialists may recommend moving to IVF sooner to avoid losing time.\u003c/p>\n\u003ch2 id=\"how-many-iui-cycles-should-you-try\">How many IUI cycles should you try?\u003c/h2>\u003cp>Often three or four cycles, depending on age and circumstances, before considering IVF.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A fertility specialist can review both partners&#39; test results and recommend the most suitable first step.\u003c/p>\n","faqs":[{"q":"Is IUI painful?","a":"Most women feel only mild cramping, similar to a smear test."},{"q":"Can I go straight to IVF?","a":"Yes, if your situation suggests IVF is more appropriate."},{"q":"Does IUI need sedation?","a":"No."}],"toc":[{"id":"what-is-iui","text":"What is IUI?"},{"id":"what-is-ivf","text":"What is IVF?"},{"id":"comparison","text":"Comparison"},{"id":"who-may-iui-suit","text":"Who may IUI suit?"},{"id":"who-may-ivf-suit","text":"Who may IVF suit?"},{"id":"how-specialists-decide","text":"How specialists decide"},{"id":"how-many-iui-cycles-should-you-try","text":"How many IUI cycles should you try?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":344,"read":2},{"slug":"egg-retrieval-explained","sp":"ivf","title":"Understanding Egg Retrieval","seo":"IVF Egg Retrieval: What Happens, Pain, Recovery & Risks","desc":"What to expect during IVF egg retrieval: preparation, the procedure under sedation, how many eggs to expect, recovery and warning signs of OHSS.","kw":["egg retrieval","oocyte pick-up","IVF egg collection","OHSS","egg retrieval recovery"],"links":["ivf-step-by-step","embryo-transfer-explained","what-to-expect-during-ivf"],"video":null,"flow":{"caption":"Egg retrieval day","steps":[{"t":"Arrive fasting","d":"About 34 to 36 hours after trigger"},{"t":"Sedation","d":"Light anaesthesia for comfort"},{"t":"Retrieval","d":"Needle guided by ultrasound"},{"t":"Recovery","d":"Rest for 1 to 2 hours; go home"}]},"img":["Ultrasound-guided needle reaching ovarian follicles (anatomical)","Follicles and eggs under the microscope","Recovery room after retrieval"],"html":"\u003cp>Egg retrieval, also called oocyte pick-up, is the step in IVF when mature eggs are collected from the ovaries. It is a short, minor procedure, usually done under sedation.\u003c/p>\n\u003ch2 id=\"before-the-procedure\">Before the procedure\u003c/h2>\u003cul>\n\u003cli>Retrieval is scheduled about \u003cstrong>34 to 36 hours\u003c/strong> after your trigger injection; timing is critical\u003c/li>\n\u003cli>You will be asked to fast for several hours beforehand\u003c/li>\n\u003cli>Wear comfortable clothes and avoid make-up, nail polish and jewellery\u003c/li>\n\u003cli>Arrange for someone to take you home\u003c/li>\n\u003c/ul>\n\u003cp>Your partner usually provides a semen sample on the same day, unless frozen sperm is being used.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Egg retrieval day\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Egg retrieval day\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Arrive fasting\u003c/b>\u003cspan>About 34 to 36 hours after trigger\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Sedation\u003c/b>\u003cspan>Light anaesthesia for comfort\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Retrieval\u003c/b>\u003cspan>Needle guided by ultrasound\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Recovery\u003c/b>\u003cspan>Rest for 1 to 2 hours; go home\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"what-happens-during-retrieval\">What happens during retrieval?\u003c/h2>\u003col>\n\u003cli>You are given light sedation or anaesthesia, so you are comfortable and usually asleep.\u003c/li>\n\u003cli>An ultrasound probe is placed in the vagina.\u003c/li>\n\u003cli>A thin needle attached to the probe passes through the vaginal wall into each ovary.\u003c/li>\n\u003cli>Fluid from each follicle is gently drawn out.\u003c/li>\n\u003cli>The embryologist examines the fluid under a microscope to identify eggs.\u003c/li>\n\u003c/ol>\n\u003cp>There are no cuts or stitches. The procedure usually takes \u003cstrong>15 to 30 minutes\u003c/strong>.\u003c/p>\n\u003ch2 id=\"how-many-eggs-will-be-collected\">How many eggs will be collected?\u003c/h2>\u003cp>The number varies widely and depends on age, egg reserve and response to medicines. Not every follicle contains an egg, and not every egg will be mature. Quality matters as much as quantity.\u003c/p>\n\u003ch2 id=\"recovery\">Recovery\u003c/h2>\u003cul>\n\u003cli>Rest for 1 to 2 hours at the clinic\u003c/li>\n\u003cli>Mild cramping, bloating and light spotting are common for a day or two\u003c/li>\n\u003cli>Most women return to normal activities the next day\u003c/li>\n\u003cli>Avoid driving and heavy exercise on the day of retrieval\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"ohss-what-to-watch-for\">OHSS: what to watch for\u003c/h2>\u003cp>\u003cstrong>Ovarian hyperstimulation syndrome (OHSS)\u003c/strong> happens when ovaries over-respond to fertility medicines. Most cases are mild. Contact your clinic urgently if you have:\u003c/p>\n\u003cul>\n\u003cli>Severe abdominal pain or bloating\u003c/li>\n\u003cli>Rapid weight gain (over 1 kg in a day)\u003c/li>\n\u003cli>Nausea or vomiting\u003c/li>\n\u003cli>Reduced urine output\u003c/li>\n\u003cli>Breathlessness\u003c/li>\n\u003c/ul>\n\u003cp>Clinics reduce OHSS risk with careful dosing, special trigger injections and freezing all embryos when needed.\u003c/p>\n\u003ch2 id=\"other-risks\">Other risks\u003c/h2>\u003cp>Uncommon risks include bleeding, infection and injury to nearby organs.\u003c/p>\n\u003ch2 id=\"what-happens-next\">What happens next?\u003c/h2>\u003cp>The next day, your clinic will tell you how many eggs fertilised. Embryos will then be monitored for 3 to 5 days.\u003c/p>\n","faqs":[{"q":"Is egg retrieval painful?","a":"You are sedated during the procedure. Afterwards, mild cramping is common."},{"q":"Will egg retrieval reduce my egg reserve?","a":"No. It collects eggs that would otherwise be lost in that cycle."},{"q":"Can I work the next day?","a":"Most women can, if they feel well."}],"toc":[{"id":"before-the-procedure","text":"Before the procedure"},{"id":"what-happens-during-retrieval","text":"What happens during retrieval?"},{"id":"how-many-eggs-will-be-collected","text":"How many eggs will be collected?"},{"id":"recovery","text":"Recovery"},{"id":"ohss-what-to-watch-for","text":"OHSS: what to watch for"},{"id":"other-risks","text":"Other risks"},{"id":"what-happens-next","text":"What happens next?"}],"words":403,"read":2},{"slug":"embryo-transfer-explained","sp":"ivf","title":"Embryo Transfer Explained","seo":"Embryo Transfer: Procedure, Fresh vs Frozen, and the Two-Week Wait","desc":"Learn what happens during embryo transfer, fresh vs frozen transfer, single embryo transfer, aftercare myths, and what to expect while waiting for results.","kw":["embryo transfer","frozen embryo transfer","single embryo transfer","two week wait","blastocyst transfer"],"links":["ivf-step-by-step","embryo-freezing","what-to-expect-during-ivf"],"video":"v-ivf","flow":{"caption":"Embryo transfer","steps":[{"t":"Embryo chosen","d":"Best embryo selected by the embryologist"},{"t":"Ultrasound guidance","d":"Abdominal scan shows the uterus"},{"t":"Gentle placement","d":"Thin catheter places the embryo"},{"t":"Rest briefly","d":"Then resume normal light activity"}]},"img":["Catheter placing an embryo in the uterus under ultrasound (anatomical)","Day 5 blastocyst illustrated","Fresh vs frozen transfer timeline"],"html":"\u003cp>Embryo transfer is the step in IVF where an embryo is placed into the uterus. It is usually quick, simple and painless, much like a smear test.\u003c/p>\n\u003ch2 id=\"fresh-or-frozen-transfer\">Fresh or frozen transfer?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Fresh transfer:\u003c/strong> the embryo is transferred a few days after egg retrieval, in the same cycle\u003c/li>\n\u003cli>\u003cstrong>Frozen embryo transfer (FET):\u003c/strong> embryos are frozen and transferred in a later cycle after preparing the uterine lining\u003c/li>\n\u003c/ul>\n\u003cp>Frozen transfer may be advised to reduce OHSS risk, allow genetic testing, or when the uterine lining is not ideal. Success rates with frozen transfer are now comparable to fresh transfer in many situations.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Embryo transfer\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Embryo transfer\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Embryo chosen\u003c/b>\u003cspan>Best embryo selected by the embryologist\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Ultrasound guidance\u003c/b>\u003cspan>Abdominal scan shows the uterus\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Gentle placement\u003c/b>\u003cspan>Thin catheter places the embryo\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Rest briefly\u003c/b>\u003cspan>Then resume normal light activity\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"how-many-embryos-are-transferred\">How many embryos are transferred?\u003c/h2>\u003cp>Many clinics now recommend \u003cstrong>single embryo transfer\u003c/strong>, especially for younger women with good-quality embryos. Transferring more than one embryo increases the chance of twins or triplets, which carry higher risks for mother and babies. In India, the ART Act limits the number of embryos that can be transferred.\u003c/p>\n\u003ch2 id=\"what-happens-during-the-procedure\">What happens during the procedure?\u003c/h2>\u003col>\n\u003cli>You may be asked to come with a comfortably full bladder, which helps the ultrasound view.\u003c/li>\n\u003cli>A speculum is inserted, as in a smear test.\u003c/li>\n\u003cli>Under ultrasound guidance, a soft, thin catheter carrying the embryo is passed through the cervix.\u003c/li>\n\u003cli>The embryo is gently placed in the uterus.\u003c/li>\n\u003cli>The embryologist checks that the catheter is empty.\u003c/li>\n\u003c/ol>\n\u003cp>The procedure takes about \u003cstrong>10 to 15 minutes\u003c/strong>. Sedation is usually not needed.\u003c/p>\n\u003ch2 id=\"after-the-transfer\">After the transfer\u003c/h2>\u003cul>\n\u003cli>You can usually go home shortly after\u003c/li>\n\u003cli>Light daily activities are fine\u003c/li>\n\u003cli>Strict bed rest is \u003cstrong>not\u003c/strong> needed and does not improve success\u003c/li>\n\u003cli>Continue progesterone and other medicines exactly as prescribed\u003c/li>\n\u003cli>Avoid heavy exercise and hot baths if advised by your clinic\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-two-week-wait\">The two-week wait\u003c/h2>\u003cp>The time between transfer and the pregnancy test can feel long. Mild cramping or spotting can occur and does not necessarily indicate success or failure. Avoid home pregnancy tests too early, as they may give misleading results.\u003c/p>\n\u003cp>A \u003cstrong>blood test (beta-hCG)\u003c/strong> is usually done about 10 to 14 days after transfer.\u003c/p>\n\u003ch2 id=\"if-the-test-is-negative\">If the test is negative\u003c/h2>\u003cp>It is natural to feel disappointed. Your specialist will review the cycle and discuss next steps, which may include a frozen embryo transfer or changes to the plan.\u003c/p>\n","faqs":[{"q":"Can the embryo fall out if I stand up?","a":"No. The embryo is held safely within the uterine lining."},{"q":"Should I avoid all activity after transfer?","a":"No. Normal light activity is recommended."},{"q":"What symptoms suggest pregnancy?","a":"Symptoms are unreliable. The blood test is the only way to know."}],"toc":[{"id":"fresh-or-frozen-transfer","text":"Fresh or frozen transfer?"},{"id":"how-many-embryos-are-transferred","text":"How many embryos are transferred?"},{"id":"what-happens-during-the-procedure","text":"What happens during the procedure?"},{"id":"after-the-transfer","text":"After the transfer"},{"id":"the-two-week-wait","text":"The two-week wait"},{"id":"if-the-test-is-negative","text":"If the test is negative"}],"words":416,"read":2},{"slug":"embryo-freezing","sp":"ivf","title":"Understanding Embryo Freezing","seo":"Embryo Freezing (Cryopreservation): How It Works, Uses & Safety","desc":"Learn how embryos are frozen by vitrification, why freezing is used, how long embryos can be stored, thawing survival and legal rules in India.","kw":["embryo freezing","vitrification","frozen embryos","cryopreservation","frozen embryo transfer"],"links":["embryo-transfer-explained","ivf-step-by-step","what-is-ivf"],"video":null,"flow":null,"img":["Vitrification: rapid freezing in liquid nitrogen","Storage tanks in an embryology lab","Thawing and transfer timeline"],"html":"\u003cp>Embryo freezing, also called cryopreservation, allows good-quality embryos from an IVF cycle to be stored for future use. It has become a routine and important part of modern IVF.\u003c/p>\n\u003ch2 id=\"how-does-it-work\">How does it work?\u003c/h2>\u003cp>Most clinics use a technique called \u003cstrong>vitrification\u003c/strong>, an ultra-rapid freezing method:\u003c/p>\n\u003col>\n\u003cli>Embryos are treated with special protective solutions.\u003c/li>\n\u003cli>They are frozen almost instantly in liquid nitrogen at about -196°C.\u003c/li>\n\u003cli>This prevents ice crystals forming, which could damage the cells.\u003c/li>\n\u003cli>Embryos are stored in secure, monitored tanks.\u003c/li>\n\u003c/ol>\n\u003cp>When needed, embryos are warmed (thawed) and prepared for transfer.\u003c/p>\n\u003ch2 id=\"why-are-embryos-frozen\">Why are embryos frozen?\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Spare embryos:\u003c/strong> good-quality embryos not used in a fresh transfer can be saved for future attempts or siblings\u003c/li>\n\u003cli>\u003cstrong>Reducing OHSS risk:\u003c/strong> freezing all embryos avoids pregnancy in a cycle with high OHSS risk\u003c/li>\n\u003cli>\u003cstrong>Better uterine preparation:\u003c/strong> if the lining is not ideal during stimulation\u003c/li>\n\u003cli>\u003cstrong>Genetic testing:\u003c/strong> embryos are frozen while test results are awaited\u003c/li>\n\u003cli>\u003cstrong>Medical reasons:\u003c/strong> delaying transfer due to illness or other factors\u003c/li>\n\u003cli>\u003cstrong>Fertility preservation:\u003c/strong> for example before cancer treatment, though egg freezing may be used for women without a partner\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-well-do-embryos-survive-thawing\">How well do embryos survive thawing?\u003c/h2>\u003cp>With vitrification, survival rates are high, often well above 90 percent in experienced laboratories. Pregnancy rates with frozen transfers are comparable to fresh transfers in many situations.\u003c/p>\n\u003ch2 id=\"is-it-safe-for-babies\">Is it safe for babies?\u003c/h2>\u003cp>Studies of children born from frozen embryos have been reassuring. Research continues to monitor long-term outcomes.\u003c/p>\n\u003ch2 id=\"how-long-can-embryos-be-stored\">How long can embryos be stored?\u003c/h2>\u003cp>Embryos remain viable for many years when properly stored. In India, the ART Act sets rules for storage periods and consent; your clinic will explain the current limits and renewal process.\u003c/p>\n\u003ch2 id=\"decisions-to-make\">Decisions to make\u003c/h2>\u003cp>Before freezing, couples sign consent forms covering:\u003c/p>\n\u003cul>\n\u003cli>How long to store embryos\u003c/li>\n\u003cli>What happens to embryos if circumstances change\u003c/li>\n\u003cli>Options for unused embryos, as permitted by law\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"frozen-embryo-transfer\">Frozen embryo transfer\u003c/h2>\u003cp>The uterus is prepared with medicines or by tracking natural ovulation. The embryo is thawed on the day of transfer and placed in the uterus, as in a fresh transfer.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Discuss embryo freezing with your fertility specialist before starting IVF, so you understand the options and consent requirements.\u003c/p>\n","faqs":[{"q":"Does freezing harm embryos?","a":"Modern vitrification has high survival rates. A small number of embryos may not survive thawing."},{"q":"Are frozen embryo transfers less successful?","a":"Not necessarily. Results are comparable to fresh transfers in many cases."},{"q":"Can I freeze eggs instead of embryos?","a":"Yes. Egg freezing is an option, particularly for women without a partner or for fertility preservation."}],"toc":[{"id":"how-does-it-work","text":"How does it work?"},{"id":"why-are-embryos-frozen","text":"Why are embryos frozen?"},{"id":"how-well-do-embryos-survive-thawing","text":"How well do embryos survive thawing?"},{"id":"is-it-safe-for-babies","text":"Is it safe for babies?"},{"id":"how-long-can-embryos-be-stored","text":"How long can embryos be stored?"},{"id":"decisions-to-make","text":"Decisions to make"},{"id":"frozen-embryo-transfer","text":"Frozen embryo transfer"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":421,"read":2},{"slug":"reasons-for-ivf","sp":"ivf","title":"Common Reasons for IVF Treatment","seo":"Why Do Couples Need IVF? Common Medical Reasons Explained","desc":"Explore the common medical reasons for IVF, including blocked tubes, male infertility, endometriosis, PCOS, low egg reserve and genetic conditions.","kw":["reasons for IVF","who needs IVF","IVF for blocked tubes","IVF for male infertility","IVF for PCOS"],"links":["understanding-infertility","what-is-ivf","ivf-vs-iui"],"video":null,"flow":null,"img":["Blocked fallopian tube diagram","Sperm problems: low count, movement, shape","Fertility preservation before cancer treatment"],"html":"\u003cp>IVF is recommended for a range of fertility problems. Sometimes it is the first choice; other times it is used after simpler treatments have not worked. Here are the most common reasons.\u003c/p>\n\u003ch2 id=\"1-blocked-or-damaged-fallopian-tubes\">1. Blocked or damaged fallopian tubes\u003c/h2>\u003cp>Eggs and sperm normally meet in the fallopian tubes. If the tubes are blocked, damaged or removed, IVF bypasses them completely. Common causes include past pelvic infections, tuberculosis, ectopic pregnancy and previous surgery.\u003c/p>\n\u003ch2 id=\"2-male-factor-infertility\">2. Male factor infertility\u003c/h2>\u003cp>Low sperm count, poor movement or abnormal shape can make natural conception difficult. \u003cstrong>IVF with ICSI\u003c/strong>, where a single sperm is injected into each egg, is highly effective. Sperm can even be retrieved surgically from the testes when none are found in semen.\u003c/p>\n\u003ch2 id=\"3-endometriosis\">3. Endometriosis\u003c/h2>\u003cp>Endometriosis can affect egg quality, the tubes and the pelvic environment. IVF is often recommended for moderate to severe endometriosis or when other treatments have not worked.\u003c/p>\n\u003ch2 id=\"4-ovulation-disorders-and-pcos\">4. Ovulation disorders and PCOS\u003c/h2>\u003cp>Many women with PCOS conceive with simpler ovulation-inducing medicines. IVF may be advised when these do not work. Women with PCOS need careful monitoring due to a higher risk of OHSS.\u003c/p>\n\u003ch2 id=\"5-reduced-egg-reserve-and-age\">5. Reduced egg reserve and age\u003c/h2>\u003cp>As women age, egg numbers and quality decline. IVF may make the best use of the available eggs. In some cases, donor eggs may be discussed.\u003c/p>\n\u003ch2 id=\"6-unexplained-infertility\">6. Unexplained infertility\u003c/h2>\u003cp>When all tests are normal but pregnancy has not happened, IVF may be considered after a period of trying or after failed IUI cycles.\u003c/p>\n\u003ch2 id=\"7-failed-iui-cycles\">7. Failed IUI cycles\u003c/h2>\u003cp>If several IUI cycles have not succeeded, IVF offers higher chances per cycle.\u003c/p>\n\u003ch2 id=\"8-genetic-conditions\">8. Genetic conditions\u003c/h2>\u003cp>Couples who carry a known genetic disorder, such as thalassaemia, may choose IVF with \u003cstrong>preimplantation genetic testing (PGT)\u003c/strong>, so that unaffected embryos can be selected. India&#39;s laws strictly prohibit sex selection.\u003c/p>\n\u003ch2 id=\"9-fertility-preservation\">9. Fertility preservation\u003c/h2>\u003cp>People about to undergo cancer treatment, or wishing to delay parenthood, may freeze eggs or embryos for future use.\u003c/p>\n\u003ch2 id=\"10-recurrent-pregnancy-loss\">10. Recurrent pregnancy loss\u003c/h2>\u003cp>In selected cases, IVF with genetic testing may be considered as part of a wider evaluation.\u003c/p>\n\u003ch2 id=\"treating-the-cause-first\">Treating the cause first\u003c/h2>\u003cp>Before IVF, specialists often treat conditions such as thyroid disorders, fibroids or polyps, and advise on weight and lifestyle, which can improve results.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A fertility specialist can determine whether IVF is the best option for your situation after evaluating both partners.\u003c/p>\n","faqs":[{"q":"Is IVF only for older women?","a":"No. IVF helps people of many ages with different causes of infertility."},{"q":"Can IVF help if my husband has no sperm in his semen?","a":"Sometimes. Sperm may be retrieved surgically for ICSI, depending on the cause."},{"q":"Can IVF be used to choose the baby's sex?","a":"No. Sex selection is illegal in India."}],"toc":[{"id":"1-blocked-or-damaged-fallopian-tubes","text":"1. Blocked or damaged fallopian tubes"},{"id":"2-male-factor-infertility","text":"2. Male factor infertility"},{"id":"3-endometriosis","text":"3. Endometriosis"},{"id":"4-ovulation-disorders-and-pcos","text":"4. Ovulation disorders and PCOS"},{"id":"5-reduced-egg-reserve-and-age","text":"5. Reduced egg reserve and age"},{"id":"6-unexplained-infertility","text":"6. Unexplained infertility"},{"id":"7-failed-iui-cycles","text":"7. Failed IUI cycles"},{"id":"8-genetic-conditions","text":"8. Genetic conditions"},{"id":"9-fertility-preservation","text":"9. Fertility preservation"},{"id":"10-recurrent-pregnancy-loss","text":"10. Recurrent pregnancy loss"},{"id":"treating-the-cause-first","text":"Treating the cause first"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":447,"read":2},{"slug":"what-to-expect-during-ivf","sp":"ivf","title":"What to Expect During IVF Treatment","seo":"What to Expect During IVF: Injections, Side Effects, Scans & Timeline","desc":"A realistic guide to day-to-day life during IVF: hormone injections, side effects, clinic visits, work, travel, the emotional rollercoaster and warning signs.","kw":["what to expect during IVF","IVF injections side effects","IVF symptoms","IVF clinic visits","IVF and work"],"links":["ivf-step-by-step","egg-retrieval-explained","preparing-for-ivf"],"video":null,"flow":null,"img":["Self-injection technique illustrated","Calendar of clinic visits during a cycle","Common side effects icons"],"html":"\u003cp>Knowing what IVF actually feels like day to day can make treatment much less daunting. While every person&#39;s experience is different, here is what many people go through.\u003c/p>\n\u003ch2 id=\"injections\">Injections\u003c/h2>\u003cul>\n\u003cli>Most stimulation injections are given \u003cstrong>under the skin\u003c/strong> of the abdomen with fine needles\u003c/li>\n\u003cli>Nurses teach you or your partner how to inject at home\u003c/li>\n\u003cli>Injections are usually given at the same time each day\u003c/li>\n\u003cli>Mild redness or bruising at injection sites is common\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"common-side-effects-during-stimulation\">Common side effects during stimulation\u003c/h2>\u003cul>\n\u003cli>Bloating and a feeling of fullness\u003c/li>\n\u003cli>Mild pelvic discomfort as the ovaries enlarge\u003c/li>\n\u003cli>Breast tenderness\u003c/li>\n\u003cli>Mood swings, irritability or tearfulness\u003c/li>\n\u003cli>Headaches\u003c/li>\n\u003cli>Tiredness\u003c/li>\n\u003c/ul>\n\u003cp>These usually settle after egg retrieval or when the next period starts.\u003c/p>\n\u003ch2 id=\"clinic-visits\">Clinic visits\u003c/h2>\u003cp>During stimulation, expect \u003cstrong>3 to 5 monitoring visits\u003c/strong> over about 10 to 14 days for ultrasound scans and blood tests. Visits are often in the morning and may be scheduled at short notice.\u003c/p>\n\u003ch2 id=\"work-and-daily-life\">Work and daily life\u003c/h2>\u003cul>\n\u003cli>Most people continue working during IVF\u003c/li>\n\u003cli>Plan for time off on the day of egg retrieval and possibly the day after\u003c/li>\n\u003cli>Light exercise such as walking is usually fine; avoid high-impact exercise as ovaries enlarge\u003c/li>\n\u003cli>Avoid alcohol and smoking\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"travelling-for-treatment\">Travelling for treatment\u003c/h2>\u003cp>International patients usually need to stay near the clinic for most of the cycle, roughly \u003cstrong>2 to 3 weeks\u003c/strong> for stimulation, retrieval and transfer. Some initial tests can be done in your home country. Discuss travel timing for after transfer with your specialist.\u003c/p>\n\u003ch2 id=\"the-emotional-side\">The emotional side\u003c/h2>\u003cp>IVF can feel like an emotional rollercoaster, with hope, anxiety and waiting at each step. It is normal to feel:\u003c/p>\n\u003cul>\n\u003cli>Anxious about results at each stage\u003c/li>\n\u003cli>Stressed by injections and appointments\u003c/li>\n\u003cli>Tense during the two-week wait\u003c/li>\n\u003c/ul>\n\u003cp>Talk openly with your partner, consider counselling, and limit online comparisons.\u003c/p>\n\u003ch2 id=\"possible-outcomes-at-each-stage\">Possible outcomes at each stage\u003c/h2>\u003cp>Not every follicle contains an egg, not every egg fertilises, and not every embryo develops. Your clinic will update you at each step. It helps to expect some loss along the way.\u003c/p>\n\u003ch2 id=\"warning-signs-contact-your-clinic-urgently\">Warning signs: contact your clinic urgently\u003c/h2>\u003cul>\n\u003cli>Severe abdominal pain or bloating\u003c/li>\n\u003cli>Breathlessness\u003c/li>\n\u003cli>Vomiting or inability to keep fluids down\u003c/li>\n\u003cli>Reduced urine\u003c/li>\n\u003cli>Heavy bleeding\u003c/li>\n\u003cli>Fever\u003c/li>\n\u003c/ul>\n\u003cp>These may indicate OHSS or another complication.\u003c/p>\n","faqs":[{"q":"Do IVF injections hurt?","a":"Most people find them less painful than expected, with a brief sting."},{"q":"Will IVF medicines cause weight gain?","a":"Bloating is common and temporary. Significant weight gain is unusual."},{"q":"Can I continue my normal diet?","a":"Yes, a balanced diet is recommended. Your clinic may give specific advice."}],"toc":[{"id":"injections","text":"Injections"},{"id":"common-side-effects-during-stimulation","text":"Common side effects during stimulation"},{"id":"clinic-visits","text":"Clinic visits"},{"id":"work-and-daily-life","text":"Work and daily life"},{"id":"travelling-for-treatment","text":"Travelling for treatment"},{"id":"the-emotional-side","text":"The emotional side"},{"id":"possible-outcomes-at-each-stage","text":"Possible outcomes at each stage"},{"id":"warning-signs-contact-your-clinic-urgently","text":"Warning signs: contact your clinic urgently"}],"words":406,"read":2},{"slug":"preparing-for-ivf","sp":"ivf","title":"Emotional and Physical Preparation for IVF","seo":"Preparing for IVF: Health, Lifestyle, Emotional Readiness & Checklist","desc":"How to prepare your body and mind for IVF: lifestyle changes for both partners, supplements, managing stress, practical planning and questions to ask.","kw":["preparing for IVF","IVF preparation tips","folic acid before IVF","lifestyle before IVF","IVF emotional support"],"links":["what-to-expect-during-ivf","understanding-infertility","ivf-step-by-step"],"video":null,"flow":null,"img":["Preparation checklist for both partners","Healthy lifestyle habits illustrated","Couple attending a counselling session"],"html":"\u003cp>Preparing for IVF is about giving yourself the best possible chance of success and feeling ready for the journey ahead. Preparation ideally begins about three months before treatment, as eggs and sperm take that long to mature.\u003c/p>\n\u003ch2 id=\"physical-preparation-for-women\">Physical preparation for women\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Folic acid:\u003c/strong> start a daily supplement, usually 400 micrograms or as advised, ideally three months before treatment\u003c/li>\n\u003cli>\u003cstrong>Healthy weight:\u003c/strong> being significantly underweight or overweight can reduce success\u003c/li>\n\u003cli>\u003cstrong>Stop smoking\u003c/strong> and avoid alcohol\u003c/li>\n\u003cli>\u003cstrong>Limit caffeine\u003c/strong> to one or two cups of tea or coffee a day\u003c/li>\n\u003cli>\u003cstrong>Stay active\u003c/strong> with moderate exercise\u003c/li>\n\u003cli>\u003cstrong>Manage medical conditions:\u003c/strong> thyroid disorders, diabetes and blood pressure should be well controlled\u003c/li>\n\u003cli>\u003cstrong>Check vaccinations,\u003c/strong> such as rubella, before pregnancy\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"physical-preparation-for-men\">Physical preparation for men\u003c/h2>\u003cp>Sperm takes about \u003cstrong>three months\u003c/strong> to develop, so changes now affect the sperm used in IVF:\u003c/p>\n\u003cul>\n\u003cli>Stop smoking and limit alcohol\u003c/li>\n\u003cli>Avoid excessive heat: hot tubs, saunas and laptops on the lap\u003c/li>\n\u003cli>Maintain a healthy weight and diet\u003c/li>\n\u003cli>Discuss any medicines or supplements with the specialist\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"a-balanced-diet\">A balanced diet\u003c/h2>\u003cul>\n\u003cli>Plenty of vegetables, fruit, whole grains and pulses\u003c/li>\n\u003cli>Adequate protein from dal, eggs, fish, paneer or lean meat\u003c/li>\n\u003cli>Healthy fats from nuts and seeds\u003c/li>\n\u003cli>Limit processed foods and sugar\u003c/li>\n\u003c/ul>\n\u003cp>Take supplements only if your doctor recommends them.\u003c/p>\n\u003ch2 id=\"emotional-preparation\">Emotional preparation\u003c/h2>\u003cul>\n\u003cli>Understand the process and possible outcomes\u003c/li>\n\u003cli>Discuss expectations, limits and plans as a couple\u003c/li>\n\u003cli>Decide whom you want to tell, and how much\u003c/li>\n\u003cli>Consider \u003cstrong>counselling,\u003c/strong> which many clinics offer\u003c/li>\n\u003cli>Practise stress-relief: walking, yoga, breathing exercises, adequate sleep\u003c/li>\n\u003cli>Connect with support groups\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"practical-preparation\">Practical preparation\u003c/h2>\u003cul>\n\u003cli>Plan time off for appointments and egg retrieval\u003c/li>\n\u003cli>Organise medicines and a schedule for injections\u003c/li>\n\u003cli>Prepare documents required by law and by your clinic\u003c/li>\n\u003cli>For international patients, plan accommodation near the clinic and the length of stay\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"questions-to-ask-your-specialist\">Questions to ask your specialist\u003c/h2>\u003cul>\n\u003cli>What treatment protocol do you recommend for me and why?\u003c/li>\n\u003cli>What are my realistic chances based on my age and tests?\u003c/li>\n\u003cli>How many embryos will be transferred?\u003c/li>\n\u003cli>What happens to remaining embryos?\u003c/li>\n\u003cli>What are the warning signs of complications?\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Do supplements improve IVF success?","a":"Folic acid is recommended for all women. Evidence for other supplements is limited; take only what your doctor advises."},{"q":"Should we stop having intercourse before IVF?","a":"Your clinic may give specific advice about abstinence before providing a semen sample."},{"q":"Can stress cause IVF failure?","a":"There is no clear evidence that stress alone causes IVF failure, but support improves wellbeing."}],"toc":[{"id":"physical-preparation-for-women","text":"Physical preparation for women"},{"id":"physical-preparation-for-men","text":"Physical preparation for men"},{"id":"a-balanced-diet","text":"A balanced diet"},{"id":"emotional-preparation","text":"Emotional preparation"},{"id":"practical-preparation","text":"Practical preparation"},{"id":"questions-to-ask-your-specialist","text":"Questions to ask your specialist"}],"words":392,"read":2},{"slug":"what-is-bone-marrow-transplant","sp":"bone-marrow-transplant","title":"What Is a Bone Marrow Transplant?","seo":"What Is a Bone Marrow Transplant? A Simple Guide for Patients","desc":"A simple explanation of bone marrow transplant: what bone marrow does, how a transplant replaces it, the main types and why it is sometimes the best option.","kw":["bone marrow transplant","BMT","stem cell transplant","blood cancer treatment","bone marrow function"],"links":["who-needs-bone-marrow-transplant","autologous-vs-allogeneic-transplant","bone-marrow-transplant-process"],"video":"v-bmt","flow":{"caption":"The idea behind a transplant","steps":[{"t":"Diseased marrow","d":"Not making healthy blood cells"},{"t":"Conditioning","d":"Chemotherapy clears the old marrow"},{"t":"New stem cells","d":"Healthy cells given through a drip"},{"t":"Engraftment","d":"New marrow starts making blood"}]},"img":["Bone marrow inside a bone producing red cells, white cells and platelets","Stem cells travelling through the bloodstream to the marrow","Transplant unit room with filtered air"],"html":"\u003cp>A bone marrow transplant (BMT) replaces damaged or diseased bone marrow with healthy blood-forming stem cells. Despite its name, it is not surgery. The new cells are given through a drip, much like a blood transfusion.\u003c/p>\n\u003ch2 id=\"what-does-bone-marrow-do\">What does bone marrow do?\u003c/h2>\u003cp>Bone marrow is the soft, spongy tissue inside larger bones such as the hips. It contains \u003cstrong>stem cells\u003c/strong> that produce:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Red blood cells,\u003c/strong> which carry oxygen\u003c/li>\n\u003cli>\u003cstrong>White blood cells,\u003c/strong> which fight infection\u003c/li>\n\u003cli>\u003cstrong>Platelets,\u003c/strong> which help blood clot\u003c/li>\n\u003c/ul>\n\u003cp>When bone marrow is affected by cancer, fails to work, or produces faulty cells, the body cannot make healthy blood.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"The idea behind a transplant\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>The idea behind a transplant\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Diseased marrow\u003c/b>\u003cspan>Not making healthy blood cells\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Conditioning\u003c/b>\u003cspan>Chemotherapy clears the old marrow\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>New stem cells\u003c/b>\u003cspan>Healthy cells given through a drip\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Engraftment\u003c/b>\u003cspan>New marrow starts making blood\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"how-does-a-transplant-work\">How does a transplant work?\u003c/h2>\u003col>\n\u003cli>\u003cstrong>Conditioning:\u003c/strong> high-dose chemotherapy, sometimes with radiation, destroys diseased cells and makes room for new ones.\u003c/li>\n\u003cli>\u003cstrong>Infusion:\u003c/strong> healthy stem cells are given through a central line into a vein.\u003c/li>\n\u003cli>\u003cstrong>Homing:\u003c/strong> the stem cells travel to the bone marrow.\u003c/li>\n\u003cli>\u003cstrong>Engraftment:\u003c/strong> they settle in and begin producing new blood cells, usually within 2 to 4 weeks.\u003c/li>\n\u003c/ol>\n\u003ch2 id=\"bmt-or-stem-cell-transplant\">BMT or stem cell transplant?\u003c/h2>\u003cp>The terms are often used interchangeably. Today, most transplants use stem cells collected from the \u003cstrong>bloodstream\u003c/strong> rather than directly from the bone marrow, so many doctors call it a \u003cstrong>haematopoietic stem cell transplant (HSCT)\u003c/strong>.\u003c/p>\n\u003ch2 id=\"the-main-types\">The main types\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Autologous:\u003c/strong> the patient&#39;s own stem cells are collected, stored and returned after high-dose treatment\u003c/li>\n\u003cli>\u003cstrong>Allogeneic:\u003c/strong> stem cells come from a donor, such as a sibling, a parent, a child or an unrelated volunteer\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"why-is-it-done\">Why is it done?\u003c/h2>\u003cp>A transplant can:\u003c/p>\n\u003cul>\n\u003cli>Allow doctors to give much higher, more effective doses of chemotherapy\u003c/li>\n\u003cli>Replace marrow that is not working\u003c/li>\n\u003cli>In donor transplants, provide a new immune system that can attack remaining cancer cells, known as the \u003cstrong>graft-versus-tumour effect\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"is-it-a-cure\">Is it a cure?\u003c/h2>\u003cp>For many conditions, BMT offers the best chance of long-term cure or control. Outcomes depend on the disease, its stage, the type of transplant, donor match and the patient&#39;s overall health.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you or a family member has a blood cancer or bone marrow disorder, ask your haematologist whether a transplant evaluation is appropriate and when the best time would be.\u003c/p>\n","faqs":[{"q":"Is a bone marrow transplant surgery?","a":"No. The stem cells are given through a drip."},{"q":"Does the patient need to stay in hospital?","a":"Yes, usually for several weeks, in a specialised transplant unit."},{"q":"Is a transplant painful?","a":"The infusion itself is not painful. Side effects of conditioning treatment are managed with medicines."}],"toc":[{"id":"what-does-bone-marrow-do","text":"What does bone marrow do?"},{"id":"how-does-a-transplant-work","text":"How does a transplant work?"},{"id":"bmt-or-stem-cell-transplant","text":"BMT or stem cell transplant?"},{"id":"the-main-types","text":"The main types"},{"id":"why-is-it-done","text":"Why is it done?"},{"id":"is-it-a-cure","text":"Is it a cure?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":408,"read":2},{"slug":"who-needs-bone-marrow-transplant","sp":"bone-marrow-transplant","title":"Who May Need a Bone Marrow Transplant?","seo":"Who Needs a Bone Marrow Transplant? Conditions Treated by BMT","desc":"Learn which cancers and blood disorders may be treated with bone marrow transplant, including leukaemia, lymphoma, myeloma, aplastic anaemia and thalassaemia.","kw":["who needs bone marrow transplant","BMT for leukaemia","BMT for thalassaemia","aplastic anaemia transplant","myeloma transplant"],"links":["what-is-bone-marrow-transplant","autologous-vs-allogeneic-transplant","leukaemia-explained"],"video":null,"flow":null,"img":["Conditions treated by BMT grouped by cancer and non-cancer","Child with thalassaemia receiving care","Haematologist explaining options to family"],"html":"\u003cp>Bone marrow transplant is recommended for a range of blood cancers and non-cancerous blood disorders. The decision depends on the condition, how it responds to treatment, the patient&#39;s fitness and donor availability.\u003c/p>\n\u003ch2 id=\"blood-cancers\">Blood cancers\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Acute myeloid leukaemia (AML):\u003c/strong> for higher-risk disease or after relapse\u003c/li>\n\u003cli>\u003cstrong>Acute lymphoblastic leukaemia (ALL):\u003c/strong> for high-risk or relapsed disease\u003c/li>\n\u003cli>\u003cstrong>Multiple myeloma:\u003c/strong> autologous transplant is a standard part of treatment for many eligible patients\u003c/li>\n\u003cli>\u003cstrong>Lymphoma:\u003c/strong> both Hodgkin and non-Hodgkin lymphoma, mainly after relapse\u003c/li>\n\u003cli>\u003cstrong>Myelodysplastic syndromes (MDS):\u003c/strong> for higher-risk disease\u003c/li>\n\u003cli>\u003cstrong>Chronic myeloid leukaemia (CML):\u003c/strong> now uncommon, only when medicines do not work\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"non-cancerous-conditions\">Non-cancerous conditions\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Aplastic anaemia:\u003c/strong> the bone marrow stops making enough blood cells\u003c/li>\n\u003cli>\u003cstrong>Thalassaemia major:\u003c/strong> an inherited condition requiring regular blood transfusions; transplant can offer a cure, ideally in childhood\u003c/li>\n\u003cli>\u003cstrong>Sickle cell disease:\u003c/strong> for selected patients with severe disease\u003c/li>\n\u003cli>\u003cstrong>Inherited immune deficiencies\u003c/strong> in children\u003c/li>\n\u003cli>\u003cstrong>Some inherited metabolic disorders\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>Thalassaemia and sickle cell disease are particularly relevant in India and parts of Africa and the Middle East.\u003c/p>\n\u003ch2 id=\"who-is-a-suitable-candidate\">Who is a suitable candidate?\u003c/h2>\u003cp>Doctors consider:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>The disease and its stage:\u003c/strong> transplant works best when the disease is under control, ideally in remission\u003c/li>\n\u003cli>\u003cstrong>Age and general fitness:\u003c/strong> heart, lung, kidney and liver function\u003c/li>\n\u003cli>\u003cstrong>Donor availability\u003c/strong> for allogeneic transplants\u003c/li>\n\u003cli>\u003cstrong>Previous treatments and responses\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Infections\u003c/strong> and other medical conditions\u003c/li>\n\u003cli>\u003cstrong>Caregiver support:\u003c/strong> a dedicated caregiver is essential\u003c/li>\n\u003c/ul>\n\u003cp>Age alone does not exclude patients. Reduced-intensity conditioning makes transplant possible for many older adults.\u003c/p>\n\u003ch2 id=\"timing-matters\">Timing matters\u003c/h2>\u003cp>For some conditions, earlier referral improves outcomes. For thalassaemia, transplant in early childhood, before organ damage from iron overload, generally gives better results.\u003c/p>\n\u003ch2 id=\"the-evaluation\">The evaluation\u003c/h2>\u003cp>Before transplant, patients undergo:\u003c/p>\n\u003cul>\n\u003cli>Blood tests and bone marrow tests\u003c/li>\n\u003cli>Heart and lung assessments\u003c/li>\n\u003cli>Infection screening\u003c/li>\n\u003cli>Dental check-up\u003c/li>\n\u003cli>HLA typing of the patient and potential donors\u003c/li>\n\u003cli>Counselling for patient and family\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>If you or your child has a condition listed above, ask for referral to a transplant centre for an early discussion, even if transplant may not be needed immediately.\u003c/p>\n","faqs":[{"q":"Can adults have a bone marrow transplant?","a":"Yes. Adults of many ages undergo transplant, depending on fitness."},{"q":"Is transplant the only cure for thalassaemia?","a":"It is currently the established curative option. Gene therapies are emerging in some countries."},{"q":"Is BMT used for solid tumours?","a":"Rarely in adults. It is used for a few childhood tumours."}],"toc":[{"id":"blood-cancers","text":"Blood cancers"},{"id":"non-cancerous-conditions","text":"Non-cancerous conditions"},{"id":"who-is-a-suitable-candidate","text":"Who is a suitable candidate?"},{"id":"timing-matters","text":"Timing matters"},{"id":"the-evaluation","text":"The evaluation"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":385,"read":2},{"slug":"autologous-vs-allogeneic-transplant","sp":"bone-marrow-transplant","title":"Autologous Versus Allogeneic Transplant","seo":"Autologous vs Allogeneic Bone Marrow Transplant: Key Differences","desc":"Compare autologous (own cells) and allogeneic (donor cells) bone marrow transplants: how each works, which conditions they treat and their risks.","kw":["autologous transplant","allogeneic transplant","auto vs allo BMT","haploidentical transplant","donor stem cell transplant"],"links":["what-is-bone-marrow-transplant","finding-a-bone-marrow-donor","graft-versus-host-disease"],"video":null,"flow":{"caption":"Autologous transplant","steps":[{"t":"Collect","d":"Patient's own stem cells collected"},{"t":"Store","d":"Frozen in the lab"},{"t":"High-dose therapy","d":"Chemotherapy given"},{"t":"Return","d":"Patient's cells infused to rebuild marrow"}]},"img":["Side-by-side flow: autologous vs allogeneic","Donor types: sibling, haploidentical, unrelated, cord blood","Graft-versus-tumour effect illustrated"],"html":"\u003cp>There are two main types of bone marrow transplant. The key difference is where the stem cells come from: your own body or a donor. Each has its own uses, benefits and risks.\u003c/p>\n\u003ch2 id=\"autologous-transplant-auto\">Autologous transplant (&quot;auto&quot;)\u003c/h2>\u003cp>Your \u003cstrong>own\u003c/strong> stem cells are collected before treatment, frozen and returned after high-dose chemotherapy.\u003c/p>\n\u003cp>\u003cstrong>Main purpose:\u003c/strong> to allow very high doses of chemotherapy that would otherwise permanently damage the marrow.\u003c/p>\n\u003cp>\u003cstrong>Commonly used for:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Multiple myeloma\u003c/li>\n\u003cli>Relapsed lymphoma\u003c/li>\n\u003cli>Some childhood solid tumours\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Advantages:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>No donor needed\u003c/li>\n\u003cli>No risk of graft-versus-host disease\u003c/li>\n\u003cli>Lower risk of serious complications\u003c/li>\n\u003cli>Shorter recovery\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Limitations:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>No graft-versus-tumour effect\u003c/li>\n\u003cli>Not suitable when the marrow itself is diseased or failing\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Autologous transplant\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Autologous transplant\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Collect\u003c/b>\u003cspan>Patient's own stem cells collected\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Store\u003c/b>\u003cspan>Frozen in the lab\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>High-dose therapy\u003c/b>\u003cspan>Chemotherapy given\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Return\u003c/b>\u003cspan>Patient's cells infused to rebuild marrow\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"allogeneic-transplant-allo\">Allogeneic transplant (&quot;allo&quot;)\u003c/h2>\u003cp>Stem cells come from a \u003cstrong>donor\u003c/strong>.\u003c/p>\n\u003cp>\u003cstrong>Types of donors:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Matched sibling:\u003c/strong> a brother or sister with the same tissue type\u003c/li>\n\u003cli>\u003cstrong>Matched unrelated donor:\u003c/strong> from a donor registry\u003c/li>\n\u003cli>\u003cstrong>Haploidentical (half-matched):\u003c/strong> usually a parent, child or sibling, now widely used thanks to improved techniques\u003c/li>\n\u003cli>\u003cstrong>Umbilical cord blood:\u003c/strong> stored stem cells from a newborn&#39;s cord\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Commonly used for:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Acute leukaemias\u003c/li>\n\u003cli>Myelodysplastic syndromes\u003c/li>\n\u003cli>Aplastic anaemia\u003c/li>\n\u003cli>Thalassaemia and sickle cell disease\u003c/li>\n\u003cli>Inherited immune disorders\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Advantages:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Replaces diseased marrow with healthy marrow\u003c/li>\n\u003cli>The donor&#39;s immune cells can attack remaining cancer cells (\u003cstrong>graft-versus-tumour effect\u003c/strong>)\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Limitations:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Requires a suitable donor\u003c/li>\n\u003cli>Risk of \u003cstrong>graft-versus-host disease (GVHD)\u003c/strong>\u003c/li>\n\u003cli>Higher risk of infections and complications\u003c/li>\n\u003cli>Longer recovery and need for immune-suppressing medicines\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"comparison\">Comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Autologous\u003c/th>\n\u003cth>Allogeneic\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Source of cells\u003c/td>\n\u003ctd>Patient\u003c/td>\n\u003ctd>Donor\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Donor search\u003c/td>\n\u003ctd>Not needed\u003c/td>\n\u003ctd>Needed\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>GVHD risk\u003c/td>\n\u003ctd>None\u003c/td>\n\u003ctd>Present\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Graft-versus-tumour effect\u003c/td>\n\u003ctd>No\u003c/td>\n\u003ctd>Yes\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Immune suppression afterwards\u003c/td>\n\u003ctd>Not usually\u003c/td>\n\u003ctd>Usually several months\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Recovery\u003c/td>\n\u003ctd>Shorter\u003c/td>\n\u003ctd>Longer\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"how-is-the-type-chosen\">How is the type chosen?\u003c/h2>\u003cp>Your transplant team considers your disease, whether it affects the marrow, your age and fitness, donor availability and the latest evidence for your condition.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask your haematologist which type of transplant is recommended for you and why.\u003c/p>\n","faqs":[{"q":"Which type is better?","a":"Neither is better overall. The right type depends on the condition."},{"q":"Can a parent be a donor?","a":"Yes. Parents are often haploidentical (half-matched) donors."},{"q":"Can I have both types?","a":"Some patients have an autologous transplant followed later by an allogeneic transplant, if needed."}],"toc":[{"id":"autologous-transplant-auto","text":"Autologous transplant (&quot;auto&quot;)"},{"id":"allogeneic-transplant-allo","text":"Allogeneic transplant (&quot;allo&quot;)"},{"id":"comparison","text":"Comparison"},{"id":"how-is-the-type-chosen","text":"How is the type chosen?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":364,"read":2},{"slug":"stem-cell-sources-explained","sp":"bone-marrow-transplant","title":"Understanding Stem Cell Transplantation","seo":"Stem Cell Sources for Transplant: Bone Marrow, Blood & Cord Blood","desc":"Understand blood-forming stem cells and the three sources used for transplant (bone marrow, peripheral blood and cord blood) and how cells are collected.","kw":["stem cell transplant","peripheral blood stem cells","cord blood transplant","bone marrow harvest","apheresis"],"links":["what-is-bone-marrow-transplant","finding-a-bone-marrow-donor","bone-marrow-transplant-process"],"video":null,"flow":{"caption":"Peripheral blood stem cell collection","steps":[{"t":"Mobilisation","d":"Injections move stem cells into the blood"},{"t":"Apheresis","d":"Blood passes through a collection machine"},{"t":"Collection","d":"Stem cells separated; rest returned"},{"t":"Processing","d":"Cells counted, stored or infused"}]},"img":["Three stem cell sources: bone marrow, bloodstream, umbilical cord","Apheresis machine connected to a donor","Bone marrow harvest from the hip bone"],"html":"\u003cp>Blood-forming stem cells are the &quot;seed&quot; cells from which all blood cells grow. In a transplant, these stem cells are collected, sometimes stored, and then given to the patient to rebuild their blood and immune system.\u003c/p>\n\u003ch2 id=\"what-are-blood-forming-stem-cells\">What are blood-forming stem cells?\u003c/h2>\u003cp>These are special cells, called \u003cstrong>haematopoietic stem cells\u003c/strong>, that can:\u003c/p>\n\u003cul>\n\u003cli>Make copies of themselves\u003c/li>\n\u003cli>Develop into red cells, white cells and platelets\u003c/li>\n\u003c/ul>\n\u003cp>They are not the same as the &quot;stem cell therapies&quot; sometimes advertised for other conditions, many of which are unproven.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Peripheral blood stem cell collection\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Peripheral blood stem cell collection\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Mobilisation\u003c/b>\u003cspan>Injections move stem cells into the blood\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Apheresis\u003c/b>\u003cspan>Blood passes through a collection machine\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Collection\u003c/b>\u003cspan>Stem cells separated; rest returned\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Processing\u003c/b>\u003cspan>Cells counted, stored or infused\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"the-three-sources-of-stem-cells\">The three sources of stem cells\u003c/h2>\u003cp>\u003cstrong>1. Peripheral blood stem cells (PBSC)\u003c/strong>\nThe most common source today, especially for adults.\u003c/p>\n\u003cul>\n\u003cli>The donor or patient receives injections of a growth factor for about \u003cstrong>4 to 5 days\u003c/strong>, which moves stem cells from the marrow into the blood\u003c/li>\n\u003cli>Cells are collected by \u003cstrong>apheresis:\u003c/strong> blood is drawn from one arm, passed through a machine that separates stem cells, and returned through the other arm\u003c/li>\n\u003cli>It takes about \u003cstrong>4 to 6 hours\u003c/strong> and may be repeated the next day\u003c/li>\n\u003cli>Side effects of the injections can include bone aches and tiredness\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>2. Bone marrow harvest\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Stem cells are collected directly from the back of the hip bones with a needle\u003c/li>\n\u003cli>Done under anaesthesia\u003c/li>\n\u003cli>Donors may have soreness in the lower back for a few days\u003c/li>\n\u003cli>Sometimes preferred in children and for certain conditions\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>3. Umbilical cord blood\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Collected from the umbilical cord and placenta after a baby&#39;s birth\u003c/li>\n\u003cli>Stored frozen in cord blood banks\u003c/li>\n\u003cli>Requires less strict matching\u003c/li>\n\u003cli>Contains fewer cells, so it is used more in children or with special techniques in adults\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"comparison\">Comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Peripheral blood\u003c/th>\n\u003cth>Bone marrow\u003c/th>\n\u003cth>Cord blood\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Collection\u003c/td>\n\u003ctd>Apheresis\u003c/td>\n\u003ctd>Needle from hip bones\u003c/td>\n\u003ctd>At birth\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Anaesthesia\u003c/td>\n\u003ctd>Not needed\u003c/td>\n\u003ctd>Needed\u003c/td>\n\u003ctd>Not needed\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Speed of engraftment\u003c/td>\n\u003ctd>Fastest\u003c/td>\n\u003ctd>Moderate\u003c/td>\n\u003ctd>Slowest\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Typical use\u003c/td>\n\u003ctd>Most adults\u003c/td>\n\u003ctd>Selected cases\u003c/td>\n\u003ctd>Mainly children\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"is-donating-stem-cells-safe\">Is donating stem cells safe?\u003c/h2>\u003cp>Yes. Donors are carefully screened. Their stem cells regenerate naturally within weeks. Serious complications are rare.\u003c/p>\n\u003ch2 id=\"processing-the-cells\">Processing the cells\u003c/h2>\u003cp>Collected cells are counted to ensure enough are available. For autologous transplants, they are frozen until needed. For donor transplants, they are often given fresh within a day or two.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Your transplant team will choose the most suitable stem cell source for your condition and donor situation.\u003c/p>\n","faqs":[{"q":"Does donating stem cells weaken the donor?","a":"No. The body replaces donated stem cells within weeks."},{"q":"Should we store our baby's cord blood privately?","a":"Discuss with your doctor; private storage is useful only in specific situations."},{"q":"Are advertised stem cell injections the same?","a":"No. Many advertised \"stem cell therapies\" are unproven. Blood stem cell transplant is an established treatment."}],"toc":[{"id":"what-are-blood-forming-stem-cells","text":"What are blood-forming stem cells?"},{"id":"the-three-sources-of-stem-cells","text":"The three sources of stem cells"},{"id":"comparison","text":"Comparison"},{"id":"is-donating-stem-cells-safe","text":"Is donating stem cells safe?"},{"id":"processing-the-cells","text":"Processing the cells"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":437,"read":2},{"slug":"finding-a-bone-marrow-donor","sp":"bone-marrow-transplant","title":"Finding a Suitable Bone Marrow Donor","seo":"Finding a Bone Marrow Donor: HLA Matching, Siblings & Registries","desc":"Learn how HLA matching works, why siblings are tested first, half-matched family donors, unrelated donor registries and what being a donor involves.","kw":["bone marrow donor","HLA matching","sibling donor","haploidentical donor","donor registry"],"links":["autologous-vs-allogeneic-transplant","stem-cell-sources-explained","graft-versus-host-disease"],"video":null,"flow":{"caption":"The donor search","steps":[{"t":"HLA typing","d":"Patient's tissue type tested"},{"t":"Siblings tested","d":"About 1 in 4 chance of a full match"},{"t":"Family half-match","d":"Parents, children or siblings considered"},{"t":"Registry search","d":"Unrelated volunteers worldwide"}]},"img":["HLA markers inherited from each parent","Chance of sibling match: 1 in 4","Cheek swab test for donor registration"],"html":"\u003cp>For an allogeneic transplant, finding the right donor is a crucial step. The donor&#39;s tissue type needs to match the patient&#39;s as closely as possible to reduce complications.\u003c/p>\n\u003ch2 id=\"what-is-hla-matching\">What is HLA matching?\u003c/h2>\u003cp>\u003cstrong>HLA (human leukocyte antigens)\u003c/strong> are proteins on the surface of cells. The immune system uses them to tell &quot;self&quot; from &quot;non-self&quot;. The closer the HLA match between donor and patient, the lower the risk of rejection and graft-versus-host disease.\u003c/p>\n\u003cp>HLA typing is done with a \u003cstrong>blood test or cheek swab\u003c/strong>.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"The donor search\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>The donor search\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>HLA typing\u003c/b>\u003cspan>Patient's tissue type tested\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Siblings tested\u003c/b>\u003cspan>About 1 in 4 chance of a full match\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Family half-match\u003c/b>\u003cspan>Parents, children or siblings considered\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Registry search\u003c/b>\u003cspan>Unrelated volunteers worldwide\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"unlike-blood-groups\">Unlike blood groups\u003c/h2>\u003cp>HLA matching is different from blood group matching. A donor can have a different blood group from the patient and still be a suitable stem cell donor.\u003c/p>\n\u003ch2 id=\"who-can-be-a-donor\">Who can be a donor?\u003c/h2>\u003cp>\u003cstrong>1. Siblings (brothers and sisters)\u003c/strong>\nWe inherit half our HLA type from each parent. Each full sibling has about a \u003cstrong>1 in 4 chance\u003c/strong> of being a perfect match. Siblings are usually tested first.\u003c/p>\n\u003cp>\u003cstrong>2. Haploidentical (half-matched) family donors\u003c/strong>\nParents, children, and many siblings are at least half-matched. With modern techniques, haploidentical transplants now achieve results comparable to matched donors in many conditions. This has greatly increased donor availability, especially in India.\u003c/p>\n\u003cp>\u003cstrong>3. Matched unrelated donors\u003c/strong>\nVolunteers registered with national and international \u003cstrong>donor registries\u003c/strong>. Finding a match is more likely when the donor shares the patient&#39;s ethnic background. Registries in India are growing but remain small compared with the population.\u003c/p>\n\u003cp>\u003cstrong>4. Umbilical cord blood\u003c/strong>\nStored cord blood units from public banks. Matching requirements are less strict.\u003c/p>\n\u003ch2 id=\"how-long-does-the-search-take\">How long does the search take?\u003c/h2>\u003cul>\n\u003cli>Family testing: usually a few weeks\u003c/li>\n\u003cli>Unrelated donor search: can take weeks to months\u003c/li>\n\u003c/ul>\n\u003cp>For urgent cases, a haploidentical family donor may allow transplant sooner.\u003c/p>\n\u003ch2 id=\"choosing-between-donors\">Choosing between donors\u003c/h2>\u003cp>When more than one donor is available, doctors also consider:\u003c/p>\n\u003cul>\n\u003cli>Donor age and health (younger donors are often preferred)\u003c/li>\n\u003cli>Blood group and virus status\u003c/li>\n\u003cli>Antibodies in the patient against the donor\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-is-involved-for-the-donor\">What is involved for the donor?\u003c/h2>\u003cul>\n\u003cli>Health assessment and blood tests\u003c/li>\n\u003cli>Usually peripheral blood stem cell donation by apheresis, after growth factor injections\u003c/li>\n\u003cli>Occasionally bone marrow harvest under anaesthesia\u003c/li>\n\u003cli>Most donors return to normal activities within days\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"legal-and-ethical-points\">Legal and ethical points\u003c/h2>\u003cp>Donation must be voluntary and unpaid. International patients and donors may need additional documents.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Start donor testing early once a transplant is being considered. Ask your transplant team which family members should be tested.\u003c/p>\n","faqs":[{"q":"Do parents always match?","a":"Parents are usually half-matched, which may be suitable for a haploidentical transplant."},{"q":"Can a donor have a different blood group?","a":"Yes. The patient's blood group will gradually change to the donor's."},{"q":"How can I register as a donor?","a":"Contact a recognised stem cell donor registry; registration usually involves a cheek swab."}],"toc":[{"id":"what-is-hla-matching","text":"What is HLA matching?"},{"id":"unlike-blood-groups","text":"Unlike blood groups"},{"id":"who-can-be-a-donor","text":"Who can be a donor?"},{"id":"how-long-does-the-search-take","text":"How long does the search take?"},{"id":"choosing-between-donors","text":"Choosing between donors"},{"id":"what-is-involved-for-the-donor","text":"What is involved for the donor?"},{"id":"legal-and-ethical-points","text":"Legal and ethical points"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":452,"read":2},{"slug":"bone-marrow-transplant-process","sp":"bone-marrow-transplant","title":"What Happens During Transplantation?","seo":"Bone Marrow Transplant Process Step by Step: Day -7 to Day +100","desc":"A step-by-step guide to the bone marrow transplant journey: evaluation, central line, conditioning, Day 0 infusion, waiting for engraftment and discharge.","kw":["bone marrow transplant process","BMT steps","conditioning chemotherapy","engraftment","day zero transplant"],"links":["what-is-bone-marrow-transplant","recovery-after-bone-marrow-transplant","bmt-complications-infections"],"video":"v-bmt","flow":{"caption":"The transplant timeline","steps":[{"t":"Pre-transplant","d":"Tests, central line, donor collection"},{"t":"Day -7 to -1","d":"Conditioning chemotherapy"},{"t":"Day 0","d":"Stem cell infusion"},{"t":"Days 1 to 21","d":"Low counts; protective care"},{"t":"Engraftment","d":"Counts recover"},{"t":"Day +100","d":"Key recovery milestone"}]},"img":["Transplant timeline graphic with day numbers","Central line (Hickman catheter) in the chest","HEPA-filtered transplant room"],"html":"\u003cp>A bone marrow transplant is a carefully planned journey that takes several weeks in hospital and several months of recovery. Transplant teams count days in relation to &quot;Day 0&quot;, the day of stem cell infusion.\u003c/p>\n\u003ch2 id=\"before-admission\">Before admission\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Detailed evaluation:\u003c/strong> heart, lungs, kidneys, liver, infections and dental check\u003c/li>\n\u003cli>\u003cstrong>Donor preparation\u003c/strong> or collection of your own stem cells\u003c/li>\n\u003cli>\u003cstrong>Central venous line:\u003c/strong> a thin, soft tube is placed in a large vein in the chest or neck. It is used for medicines, blood tests, transfusions and the stem cell infusion, reducing needle pricks.\u003c/li>\n\u003cli>\u003cstrong>Fertility preservation:\u003c/strong> egg or sperm banking can be discussed, as conditioning may affect fertility\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"The transplant timeline\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>The transplant timeline\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Pre-transplant\u003c/b>\u003cspan>Tests, central line, donor collection\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Day -7 to -1\u003c/b>\u003cspan>Conditioning chemotherapy\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Day 0\u003c/b>\u003cspan>Stem cell infusion\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Days 1 to 21\u003c/b>\u003cspan>Low counts; protective care\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">5\u003c/span>\u003cb>Engraftment\u003c/b>\u003cspan>Counts recover\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">6\u003c/span>\u003cb>Day +100\u003c/b>\u003cspan>Key recovery milestone\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"conditioning-around-day-7-to-day-1\">Conditioning (around Day -7 to Day -1)\u003c/h2>\u003cp>You receive \u003cstrong>high-dose chemotherapy\u003c/strong>, sometimes with total body irradiation, over several days. This:\u003c/p>\n\u003cul>\n\u003cli>Destroys diseased cells\u003c/li>\n\u003cli>Suppresses the immune system to prevent rejection (in donor transplants)\u003c/li>\n\u003cli>Makes space in the marrow\u003c/li>\n\u003c/ul>\n\u003cp>Side effects may include nausea, mouth sores, diarrhoea, hair loss and tiredness. These are managed with medicines.\u003c/p>\n\u003cp>\u003cstrong>Reduced-intensity conditioning\u003c/strong> uses lower doses and is suitable for older or less fit patients.\u003c/p>\n\u003ch2 id=\"day-0-stem-cell-infusion\">Day 0: stem cell infusion\u003c/h2>\u003cul>\n\u003cli>Stem cells are given through the central line, like a blood transfusion\u003c/li>\n\u003cli>It usually takes 30 minutes to a few hours\u003c/li>\n\u003cli>Frozen cells may cause a garlic-like taste or smell from the preservative\u003c/li>\n\u003cli>You are awake throughout\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"waiting-for-engraftment-day-1-to-about-day-21\">Waiting for engraftment (Day +1 to about Day +21)\u003c/h2>\u003cp>This is often the most challenging period:\u003c/p>\n\u003cul>\n\u003cli>Blood counts are very low\u003c/li>\n\u003cli>Risk of infection and bleeding is high\u003c/li>\n\u003cli>You stay in a \u003cstrong>protective room\u003c/strong> with filtered air\u003c/li>\n\u003cli>You may need blood and platelet transfusions\u003c/li>\n\u003cli>Antibiotics, antivirals and antifungal medicines are given to prevent or treat infections\u003c/li>\n\u003cli>Mouth sores may make eating difficult; nutritional support may be given\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"engraftment\">Engraftment\u003c/h2>\u003cp>The new stem cells begin producing blood cells, usually within \u003cstrong>2 to 4 weeks\u003c/strong>. Engraftment is confirmed when white cell and platelet counts rise and stay stable.\u003c/p>\n\u003ch2 id=\"discharge\">Discharge\u003c/h2>\u003cp>Most patients go home, or to accommodation near the hospital, once counts recover, infections are controlled and they can eat and drink. This is typically \u003cstrong>3 to 6 weeks\u003c/strong> after admission.\u003c/p>\n\u003ch2 id=\"the-first-100-days\">The first 100 days\u003c/h2>\u003cp>Close follow-up continues with frequent clinic visits, often several times a week initially. Many centres advise staying near the hospital for about \u003cstrong>100 days\u003c/strong> after a donor transplant.\u003c/p>\n","faqs":[{"q":"Will I be in isolation?","a":"You will be in a protective room with restricted visitors to reduce infection risk."},{"q":"Can family stay with me?","a":"Usually one healthy caregiver can stay, following strict hygiene rules."},{"q":"How long is the hospital stay?","a":"Typically 3 to 6 weeks, depending on the transplant type and recovery."}],"toc":[{"id":"before-admission","text":"Before admission"},{"id":"conditioning-around-day-7-to-day-1","text":"Conditioning (around Day -7 to Day -1)"},{"id":"day-0-stem-cell-infusion","text":"Day 0: stem cell infusion"},{"id":"waiting-for-engraftment-day-1-to-about-day-21","text":"Waiting for engraftment (Day +1 to about Day +21)"},{"id":"engraftment","text":"Engraftment"},{"id":"discharge","text":"Discharge"},{"id":"the-first-100-days","text":"The first 100 days"}],"words":432,"read":2},{"slug":"recovery-after-bone-marrow-transplant","sp":"bone-marrow-transplant","title":"Recovery After Bone Marrow Transplantation","seo":"Recovery After Bone Marrow Transplant: First 100 Days & Beyond","desc":"What recovery after bone marrow transplant involves: the first 100 days, infection precautions, diet, energy, follow-up visits and returning to normal life.","kw":["recovery after bone marrow transplant","first 100 days after BMT","BMT precautions","diet after transplant","BMT follow-up"],"links":["bmt-complications-infections","graft-versus-host-disease","life-after-bone-marrow-transplant"],"video":null,"flow":{"caption":"Recovery milestones","steps":[{"t":"Weeks 1 to 4 after discharge","d":"Frequent clinic visits"},{"t":"Day +100","d":"Key milestone; many restrictions eased"},{"t":"Months 3 to 12","d":"Immune system rebuilds"},{"t":"After 1 year","d":"Re-vaccination; return to routine"}]},"img":["Infection prevention checklist at home","Safe food handling illustrated","Clinic follow-up calendar"],"html":"\u003cp>Recovery after a bone marrow transplant is gradual. While blood counts may recover within weeks, the \u003cstrong>immune system takes months to a year or more to rebuild fully\u003c/strong>. Careful precautions during this time help prevent complications.\u003c/p>\n\u003ch2 id=\"the-first-100-days\">The first 100 days\u003c/h2>\u003cp>The first 100 days are the most critical, especially after a donor transplant. During this time:\u003c/p>\n\u003cul>\n\u003cli>Frequent clinic visits, often 2 to 3 times a week at first\u003c/li>\n\u003cli>Regular blood tests to check counts, organ function and medicine levels\u003c/li>\n\u003cli>Monitoring for infections and graft-versus-host disease\u003c/li>\n\u003cli>Possible transfusions\u003c/li>\n\u003c/ul>\n\u003cp>Many patients need to stay \u003cstrong>near the transplant centre\u003c/strong> for this period.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Recovery milestones\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Recovery milestones\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Weeks 1 to 4 after discharge\u003c/b>\u003cspan>Frequent clinic visits\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Day +100\u003c/b>\u003cspan>Key milestone; many restrictions eased\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Months 3 to 12\u003c/b>\u003cspan>Immune system rebuilds\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>After 1 year\u003c/b>\u003cspan>Re-vaccination; return to routine\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"preventing-infection\">Preventing infection\u003c/h2>\u003cul>\n\u003cli>Wash hands frequently, and ask visitors to do the same\u003c/li>\n\u003cli>Wear a mask in crowded places and hospitals\u003c/li>\n\u003cli>Avoid people with colds, flu, chickenpox or other infections\u003c/li>\n\u003cli>Avoid crowds, construction sites and dusty areas\u003c/li>\n\u003cli>Keep pets away from your face, and avoid cleaning cages or litter boxes\u003c/li>\n\u003cli>Keep your central line clean and dry as instructed\u003c/li>\n\u003cli>Do not garden or handle soil until your team allows it\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"food-safety\">Food safety\u003c/h2>\u003cul>\n\u003cli>Eat freshly cooked, well-cooked food\u003c/li>\n\u003cli>Avoid raw or undercooked eggs, meat and fish\u003c/li>\n\u003cli>Avoid street food and unpasteurised milk and juices\u003c/li>\n\u003cli>Wash fruits and vegetables thoroughly; peel when possible\u003c/li>\n\u003cli>Drink safe, boiled or filtered water\u003c/li>\n\u003c/ul>\n\u003cp>Your team will give specific dietary guidelines.\u003c/p>\n\u003ch2 id=\"energy-and-activity\">Energy and activity\u003c/h2>\u003cp>Tiredness is very common and can last months. Gentle daily walking helps rebuild strength. Increase activity gradually and rest when needed.\u003c/p>\n\u003ch2 id=\"medicines\">Medicines\u003c/h2>\u003cp>After a donor transplant, you will take \u003cstrong>immunosuppressive medicines\u003c/strong> to prevent GVHD, along with medicines to prevent infections. Take them exactly as prescribed. Never stop or change doses without advice.\u003c/p>\n\u003ch2 id=\"emotional-recovery\">Emotional recovery\u003c/h2>\u003cp>It is common to feel low, anxious or frustrated during a long recovery. Talk to your team, family or a counsellor.\u003c/p>\n\u003ch2 id=\"returning-to-normal-life\">Returning to normal life\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Activity\u003c/th>\n\u003cth>Typical guidance\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Return to school or work\u003c/td>\n\u003ctd>Often 6 to 12 months after a donor transplant; sooner after autologous\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>International travel\u003c/td>\n\u003ctd>As advised by your team, usually after the early recovery period\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Re-vaccination\u003c/td>\n\u003ctd>Usually starting from 6 to 12 months\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"warning-signs-contact-your-team-immediately\">Warning signs: contact your team immediately\u003c/h2>\u003cul>\n\u003cli>Fever of 38°C (100.4°F) or higher, or chills\u003c/li>\n\u003cli>New rash, diarrhoea or jaundice\u003c/li>\n\u003cli>Breathlessness or cough\u003c/li>\n\u003cli>Bleeding or unusual bruising\u003c/li>\n\u003cli>Redness or discharge around the central line\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Why do I need vaccinations again?","a":"Transplant wipes out previous immunity, so childhood vaccines need to be repeated."},{"q":"When can I eat outside food?","a":"Usually only after your immune system recovers. Your team will advise."},{"q":"When will I feel normal?","a":"Many people feel significantly better within 6 to 12 months, though it varies."}],"toc":[{"id":"the-first-100-days","text":"The first 100 days"},{"id":"preventing-infection","text":"Preventing infection"},{"id":"food-safety","text":"Food safety"},{"id":"energy-and-activity","text":"Energy and activity"},{"id":"medicines","text":"Medicines"},{"id":"emotional-recovery","text":"Emotional recovery"},{"id":"returning-to-normal-life","text":"Returning to normal life"},{"id":"warning-signs-contact-your-team-immediately","text":"Warning signs: contact your team immediately"}],"words":426,"read":2},{"slug":"bmt-complications-infections","sp":"bone-marrow-transplant","title":"Possible Complications and Infections After Bone Marrow Transplant","seo":"Bone Marrow Transplant Complications: Infections, Organ Effects & Care","desc":"Understand possible complications after bone marrow transplant, including infections, mucositis, graft failure, organ toxicity and long-term effects.","kw":["bone marrow transplant complications","infections after BMT","mucositis","graft failure","CMV after transplant"],"links":["graft-versus-host-disease","recovery-after-bone-marrow-transplant","life-after-bone-marrow-transplant"],"video":null,"flow":null,"img":["Timeline of infection risks after transplant (early, intermediate, late)","Mouth care for mucositis","Monitoring tests panel"],"html":"\u003cp>Bone marrow transplant is a powerful treatment, but it carries significant risks because the body&#39;s blood and immune systems are temporarily weakened. Transplant teams work hard to prevent, detect and treat complications early.\u003c/p>\n\u003ch2 id=\"infections\">Infections\u003c/h2>\u003cp>Infections are the most common complication. Risks change over time:\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Period\u003c/th>\n\u003cth>Main infection risks\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>First 3 to 4 weeks\u003c/td>\n\u003ctd>Bacterial and fungal infections while counts are very low\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>1 to 3 months\u003c/td>\n\u003ctd>Virus reactivation, such as CMV; fungal infections\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>After 3 months\u003c/td>\n\u003ctd>Chest infections, shingles, and others while immunity rebuilds\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>\u003cstrong>Prevention:\u003c/strong> preventive antibiotics, antivirals and antifungals, filtered air rooms, hand hygiene, food safety and regular blood tests to detect viruses early.\u003c/p>\n\u003cp>\u003cstrong>Fever is an emergency\u003c/strong> during low counts and needs immediate treatment.\u003c/p>\n\u003ch2 id=\"mucositis\">Mucositis\u003c/h2>\u003cp>Painful sores in the mouth and throat caused by conditioning chemotherapy. They usually heal as counts recover. Treatment includes mouth care, pain relief and nutritional support.\u003c/p>\n\u003ch2 id=\"bleeding-and-anaemia\">Bleeding and anaemia\u003c/h2>\u003cp>Low platelets and red cells may require transfusions until the new marrow engrafts.\u003c/p>\n\u003ch2 id=\"graft-failure\">Graft failure\u003c/h2>\u003cp>Occasionally, the new stem cells do not engraft or later stop working. Options may include a second infusion of stem cells or another transplant.\u003c/p>\n\u003ch2 id=\"graft-versus-host-disease-gvhd\">Graft-versus-host disease (GVHD)\u003c/h2>\u003cp>In donor transplants, the donor&#39;s immune cells may attack the patient&#39;s tissues. This is covered in detail in a separate article.\u003c/p>\n\u003ch2 id=\"organ-effects\">Organ effects\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Liver:\u003c/strong> a condition called veno-occlusive disease (VOD) or sinusoidal obstruction syndrome can occur in the first weeks\u003c/li>\n\u003cli>\u003cstrong>Kidneys:\u003c/strong> some medicines can affect kidney function\u003c/li>\n\u003cli>\u003cstrong>Lungs:\u003c/strong> inflammation or infection\u003c/li>\n\u003cli>\u003cstrong>Heart:\u003c/strong> some conditioning treatments can affect heart function\u003c/li>\n\u003c/ul>\n\u003cp>Regular tests monitor organ function.\u003c/p>\n\u003ch2 id=\"long-term-effects\">Long-term effects\u003c/h2>\u003cul>\n\u003cli>Infertility\u003c/li>\n\u003cli>Early menopause or hormone problems\u003c/li>\n\u003cli>Thyroid problems\u003c/li>\n\u003cli>Cataracts\u003c/li>\n\u003cli>Bone thinning\u003c/li>\n\u003cli>A small increased risk of other cancers later in life\u003c/li>\n\u003cli>Disease relapse\u003c/li>\n\u003c/ul>\n\u003cp>Long-term follow-up clinics screen for these effects.\u003c/p>\n\u003ch2 id=\"reducing-your-risk\">Reducing your risk\u003c/h2>\u003cul>\n\u003cli>Follow infection precautions carefully\u003c/li>\n\u003cli>Take all medicines as prescribed\u003c/li>\n\u003cli>Attend every follow-up appointment\u003c/li>\n\u003cli>Report symptoms early\u003c/li>\n\u003cli>Avoid smoking and alcohol\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"warning-signs-contact-your-team-immediately\">Warning signs: contact your team immediately\u003c/h2>\u003cul>\n\u003cli>Fever or chills\u003c/li>\n\u003cli>Breathlessness or chest pain\u003c/li>\n\u003cli>Yellowing of the skin or eyes, or rapid weight gain\u003c/li>\n\u003cli>Severe diarrhoea\u003c/li>\n\u003cli>Bleeding\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Are complications common?","a":"Some complications, such as infections, are common, but most are managed successfully."},{"q":"What is CMV?","a":"A common virus that can reactivate after transplant. It is monitored with blood tests and treated early."},{"q":"Can the disease come back after transplant?","a":"Yes, relapse is possible. Your team will monitor for it."}],"toc":[{"id":"infections","text":"Infections"},{"id":"mucositis","text":"Mucositis"},{"id":"bleeding-and-anaemia","text":"Bleeding and anaemia"},{"id":"graft-failure","text":"Graft failure"},{"id":"graft-versus-host-disease-gvhd","text":"Graft-versus-host disease (GVHD)"},{"id":"organ-effects","text":"Organ effects"},{"id":"long-term-effects","text":"Long-term effects"},{"id":"reducing-your-risk","text":"Reducing your risk"},{"id":"warning-signs-contact-your-team-immediately","text":"Warning signs: contact your team immediately"}],"words":392,"read":2},{"slug":"graft-versus-host-disease","sp":"bone-marrow-transplant","title":"Understanding Graft-Versus-Host Disease","seo":"Graft-Versus-Host Disease (GVHD): Symptoms, Types & Treatment","desc":"Learn what graft-versus-host disease is, the difference between acute and chronic GVHD, the symptoms to report and how it is prevented and treated.","kw":["graft versus host disease","GVHD","acute GVHD","chronic GVHD","GVHD symptoms"],"links":["autologous-vs-allogeneic-transplant","bmt-complications-infections","life-after-bone-marrow-transplant"],"video":null,"flow":{"caption":"How GVHD happens","steps":[{"t":"Donor immune cells","d":"Arrive with the transplant"},{"t":"Recognise \"foreign\" tissue","d":"Patient's cells look different"},{"t":"Attack","d":"Skin, gut, liver and other organs affected"},{"t":"Treatment","d":"Immune-suppressing medicines calm the reaction"}]},"img":["Donor T-cells attacking patient tissues","Organs commonly affected by acute vs chronic GVHD","Skin rash pattern on palms and soles"],"html":"\u003cp>Graft-versus-host disease (GVHD) is a complication that can occur after an \u003cstrong>allogeneic (donor)\u003c/strong> bone marrow transplant. It happens when immune cells from the donor recognise the patient&#39;s body as foreign and attack it. It does not occur after autologous transplants.\u003c/p>\n\u003ch2 id=\"why-does-it-happen\">Why does it happen?\u003c/h2>\u003cp>The donor&#39;s immune cells are meant to protect the patient and fight remaining cancer. But because the donor and patient are not identical, these cells may also attack healthy tissues.\u003c/p>\n\u003cp>Interestingly, a mild degree of this immune reaction can be helpful, as the same process can attack cancer cells, known as the graft-versus-tumour effect.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"How GVHD happens\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How GVHD happens\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Donor immune cells\u003c/b>\u003cspan>Arrive with the transplant\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Recognise &quot;foreign&quot; tissue\u003c/b>\u003cspan>Patient's cells look different\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Attack\u003c/b>\u003cspan>Skin, gut, liver and other organs affected\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Treatment\u003c/b>\u003cspan>Immune-suppressing medicines calm the reaction\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"types-of-gvhd\">Types of GVHD\u003c/h2>\u003cp>\u003cstrong>Acute GVHD\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Usually develops in the first few months after transplant\u003c/li>\n\u003cli>Mainly affects the \u003cstrong>skin, gut and liver\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>Chronic GVHD\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Usually develops later, often after the first few months\u003c/li>\n\u003cli>Can affect almost any organ, including skin, mouth, eyes, lungs, joints and liver\u003c/li>\n\u003cli>May last for months or years\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms-of-acute-gvhd\">Symptoms of acute GVHD\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Skin:\u003c/strong> rash, often starting on the palms, soles or face, which may spread\u003c/li>\n\u003cli>\u003cstrong>Gut:\u003c/strong> diarrhoea, stomach cramps, nausea, vomiting, loss of appetite\u003c/li>\n\u003cli>\u003cstrong>Liver:\u003c/strong> yellowing of the skin and eyes (jaundice), dark urine\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"symptoms-of-chronic-gvhd\">Symptoms of chronic GVHD\u003c/h2>\u003cul>\n\u003cli>Dry, gritty eyes\u003c/li>\n\u003cli>Dry mouth, mouth sores or sensitivity to spicy food\u003c/li>\n\u003cli>Skin tightening, thickening or colour changes\u003c/li>\n\u003cli>Joint stiffness\u003c/li>\n\u003cli>Breathlessness or persistent cough\u003c/li>\n\u003cli>Weight loss\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"risk-factors\">Risk factors\u003c/h2>\u003cul>\n\u003cli>Less closely matched donors\u003c/li>\n\u003cli>Unrelated or older donors\u003c/li>\n\u003cli>Female donor to male patient\u003c/li>\n\u003cli>Peripheral blood stem cells compared with bone marrow\u003c/li>\n\u003cli>Older patient age\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"prevention\">Prevention\u003c/h2>\u003cp>Patients receive \u003cstrong>immunosuppressive medicines\u003c/strong> for several months after transplant to reduce the risk of GVHD. Additional preventive strategies are used depending on the donor type.\u003c/p>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cp>Based on symptoms, examination and tests. Sometimes a small skin or gut biopsy is needed to confirm.\u003c/p>\n\u003ch2 id=\"treatment\">Treatment\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Steroids:\u003c/strong> the first-line treatment for many cases\u003c/li>\n\u003cli>\u003cstrong>Other immune-suppressing or targeted medicines\u003c/strong> when steroids are not enough\u003c/li>\n\u003cli>\u003cstrong>Supportive care:\u003c/strong> eye drops, mouth care, skin moisturisers and nutritional support\u003c/li>\n\u003cli>\u003cstrong>Physiotherapy\u003c/strong> for joint stiffness\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"living-with-gvhd\">Living with GVHD\u003c/h2>\u003cp>Many people with GVHD lead fulfilling lives with treatment. Treatment also increases infection risk, so precautions remain important.\u003c/p>\n\u003ch2 id=\"when-should-you-contact-your-team\">When should you contact your team?\u003c/h2>\u003cp>Report any new rash, diarrhoea, jaundice, dry eyes or mouth, breathlessness or skin changes promptly. Early treatment works best.\u003c/p>\n","faqs":[{"q":"Does GVHD mean the transplant has failed?","a":"No. GVHD means the donor cells are active. It needs treatment but is not graft failure."},{"q":"Can GVHD be cured?","a":"Many cases settle with treatment. Chronic GVHD may need longer-term management."},{"q":"Can GVHD occur years later?","a":"Chronic GVHD can develop or flare months or even years after transplant."}],"toc":[{"id":"why-does-it-happen","text":"Why does it happen?"},{"id":"types-of-gvhd","text":"Types of GVHD"},{"id":"symptoms-of-acute-gvhd","text":"Symptoms of acute GVHD"},{"id":"symptoms-of-chronic-gvhd","text":"Symptoms of chronic GVHD"},{"id":"risk-factors","text":"Risk factors"},{"id":"prevention","text":"Prevention"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment","text":"Treatment"},{"id":"living-with-gvhd","text":"Living with GVHD"},{"id":"when-should-you-contact-your-team","text":"When should you contact your team?"}],"words":426,"read":2},{"slug":"life-after-bone-marrow-transplant","sp":"bone-marrow-transplant","title":"Life After Bone Marrow Transplantation","seo":"Life After Bone Marrow Transplant: Long-Term Health, Work & Family","desc":"Living well after bone marrow transplant: long-term follow-up, re-vaccination, fertility, returning to work and school, emotional health and healthy habits.","kw":["life after bone marrow transplant","long term follow-up BMT","fertility after transplant","returning to work after BMT","BMT survivorship"],"links":["recovery-after-bone-marrow-transplant","graft-versus-host-disease","bmt-complications-infections"],"video":null,"flow":null,"img":["Survivorship care plan checklist","Re-vaccination schedule graphic","Patient returning to work or school"],"html":"\u003cp>Many people go on to live full, active lives after a bone marrow transplant. Life after transplant involves gradually returning to normal routines while continuing long-term health care.\u003c/p>\n\u003ch2 id=\"long-term-follow-up\">Long-term follow-up\u003c/h2>\u003cp>Even after you feel well, regular check-ups remain important:\u003c/p>\n\u003cul>\n\u003cli>Monitoring blood counts and disease status\u003c/li>\n\u003cli>Screening for late effects on the heart, lungs, thyroid, bones, eyes and hormones\u003c/li>\n\u003cli>Monitoring for chronic GVHD after donor transplants\u003c/li>\n\u003cli>Cancer screening as recommended\u003c/li>\n\u003c/ul>\n\u003cp>Most centres provide a \u003cstrong>survivorship care plan\u003c/strong> outlining what tests are needed and when.\u003c/p>\n\u003ch2 id=\"re-vaccination\">Re-vaccination\u003c/h2>\u003cp>Transplant erases immunity from previous vaccines. Re-vaccination usually begins \u003cstrong>6 to 12 months\u003c/strong> after transplant, following a schedule set by your team. Live vaccines are delayed until the immune system has recovered sufficiently.\u003c/p>\n\u003ch2 id=\"returning-to-work-and-school\">Returning to work and school\u003c/h2>\u003cul>\n\u003cli>Many people return within \u003cstrong>6 to 12 months\u003c/strong> after a donor transplant, and sooner after an autologous transplant\u003c/li>\n\u003cli>A gradual return, such as part-time hours, often helps\u003c/li>\n\u003cli>Children can usually return to school when their team advises, with infection precautions\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"fertility-and-family-planning\">Fertility and family planning\u003c/h2>\u003cul>\n\u003cli>Conditioning treatment can affect fertility in both men and women\u003c/li>\n\u003cli>Fertility preservation before transplant, such as egg, embryo or sperm freezing, may allow future parenthood\u003c/li>\n\u003cli>Some people recover fertility naturally; others may use assisted reproductive techniques\u003c/li>\n\u003cli>Women may experience early menopause and may need hormone therapy\u003c/li>\n\u003c/ul>\n\u003cp>Discuss family planning with your transplant team and a fertility specialist.\u003c/p>\n\u003ch2 id=\"emotional-health\">Emotional health\u003c/h2>\u003cp>Recovery can bring relief and gratitude, but also anxiety about relapse, fatigue or changes in body image and relationships. This is normal. Counselling, support groups and talking with other transplant survivors can help.\u003c/p>\n\u003ch2 id=\"healthy-habits\">Healthy habits\u003c/h2>\u003cul>\n\u003cli>Do not smoke, and limit alcohol\u003c/li>\n\u003cli>Eat a balanced diet\u003c/li>\n\u003cli>Exercise regularly to rebuild strength\u003c/li>\n\u003cli>Protect your skin from the sun, especially if you have had GVHD\u003c/li>\n\u003cli>Maintain good dental hygiene and regular dental check-ups\u003c/li>\n\u003cli>Get enough sleep\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"travel\">Travel\u003c/h2>\u003cp>International travel is usually possible once your team approves. Carry a summary of your medical history and medicines, and check vaccination requirements for your destination.\u003c/p>\n\u003ch2 id=\"knowing-when-to-seek-help\">Knowing when to seek help\u003c/h2>\u003cp>Contact your team if you notice:\u003c/p>\n\u003cul>\n\u003cli>Persistent fever or infections\u003c/li>\n\u003cli>New fatigue, bruising or bleeding\u003c/li>\n\u003cli>Breathlessness\u003c/li>\n\u003cli>Signs of chronic GVHD, such as dry eyes, mouth sores or skin tightening\u003c/li>\n\u003c/ul>\n","faqs":[{"q":"Will I need follow-up for life?","a":"Long-term follow-up is recommended, though visits become less frequent over time."},{"q":"Can I have children after transplant?","a":"Some people can, either naturally or with assisted reproduction. Discuss options early."},{"q":"Will my blood group change?","a":"After a donor transplant with a different blood group, your blood group gradually changes to match your donor's."}],"toc":[{"id":"long-term-follow-up","text":"Long-term follow-up"},{"id":"re-vaccination","text":"Re-vaccination"},{"id":"returning-to-work-and-school","text":"Returning to work and school"},{"id":"fertility-and-family-planning","text":"Fertility and family planning"},{"id":"emotional-health","text":"Emotional health"},{"id":"healthy-habits","text":"Healthy habits"},{"id":"travel","text":"Travel"},{"id":"knowing-when-to-seek-help","text":"Knowing when to seek help"}],"words":427,"read":2},{"slug":"chronic-kidney-disease","sp":"kidney-transplant","title":"Understanding Chronic Kidney Disease","seo":"Chronic Kidney Disease (CKD): Stages, Symptoms, Causes & Treatment","desc":"Learn what chronic kidney disease is, the five stages, early warning signs, main causes such as diabetes and high blood pressure, and treatment options.","kw":["chronic kidney disease","CKD stages","kidney failure symptoms","eGFR","diabetic kidney disease"],"links":["when-kidney-transplant-is-needed","kidney-transplant-explained","living-vs-deceased-donor"],"video":null,"flow":null,"img":["Kidney anatomy and filtering units (nephrons)","CKD stages 1 to 5 by eGFR","Swollen ankles and puffy eyes as warning signs"],"html":"\u003cp>Chronic kidney disease (CKD) means the kidneys are gradually losing their ability to filter waste and excess fluid from the blood. It often develops silently over years. Early detection can slow its progress.\u003c/p>\n\u003ch2 id=\"what-do-the-kidneys-do\">What do the kidneys do?\u003c/h2>\u003cul>\n\u003cli>Filter waste and excess water to make urine\u003c/li>\n\u003cli>Balance salts and minerals\u003c/li>\n\u003cli>Help control blood pressure\u003c/li>\n\u003cli>Make a hormone that helps produce red blood cells\u003c/li>\n\u003cli>Keep bones healthy by activating vitamin D\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-five-stages-of-ckd\">The five stages of CKD\u003c/h2>\u003cp>Doctors measure kidney function using \u003cstrong>eGFR\u003c/strong> (estimated glomerular filtration rate), calculated from a blood creatinine test.\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Stage\u003c/th>\n\u003cth>eGFR (approx.)\u003c/th>\n\u003cth>What it means\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>1\u003c/td>\n\u003ctd>90 or above\u003c/td>\n\u003ctd>Normal function with signs of kidney damage\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>2\u003c/td>\n\u003ctd>60–89\u003c/td>\n\u003ctd>Mildly reduced\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>3\u003c/td>\n\u003ctd>30–59\u003c/td>\n\u003ctd>Moderately reduced\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>4\u003c/td>\n\u003ctd>15–29\u003c/td>\n\u003ctd>Severely reduced\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>5\u003c/td>\n\u003ctd>Below 15\u003c/td>\n\u003ctd>Kidney failure (end-stage kidney disease)\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"symptoms\">Symptoms\u003c/h2>\u003cp>Early CKD usually has \u003cstrong>no symptoms\u003c/strong>. As it advances, people may notice:\u003c/p>\n\u003cul>\n\u003cli>Swelling of the feet, ankles or around the eyes\u003c/li>\n\u003cli>Tiredness and weakness\u003c/li>\n\u003cli>Reduced appetite, nausea or vomiting\u003c/li>\n\u003cli>Itching\u003c/li>\n\u003cli>Changes in urination, including foamy urine or passing urine at night\u003c/li>\n\u003cli>Breathlessness\u003c/li>\n\u003cli>Muscle cramps\u003c/li>\n\u003cli>Difficulty concentrating\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"main-causes\">Main causes\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Diabetes:\u003c/strong> the leading cause\u003c/li>\n\u003cli>\u003cstrong>High blood pressure\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Glomerulonephritis:\u003c/strong> inflammation of the kidney&#39;s filters\u003c/li>\n\u003cli>\u003cstrong>Polycystic kidney disease:\u003c/strong> an inherited condition\u003c/li>\n\u003cli>Repeated kidney infections, kidney stones or blockages\u003c/li>\n\u003cli>Long-term use of certain painkillers or unregulated herbal remedies\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diagnosis\">Diagnosis\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Blood test\u003c/strong> for creatinine and eGFR\u003c/li>\n\u003cli>\u003cstrong>Urine test\u003c/strong> for protein (albumin) and blood\u003c/li>\n\u003cli>\u003cstrong>Ultrasound\u003c/strong> of the kidneys\u003c/li>\n\u003cli>Sometimes a \u003cstrong>kidney biopsy\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>People with diabetes or high blood pressure should have these tests at least once a year.\u003c/p>\n\u003ch2 id=\"treatment-options\">Treatment options\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Controlling blood sugar and blood pressure\u003c/strong>\u003c/li>\n\u003cli>Medicines that protect the kidneys\u003c/li>\n\u003cli>Diet changes, such as reducing salt and, in some stages, protein and potassium\u003c/li>\n\u003cli>Avoiding medicines that harm the kidneys, such as some painkillers\u003c/li>\n\u003cli>Treating anaemia and bone problems\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-kidneys-fail\">When kidneys fail\u003c/h2>\u003cp>At stage 5, the options are:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Dialysis:\u003c/strong> haemodialysis or peritoneal dialysis\u003c/li>\n\u003cli>\u003cstrong>Kidney transplant:\u003c/strong> often the best long-term option for suitable patients\u003c/li>\n\u003cli>\u003cstrong>Conservative care:\u003c/strong> focusing on symptoms and quality of life\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>See a nephrologist if your eGFR is falling, protein is found in your urine, or you have diabetes or high blood pressure with abnormal kidney tests.\u003c/p>\n","faqs":[{"q":"Can CKD be reversed?","a":"Damage usually cannot be reversed, but progression can often be slowed significantly."},{"q":"Does drinking more water cure kidney disease?","a":"No. Fluid needs vary, and some patients need to limit fluids. Follow your doctor's advice."},{"q":"Is CKD always progressive?","a":"Not always. Many people remain stable for years with good control."}],"toc":[{"id":"what-do-the-kidneys-do","text":"What do the kidneys do?"},{"id":"the-five-stages-of-ckd","text":"The five stages of CKD"},{"id":"symptoms","text":"Symptoms"},{"id":"main-causes","text":"Main causes"},{"id":"diagnosis","text":"Diagnosis"},{"id":"treatment-options","text":"Treatment options"},{"id":"when-kidneys-fail","text":"When kidneys fail"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":413,"read":2},{"slug":"when-kidney-transplant-is-needed","sp":"kidney-transplant","title":"When Does a Patient Need a Kidney Transplant?","seo":"When Is a Kidney Transplant Needed? Eligibility & Pre-Emptive Transplant","desc":"Learn when a kidney transplant is recommended, why it often beats long-term dialysis, the eligibility assessment and the benefits of pre-emptive transplant.","kw":["when is kidney transplant needed","kidney transplant eligibility","dialysis vs transplant","pre-emptive kidney transplant","end-stage kidney disease"],"links":["chronic-kidney-disease","kidney-transplant-explained","preparing-for-kidney-transplant"],"video":null,"flow":null,"img":["Comparison: dialysis vs transplant lifestyle","Transplant evaluation checklist","Timeline of referral and evaluation"],"html":"\u003cp>A kidney transplant is considered when the kidneys have failed or are close to failing. For many patients, transplantation offers longer life and better quality of life than long-term dialysis.\u003c/p>\n\u003ch2 id=\"when-is-it-recommended\">When is it recommended?\u003c/h2>\u003cp>A transplant is usually considered for people with:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>End-stage kidney disease\u003c/strong> (CKD stage 5), with eGFR below about 15\u003c/li>\n\u003cli>Kidney function steadily declining towards failure, often with eGFR below about 20\u003c/li>\n\u003cli>Patients already on dialysis who are fit for surgery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"pre-emptive-transplant\">Pre-emptive transplant\u003c/h2>\u003cp>A \u003cstrong>pre-emptive transplant\u003c/strong> is done before dialysis begins, usually with a living donor. It is associated with better outcomes and avoids the burden of dialysis. Early referral to a transplant team makes this possible.\u003c/p>\n\u003ch2 id=\"transplant-vs-dialysis\">Transplant vs dialysis\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Dialysis\u003c/th>\n\u003cth>Transplant\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>How it works\u003c/td>\n\u003ctd>Machine or fluid filters the blood\u003c/td>\n\u003ctd>A new kidney does the work\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Time commitment\u003c/td>\n\u003ctd>Several sessions a week or daily exchanges\u003c/td>\n\u003ctd>Regular follow-up visits\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Diet and fluids\u003c/td>\n\u003ctd>More restricted\u003c/td>\n\u003ctd>Fewer restrictions\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Energy and quality of life\u003c/td>\n\u003ctd>Often reduced\u003c/td>\n\u003ctd>Usually better\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Long-term survival\u003c/td>\n\u003ctd>Lower on average\u003c/td>\n\u003ctd>Generally better for suitable patients\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Lifelong medicines\u003c/td>\n\u003ctd>Some\u003c/td>\n\u003ctd>Daily immunosuppressants\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"who-is-eligible\">Who is eligible?\u003c/h2>\u003cp>The transplant team assesses:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Overall health:\u003c/strong> heart, lungs and blood vessels\u003c/li>\n\u003cli>\u003cstrong>Infections:\u003c/strong> active infections must be treated first\u003c/li>\n\u003cli>\u003cstrong>Cancer:\u003c/strong> active cancer usually needs to be treated, with a period of remission\u003c/li>\n\u003cli>\u003cstrong>Ability to take lifelong medicines\u003c/strong> and attend follow-up\u003c/li>\n\u003cli>\u003cstrong>Psychological and social support\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>Age alone does not rule out a transplant. Fitness matters more.\u003c/p>\n\u003ch2 id=\"who-may-not-be-suitable\">Who may not be suitable?\u003c/h2>\u003cul>\n\u003cli>Severe heart or lung disease that makes surgery unsafe\u003c/li>\n\u003cli>Active cancer or uncontrolled infection\u003c/li>\n\u003cli>Inability to follow treatment, such as active substance misuse\u003c/li>\n\u003cli>Very limited life expectancy from other conditions\u003c/li>\n\u003c/ul>\n\u003cp>Some conditions can be treated first so that a transplant becomes possible later.\u003c/p>\n\u003ch2 id=\"the-evaluation-process\">The evaluation process\u003c/h2>\u003cp>Expect blood tests, heart tests, imaging, dental and gynaecological check-ups, infection screening, blood group and tissue typing, and counselling for both recipient and donor.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Ask your nephrologist about transplant referral once your kidney function reaches stage 4. Early discussion gives time to evaluate potential donors.\u003c/p>\n","faqs":[{"q":"Is a transplant a cure for kidney failure?","a":"It is a treatment, not a cure. It requires lifelong medicines and follow-up."},{"q":"Can I have a transplant if I am already on dialysis?","a":"Yes. Many transplant recipients have been on dialysis."},{"q":"Do I need to stop dialysis immediately after transplant?","a":"Most people no longer need dialysis once the new kidney works well, though some need it briefly."}],"toc":[{"id":"when-is-it-recommended","text":"When is it recommended?"},{"id":"pre-emptive-transplant","text":"Pre-emptive transplant"},{"id":"transplant-vs-dialysis","text":"Transplant vs dialysis"},{"id":"who-is-eligible","text":"Who is eligible?"},{"id":"who-may-not-be-suitable","text":"Who may not be suitable?"},{"id":"the-evaluation-process","text":"The evaluation process"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":407,"read":2},{"slug":"kidney-transplant-explained","sp":"kidney-transplant","title":"Kidney Transplant Procedure Explained","seo":"How Does a Kidney Transplant Work? Procedure Explained Simply","desc":"Learn how a kidney transplant works: where the new kidney is placed, why old kidneys are usually left, how it connects and how long transplanted kidneys last.","kw":["kidney transplant procedure","how kidney transplant works","renal transplant","new kidney placement","transplant kidney lifespan"],"links":["kidney-transplant-surgery-day","living-vs-deceased-donor","immunosuppressant-medicines"],"video":"v-kidney","flow":{"caption":"How the new kidney connects","steps":[{"t":"Placement","d":"Lower abdomen, right or left side"},{"t":"Artery","d":"Joined to an artery supplying the leg"},{"t":"Vein","d":"Joined to a nearby vein"},{"t":"Ureter","d":"Connected to the bladder; urine flows"}]},"img":["New kidney in the lower abdomen with connections labelled (anatomical)","Native kidneys left in place","Temporary stent in the ureter"],"html":"\u003cp>A kidney transplant places a healthy kidney from a donor into a person whose kidneys have failed. One healthy kidney can do the work of two. This article explains how the transplant works; see our separate guide on what happens on the day of surgery.\u003c/p>\n\u003ch2 id=\"where-is-the-new-kidney-placed\">Where is the new kidney placed?\u003c/h2>\u003cp>Unlike what many people expect, the new kidney is \u003cstrong>not\u003c/strong> placed where the old kidneys are. It is placed in the \u003cstrong>lower abdomen\u003c/strong>, on the right or left side, just above the groin. This location:\u003c/p>\n\u003cul>\n\u003cli>Allows easy connection to large blood vessels\u003c/li>\n\u003cli>Keeps the kidney close to the bladder\u003c/li>\n\u003cli>Makes it easier to monitor and, if needed, biopsy\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"How the new kidney connects\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>How the new kidney connects\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Placement\u003c/b>\u003cspan>Lower abdomen, right or left side\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Artery\u003c/b>\u003cspan>Joined to an artery supplying the leg\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Vein\u003c/b>\u003cspan>Joined to a nearby vein\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Ureter\u003c/b>\u003cspan>Connected to the bladder; urine flows\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"what-happens-to-the-old-kidneys\">What happens to the old kidneys?\u003c/h2>\u003cp>Usually, the patient&#39;s own kidneys are \u003cstrong>left in place\u003c/strong>. They are removed only in specific situations, such as repeated infections, very large polycystic kidneys or uncontrolled blood pressure.\u003c/p>\n\u003ch2 id=\"how-is-the-kidney-connected\">How is the kidney connected?\u003c/h2>\u003cp>The surgeon makes three connections:\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>The kidney&#39;s artery\u003c/strong> is joined to an artery in the pelvis\u003c/li>\n\u003cli>\u003cstrong>The kidney&#39;s vein\u003c/strong> is joined to a nearby vein\u003c/li>\n\u003cli>\u003cstrong>The ureter\u003c/strong> (the tube that carries urine) is connected to the bladder\u003c/li>\n\u003c/ol>\n\u003cp>A small temporary tube called a \u003cstrong>stent\u003c/strong> is often placed in the ureter to help healing. It is removed a few weeks later in a short procedure.\u003c/p>\n\u003ch2 id=\"when-does-the-new-kidney-start-working\">When does the new kidney start working?\u003c/h2>\u003cul>\n\u003cli>Kidneys from \u003cstrong>living donors\u003c/strong> often start producing urine immediately\u003c/li>\n\u003cli>Kidneys from \u003cstrong>deceased donors\u003c/strong> may take days or weeks to start working fully; temporary dialysis may be needed\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"preventing-rejection\">Preventing rejection\u003c/h2>\u003cp>The immune system sees the new kidney as foreign. \u003cstrong>Immunosuppressant medicines\u003c/strong> are started around the time of surgery and taken for life to prevent rejection.\u003c/p>\n\u003ch2 id=\"special-types-of-transplant\">Special types of transplant\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>ABO-incompatible transplant:\u003c/strong> possible between donors and recipients with different blood groups, using special treatment to remove antibodies before surgery\u003c/li>\n\u003cli>\u003cstrong>Paired exchange (swap) transplant:\u003c/strong> two incompatible donor-recipient pairs exchange kidneys, where legally permitted\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-long-does-a-transplanted-kidney-last\">How long does a transplanted kidney last?\u003c/h2>\u003cp>On average:\u003c/p>\n\u003cul>\n\u003cli>Living donor kidneys often last \u003cstrong>15 to 20 years\u003c/strong> or more\u003c/li>\n\u003cli>Deceased donor kidneys often last \u003cstrong>10 to 15 years\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>Taking medicines regularly and attending follow-up are key to long-term success. If a kidney eventually fails, another transplant may be possible.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>A transplant nephrologist and surgeon will explain whether you are suitable and which type of transplant fits your situation.\u003c/p>\n","faqs":[{"q":"Will I have three kidneys after a transplant?","a":"Often yes, as the native kidneys are usually left in place."},{"q":"Is a kidney transplant major surgery?","a":"Yes, it is major surgery, usually lasting 3 to 4 hours."},{"q":"Can I have a second transplant?","a":"Yes, if a transplanted kidney fails and you are still fit."}],"toc":[{"id":"where-is-the-new-kidney-placed","text":"Where is the new kidney placed?"},{"id":"what-happens-to-the-old-kidneys","text":"What happens to the old kidneys?"},{"id":"how-is-the-kidney-connected","text":"How is the kidney connected?"},{"id":"when-does-the-new-kidney-start-working","text":"When does the new kidney start working?"},{"id":"preventing-rejection","text":"Preventing rejection"},{"id":"special-types-of-transplant","text":"Special types of transplant"},{"id":"how-long-does-a-transplanted-kidney-last","text":"How long does a transplanted kidney last?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":446,"read":2},{"slug":"living-vs-deceased-donor","sp":"kidney-transplant","title":"Living Donor Versus Deceased Donor Transplantation","seo":"Living vs Deceased Donor Kidney Transplant: Differences & Indian Law","desc":"Compare living and deceased donor kidney transplants: outcomes, waiting times, who can donate under Indian law, and what international patients should know.","kw":["living donor kidney transplant","deceased donor transplant","cadaver kidney","kidney donor India","THOTA"],"links":["kidney-donor-compatibility","kidney-transplant-explained","preparing-for-kidney-transplant"],"video":null,"flow":null,"img":["Living donor and deceased donor pathways side by side","Laparoscopic donor surgery small incisions","Organ donation pledge card"],"html":"\u003cp>A donated kidney can come from a living person or from someone who has died. Both can be life-changing. Understanding the differences helps patients and families plan.\u003c/p>\n\u003ch2 id=\"living-donor-transplant\">Living donor transplant\u003c/h2>\u003cp>A healthy person donates one of their two kidneys. The donor lives normally with one kidney.\u003c/p>\n\u003cp>\u003cstrong>Advantages:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Better long-term kidney survival on average\u003c/li>\n\u003cli>The kidney usually works immediately\u003c/li>\n\u003cli>Surgery can be planned at the best time, including before dialysis begins\u003c/li>\n\u003cli>Shorter or no waiting time\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"deceased-donor-transplant\">Deceased donor transplant\u003c/h2>\u003cp>Kidneys are donated by a person who has been declared \u003cstrong>brain dead\u003c/strong>, with consent from their family. Allocation follows a waiting list managed by state and national organ-sharing networks.\u003c/p>\n\u003cp>\u003cstrong>Considerations:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Waiting times can be long, often several years\u003c/li>\n\u003cli>The kidney may take time to start working\u003c/li>\n\u003cli>Average kidney lifespan is somewhat shorter than from living donors\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"comparison\">Comparison\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>Living donor\u003c/th>\n\u003cth>Deceased donor\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Waiting time\u003c/td>\n\u003ctd>Short, planned\u003c/td>\n\u003ctd>Often years\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Kidney starts working\u003c/td>\n\u003ctd>Usually immediately\u003c/td>\n\u003ctd>May be delayed\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Average kidney lifespan\u003c/td>\n\u003ctd>Longer\u003c/td>\n\u003ctd>Somewhat shorter\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Surgery timing\u003c/td>\n\u003ctd>Planned\u003c/td>\n\u003ctd>At short notice\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Donor surgery\u003c/td>\n\u003ctd>Required\u003c/td>\n\u003ctd>Not applicable\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"who-can-be-a-living-donor-in-india\">Who can be a living donor in India?\u003c/h2>\u003cp>Living organ donation in India is regulated by the \u003cstrong>Transplantation of Human Organs and Tissues Act (THOTA)\u003c/strong>:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Near relatives\u003c/strong>, such as parents, siblings, children, spouse and grandparents, can donate after verification of the relationship\u003c/li>\n\u003cli>\u003cstrong>Donors who are not near relatives\u003c/strong> may donate only with approval from an official \u003cstrong>Authorisation Committee\u003c/strong>, which checks that the donation is voluntary and not commercial\u003c/li>\n\u003cli>\u003cstrong>Buying or selling organs is illegal\u003c/strong> and punishable by law\u003c/li>\n\u003cli>\u003cstrong>Swap (paired) donation\u003c/strong> between families is permitted under the law with appropriate approvals\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"international-patients\">International patients\u003c/h2>\u003cp>Patients travelling to India usually need a related living donor. Additional documents are required, including proof of relationship and verification from their country&#39;s embassy or relevant authority. The transplant hospital guides families through this process.\u003c/p>\n\u003ch2 id=\"is-living-donation-safe-for-the-donor\">Is living donation safe for the donor?\u003c/h2>\u003cp>Donors undergo thorough medical and psychological screening. The surgery is usually done by \u003cstrong>laparoscopy\u003c/strong> (keyhole surgery). Most donors return home in a few days and to normal activities within several weeks. Long-term risks are low for carefully selected donors, and lifelong check-ups are recommended.\u003c/p>\n\u003ch2 id=\"organ-donation-pledges\">Organ donation pledges\u003c/h2>\u003cp>Anyone can pledge to donate organs after death. Discussing this with family is important, as their consent is needed.\u003c/p>\n","faqs":[{"q":"Can a friend donate a kidney to me?","a":"Only with approval from the Authorisation Committee, which verifies that there is no commercial arrangement."},{"q":"Does donating a kidney shorten the donor's life?","a":"For carefully screened donors, long-term health is generally very good."},{"q":"Can a donor have children later?","a":"Yes. Women can usually have healthy pregnancies after donating, with appropriate monitoring."}],"toc":[{"id":"living-donor-transplant","text":"Living donor transplant"},{"id":"deceased-donor-transplant","text":"Deceased donor transplant"},{"id":"comparison","text":"Comparison"},{"id":"who-can-be-a-living-donor-in-india","text":"Who can be a living donor in India?"},{"id":"international-patients","text":"International patients"},{"id":"is-living-donation-safe-for-the-donor","text":"Is living donation safe for the donor?"},{"id":"organ-donation-pledges","text":"Organ donation pledges"}],"words":440,"read":2},{"slug":"kidney-donor-compatibility","sp":"kidney-transplant","title":"How Is Kidney Donor Compatibility Assessed?","seo":"Kidney Donor Compatibility: Blood Group, HLA & Crossmatch Tests","desc":"Learn how kidney donor compatibility is tested, including blood group, HLA tissue typing and crossmatch, and options when donor and recipient do not match.","kw":["kidney donor compatibility","crossmatch test","HLA typing kidney","blood group kidney transplant","ABO incompatible transplant"],"links":["living-vs-deceased-donor","kidney-transplant-explained","immunosuppressant-medicines"],"video":null,"flow":{"caption":"Compatibility testing","steps":[{"t":"Blood group","d":"Checks ABO compatibility"},{"t":"HLA typing","d":"Compares tissue markers"},{"t":"Antibody screen","d":"Checks recipient antibodies against donors"},{"t":"Crossmatch","d":"Final test mixing donor cells with recipient blood"}]},"img":["Blood group compatibility chart for kidney donation","HLA tissue markers explained","Crossmatch test in the laboratory"],"html":"\u003cp>Before a kidney transplant, doctors carry out several tests to check whether a donor&#39;s kidney is likely to be accepted by the recipient&#39;s immune system. This reduces the risk of rejection.\u003c/p>\n\u003ch2 id=\"1-blood-group-abo-compatibility\">1. Blood group (ABO) compatibility\u003c/h2>\u003cp>Blood group compatibility for kidney donation follows similar rules to blood transfusion:\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Recipient blood group\u003c/th>\n\u003cth>Compatible donor blood groups\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>O\u003c/td>\n\u003ctd>O\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>A\u003c/td>\n\u003ctd>A, O\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>B\u003c/td>\n\u003ctd>B, O\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>AB\u003c/td>\n\u003ctd>A, B, AB, O\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>The Rh factor (positive or negative) does not matter for kidney transplantation.\u003c/p>\n\u003cfigure class=\"flow\" aria-label=\"Compatibility testing\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Compatibility testing\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Blood group\u003c/b>\u003cspan>Checks ABO compatibility\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>HLA typing\u003c/b>\u003cspan>Compares tissue markers\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Antibody screen\u003c/b>\u003cspan>Checks recipient antibodies against donors\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Crossmatch\u003c/b>\u003cspan>Final test mixing donor cells with recipient blood\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"2-hla-tissue-typing\">2. HLA tissue typing\u003c/h2>\u003cp>\u003cstrong>HLA (human leukocyte antigens)\u003c/strong> are markers on cells that help the immune system recognise what belongs to the body. Donor and recipient HLA types are compared. A closer match may improve long-term kidney survival, but a perfect match is \u003cstrong>not required\u003c/strong>. Many successful transplants occur with partial matches.\u003c/p>\n\u003ch2 id=\"3-antibody-screening\">3. Antibody screening\u003c/h2>\u003cp>Some recipients have antibodies against certain HLA types, often from previous pregnancies, blood transfusions or transplants. A test called \u003cstrong>PRA\u003c/strong> or single antigen testing identifies these antibodies, helping doctors understand which donors may be unsuitable.\u003c/p>\n\u003ch2 id=\"4-crossmatch-test\">4. Crossmatch test\u003c/h2>\u003cp>The crossmatch is a key final test. The recipient&#39;s blood is mixed with the donor&#39;s cells to check whether the recipient has antibodies that would attack the donor kidney.\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Negative crossmatch:\u003c/strong> good; the transplant can usually proceed\u003c/li>\n\u003cli>\u003cstrong>Positive crossmatch:\u003c/strong> indicates a higher risk of rejection; special treatment or a different donor may be needed\u003c/li>\n\u003c/ul>\n\u003cp>The crossmatch is often repeated close to the date of surgery.\u003c/p>\n\u003ch2 id=\"5-donor-health-assessment\">5. Donor health assessment\u003c/h2>\u003cp>Compatibility is not only about immune matching. Donors also undergo:\u003c/p>\n\u003cul>\n\u003cli>Kidney function tests and urine tests\u003c/li>\n\u003cli>Imaging, usually a CT scan, to check kidney anatomy\u003c/li>\n\u003cli>Heart and general health checks\u003c/li>\n\u003cli>Infection screening\u003c/li>\n\u003cli>Psychological assessment\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-if-the-donor-is-not-compatible\">What if the donor is not compatible?\u003c/h2>\u003cp>Options may include:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>ABO-incompatible transplant:\u003c/strong> antibodies are reduced before surgery with special treatment\u003c/li>\n\u003cli>\u003cstrong>Desensitisation:\u003c/strong> treatment to lower harmful antibodies\u003c/li>\n\u003cli>\u003cstrong>Paired kidney exchange (swap):\u003c/strong> two incompatible pairs exchange donors, with legal approval\u003c/li>\n\u003cli>Waiting for a deceased donor kidney\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"how-long-does-testing-take\">How long does testing take?\u003c/h2>\u003cp>Donor and recipient evaluation usually takes several weeks, depending on test results and legal documentation.\u003c/p>\n\u003ch2 id=\"when-should-you-consult-a-specialist\">When should you consult a specialist?\u003c/h2>\u003cp>Start the compatibility testing process early with your transplant team, especially if you have more than one potential donor.\u003c/p>\n","faqs":[{"q":"Does the donor need the same blood group?","a":"Not necessarily. Compatible groups can donate, and ABO-incompatible transplants are possible."},{"q":"Is a perfect HLA match necessary?","a":"No. Many transplants succeed with partial matches."},{"q":"What does a positive crossmatch mean?","a":"That the recipient may react against the donor kidney. Your team will discuss options."}],"toc":[{"id":"1-blood-group-abo-compatibility","text":"1. Blood group (ABO) compatibility"},{"id":"2-hla-tissue-typing","text":"2. HLA tissue typing"},{"id":"3-antibody-screening","text":"3. Antibody screening"},{"id":"4-crossmatch-test","text":"4. Crossmatch test"},{"id":"5-donor-health-assessment","text":"5. Donor health assessment"},{"id":"what-if-the-donor-is-not-compatible","text":"What if the donor is not compatible?"},{"id":"how-long-does-testing-take","text":"How long does testing take?"},{"id":"when-should-you-consult-a-specialist","text":"When should you consult a specialist?"}],"words":421,"read":2},{"slug":"preparing-for-kidney-transplant","sp":"kidney-transplant","title":"Preparing for Kidney Transplantation","seo":"Preparing for a Kidney Transplant: Tests, Health, Documents & Checklist","desc":"How recipients and donors prepare for a kidney transplant: medical work-up, vaccinations, dental care, lifestyle, legal documents and practical planning.","kw":["preparing for kidney transplant","kidney transplant work-up","kidney transplant checklist","transplant documents India","before kidney transplant"],"links":["when-kidney-transplant-is-needed","kidney-donor-compatibility","kidney-transplant-surgery-day"],"video":null,"flow":{"caption":"Preparation pathway","steps":[{"t":"Medical work-up","d":"Recipient and donor tests"},{"t":"Fitness and vaccines","d":"Infections treated; vaccines updated"},{"t":"Legal approval","d":"Documents and committee clearance"},{"t":"Surgery scheduled","d":"Admission planned"}]},"img":["Pre-transplant checklist for recipient and donor","Vaccination record","Documents folder for legal approval"],"html":"\u003cp>Preparing well for a kidney transplant helps surgery go smoothly and supports long-term success. Preparation involves medical tests, lifestyle changes, legal documentation and practical planning.\u003c/p>\n\u003ch2 id=\"medical-preparation-for-the-recipient\">Medical preparation for the recipient\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Blood and urine tests:\u003c/strong> including blood group, tissue typing and infection screening such as hepatitis B, hepatitis C, HIV and tuberculosis\u003c/li>\n\u003cli>\u003cstrong>Heart evaluation:\u003c/strong> ECG, echocardiogram and sometimes a stress test or angiogram\u003c/li>\n\u003cli>\u003cstrong>Imaging:\u003c/strong> chest X-ray, abdominal ultrasound and sometimes scans of blood vessels\u003c/li>\n\u003cli>\u003cstrong>Dental check-up:\u003c/strong> to treat any infection before surgery\u003c/li>\n\u003cli>\u003cstrong>Cancer screening:\u003c/strong> as appropriate for age, such as Pap smear or mammogram\u003c/li>\n\u003cli>\u003cstrong>Vaccinations:\u003c/strong> updated before transplant, as some vaccines cannot be given afterwards\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Preparation pathway\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Preparation pathway\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Medical work-up\u003c/b>\u003cspan>Recipient and donor tests\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Fitness and vaccines\u003c/b>\u003cspan>Infections treated; vaccines updated\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Legal approval\u003c/b>\u003cspan>Documents and committee clearance\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Surgery scheduled\u003c/b>\u003cspan>Admission planned\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"medical-preparation-for-the-living-donor\">Medical preparation for the living donor\u003c/h2>\u003cp>The donor undergoes a detailed evaluation to make sure donation is safe, including kidney function, imaging, heart and general health checks, and counselling.\u003c/p>\n\u003ch2 id=\"getting-healthy\">Getting healthy\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Stop smoking\u003c/strong> completely\u003c/li>\n\u003cli>Maintain a healthy weight\u003c/li>\n\u003cli>Control blood sugar and blood pressure\u003c/li>\n\u003cli>Stay active as much as possible\u003c/li>\n\u003cli>Follow your dialysis schedule and diet carefully if you are on dialysis\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"emotional-preparation\">Emotional preparation\u003c/h2>\u003cul>\n\u003cli>Understand the risks and benefits\u003c/li>\n\u003cli>Talk openly with your donor and family\u003c/li>\n\u003cli>Counselling is part of the process for both recipient and donor\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"legal-documentation-in-india\">Legal documentation in India\u003c/h2>\u003cp>Transplants in India require legal approval under the \u003cstrong>Transplantation of Human Organs and Tissues Act\u003c/strong>. Documents typically include:\u003c/p>\n\u003cul>\n\u003cli>Proof of identity for donor and recipient\u003c/li>\n\u003cli>Proof of relationship, such as birth certificates or family documents\u003c/li>\n\u003cli>Consent forms\u003c/li>\n\u003cli>Approval from the hospital or state \u003cstrong>Authorisation Committee\u003c/strong>, where required\u003c/li>\n\u003c/ul>\n\u003cp>For \u003cstrong>international patients\u003c/strong>, additional documents are needed, including verification from the embassy or relevant authority of the home country. Start this process early, as it can take time.\u003c/p>\n\u003ch2 id=\"practical-preparation\">Practical preparation\u003c/h2>\u003cul>\n\u003cli>Plan time off work for both recipient and donor\u003c/li>\n\u003cli>International patients usually need to stay near the hospital for several weeks after surgery\u003c/li>\n\u003cli>Arrange a caregiver to support recovery\u003c/li>\n\u003cli>Prepare a list of all medicines\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"before-admission\">Before admission\u003c/h2>\u003cul>\n\u003cli>Follow instructions about fasting and medicines\u003c/li>\n\u003cli>Inform your team if you develop fever, cough or any infection\u003c/li>\n\u003cli>If on dialysis, you may need a session shortly before surgery\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"when-should-you-contact-your-team\">When should you contact your team?\u003c/h2>\u003cp>Contact your team if you become unwell, develop an infection, or if anything changes in your health or your donor&#39;s health during preparation.\u003c/p>\n","faqs":[{"q":"How long does preparation take?","a":"Often several weeks to a few months, depending on tests and legal approvals."},{"q":"Why do I need dental treatment?","a":"Infections in the mouth can become dangerous after transplant due to immunosuppression."},{"q":"Can my surgery be postponed?","a":"Yes, if an infection or new health issue is found. Safety comes first."}],"toc":[{"id":"medical-preparation-for-the-recipient","text":"Medical preparation for the recipient"},{"id":"medical-preparation-for-the-living-donor","text":"Medical preparation for the living donor"},{"id":"getting-healthy","text":"Getting healthy"},{"id":"emotional-preparation","text":"Emotional preparation"},{"id":"legal-documentation-in-india","text":"Legal documentation in India"},{"id":"practical-preparation","text":"Practical preparation"},{"id":"before-admission","text":"Before admission"},{"id":"when-should-you-contact-your-team","text":"When should you contact your team?"}],"words":426,"read":2},{"slug":"kidney-transplant-surgery-day","sp":"kidney-transplant","title":"What Happens During Kidney Transplant Surgery?","seo":"Kidney Transplant Surgery Day: What Happens to Donor and Recipient","desc":"A walk through the day of kidney transplant surgery for both donor and recipient: admission, anaesthesia, keyhole donor surgery, the operation and waking up.","kw":["kidney transplant surgery","kidney transplant operation day","laparoscopic donor nephrectomy","transplant surgery duration","kidney transplant ICU"],"links":["kidney-transplant-explained","recovery-after-kidney-transplant","preparing-for-kidney-transplant"],"video":"v-kidney","flow":{"caption":"Surgery day","steps":[{"t":"Admission","d":"Final checks and crossmatch"},{"t":"Donor surgery","d":"Keyhole removal of one kidney"},{"t":"Recipient surgery","d":"New kidney connected"},{"t":"Recovery","d":"Close monitoring in the transplant unit"}]},"img":["Two operating theatres working side by side","Laparoscopic donor nephrectomy ports","Monitoring lines and catheter after surgery"],"html":"\u003cp>For living donor transplants, the donor and recipient usually have surgery on the same day, often in adjoining operating theatres. Here is what typically happens.\u003c/p>\n\u003ch2 id=\"admission\">Admission\u003c/h2>\u003cul>\n\u003cli>Admission usually 1 to 2 days before surgery\u003c/li>\n\u003cli>Final blood tests, including a repeat \u003cstrong>crossmatch\u003c/strong>\u003c/li>\n\u003cli>Anaesthesia review\u003c/li>\n\u003cli>Dialysis, if needed, to optimise the recipient&#39;s condition\u003c/li>\n\u003cli>Fasting from the night before\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Surgery day\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Surgery day\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Admission\u003c/b>\u003cspan>Final checks and crossmatch\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Donor surgery\u003c/b>\u003cspan>Keyhole removal of one kidney\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Recipient surgery\u003c/b>\u003cspan>New kidney connected\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>Recovery\u003c/b>\u003cspan>Close monitoring in the transplant unit\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"the-donor-39-s-surgery\">The donor&#39;s surgery\u003c/h2>\u003cul>\n\u003cli>Performed under general anaesthesia\u003c/li>\n\u003cli>Usually done by \u003cstrong>laparoscopic (keyhole) surgery\u003c/strong> through small incisions, with one slightly larger cut to remove the kidney\u003c/li>\n\u003cli>The surgery takes about \u003cstrong>2 to 4 hours\u003c/strong>\u003c/li>\n\u003cli>The kidney is carefully removed, flushed with a cold preservation solution and taken to the recipient&#39;s theatre\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"the-recipient-39-s-surgery\">The recipient&#39;s surgery\u003c/h2>\u003cul>\n\u003cli>Performed under general anaesthesia\u003c/li>\n\u003cli>An incision is made in the lower abdomen, on the right or left side\u003c/li>\n\u003cli>The new kidney is placed and connected to an artery, a vein and the bladder\u003c/li>\n\u003cli>A temporary stent may be placed in the ureter\u003c/li>\n\u003cli>The surgery usually takes \u003cstrong>3 to 4 hours\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>Immunosuppressant medicines are started around the time of surgery.\u003c/p>\n\u003ch2 id=\"waking-up\">Waking up\u003c/h2>\u003cp>The recipient wakes up in the recovery area or transplant ICU with:\u003c/p>\n\u003cul>\n\u003cli>A \u003cstrong>urinary catheter\u003c/strong> to measure urine output\u003c/li>\n\u003cli>A \u003cstrong>central line\u003c/strong> in the neck or chest for medicines and fluids\u003c/li>\n\u003cli>Possibly a \u003cstrong>surgical drain\u003c/strong> near the incision\u003c/li>\n\u003cli>Pain relief through a drip or epidural\u003c/li>\n\u003c/ul>\n\u003cp>Many recipients notice the new kidney producing urine soon after surgery, especially with a living donor kidney.\u003c/p>\n\u003ch2 id=\"the-first-few-days\">The first few days\u003c/h2>\u003cp>\u003cstrong>For the recipient:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Close monitoring of urine output, fluid balance and blood tests\u003c/li>\n\u003cli>Walking begins within a day or two\u003c/li>\n\u003cli>Catheter and drains are removed over several days\u003c/li>\n\u003cli>Hospital stay of about \u003cstrong>5 to 10 days\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>\u003cstrong>For the donor:\u003c/strong>\u003c/p>\n\u003cul>\n\u003cli>Walking the next day\u003c/li>\n\u003cli>Hospital stay of about \u003cstrong>2 to 4 days\u003c/strong>\u003c/li>\n\u003cli>Return to light activities within a few weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"possible-risks-of-surgery\">Possible risks of surgery\u003c/h2>\u003cul>\n\u003cli>Bleeding or infection\u003c/li>\n\u003cli>Blood clots\u003c/li>\n\u003cli>Leakage or narrowing at the ureter connection\u003c/li>\n\u003cli>Delayed kidney function\u003c/li>\n\u003cli>Rejection\u003c/li>\n\u003c/ul>\n\u003cp>The transplant team monitors closely for these and treats them early.\u003c/p>\n\u003ch2 id=\"family-support\">Family support\u003c/h2>\u003cp>Family members are kept informed during surgery. Having a dedicated caregiver for both donor and recipient makes recovery easier.\u003c/p>\n","faqs":[{"q":"Is the donor awake during surgery?","a":"No. Both donor and recipient are under general anaesthesia."},{"q":"How long will I be in hospital?","a":"Recipients typically stay 5 to 10 days; donors 2 to 4 days."},{"q":"Will the new kidney work immediately?","a":"Living donor kidneys usually start working quickly; some take a few days."}],"toc":[{"id":"admission","text":"Admission"},{"id":"the-donor-39-s-surgery","text":"The donor&#39;s surgery"},{"id":"the-recipient-39-s-surgery","text":"The recipient&#39;s surgery"},{"id":"waking-up","text":"Waking up"},{"id":"the-first-few-days","text":"The first few days"},{"id":"possible-risks-of-surgery","text":"Possible risks of surgery"},{"id":"family-support","text":"Family support"}],"words":399,"read":2},{"slug":"recovery-after-kidney-transplant","sp":"kidney-transplant","title":"Recovery After Kidney Transplantation","seo":"Recovery After Kidney Transplant: First Weeks, Signs of Rejection & Care","desc":"What to expect in the weeks after kidney transplant: frequent blood tests, medicines, wound care, signs of rejection and infection, and returning home.","kw":["recovery after kidney transplant","kidney transplant rejection signs","kidney transplant follow-up","after kidney transplant care","transplant recovery time"],"links":["immunosuppressant-medicines","life-after-kidney-transplant","kidney-transplant-surgery-day"],"video":null,"flow":{"caption":"Recovery timeline","steps":[{"t":"Week 1","d":"Hospital monitoring; walking starts"},{"t":"Weeks 2 to 6","d":"Frequent blood tests; stent removal"},{"t":"Months 2 to 3","d":"Medicines adjusted; visits reduce"},{"t":"After 3 months","d":"Return to most normal activities"}]},"img":["Follow-up visit schedule graphic","Daily self-monitoring log: weight, BP, temperature, urine","Signs of rejection and infection card"],"html":"\u003cp>The first three months after a kidney transplant are the most important for recovery. This is when the risk of rejection and infection is highest and medicines are adjusted most often.\u003c/p>\n\u003ch2 id=\"after-discharge\">After discharge\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Frequent blood tests:\u003c/strong> often two to three times a week at first, to check kidney function and medicine levels\u003c/li>\n\u003cli>\u003cstrong>Clinic visits\u003c/strong> are gradually reduced as you recover\u003c/li>\n\u003cli>International patients usually need to stay near the transplant centre for several weeks before returning home\u003c/li>\n\u003cli>The ureteric stent, if placed, is usually removed after 4 to 6 weeks in a short procedure\u003c/li>\n\u003c/ul>\n\u003cfigure class=\"flow\" aria-label=\"Recovery timeline\">\u003cfigcaption>\u003cspan class=\"flow-k\">Diagram\u003c/span>Recovery timeline\u003c/figcaption>\u003col>\u003cli>\u003cspan class=\"flow-n\">1\u003c/span>\u003cb>Week 1\u003c/b>\u003cspan>Hospital monitoring; walking starts\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">2\u003c/span>\u003cb>Weeks 2 to 6\u003c/b>\u003cspan>Frequent blood tests; stent removal\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">3\u003c/span>\u003cb>Months 2 to 3\u003c/b>\u003cspan>Medicines adjusted; visits reduce\u003c/span>\u003c/li>\u003cli>\u003cspan class=\"flow-n\">4\u003c/span>\u003cb>After 3 months\u003c/b>\u003cspan>Return to most normal activities\u003c/span>\u003c/li>\u003c/ol>\u003c/figure>\u003ch2 id=\"medicines\">Medicines\u003c/h2>\u003cp>You will take several medicines, including \u003cstrong>immunosuppressants\u003c/strong> to prevent rejection, and medicines to prevent infections. Take them \u003cstrong>exactly on time\u003c/strong>, every day. Never miss doses or stop medicines without advice.\u003c/p>\n\u003ch2 id=\"self-monitoring-at-home\">Self-monitoring at home\u003c/h2>\u003cp>Many centres ask you to keep a daily record of:\u003c/p>\n\u003cul>\n\u003cli>Weight\u003c/li>\n\u003cli>Blood pressure\u003c/li>\n\u003cli>Temperature\u003c/li>\n\u003cli>Urine output, in the early weeks\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"wound-care-and-activity\">Wound care and activity\u003c/h2>\u003cul>\n\u003cli>Keep the wound clean and dry\u003c/li>\n\u003cli>Walk daily and build up gradually\u003c/li>\n\u003cli>Avoid lifting more than about 5 kg for 6 to 8 weeks\u003c/li>\n\u003cli>Avoid driving for several weeks, as advised\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"diet-and-fluids\">Diet and fluids\u003c/h2>\u003cul>\n\u003cli>Drink the amount of fluid your team recommends\u003c/li>\n\u003cli>Eat a balanced, low-salt diet\u003c/li>\n\u003cli>Follow food safety rules: freshly cooked food, safe water, washed fruits and vegetables\u003c/li>\n\u003cli>\u003cstrong>Avoid grapefruit and pomegranate\u003c/strong> unless your team approves, as they can affect medicine levels\u003c/li>\n\u003cli>Avoid herbal remedies and supplements unless approved\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"signs-of-rejection\">Signs of rejection\u003c/h2>\u003cp>Rejection is when the immune system attacks the new kidney. Often it is detected only by \u003cstrong>blood tests\u003c/strong>, which is why regular testing is essential. Possible symptoms include:\u003c/p>\n\u003cul>\n\u003cli>Reduced urine output\u003c/li>\n\u003cli>Swelling or rapid weight gain\u003c/li>\n\u003cli>Fever\u003c/li>\n\u003cli>Pain or tenderness over the transplant\u003c/li>\n\u003cli>Rising blood pressure\u003c/li>\n\u003c/ul>\n\u003cp>Most rejection episodes can be treated successfully if caught early.\u003c/p>\n\u003ch2 id=\"signs-of-infection\">Signs of infection\u003c/h2>\u003cul>\n\u003cli>Fever or chills\u003c/li>\n\u003cli>Burning while passing urine\u003c/li>\n\u003cli>Cough or breathlessness\u003c/li>\n\u003cli>Diarrhoea\u003c/li>\n\u003cli>Redness or discharge from the wound\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"returning-to-normal-life\">Returning to normal life\u003c/h2>\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Activity\u003c/th>\n\u003cth>Typical timing\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Light daily activities\u003c/td>\n\u003ctd>A few weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Desk work\u003c/td>\n\u003ctd>About 6 to 12 weeks\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Driving\u003c/td>\n\u003ctd>Several weeks, when cleared\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Exercise\u003c/td>\n\u003ctd>Gradually; avoid contact sports initially\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003ch2 id=\"when-should-you-contact-your-team\">When should you contact your team?\u003c/h2>\u003cp>Contact your transplant team immediately for any signs of rejection or infection, if you miss doses of medicines, or if you develop vomiting or diarrhoea that stops you taking medicines.\u003c/p>\n","faqs":[{"q":"How long will recovery take?","a":"Most people feel significantly better within 6 to 12 weeks."},{"q":"Can rejection happen without symptoms?","a":"Yes. That is why regular blood tests are vital."},{"q":"Can I eat normally after transplant?","a":"Most people have fewer restrictions than on dialysis, but food safety and some limits remain."}],"toc":[{"id":"after-discharge","text":"After discharge"},{"id":"medicines","text":"Medicines"},{"id":"self-monitoring-at-home","text":"Self-monitoring at home"},{"id":"wound-care-and-activity","text":"Wound care and activity"},{"id":"diet-and-fluids","text":"Diet and fluids"},{"id":"signs-of-rejection","text":"Signs of rejection"},{"id":"signs-of-infection","text":"Signs of infection"},{"id":"returning-to-normal-life","text":"Returning to normal life"},{"id":"when-should-you-contact-your-team","text":"When should you contact your team?"}],"words":432,"read":2},{"slug":"immunosuppressant-medicines","sp":"kidney-transplant","title":"Understanding Immunosuppressant Medicines","seo":"Immunosuppressants After Transplant: How They Work, Side Effects & Tips","desc":"Learn why transplant patients take lifelong immunosuppressant medicines, the common types, side effects, drug interactions and tips for taking them safely.","kw":["immunosuppressant medicines","anti-rejection drugs","tacrolimus","mycophenolate","transplant medicines side effects"],"links":["recovery-after-kidney-transplant","life-after-kidney-transplant","kidney-transplant-explained"],"video":null,"flow":null,"img":["Immune system \"dimmer switch\" illustration","Pill organiser with daily schedule","Common medicine interactions chart"],"html":"\u003cp>After a transplant, the body&#39;s immune system sees the new organ as foreign and tries to attack it. Immunosuppressant, or anti-rejection, medicines lower the immune response to protect the new organ. They must be taken for as long as the transplant works.\u003c/p>\n\u003ch2 id=\"how-do-they-work\">How do they work?\u003c/h2>\u003cp>These medicines act like a \u003cstrong>dimmer switch\u003c/strong> on the immune system, turning it down enough to prevent rejection while still allowing some protection against infection.\u003c/p>\n\u003ch2 id=\"common-types\">Common types\u003c/h2>\u003cp>Most patients take a combination of medicines:\u003c/p>\n\u003cdiv class=\"tbl\">\u003ctable>\u003cthead>\u003ctr>\n\u003cth>Group\u003c/th>\n\u003cth>Examples\u003c/th>\n\u003cth>Purpose\u003c/th>\n\u003c/tr>\n\u003c/thead>\u003ctbody>\u003ctr>\n\u003ctd>Calcineurin inhibitors\u003c/td>\n\u003ctd>Tacrolimus, cyclosporine\u003c/td>\n\u003ctd>Main anti-rejection medicine\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Antiproliferative agents\u003c/td>\n\u003ctd>Mycophenolate, azathioprine\u003c/td>\n\u003ctd>Stop immune cells multiplying\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>Steroids\u003c/td>\n\u003ctd>Prednisolone\u003c/td>\n\u003ctd>Reduce inflammation and immune activity\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>mTOR inhibitors\u003c/td>\n\u003ctd>Sirolimus, everolimus\u003c/td>\n\u003ctd>Used in selected patients\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\u003c/div>\u003cp>Doses are highest soon after transplant and are gradually reduced.\u003c/p>\n\u003ch2 id=\"blood-level-monitoring\">Blood level monitoring\u003c/h2>\u003cp>Some medicines, especially tacrolimus, need regular \u003cstrong>blood level checks\u003c/strong>. The blood test is usually done \u003cstrong>before\u003c/strong> the morning dose. Levels that are too low increase rejection risk; levels that are too high increase side effects.\u003c/p>\n\u003ch2 id=\"possible-side-effects\">Possible side effects\u003c/h2>\u003cul>\n\u003cli>Higher risk of \u003cstrong>infections\u003c/strong>\u003c/li>\n\u003cli>High blood pressure\u003c/li>\n\u003cli>High blood sugar or diabetes\u003c/li>\n\u003cli>Tremor\u003c/li>\n\u003cli>Effects on kidney function\u003c/li>\n\u003cli>High cholesterol\u003c/li>\n\u003cli>Weight gain and bone thinning (with steroids)\u003c/li>\n\u003cli>Stomach upset or diarrhoea\u003c/li>\n\u003cli>Increased risk of some cancers over time, particularly \u003cstrong>skin cancer\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003cp>Many side effects can be managed by adjusting doses or adding other medicines.\u003c/p>\n\u003ch2 id=\"drug-and-food-interactions\">Drug and food interactions\u003c/h2>\u003cp>Some medicines and foods can change immunosuppressant levels:\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>Grapefruit and pomegranate\u003c/strong> juice\u003c/li>\n\u003cli>Certain antibiotics and antifungal medicines\u003c/li>\n\u003cli>Some anti-seizure and tuberculosis medicines\u003c/li>\n\u003cli>Herbal remedies and supplements\u003c/li>\n\u003c/ul>\n\u003cp>Always tell any doctor or pharmacist that you are a transplant patient before starting new medicines.\u003c/p>\n\u003ch2 id=\"tips-for-taking-medicines-safely\">Tips for taking medicines safely\u003c/h2>\u003cul>\n\u003cli>Take medicines at the \u003cstrong>same time every day\u003c/strong>\u003c/li>\n\u003cli>Use a pill organiser and phone reminders\u003c/li>\n\u003cli>Never stop or change doses on your own\u003c/li>\n\u003cli>Do not run out; plan refills in advance, especially when travelling\u003c/li>\n\u003cli>Carry a list of your medicines\u003c/li>\n\u003cli>Keep the same brand where possible, as switching brands may change blood levels\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"what-if-i-miss-a-dose\">What if I miss a dose?\u003c/h2>\u003cp>Follow your transplant team&#39;s specific advice. Do not take a double dose without checking first.\u003c/p>\n\u003ch2 id=\"when-should-you-contact-your-team\">When should you contact your team?\u003c/h2>\u003cp>Contact your team if you miss doses, have vomiting or diarrhoea that stops you absorbing medicines, or notice new side effects.\u003c/p>\n","faqs":[{"q":"Will I need these medicines forever?","a":"Yes, for as long as the transplanted kidney is working."},{"q":"Can I take painkillers?","a":"Some painkillers can harm the kidney. Paracetamol is often preferred, but always check first."},{"q":"Why do I need sun protection?","a":"Immunosuppressants increase the risk of skin cancer."}],"toc":[{"id":"how-do-they-work","text":"How do they work?"},{"id":"common-types","text":"Common types"},{"id":"blood-level-monitoring","text":"Blood level monitoring"},{"id":"possible-side-effects","text":"Possible side effects"},{"id":"drug-and-food-interactions","text":"Drug and food interactions"},{"id":"tips-for-taking-medicines-safely","text":"Tips for taking medicines safely"},{"id":"what-if-i-miss-a-dose","text":"What if I miss a dose?"},{"id":"when-should-you-contact-your-team","text":"When should you contact your team?"}],"words":420,"read":2},{"slug":"life-after-kidney-transplant","sp":"kidney-transplant","title":"Life After Kidney Transplantation","seo":"Life After Kidney Transplant: Long-Term Health, Work, Travel & Family","desc":"Living well after a kidney transplant: long-term follow-up, diet, exercise, infection prevention, work, travel, pregnancy and protecting your new kidney.","kw":["life after kidney transplant","long term kidney transplant care","pregnancy after kidney transplant","travel after transplant","kidney transplant lifestyle"],"links":["immunosuppressant-medicines","recovery-after-kidney-transplant","chronic-kidney-disease"],"video":null,"flow":null,"img":["Healthy habits to protect your kidney","Travel checklist for transplant patients","Long-term follow-up schedule"],"html":"\u003cp>A successful kidney transplant can give people the freedom to work, travel, exercise and enjoy family life without dialysis. Protecting the new kidney for the long term depends on daily habits and regular care.\u003c/p>\n\u003ch2 id=\"long-term-follow-up\">Long-term follow-up\u003c/h2>\u003cul>\n\u003cli>Clinic visits become less frequent over time, often every few months after the first year\u003c/li>\n\u003cli>Regular blood tests monitor kidney function and medicine levels\u003c/li>\n\u003cli>Annual checks for blood pressure, diabetes, cholesterol and bone health\u003c/li>\n\u003cli>\u003cstrong>Skin checks\u003c/strong> and cancer screening, as transplant medicines raise some cancer risks\u003c/li>\n\u003c/ul>\n\u003cp>International patients usually continue follow-up with a nephrologist in their home country, in coordination with the transplant team.\u003c/p>\n\u003ch2 id=\"protecting-your-kidney\">Protecting your kidney\u003c/h2>\u003cul>\n\u003cli>Take immunosuppressants exactly on time, every day, for life\u003c/li>\n\u003cli>Control blood pressure and blood sugar\u003c/li>\n\u003cli>Stay well hydrated, as advised\u003c/li>\n\u003cli>Avoid painkillers that harm the kidney unless approved\u003c/li>\n\u003cli>Avoid unprescribed herbal or traditional remedies\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"healthy-lifestyle\">Healthy lifestyle\u003c/h2>\u003cul>\n\u003cli>\u003cstrong>Diet:\u003c/strong> balanced, low in salt, rich in vegetables and fruit, with controlled sugar and fat\u003c/li>\n\u003cli>\u003cstrong>Weight:\u003c/strong> avoid excess weight gain, which is common after transplant\u003c/li>\n\u003cli>\u003cstrong>Exercise:\u003c/strong> regular walking, cycling, swimming or other activities; avoid contact sports that could injure the transplant\u003c/li>\n\u003cli>\u003cstrong>No smoking,\u003c/strong> and limit alcohol\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"preventing-infections\">Preventing infections\u003c/h2>\u003cul>\n\u003cli>Wash hands regularly\u003c/li>\n\u003cli>Avoid close contact with people who are unwell\u003c/li>\n\u003cli>Practise food and water safety\u003c/li>\n\u003cli>Keep up with recommended vaccinations; \u003cstrong>live vaccines are usually avoided\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"work-and-daily-life\">Work and daily life\u003c/h2>\u003cp>Most people return to work, study and normal routines within a few months. Jobs with heavy lifting or infection exposure may need adjustments.\u003c/p>\n\u003ch2 id=\"travel\">Travel\u003c/h2>\u003cul>\n\u003cli>Carry enough medicines for the whole trip, plus extra, in your hand luggage\u003c/li>\n\u003cli>Carry a medical summary and your transplant team&#39;s contact details\u003c/li>\n\u003cli>Take care with food and water\u003c/li>\n\u003cli>Check whether vaccinations are needed for your destination, and discuss them with your team first\u003c/li>\n\u003cli>Use sun protection\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"pregnancy-and-family-planning\">Pregnancy and family planning\u003c/h2>\u003cul>\n\u003cli>Women can often have successful pregnancies after transplant, usually advised to wait \u003cstrong>at least one year\u003c/strong> with stable kidney function\u003c/li>\n\u003cli>Some medicines must be changed before pregnancy, so planning with the transplant team is essential\u003c/li>\n\u003cli>Men taking certain medicines should also discuss family planning\u003c/li>\n\u003c/ul>\n\u003ch2 id=\"emotional-wellbeing\">Emotional wellbeing\u003c/h2>\u003cp>Adjusting to life after transplant can bring mixed emotions, including gratitude, worry about rejection and changes in relationships. Support groups and counselling can help.\u003c/p>\n\u003ch2 id=\"when-should-you-contact-your-team\">When should you contact your team?\u003c/h2>\u003cp>Contact your team for fever, reduced urine, swelling, rising blood pressure, new medicines, or any symptoms that concern you.\u003c/p>\n","faqs":[{"q":"Can I live a normal life after a kidney transplant?","a":"Many people live full, active lives with good care."},{"q":"Can I play sports?","a":"Yes, most sports are encouraged. Avoid contact sports that could injure the kidney."},{"q":"What happens if the kidney stops working?","a":"Options include dialysis or another transplant. Your team will guide you."}],"toc":[{"id":"long-term-follow-up","text":"Long-term follow-up"},{"id":"protecting-your-kidney","text":"Protecting your kidney"},{"id":"healthy-lifestyle","text":"Healthy lifestyle"},{"id":"preventing-infections","text":"Preventing infections"},{"id":"work-and-daily-life","text":"Work and daily life"},{"id":"travel","text":"Travel"},{"id":"pregnancy-and-family-planning","text":"Pregnancy and family planning"},{"id":"emotional-wellbeing","text":"Emotional wellbeing"},{"id":"when-should-you-contact-your-team","text":"When should you contact your team?"}],"words":444,"read":2}],"videos":[{"id":"v-cabg","scenes":[{"t":"0:00-0:10","visual":"A beating heart; camera zooms to the coronary arteries on its surface","vo":"Your heart is a muscle, and like every muscle it needs a steady supply of blood. That blood flows through small vessels called coronary arteries."},{"t":"0:10-0:25","visual":"Plaque slowly builds inside an artery; blood flow thins to a trickle","vo":"Over time, fatty plaque can build up inside these arteries, narrowing them. Less blood reaches the heart, which can cause chest pain, breathlessness or a heart attack."},{"t":"0:25-0:40","visual":"Animated road map with a traffic jam and a new bypass road","vo":"When several arteries are badly blocked, doctors may recommend bypass surgery. Just like a road bypass lets traffic avoid a jam, a surgical bypass lets blood flow around a blockage."},{"t":"0:40-0:55","visual":"Highlight graft sources: chest wall artery, leg vein, forearm artery","vo":"The surgeon uses a healthy blood vessel called a graft, usually taken from inside the chest wall, the leg or the forearm."},{"t":"0:55-1:10","visual":"Graft attached above and below the blockage; blood flows freely","vo":"One end of the graft is attached above the blockage and the other end below it. Blood now has a new path to reach the heart muscle."},{"t":"1:10-1:30","visual":"Patient walking, attending cardiac rehab, taking medicines","vo":"Most patients spend a few days in hospital and recover over two to three months. Medicines, cardiac rehabilitation and healthy habits help keep the new grafts open for years. Talk to your heart specialist about whether bypass surgery is right for you."}],"title":"How Heart Bypass Surgery (CABG) Works","duration":"90 seconds","articles":["cabg-heart-bypass-surgery","coronary-artery-disease","life-after-heart-surgery"],"style":"2D animation, warm medical palette, on-screen captions; no surgical footage","words":173},{"id":"v-angioplasty","scenes":[{"t":"0:00-0:10","visual":"A narrowed coronary artery with reduced blood flow","vo":"When a coronary artery becomes narrowed or blocked, the heart muscle does not get enough blood."},{"t":"0:10-0:25","visual":"A thin tube travels from the wrist up the arm to the heart","vo":"Angioplasty opens the artery without open surgery. A thin tube, called a catheter, is guided from the wrist or groin up to the heart."},{"t":"0:25-0:35","visual":"Dye highlights the blockage on an X-ray screen","vo":"A special dye is injected so the doctor can see exactly where the blockage is."},{"t":"0:35-0:50","visual":"Guide wire crosses blockage; balloon inflates and pushes plaque aside","vo":"A fine wire crosses the blockage. A tiny balloon is then inflated to press the plaque against the artery wall."},{"t":"0:50-1:05","visual":"Mesh stent expands and stays in place; balloon removed","vo":"A small mesh tube called a stent is expanded and left in place to keep the artery open. Most stents release medicine slowly to help prevent re-narrowing."},{"t":"1:05-1:15","visual":"Patient going home with medicines","vo":"Most patients go home within a day or two. Taking your blood-thinning medicines exactly as prescribed is essential."}],"title":"How Angioplasty and Stenting Are Performed","duration":"75 seconds","articles":["angioplasty-and-stenting","heart-attack-warning-signs","coronary-artery-disease"],"style":"2D animation with simple cutaway views; captions","words":120},{"id":"v-cart","scenes":[{"t":"0:00-0:15","visual":"Immune T-cells patrolling the bloodstream, passing by cancer cells that look disguised","vo":"Your immune system has soldier cells called T-cells. They protect you from infections, but some cancer cells manage to hide from them."},{"t":"0:15-0:30","visual":"Blood flowing from patient's arm into an apheresis machine and back","vo":"CAR-T therapy begins by collecting some of the patient's own T-cells. Blood is passed through a machine that separates the T-cells and returns the rest."},{"t":"0:30-0:50","visual":"Laboratory: T-cells receive a new receptor that fits a marker on cancer cells","vo":"In a specialised laboratory, the T-cells are given a new receptor, called a CAR. It works like a key that fits a specific marker on certain cancer cells, such as CD19 on B-cell lymphoma and leukaemia."},{"t":"0:50-1:05","visual":"Cells multiplying into millions over weeks","vo":"The modified cells are multiplied into millions. This takes a few weeks."},{"t":"1:05-1:20","visual":"Patient receives short chemotherapy, then a drip infusion","vo":"The patient receives a short course of chemotherapy to make room for the new cells. Then the CAR-T cells are given back through a drip."},{"t":"1:20-1:40","visual":"CAR-T cells locking onto and destroying cancer cells, then multiplying","vo":"Inside the body, the CAR-T cells find the cancer cells, attack them and multiply."},{"t":"1:40-2:00","visual":"Patient monitored by nurses; on-screen text about approved uses","vo":"Patients are monitored closely for several weeks for side effects such as fever and confusion. CAR-T is approved only for certain blood cancers, usually after other treatments have not worked. Ask a haematologist whether it may be suitable for you."}],"title":"How CAR-T Cell Therapy Works","duration":"120 seconds","articles":["car-t-cell-therapy-overview","how-car-t-therapy-works","car-t-treatment-journey"],"style":"2D animation; friendly cell characters; include on-screen note \"Approved only for certain blood cancers\"","words":174},{"id":"v-chemo-radiation","scenes":[{"t":"0:00-0:12","visual":"Normal cells dividing in order; cancer cells dividing rapidly","vo":"Cancer cells grow and divide faster than most normal cells. Chemotherapy and radiation therapy both take advantage of this."},{"t":"0:12-0:30","visual":"Chemotherapy drip; medicine particles travel through the bloodstream","vo":"Chemotherapy uses medicines that travel through the bloodstream to reach cancer cells almost anywhere in the body. It is usually given in cycles, with rest periods for the body to recover."},{"t":"0:30-0:45","visual":"Medicine also affecting hair follicles and mouth lining; icons for side effects","vo":"Because some healthy cells also divide quickly, chemo can cause side effects like tiredness, nausea or hair loss. Most are temporary and can be managed."},{"t":"0:45-1:05","visual":"Radiation machine; beams shaped around a tumour avoiding nearby organs","vo":"Radiation therapy uses precisely targeted high-energy rays to damage the DNA of cancer cells in a specific area. Modern machines shape the beams to protect healthy organs."},{"t":"1:05-1:25","visual":"Patient lying still for a few minutes; calendar of daily sessions","vo":"Treatment is painless and usually takes a few minutes a day over several weeks. Side effects mainly affect the treated area."},{"t":"1:25-1:50","visual":"Team of doctors planning together","vo":"Your cancer team may use chemotherapy, radiation, surgery or a combination. They will plan the treatment best suited to your cancer."}],"title":"How Chemotherapy and Radiation Therapy Work","duration":"110 seconds","articles":["chemotherapy-what-to-expect","radiation-therapy-explained","how-cancer-develops"],"style":"Split-screen 2D animation; calm narration; captions","words":144},{"id":"v-dbs","scenes":[{"t":"0:00-0:15","visual":"Hand with tremor; brain signals shown as erratic flashes","vo":"In conditions like Parkinson's disease and essential tremor, abnormal signals in deep parts of the brain cause shaking, stiffness and slow movement."},{"t":"0:15-0:30","visual":"Medicines working well, then fluctuating over the day","vo":"Medicines often help for many years. But for some people, symptoms become hard to control."},{"t":"0:30-0:50","visual":"Electrode placed into a precise deep brain target; wire runs under the skin to a chest device","vo":"Deep Brain Stimulation places very thin electrodes in a precise target deep in the brain. They connect to a small battery device under the skin of the chest, similar to a heart pacemaker."},{"t":"0:50-1:05","visual":"Erratic signals calm into a smooth rhythm; tremor reduces","vo":"The device sends mild electrical pulses that calm the abnormal signals, which can reduce tremor and stiffness."},{"t":"1:05-1:20","visual":"Doctor adjusting settings with a tablet","vo":"Doctors adjust the settings over several visits to get the best result. Stimulation can be changed or switched off."},{"t":"1:20-1:30","visual":"Patient walking and gardening","vo":"DBS does not cure the condition, but it can greatly improve daily life for carefully selected patients."}],"title":"How Deep Brain Stimulation Works","duration":"90 seconds","articles":["deep-brain-stimulation","parkinsons-disease","neuro-rehabilitation"],"style":"2D animation with translucent head and brain; captions","words":123},{"id":"v-joint-replacement","scenes":[{"t":"0:00-0:15","visual":"Healthy knee with smooth cartilage vs worn knee with bone rubbing","vo":"Healthy joints are covered with smooth cartilage. In arthritis, this cartilage wears away and bone rubs on bone, causing pain and stiffness."},{"t":"0:15-0:35","visual":"Knee: damaged surfaces trimmed; metal and plastic parts fitted","vo":"In a knee replacement, the surgeon removes the damaged surfaces of the thigh and shin bones and fits smooth metal parts with a plastic spacer in between."},{"t":"0:35-0:55","visual":"Hip: worn ball and socket replaced with cup, liner, ball and stem","vo":"In a hip replacement, the worn ball and socket are replaced with a new socket in the pelvis and a ball on a stem fitted into the thigh bone."},{"t":"0:55-1:10","visual":"Robotic arm assisting surgeon (optional segment)","vo":"Some centres use robotic assistance to help plan and position the implants precisely."},{"t":"1:10-1:30","visual":"Patient walking with a walker on day one; physiotherapy","vo":"Most patients stand and walk with support within a day of surgery. Physiotherapy is essential to regain strength and movement."},{"t":"1:30-1:50","visual":"Patient walking comfortably months later","vo":"Most people return to daily activities within a few months, with far less pain. Talk to an orthopaedic surgeon about whether joint replacement is right for you."}],"title":"How Knee and Hip Replacement Surgeries Are Performed","duration":"110 seconds","articles":["when-you-need-knee-replacement","total-hip-replacement","joint-replacement-before-and-after"],"style":"2D anatomical animation; no surgical footage; captions","words":138},{"id":"v-mis-spine","scenes":[{"t":"0:00-0:15","visual":"Spine segment; disc bulge pressing on a nerve; pain path down the leg","vo":"When a slipped disc or narrowing of the spine presses on a nerve, it can cause pain, numbness or weakness in the arm or leg."},{"t":"0:15-0:30","visual":"Most patients improving with physiotherapy","vo":"Most people improve without surgery. When symptoms persist or weakness develops, surgery may be recommended."},{"t":"0:30-0:50","visual":"Small incision; tube gently parting muscles instead of cutting","vo":"Minimally invasive spine surgery uses a small incision and a narrow tube that gently separates the muscles instead of cutting them."},{"t":"0:50-1:05","visual":"Magnified camera view; disc fragment removed; nerve freed","vo":"Using a microscope or a tiny camera, the surgeon removes the disc fragment or bone pressing on the nerve."},{"t":"1:05-1:20","visual":"Patient walking the same day","vo":"Because there is less muscle damage, many patients walk the same day and go home sooner."},{"t":"1:20-1:30","visual":"Spine specialist consultation","vo":"It is not suitable for every condition. A spine specialist will advise the best approach for you."}],"title":"How Minimally Invasive Spine Surgery Works","duration":"90 seconds","articles":["minimally-invasive-spine-surgery","slip-disc-symptoms","spinal-decompression-surgery"],"style":"2D cutaway animation of the spine; captions","words":113},{"id":"v-ivf","scenes":[{"t":"0:00-0:15","visual":"Natural conception: egg meets sperm in the fallopian tube","vo":"In natural conception, an egg released from the ovary meets sperm in the fallopian tube. IVF carries out this step in a laboratory."},{"t":"0:15-0:30","visual":"Daily injections; ovaries with several follicles growing","vo":"First, hormone injections help the ovaries develop several eggs. Regular scans track their growth."},{"t":"0:30-0:45","visual":"Ultrasound-guided needle collecting eggs under sedation","vo":"When the eggs are ready, they are collected in a short procedure under sedation, using a thin needle guided by ultrasound."},{"t":"0:45-1:05","visual":"Lab dish; sperm meets egg, or single sperm injected (ICSI)","vo":"In the laboratory, the eggs are combined with sperm. Sometimes a single sperm is injected into each egg, a technique called ICSI."},{"t":"1:05-1:20","visual":"Embryo dividing from day 1 to day 5 blastocyst","vo":"The fertilised eggs grow into embryos over three to five days."},{"t":"1:20-1:40","visual":"Thin catheter placing an embryo into the uterus under ultrasound","vo":"A selected embryo is gently placed in the uterus through a thin, soft tube. It is usually quick and painless. Extra good-quality embryos can be frozen."},{"t":"1:40-2:00","visual":"Calendar showing two-week wait; blood test","vo":"About two weeks later, a blood test shows whether pregnancy has begun. Success depends on many factors, especially age, so talk to a fertility specialist about your situation."}],"title":"How IVF and Embryo Transfer Work","duration":"120 seconds","articles":["what-is-ivf","ivf-step-by-step","embryo-transfer-explained"],"style":"Soft 2D animation; gentle palette; captions","words":145},{"id":"v-bmt","scenes":[{"t":"0:00-0:15","visual":"Bone marrow inside bone producing red cells, white cells and platelets","vo":"Inside your bones is bone marrow, a soft tissue that makes all your blood cells."},{"t":"0:15-0:30","visual":"Marrow filled with abnormal cells crowding out healthy ones","vo":"In some blood cancers and blood disorders, the bone marrow becomes diseased or stops working properly."},{"t":"0:30-0:45","visual":"Two sources: patient's own cells, or a donor's cells","vo":"A bone marrow transplant replaces it with healthy stem cells, either the patient's own, collected earlier, or cells from a matched donor."},{"t":"0:45-1:00","visual":"Conditioning chemotherapy clearing the marrow","vo":"First, high-dose chemotherapy clears the diseased marrow and makes space for the new cells."},{"t":"1:00-1:15","visual":"Stem cells given through a drip, travelling to the bones","vo":"The healthy stem cells are then given through a drip, like a blood transfusion. They travel to the bones on their own."},{"t":"1:15-1:35","visual":"Protective room; counts slowly rising on a chart","vo":"Over two to four weeks, the new cells settle in and start making blood again. During this time, patients stay in a protective room to avoid infection."},{"t":"1:35-1:50","visual":"Patient going home; follow-up visits","vo":"Recovery continues for months, with close follow-up. Your transplant team will guide you at every step."}],"title":"How Bone Marrow Transplantation Works","duration":"110 seconds","articles":["what-is-bone-marrow-transplant","bone-marrow-transplant-process","autologous-vs-allogeneic-transplant"],"style":"2D animation; bone cutaway showing marrow; captions","words":132},{"id":"v-kidney","scenes":[{"t":"0:00-0:15","visual":"Kidneys filtering blood; then failing kidneys","vo":"Your kidneys filter waste and extra water from your blood. When they fail, dialysis or a kidney transplant is needed."},{"t":"0:15-0:30","visual":"Living donor and recipient in adjoining rooms","vo":"A new kidney can come from a living donor, usually a close family member, or from a deceased donor."},{"t":"0:30-0:45","visual":"Keyhole removal of donor kidney through small incisions","vo":"For a living donation, the donor's kidney is usually removed by keyhole surgery. The donor lives normally with one kidney."},{"t":"0:45-1:05","visual":"New kidney placed in lower abdomen; artery, vein and ureter connected","vo":"The new kidney is placed in the lower abdomen, not where the old kidneys are. It is connected to an artery, a vein and the bladder. The old kidneys usually stay in place."},{"t":"1:05-1:20","visual":"Urine flowing; patient waking up","vo":"A kidney from a living donor often starts making urine almost immediately."},{"t":"1:20-1:40","visual":"Daily medicines; follow-up blood tests","vo":"Lifelong anti-rejection medicines protect the new kidney, and regular check-ups help it last for many years."}],"title":"How Kidney Transplantation Is Performed","duration":"100 seconds","articles":["kidney-transplant-explained","kidney-transplant-surgery-day","living-vs-deceased-donor"],"style":"2D anatomical animation; captions","words":120}],"popular":["heart-attack-warning-signs","car-t-cell-therapy-overview","when-you-need-knee-replacement","stroke-warning-signs","slip-disc-symptoms","what-is-ivf","gastric-sleeve-surgery","fue-vs-fut","what-is-bone-marrow-transplant","living-vs-deceased-donor"]};